(window.NP_UZ_EXTRA = window.NP_UZ_EXTRA || []).push({"Рассчет":"Ҳисоб","Данные 2":"Маълумотлар 2","! ЗАПОЛНЯТЬ ТОЛЬКО ПОЛЯ, ВЫДЕЛЕННЫЕ СЕРЫМ ЦВЕТОМ, БЕЗ ПРОБЕЛОВ":"! ФАҚАТ КУЛРАНГ БИЛАН АЖРАТИЛГАН МАЙДОНЛАРНИ БЎШЛИҚСИЗ ТЎЛДИРИНГ","День":"Кун","Текущий год":"Жорий йил","Месяц":"Ой","Текущий месяц":"Жорий ой","Текущий день":"Жорий кун","Число Дживы (характер человека)":"Джива сони (инсон характери)","Число Дхармы (то, что даст устойчивость и удовлетворение)":"Дхарма сони (барқарорлик ва қониқиш берадиган нарса)","Число Кармы (основные события в жизни человека)":"Карма сони (инсон ҳаётидаги асосий воқеалар)","Число Проблем (проблема, которая стоит перед человеком в его жизни)":"Муаммолар сони (инсон олдида ҳаётида турган муаммо)","Агама Карма":"Агама Карма","Уровень развития души":"Руҳнинг ривожланиш даражаси","Нумерологический гороскоп:":"Нумерологик гороскоп:","Янтра:":"Янтра:","Янтра: Интегральное число:":"Янтра: Интеграл сон:","Прогноз:":"Прогноз:","Возраст:":"Ёш:","1 цикл":"1-цикл","2 цикл":"2-цикл","3 цикл":"3-цикл","Прогноз Года:":"Йил прогнози:","Прогноз по месяцам:":"Ойлар бўйича прогноз:","Число Дживы (сознание, характер человека)":"Джива сони (онг, инсон характери)","Рекомендации по Числу Дживы":"Джива сони бўйича тавсиялар","Рекомендации по Числу Кармы":"Карма сони бўйича тавсиялар","Брахман":"Браҳман","Кшатрий":"Кшатрий","Вайшья":"Вайшья","Шудра":"Шудра","Нумерологический гороскоп - это вид гороскопа, который показывает наш потенциал по рождению":"Нумерологик гороскоп — бу туғилишдаги салоҳиятимизни кўрсатадиган гороскоп тури","Уровни развития души":"Руҳнинг ривожланиш даражалари","Число Метода":"Усул сони","Число Праны":"Прана сони","Число взаимоотношений с близкими":"Яқинлар билан муносабатлар сони","Число расходов, потери":"Харажатлар, йўқотиш сони","Отношения с партнером, мужем или женой, а также с людьми в целом":"Шерик, эр ёки хотин, шунингдек умуман одамлар билан муносабатлар","Число талантов, способностей и предрасположенности":"Истеъдодлар, қобилиятлар ва мойиллик сони","Источник радости и удачи":"Қувонч ва омад манбаи","Число Ключевых задач, повторяющиеся события":"Асосий вазифалар, такрорланувчи воқеалар сони","Число того, что приносит любовь и что ожидать от нее?":"Муҳаббатни нима олиб келади ва ундан нима кутиш керак сони","Число Самореализации, денег":"Ўзини рўёбга чиқариш, пул сони","Число отдачи, заботливости, внимательности к близким":"Бериш, ғамхўрлик, яқинларга эътибор сони","Число наших возможностей, что нам помогает в жизни":"Имкониятларимиз, ҳаётда бизга нима ёрдам беради сони","Число Мировоззрения":"Дунёқараш сони","Прогноз Года":"Йил прогнози","Прогноз месяца":"Ой прогнози","Число Агама кармы - это число, которое говорит о том, что хорошо бы спланировать свою жизнь на духовном уровне, чтобы год был благоприятным.":"Агама карма сони — бу йил қулай бўлиши учун ҳаётингизни маънавий даражада режалаштириш яхши эканини айтадиган сон.","Язык любви":"Муҳаббат тили","число":"сон","месяц":"ой","год":"йил","текущий год":"жорий йил","текущий месяц":"жорий ой","Уровень души":"Руҳ даражаси","текущий день":"жорий кун","Агама карма":"Агама карма","число дживы:":"джива сони:","для числа дхармы:":"дхарма сони учун:","число дхармы:":"дхарма сони:","для число кармы:":"карма сони учун:","число кармы:":"карма сони:","для числа проблем (а):":"муаммолар сони учун (а):","для числа проблем(б):":"муаммолар сони учун (б):","Число проблем:":"Муаммолар сони:","Подготовка к год прогнозу":"Йиллик прогнозга тайёргарлик","Годовой прогноз:":"Йиллик прогноз:","Подготовка к мес прогнозу":"Ойлик прогнозга тайёргарлик","Прогноз месяца:":"Ой прогнози:","Циклы жизни:":"Ҳаёт цикллари:","Циклы по годам:":"Йиллар бўйича цикллар:","от 0 до":"0 дан","от":"дан","до":"гача","Подготовка близкие люди:":"Тайёргарлик: яқин одамлар:","Подг Отношения":"Тайёргарлик: Муносабатлар","подг Способности":"тайёргарлик: Қобилиятлар","подг Удача, радость":"тайёргарлик: Омад, қувонч","подг деньги":"тайёргарлик: пул","подг возможности":"тайёргарлик: имкониятлар","подг интегральное число":"тайёргарлик: интеграл сон","энергия":"энергия","Число месяца:":"Ой сони:","Число рождения:":"Туғилиш сони:","Число года:":"Йил сони:","Число кармы:":"Карма сони:","расходы и потери":"харажатлар ва йўқотишлар","Энергия:":"Энергия:","Близкие люди:":"Яқин одамлар:","Расходы:":"Харажатлар:","задача":"вазифа","Способности:":"Қобилиятлар:","Радость:":"Қувонч:","Задача:":"Вазифа:","Любовь:":"Муҳаббат:","Любовь":"Муҳаббат","Деньги:":"Пул:","Забота:":"Ғамхўрлик:","Возможности:":"Имкониятлар:","Мировозрение:":"Дунёқараш:","заботливость":"ғамхўрлик","Мировозрение":"Дунёқараш","Значение янтры:":"Янтранинг маъноси:","энергия человека, ее характер, откуда она берется, ее запас, а также способность энергии вкладываться во что-то. В зависимости от числа человек не только вкладывает в ту область основную энергию, но и черпает ее оттуда.":"инсон энергияси, унинг характери, у қаердан келади, унинг заҳираси, шунингдек энергиянинг нимагадир сарфланиш қобилияти. Сонга қараб инсон асосий энергияни ўша соҳага нафақат сарфлайди, балки ундан олади ҳам.","связано с эго, поэтому и энергия чрезмерно может тратиться на себя, например, стремление выделиться перед кем-то. Нужно гармонизировать 1 (Солнце). Энергию направляем на карьеру, саморазвитие и социальную реализацию. Для гармонизации нужно принимать решения и следовать своим обещаниям, культивировать ответственность и осознанность в ежедневных обязанностях, рано вставать, налаживать режим дня, здраво оценивать себя и свои таланты, уважать мнение других людей, ценить мужчин;":"эго билан боғлиқ, шунинг учун энергия ҳаддан ташқари ўзига, масалан, кимнингдир олдида ажралиб туриш истагига сарфланиши мумкин. 1 (Қуёш)ни уйғунлаштириш керак. Энергияни карьера, ўз-ўзини ривожлантириш ва ижтимоий рўёбга чиқишга йўналтирамиз. Уйғунлаштириш учун қарорлар қабул қилиш ва ваъдаларга амал қилиш, кундалик мажбуриятларда масъулият ва онглиликни ривожлантириш, эрта туриш, кун тартибини созлаш, ўзини ва истеъдодларини соғлом баҳолаш, бошқа одамларнинг фикрини ҳурмат қилиш, эркакларни қадрлаш керак;","Нехватка энергии, либо внезапная потеря. Для гармонизации нужно обратить внимание на то, есть у него какие-то незаконченные дела, их необходимо обязательно закрывать. Нужно составить список дел, проектов, которые человек начал делать, но не закончил в данный момент. Можно их пересмотреть, либо избавиться от них. Огромное количество энергии вытекает в незаконченные дела. Большое количество время нужно проводить такому человеку на природе, общаться с природой осознанно, то есть ходить по земле, дышать свежим воздухом, убирать все гаджеты. Этому человеку также важно больше спать, нежели другим людям, т.е. понять своё количество сна и придерживаться его, иначе этот недосып очень сказывается на энергии. Энергия тоже уходит тогда, когда человека заполняет много вещей, старых и ненужных. Поэтому появляется раздражение, которая забирает кусочки энергии.":"Энергия етишмаслиги ёки тўсатдан йўқотилиши. Уйғунлаштириш учун унинг қандайдир тугалланмаган ишлари бор-йўқлигига эътибор бериш керак, уларни албатта ёпиш зарур. Инсон бошлаган, лекин ҳозирги пайтда тугатмаган ишлар, лойиҳалар рўйхатини тузиш керак. Уларни қайта кўриб чиқиш ёки улардан қутулиш мумкин. Улкан миқдордаги энергия тугалланмаган ишларга оқиб кетади. Бундай инсонга табиатда кўп вақт ўтказиш, табиат билан онгли мулоқот қилиш, яъни ерда юриш, тоза ҳаво нафас олиш, барча гаджетларни олиб қўйиш керак. Бу инсонга шунингдек бошқа одамларга қараганда кўпроқ ухлаш, яъни ўз уйқу миқдорини тушуниш ва унга амал қилиш муҳим, акс ҳолда уйқу етишмаслиги энергияга жуда таъсир қилади. Энергия инсонни кўп нарсалар, эски ва кераксиз нарсалар тўлдирганда ҳам кетади. Шунинг учун энергия бўлакларини олиб кетадиган жаҳл пайдо бўлади.","Кроме того, есть люди, которые тянут энергию, при общении с ними человек испытывает негатив, нехватка энергии, либо внезапная потеря. Для гармонизации нужно обратить внимание на то, есть ли у человека какие-то незаконченные дела или невыполненные обещания. Нужно составить список дел, проектов, которые человек начал делать, но не закончил в данный момент. Можно их пересмотреть: закончить, либо избавиться от них.":"Бундан ташқари, энергияни тортадиган одамлар бор, улар билан мулоқотда инсон салбийлик, энергия етишмаслиги ёки тўсатдан йўқотилишини бошдан кечиради. Уйғунлаштириш учун инсонда қандайдир тугалланмаган ишлар ёки бажарилмаган ваъдалар бор-йўқлигига эътибор бериш керак. Инсон бошлаган, лекин ҳозирги пайтда тугатмаган ишлар, лойиҳалар рўйхатини тузиш керак. Уларни қайта кўриб чиқиш мумкин: тугатиш ёки улардан қутулиш.","Большое количество времени нужно проводить человеку на природе, общаться с природой осознанно, то есть ходить по земле, дышать свежим воздухом, убирать все гаджеты.":"Инсонга табиатда кўп вақт ўтказиш, табиат билан онгли мулоқот қилиш, яъни ерда юриш, тоза ҳаво нафас олиш, барча гаджетларни олиб қўйиш керак.","Также важно отрегулировать сон, возможно потребуется больше сна, нежели другим людям. Недосып очень сказывается на энергии.":"Шунингдек уйқуни тартибга солиш муҳим, эҳтимол, бошқа одамларга қараганда кўпроқ уйқу керак бўлади. Уйқу етишмаслиги энергияга жуда таъсир қилади.","Энергия уходит тогда, когда человек заполняет свое пространство множеством вещей, старых и ненужных, из-за этого появляется раздражение, которое забирает кусочки энергии. Можно создать экстренную «медицинскую» помощь для себя, где человек с нулевой энергией может тут же подкрепиться. Для этого необходимо понять самому, что больше всего нравится (книга, музыка и т.д.). Когда человек чувствует бессилие, нужно принять эти спасательные действия. Это может быстро пополнить запас.":"Энергия инсон ўз маконини кўплаб эски ва кераксиз нарсалар билан тўлдирганда кетади, шу сабабли энергия бўлакларини олиб кетадиган жаҳл пайдо бўлади. Ўзингиз учун нол энергияли инсон дарҳол қувват ола оладиган шошилинч «тиббий» ёрдам яратиш мумкин. Бунинг учун энг кўп нима ёқишини (китоб, мусиқа ва ҳ.к.) ўзингиз тушунишингиз керак. Инсон ҳолсизликни ҳис қилганда, бу қутқариш ҳаракатларини қабул қилиш керак. Бу заҳирани тез тўлдириши мумкин.","Можно создать экстренную «медицинскую» помощь для себя, где человек с нулевой энергией может тут же подкрепиться. Для этого человеку необходимо понять самому, что ему больше всего нравится (книга, музыка и т.д.). Когда человек чувствует бессилие, нужно принять эти спасательные действия. Это может быстро пополнить запас.":"Ўзингиз учун нол энергияли инсон дарҳол қувват ола оладиган шошилинч «тиббий» ёрдам яратиш мумкин. Бунинг учун инсонга унга энг кўп нима ёқишини (китоб, мусиқа ва ҳ.к.) ўзи тушуниши керак. Инсон ҳолсизликни ҳис қилганда, бу қутқариш ҳаракатларини қабул қилиш керак. Бу заҳирани тез тўлдириши мумкин.","на карьеру, саморазвитие, на социальную реализацию. Для гармонизации нужно принимать решения и следовать своим обещаниям, культивировать ответственность и осознанность в ежедневных обязанностях, рано вставать, налаживать режим дня, здраво оценивать себя и свои таланты, уважать мнение других людей, ценить мужчин;":"карьерага, ўз-ўзини ривожлантиришга, ижтимоий рўёбга чиқишга. Уйғунлаштириш учун қарорлар қабул қилиш ва ваъдаларга амал қилиш, кундалик мажбуриятларда масъулият ва онглиликни ривожлантириш, эрта туриш, кун тартибини созлаш, ўзини ва истеъдодларини соғлом баҳолаш, бошқа одамларнинг фикрини ҳурмат қилиш, эркакларни қадрлаш керак;","на отношения, поиск второй половины, на психическое равновесие и спокойствие ума, творчество, на занятие йогой, общение в женском кругу. Важно проявлять уважение и терпение к матери, дарить ей подарки. Помимо родной матери, Веды причисляют к статусу матери также: корову, землю, жену священника, любую женщину, которая дает покровительство и заботу. Для гармонизации энергии важно пребывать в местах, где есть водоемы, красивые места на природе, ходить босиком, принимать ванну, убираться в квартире, избавляться от хлама и наводить уют;":"муносабатларга, иккинчи ярмини излашга, руҳий мувозанат ва ақл хотиржамлигига, ижодга, йога билан шуғулланишга, аёллар даврасида мулоқотга. Онага ҳурмат ва сабр кўрсатиш, унга совғалар қилиш муҳим. Туғишган онадан ташқари, Ведалар она мақомига шунингдек: сигир, ер, руҳоний хотини, ҳомийлик ва ғамхўрлик берадиган ҳар қандай аёлни киритади. Энергияни уйғунлаштириш учун сув ҳавзалари бор жойларда, табиатдаги чиройли жойларда бўлиш, ялангоёқ юриш, ванна қабул қилиш, квартирада тозалаш, ахлатдан қутулиш ва қулайлик яратиш муҳим;","на расширение деятельности, обучение себя и других, передачу опыта, на воспитание детей и младших, обретение мудрости, благотворительность. Важно читать священную литературу, читать мантры/молитвы, совершать бескорыстное служение в храмах. Для гармонизации энергии нужно иметь денежную подушку безопасности (чтобы всегда были деньги);":"фаолиятни кенгайтиришга, ўзини ва бошқаларни ўқитишга, тажриба етказишга, фарзандлар ва кичикларни тарбиялашга, донолик орттиришга, хайрияга. Муқаддас адабиётни ўқиш, мантра/дуоларни ўқиш, ибодатхоналарда беғараз хизмат қилиш муҳим. Энергияни уйғунлаштириш учун пул хавфсизлик ёстиғига эга бўлиш керак (доим пул бўлиши учун);","энергия направляется либо на низшие желания (зависнуть в интернете, интоксикации), либо в благости – на духовное развитие и ее стабильность. Важно отслеживать в себе процессы саморазрушения: тревогу, беспокойства, панику. Нужно строго следовать режиму дня, следить за своим питанием (ЗОЖ в идеале, вегетарианская диета), следить за балансом работы и отдыха. Если есть признаки уныния, то нужно развеивать пребыванием в паломничестве, в горах и лесах, у воды;":"энергия ё қуйи истакларга (интернетда қотиб қолиш, интоксикациялар), ё эзгуликда — маънавий ривожланиш ва унинг барқарорлигига йўналтирилади. Ўзингизда ўз-ўзини вайрон қилиш жараёнларини: хавотир, безовталик, ваҳимани кузатиш муҳим. Кун тартибига қатъий амал қилиш, овқатланишни кузатиш (идеалда СТТ, вегетариан парҳез), иш ва дам олиш мувозанатини кузатиш керак. Агар тушкунлик белгилари бўлса, уни зиёратда, тоғлар ва ўрмонларда, сув ёнида бўлиш билан тарқатиш керак;","на интеллект, знание, стремление к качественному общению, размышлению и анализу, развитию своего дела, на совмещение своих знаний и навыков. Важно научиться выделять главные и второстепенные цели, экономить энергию для важных дел, ограничить посещение увеселительных мероприятий, меньше пустословить, научиться концентрироваться, совмещать знания. Хорошо соблюдать мауну-врату (обет молчания) хотя бы раз в месяц и также хорошо практиковать публичные выступления;":"интеллектга, билимга, сифатли мулоқотга, мулоҳаза ва таҳлилга интилишга, ўз ишини ривожлантиришга, билим ва кўникмаларини бирлаштиришга. Асосий ва иккинчи даражали мақсадларни ажратишни, муҳим ишлар учун энергияни тежашни, кўнгилочар тадбирларга боришни чеклашни, камроқ бўш гапиришни, диққатни жамлашни, билимларни бирлаштиришни ўрганиш муҳим. Ҳеч бўлмаганда ойда бир марта мауна-врата (сукут назри)га риоя қилиш ва шунингдек омма олдида чиқишларни амалда қўллаш яхши;","на удовольствия, приятную работу, творчество, наслаждения в гуне благости. Важно любоваться пейзажами, картинами, природой, архитектурой, танцами, благостными фильмами. Посещать курсы по кулинарии, дизайну, пению, рисованию, флористики. Развивать вкус: украшать тело и дом. Следить за диетой, не переедать. Обязательно регулярно отдыхать, наиболее благоприятно в красивых местах, не накапливать напряжение. Принимать дома гостей и угощать их. Помогать другим женщинам развивать женские качества;":"завқларга, ёқимли ишга, ижодга, эзгулик гунасидаги лаззатларга. Манзаралар, суратлар, табиат, архитектура, рақслар, эзгу фильмлардан завқланиш муҳим. Ошпазлик, дизайн, қўшиқ, расм чизиш, флористика бўйича курсларга бориш. Дидни ривожлантириш: танани ва уйни безатиш. Парҳезни кузатиш, ортиқча овқатланмаслик. Мунтазам дам олиш, энг қулайи чиройли жойларда, таранглик тўпламаслик шарт. Уйда меҳмон кутиш ва уларни меҳмон қилиш. Бошқа аёлларга аёллик фазилатларини ривожлантиришда ёрдам бериш;","на йогу и медитацию, духовный путь, трансформацию сознания, эзотерику. Развивать бескорыстное служение миру, развивать интуицию. Избавляться от старых и испорченных вещей, бывать чаще на природе. Придерживаться ЗОЖ и вегетарианской диеты. Учиться концентрации. Жить нужно в настоящем мгновении, трезво оценивая свои силы и не тревожась о надуманных проблемах, будь то боязнь перемен или прошлый опыт, мешающий двигаться вперед.":"йога ва медитацияга, маънавий йўлга, онг трансформациясига, эзотерикага. Дунёга беғараз хизматни ривожлантириш, интуицияни ривожлантириш. Эски ва бузилган нарсалардан қутулиш, табиатда тез-тез бўлиш. СТТ ва вегетариан парҳезга амал қилиш. Диққатни жамлашни ўрганиш. Ҳозирги лаҳзада, кучини ҳушёр баҳолаб ва ўйлаб топилган муаммолар — ўзгаришлардан қўрқув ёки олдинга ҳаракатланишга халақит берадиган ўтмиш тажрибаси ҳақида хавотирланмай яшаш керак.","Близкие люди.":"Яқин одамлар.","показатель того, что привносят друзья, близкие люди, семья в жизнь человека":"дўстлар, яқин одамлар, оила инсон ҳаётига нима олиб киришининг кўрсаткичи","либо конфликты и борьба за власть, конкуренция, зависть, либо человек чувствует себя одиноко, не смотря на то, что его могут окружать много людей, окружение таким образом вырабатывает самостоятельность и ответственность за свою жизнь и поступки, и человек склонен быть самим по себе;":"ё низолар ва ҳокимият учун кураш, рақобат, ҳасад, ё инсон атрофида кўп одамлар бўлишига қарамай ўзини ёлғиз ҳис қилади, атроф шу тарзда мустақиллик ва ўз ҳаёти ва қилмишлари учун масъулиятни ишлаб чиқади, ва инсон ўзича бўлишга мойил;","хорошие, глубокие отношения, проявление заботы, нежности, понимания, но может быть у человека две семьи, либо две семьи каждого из родителя – семья увеличивается на два, в том числе дети с разных браков;":"яхши, чуқур муносабатлар, ғамхўрлик, нозиклик, тушуниш кўрсатиш, лекин инсонда икки оила ёки ота-онанинг ҳар биридан икки оила бўлиши мумкин — оила иккига, жумладан турли никоҳлардан фарзандлар билан кўпаяди;","семья принесет развитие, расширение, богатство, успех, поддержку, и также сам человек нуждается в семейном тепле и уюте, в желании заботиться о других, покровительствовать им;":"оила ривожланиш, кенгайиш, бойлик, муваффақият, қўллаб-қувватлаш олиб келади, шунингдек инсоннинг ўзи ҳам оилавий илиқлик ва қулайликка, бошқаларга ғамхўрлик қилиш, уларга ҳомийлик қилиш истагига муҳтож;","странная семья, всем что-то надо, потому что Раху – планета, которая дает человеку все, некий ящик Пандоры, но она не дает удовлетворение от того, что предоставляет, а у окружающих видение, словно у человека все есть; здесь может быть хаос в отношениях, неуважение, предательства, странность и абсурд; но если Раху довести до гуны благости, то может быть духовная общность;":"ғалати оила, ҳаммага нимадир керак, чунки Раҳу — инсонга ҳамма нарсани берадиган сайёра, ўзига хос Пандора қутиси, лекин у берган нарсадан қониқиш бермайди, атрофдагиларда эса инсонда ҳамма нарса бордек тасаввур; бу ерда муносабатларда хаос, ҳурматсизлик, хиёнатлар, ғалатилик ва бемаънилик бўлиши мумкин; лекин агар Раҳуни эзгулик гунасигача етказилса, маънавий умумийлик бўлиши мумкин;","много контактов и родственников, могут быть прохладные отношения, нет эмоциональной близости, хотя внешне связь может хорошо поддерживаться, интеллектуальные беседы;":"кўп алоқалар ва қариндошлар, совуқроқ муносабатлар бўлиши мумкин, ҳиссий яқинлик йўқ, гарчи ташқаридан алоқа яхши сақланиши мумкин бўлса ҳам, интеллектуал суҳбатлар;","человек счастлив в отношениях, есть близость, наслаждение, хотя в низших гунах могут проявляться измены;":"инсон муносабатларда бахтли, яқинлик, лаззат бор, гарчи қуйи гуналарда хиёнатлар намоён бўлиши мумкин бўлса ҳам;","неожиданности, разочарования, потому что Кету – отшельник, ему трудно в отношениях;":"кутилмаган ҳодисалар, ҳафсаласизликлар, чунки Кету — зоҳид, унга муносабатларда қийин;","деловые отношения, напряжение, недостаток теплоты, чувство долга и сила ответственности, но могут быть серьезные отношения с высокими ценностями;":"ишчан муносабатлар, таранглик, илиқлик етишмаслиги, бурч ҳисси ва масъулият кучи, лекин юксак қадриятларга эга жиддий муносабатлар бўлиши мумкин;","в минусе могут быть темпераментные и вспыльчивые отношения, ощущение жесткости и давления, в семье родителей могут быть частые конфликты. В плюсе человека окружают люди дисциплинированные, сильные, решительные, творческие.":"минусда темпераментли ва жаҳлдор муносабатлар, қаттиққўллик ва босим ҳисси бўлиши мумкин, ота-оналар оиласида тез-тез низолар бўлиши мумкин. Плюсда инсонни интизомли, кучли, қатъиятли, ижодкор одамлар ўраб туради.","Расходы, потери.":"Харажатлар, йўқотишлар.","куда вкладываются деньги, щедрость человека.":"пул қаерга сарфланади, инсоннинг саховати.","Если есть позитивные цифры 2, 3, 5, 6, то это защищает от потерь.":"Агар ижобий 2, 3, 5, 6 рақамлари бўлса, бу йўқотишлардан ҳимоя қилади.","Расходы могут проявляться как безответственная трата денег либо наоборот скупость, жалко тратить деньги, в особенности на себя.":"Харажатлар пулни масъулиятсиз сарфлаш ёки аксинча хасислик, пул сарфлашга, айниқса ўзига, ачиниш сифатида намоён бўлиши мумкин.","Нужно научиться инвестировать в себя, например, в образование и в свои потребности. Нужно гармонизировать Солнце, научиться инвестировать в себя":"Ўзига, масалан, таълим ва ўз эҳтиёжларига сармоя киритишни ўрганиш керак. Қуёшни уйғунлаштириш, ўзига сармоя киритишни ўрганиш керак","Потери непонятного направления. Инвестировать нужно в здоровый образ жизни и духовную практику, в познание и развития себя. Рекомендация: чтобы изменить ситуацию нужно прикладывать усилия, например, учится правильно использовать деньги, выписывать все траты, чтобы после проанализировать, какая из статьи расходов была инвестицией, а какая – тратой? Вести домашний бюджет, также прочитать соответствующие книги (например, \"Богатый папа, бедный папа\"), пройти денежный марафон – это повышает осознанность, а осознанность повышает гуну благости.":"Тушунарсиз йўналишдаги йўқотишлар. Соғлом турмуш тарзи ва маънавий амалиётга, ўзини англаш ва ривожлантиришга сармоя киритиш керак. Тавсия: вазиятни ўзгартириш учун саъй-ҳаракат қилиш керак, масалан, пулдан тўғри фойдаланишни ўрганиш, кейин қайси харажат моддаси сармоя, қайсиси — сарф бўлганини таҳлил қилиш учун барча харажатларни ёзиб бориш. Уй бюджетини юритиш, шунингдек тегишли китобларни ўқиш (масалан, «Бой ота, камбағал ота»), пул марафонидан ўтиш — бу онглиликни оширади, онглилик эса эзгулик гунасини оширади.","Расходы могут быть на дорогие и престижные вещи. Нужно вкладывать деньги в карьеру, в свое образование, в свой статус, в стремление к славе; Может быть потеря денег из-за гордости;":"Харажатлар қиммат ва нуфузли нарсаларга бўлиши мумкин. Пулни карьера, ўз таълими, мавқеи, шуҳратга интилишга киритиш керак; Ғурур туфайли пул йўқотиш бўлиши мумкин;","Расходы связаны с отношениями: заплатить за кого-то, дать в долг, купить подарок, но важно не забывать о своих потребностях и желаниях. Вкладывайте деньги в путешествия у воды: озеро, море, океан, и подойдет и спа;":"Харажатлар муносабатлар билан боғлиқ: кимнингдир ўрнига тўлаш, қарз бериш, совға сотиб олиш, лекин ўз эҳтиёжлари ва истакларини унутмаслик муҳим. Пулни сув ёнидаги саёҳатларга киритинг: кўл, денгиз, океан, спа ҳам мос келади;","Расходы связаны с детьми или обучением. Это число отвечает за приумножение всех ресурсов, поэтому важно учиться сберегать и инвестировать;":"Харажатлар фарзандлар ёки ўқиш билан боғлиқ. Бу сон барча ресурсларни кўпайтириш учун жавоб беради, шунинг учун жамғариш ва сармоя киритишни ўрганиш муҳим;","Расходы в никуда: на иллюзии, фантики, алкоголь, мишуру; Инвестировать нужно в здоровый образ жизни и в духовную практику, в познание и развитие себя. Рекомендация: чтобы изменить ситуацию нужно прикладывать усилия, например, учится правильно использовать деньги, выписывать все траты, чтобы после проанализировать, какая из статьи расходов была инвестицией, а какая – тратой? Вести домашний бюджет, также прочитать соответствующие книги (например, \"Богатый папа, бедный папа\"), пройти денежный марафон – это повышает осознанность, а осознанность повышает гуну благости.":"Ҳеч қаёққа харажатлар: иллюзиялар, ялтироқ нарсалар, алкоголь, безакларга; Соғлом турмуш тарзи ва маънавий амалиётга, ўзини англаш ва ривожлантиришга сармоя киритиш керак. Тавсия: вазиятни ўзгартириш учун саъй-ҳаракат қилиш керак, масалан, пулдан тўғри фойдаланишни ўрганиш, кейин қайси харажат моддаси сармоя, қайсиси — сарф бўлганини таҳлил қилиш учун барча харажатларни ёзиб бориш. Уй бюджетини юритиш, шунингдек тегишли китобларни ўқиш (масалан, «Бой ота, камбағал ота»), пул марафонидан ўтиш — бу онглиликни оширади, онглилик эса эзгулик гунасини оширади.","Исходя из своего опыта, даю практическую рекомендацию: чтобы изменить ситуацию нужно прикладывать усилия, например, учится правильно использовать деньги, выписывать все траты, чтобы после проанализировать, какая из статьи расходов была инвестицией, а какая – тратой? Предположим, еда может быть и инвестицией, и тратой: чипсы - это явно трата, но ягоды - это инвестиция в здоровье. Вести домашний бюджет, также прочитать соответствующие книги (например, \"Богатый папа, бедный папа\"), пройти денежный марафон – это повышает осознанность, а осознанность повышает гуну благости.":"Ўз тажрибамдан келиб чиқиб, амалий тавсия бераман: вазиятни ўзгартириш учун саъй-ҳаракат қилиш керак, масалан, пулдан тўғри фойдаланишни ўрганиш, кейин қайси харажат моддаси сармоя, қайсиси — сарф бўлганини таҳлил қилиш учун барча харажатларни ёзиб бориш. Фараз қилайлик, овқат ҳам сармоя, ҳам сарф бўлиши мумкин: чипслар — аниқ сарф, лекин резавор мевалар — саломатликка сармоя. Уй бюджетини юритиш, шунингдек тегишли китобларни ўқиш (масалан, «Бой ота, камбағал ота»), пул марафонидан ўтиш — бу онглиликни оширади, онглилик эса эзгулик гунасини оширади.","Расходы связаны с эмоциями и импульсивными покупками. Важно вкладывать деньги на учебу, развитие, хобби, путешествия, в ораторское искусство":"Харажатлар ҳис-туйғулар ва импульсив харидлар билан боғлиқ. Пулни ўқиш, ривожланиш, хобби, саёҳатлар, нотиқлик санъатига киритиш муҳим","Траты идут на красоту, удобство и обустройство жизни. Один из принципов числа 6 - это притяжение того, что вам нравится или хочется. Вкладывайте свои деньги в область, связанную с искусством, культурой, красотой, модой, дизайном, удобством и комфортом":"Сарфлар гўзаллик, қулайлик ва ҳаётни жиҳозлашга кетади. 6 сонининг тамойилларидан бири — сизга ёққан ёки истаган нарсани жалб қилиш. Пулингизни санъат, маданият, гўзаллик, мода, дизайн, қулайлик ва роҳат билан боғлиқ соҳага киритинг","Неясно, куда уходят деньги; люди с 7 часто зарабатывают много денег, но их нет: они «куда-то» деваются; Инвестировать нужно в здоровый образ жизни и в духовную практику, в познание и развитие себя. Рекомендация: чтобы изменить ситуацию нужно прикладывать усилия, например, учится правильно использовать деньги, выписывать все траты, чтобы после проанализировать, какая из статьи расходов была инвестицией, а какая – тратой? Вести домашний бюджет, также прочитать соответствующие книги (например, \"Богатый папа, бедный папа\"), пройти денежный марафон – это повышает осознанность, а осознанность повышает гуну благости.":"Пул қаерга кетиши ноаниқ; 7 ли одамлар кўпинча кўп пул топади, лекин у йўқ: «қаергадир» ғойиб бўлади; Соғлом турмуш тарзи ва маънавий амалиётга, ўзини англаш ва ривожлантиришга сармоя киритиш керак. Тавсия: вазиятни ўзгартириш учун саъй-ҳаракат қилиш керак, масалан, пулдан тўғри фойдаланишни ўрганиш, кейин қайси харажат моддаси сармоя, қайсиси — сарф бўлганини таҳлил қилиш учун барча харажатларни ёзиб бориш. Уй бюджетини юритиш, шунингдек тегишли китобларни ўқиш (масалан, «Бой ота, камбағал ота»), пул марафонидан ўтиш — бу онглиликни оширади, онглилик эса эзгулик гунасини оширади.","Отношения.":"Муносабатлар.","как складываются отношения с другими: друзьями, знакомыми, окружающими человека людьми, коллегами.":"бошқалар: дўстлар, танишлар, инсонни ўраб турган одамлар, ҳамкасблар билан муносабатлар қандай кечади.","мало друзей, не стремится расширять круг знакомств, потому что от этого может быть конкуренция;":"дўстлари кам, танишлар доирасини кенгайтиришга интилмайди, чунки бундан рақобат бўлиши мумкин;","для отношений хорошо, много друзей, но они непродолжительные, потому что 2 всегда переменчивая натура: хочется со многими дружить, будет не успевать идти в длительные отношения;":"муносабатлар учун яхши, дўстлари кўп, лекин улар қисқа муддатли, чунки 2 доим ўзгарувчан табиат: кўплар билан дўстлашгиси келади, узоқ муносабатларга киришга улгурмайди;","много друзей, знакомых, много возможностей для создания хороших отношений;":"дўстлар, танишлар кўп, яхши муносабатлар яратиш учун кўплаб имкониятлар;","странные отношения с другими людьми, это мистические отношения, может быть хаос в отношениях, эта цифра учит быть самодостаточным человеком; человек заметен в обществе, могут быть необычные знакомые, связанные с необычной профессией и увлечениями эзотерическими знаниями, духовными знаниями, необычными методами работы, за рамками обычного материалистического подхода;":"бошқа одамлар билан ғалати муносабатлар, бу мистик муносабатлар, муносабатларда хаос бўлиши мумкин, бу рақам ўзига етарли инсон бўлишга ўргатади; инсон жамиятда кўзга ташланади, ғайриоддий касб ва эзотерик билимлар, маънавий билимлар, оддий материалистик ёндашувдан ташқари ғайриоддий иш усулларига қизиқиш билан боғлиқ ғайриоддий танишлар бўлиши мумкин;","много отношений, контактов, скорее интеллектуальные отношения или связанные с путешествиями, играми, либо закрытие от отношений, также может быть очень поверхностное общение;":"кўп муносабатлар, алоқалар, кўпроқ интеллектуал муносабатлар ёки саёҳатлар, ўйинлар билан боғлиқ, ёки муносабатлардан ёпилиш, шунингдек жуда юзаки мулоқот бўлиши мумкин;","все очень хорошо в отношениях: сам человек проявляет уважение и принятие других людей, и к нему относятся с уважением, есть доброжелательность, открытость и верность в отношениях;":"муносабатларда ҳаммаси жуда яхши: инсоннинг ўзи бошқа одамларга ҳурмат ва қабул қилиш кўрсатади ва унга ҳурмат билан муносабатда бўлишади, муносабатларда хайрихоҳлик, очиқлик ва садоқат бор;","странные отношения с другими людьми, это мистические отношения, может быть хаос в отношениях, некое непонимание, эта цифра учит быть самодостаточным человеком;":"бошқа одамлар билан ғалати муносабатлар, бу мистик муносабатлар, муносабатларда хаос, қандайдир тушунмовчилик бўлиши мумкин, бу рақам ўзига етарли инсон бўлишга ўргатади;","отношения строятся на деловой основе: конкретные, практические отношения, человеку важно доверие и рациональность, иногда его могут обвинять в холодности и безэмоциональности, но он показывает свое отношение через поступки и преданность;":"муносабатлар ишчан асосда қурилади: аниқ, амалий муносабатлар, инсонга ишонч ва рационаллик муҳим, баъзан уни совуқлик ва ҳиссизликда айблашлари мумкин, лекин у ўз муносабатини қилмишлар ва садоқат орқали кўрсатади;","вспыльчивость и конфликтность в отношениях, нужно избегать конфликтов, но в плюсе сплоченность, умение быть в команде, желание защищать слабых.":"муносабатларда жаҳлдорлик ва низоликка мойиллик, низолардан қочиш керак, лекин плюсда жипслик, жамоада бўла олиш, заифларни ҳимоя қилиш истаги.","Способности.":"Қобилиятлар.","Или сиддхи (санскрит) – сверхъестественные силы, то есть то, где лежит сила человека.":"Ёки сиддхи (санскрит) — ғайритабиий кучлар, яъни инсоннинг кучи нимада ётгани.","величие, сила воли, яркость, авторитет, незаурядность, амбициозность, смелость, харизма, чувство собственного достоинства, целеустремленность, лидерство и способность руководить, вдохновлять, руководить, вести за собой, способность быть первым или первой в чем-либо;":"улуғворлик, ирода кучи, ёрқинлик, обрў, ноёблик, шуҳратпарастлик, жасорат, харизма, ўз қадр-қиммати ҳисси, мақсадга интилувчанлик, етакчилик ва раҳбарлик қила олиш, илҳомлантириш, бошқариш, ортидан эргаштириш, нимададир биринчи бўлиш қобилияти;","женственность, чувственность, утонченность, способность налаживать партнерство, деликатность, мягкость, общительность, забота о других, умение понимать психологию людей, сильная интуиция, способности к пению, творчеству в целом;":"аёллик, ҳиссиётлилик, нафислик, шерикликни йўлга қўйиш қобилияти, нозиклик, юмшоқлик, киришимлилик, бошқаларга ғамхўрлик, одамлар психологиясини тушуниш маҳорати, кучли интуиция, қўшиқ, умуман ижодга қобилиятлар;","умение накапливать и перераспределять финансы (инвестирование и благотворительность), способность к постоянному обретению знаний, поиску духовности, оптимизм и популярность, дар речи, способность давать мудрые советы, передавать знания простыми словами;":"молияни жамғариш ва қайта тақсимлаш маҳорати (сармоя ва хайрия), доимий билим орттириш, маънавиятни излаш қобилияти, оптимизм ва машҳурлик, нутқ иқтидори, доно маслаҳатлар бериш, билимларни оддий сўзлар билан етказиш қобилияти;","экстрасенсорные способности, изобретательность, оригинальность, стабильность, необычный юмор, интерес к иностранным культурам, богатое воображение, способность придумывать и осуществлять самые смелые идеи, сила внутреннего мира, целительство;":"экстрасенсор қобилиятлар, ихтирочилик, ўзига хослик, барқарорлик, ғайриоддий юмор, чет маданиятларга қизиқиш, бой тасаввур, энг жасур ғояларни ўйлаб топиш ва амалга ошириш қобилияти, ички дунё кучи, шифокорлик;","гибкость, смекалка, молодость духа, веселье, быстрота, интеллект и эрудиция, стратегическое планирование, развитие в области маркетинга; способность вдохновлять, разъяснять (можно читать лекции, давать консультации) и то, что связано с речью, словом, умением, находить общий язык со всеми, коммуникабельностью в целом; аналитические способности, умение быстро схватить суть, расположенность к языкам и наукам;":"мослашувчанлик, зийраклик, руҳ ёшлиги, қувноқлик, тезлик, интеллект ва билимдонлик, стратегик режалаштириш, маркетинг соҳасида ривожланиш; илҳомлантириш, тушунтириш (маърузалар ўқиш, маслаҳатлар бериш мумкин) қобилияти ва нутқ, сўз, маҳорат, ҳамма билан тил топишиш, умуман киришимлилик билан боғлиқ нарсалар; таҳлилий қобилиятлар, моҳиятни тез илғаш маҳорати, тиллар ва фанларга мойиллик;","способность создавать уют, комфорт, красоту, определенную атмосферу (например, расслабляющую, восстанавливающую), получать и дарить наслаждение, художественные и творческие способности, романтичность, стремление к роскоши;":"қулайлик, роҳат, гўзаллик, маълум муҳит (масалан, бўшаштирувчи, тикловчи) яратиш, лаззат олиш ва ҳадя қилиш қобилияти, бадиий ва ижодий қобилиятлар, романтиклик, ҳашаматга интилиш;","интуиция и проницательность, предвидение, духовность, исследовательский дар, искусство тонко чувствовать не только людей, но и различные события, способности в области психологии, эзотерики, астрологии и нумерологии;":"интуиция ва зийраклик, олдиндан кўриш, маънавият, тадқиқотчилик иқтидори, нафақат одамларни, балки турли воқеаларни ҳам нозик ҳис қилиш санъати, психология, эзотерика, астрология ва нумерология соҳасидаги қобилиятлар;","способность трудиться и достигать результатов, мудрость, усердие, терпение, дисциплина, сила духа, статусность в обществе, надежность, ответственность, организаторские, исполнительные способности, талант в систематизации, создании структуры;":"меҳнат қилиш ва натижаларга эришиш қобилияти, донолик, тиришқоқлик, сабр, интизом, руҳ кучи, жамиятдаги мавқе, ишончлилик, масъулият, ташкилотчилик, ижрочилик қобилиятлари, тизимлаштириш, тузилма яратишда истеъдод;","смелость, сила, выносливость, страсть, умение творить и заниматься искусством, способность энергетического воздействия, например, целить людей; энергичность, спортивные способности и в целом активность в социуме, энтузиазм, способность защищать, склонность к героическим поступкам, талант в технических направлениях, мастерское владение инструментами.":"жасорат, куч, чидамлилик, эҳтирос, ижод қилиш ва санъат билан шуғулланиш маҳорати, энергетик таъсир кўрсатиш, масалан, одамларни даволаш қобилияти; ғайратлилик, спорт қобилиятлари ва умуман жамиятдаги фаоллик, иштиёқ, ҳимоя қилиш қобилияти, қаҳрамонона қилмишларга мойиллик, техник йўналишларда истеъдод, асбоблардан моҳирона фойдаланиш.","Радость, удача.":"Қувонч, омад.","оптимизм, как выглядит радость жизни.":"оптимизм, ҳаёт қувончи қандай кўринади.","от лидерства и активности, от самореализации, от придумывания идей и проектов, от достижений целей, от возможности побыть наедине с собой, от развлечений, атрибутов статуса, подарков другим, от признания окружающих;":"етакчилик ва фаолликдан, ўзини рўёбга чиқаришдан, ғоя ва лойиҳалар ўйлаб топишдан, мақсадларга эришишдан, ўзи билан ёлғиз қолиш имкониятидан, кўнгилочар машғулотлардан, мавқе атрибутларидан, бошқаларга совғалардан, атрофдагиларнинг эътирофидан;","от отношений: человек счастлив, когда он с кем-то общается, дарит свою любовь и заботу, и в обмен получает благодарность, от принятия его другими, от творчества, от взаимодействия с водой, от медитаций, от заботы о себе, от доверия к людям, миру и Богу;":"муносабатлардан: инсон кимдир билан мулоқот қилганда, ўз муҳаббати ва ғамхўрлигини ҳадя қилганда ва эвазига миннатдорлик олганда бахтли, бошқалар уни қабул қилишидан, ижоддан, сув билан ўзаро таъсирдан, медитациялардан, ўзига ғамхўрликдан, одамларга, дунёга ва Худога ишончдан;","от детей: развлечения с ними, семейные походы; радость от обучения, финансовой деятельности. Например: посмотреть вебинар, почитать книгу, общение с людьми более статусными, от которых можно чему-то научиться, путешествовать для расширения своего кругозора, поработать, позаниматься йогой, помедитировать. Внимание на те области, где можно передать свой опыт и знания;":"фарзандлардан: улар билан кўнгил очиш, оилавий юришлар; ўқишдан, молиявий фаолиятдан қувонч. Масалан: вебинар кўриш, китоб ўқиш, ниманидир ўрганиш мумкин бўлган мавқеироқ одамлар билан мулоқот, дунёқарашни кенгайтириш учун саёҳат қилиш, ишлаш, йога билан шуғулланиш, медитация қилиш. Ўз тажрибаси ва билимларини етказиш мумкин бўлган соҳаларга эътибор;","от занятия йогой, духовной практики, танцы, путешествия, от здорового и натурального питания (в том числе аюрведа), работы на земле и с землей, натуральных аромамасел, важна обеспеченность, высокое социальное положение, достаток, недвижимость, накопления, а также поддержание чистоты и порядка;":"йога билан шуғулланиш, маънавий амалиёт, рақслар, саёҳатлардан, соғлом ва табиий овқатланишдан (жумладан аюрведа), ерда ва ер билан ишлашдан, табиий хушбўй ёғлардан, таъминланганлик, юқори ижтимоий мавқе, фаровонлик, кўчмас мулк, жамғармалар, шунингдек тозалик ва тартибни сақлаш муҳим;","от учебы, контактов, общения, перемен, интеллектуальных бесед, путешествий, от вокала, блогерства, от игры на музыкальных инструментах, от комплиментов, от молитвы, важно делиться знаниями, заниматься творчеством, проговаривать свои мысли, делать письменные практики;":"ўқиш, алоқалар, мулоқот, ўзгаришлар, интеллектуал суҳбатлар, саёҳатлардан, вокалдан, блогерликдан, мусиқа асбобларида чалишдан, мақтовлардан, дуодан, билимлар билан бўлишиш, ижод билан шуғулланиш, фикрларни айтиб бериш, ёзма амалиётлар қилиш муҳим;","от удовольствий, роскоши, отношений, комфорта, удобства, творчества, заботы о себе. Например: шоппинг, балование себя, то, что приносит удовольствие. Следует развивать личный стиль в одежде, носить украшения, краситься и делать укладку, посещать массаж и делать косметические процедуры, окружать себя красивой обстановкой (посуда, постельное белье, декор и прочее), пообниматься с любимыми, давать себе отдохнуть, заземлятся, смотреть красивые фильмы, покупать аромасвечи;":"завқлар, ҳашамат, муносабатлар, роҳат, қулайлик, ижод, ўзига ғамхўрликдан. Масалан: шоппинг, ўзини эркалаш, завқ келтирадиган нарсалар. Кийимда шахсий услубни ривожлантириш, безаклар тақиш, пардоз ва соч турмаги қилиш, массажга бориш ва косметик муолажалар қилиш, ўзини чиройли муҳит билан ўраш (идишлар, чойшаблар, безак ва бошқалар), севимлилар билан қучоқлашиш, ўзига дам беришга имкон бериш, ерга боғланиш, чиройли фильмлар кўриш, хушбўй шамлар сотиб олиш керак;","от самопознания, духовной практики, медитации, передачи знания, изучения астрологии, нумерологии, хиромантии, аюрведы, эзотерики, священных писаний, от самоанализа и саморазвития, ведения дневника, времени наедине с собой, нахождения на природе, занятия йогой;":"ўзини англаш, маънавий амалиёт, медитация, билимларни етказиш, астрология, нумерология, хиромантия, аюрведа, эзотерика, муқаддас битикларни ўрганишдан, ўзини таҳлил қилиш ва ўз-ўзини ривожлантиришдан, кундалик юритишдан, ўзи билан ёлғиз вақтдан, табиатда бўлишдан, йога билан шуғулланишдан;","от работы: человек работает и от этого получает удовлетворение, от успеха в карьере, статусности. От удовлетворения базовых потребностей, отсутствие долгов, наличия финансовой подушки безопасности, обустройства жилья, когда есть стабильность и защищенность, от взаимодействия с землей и природными материалами. Благоприятны родовые практики;":"ишдан: инсон ишлайди ва бундан қониқиш олади, карьерадаги муваффақиятдан, мавқедан. Асосий эҳтиёжларни қондиришдан, қарзларнинг йўқлигидан, молиявий хавфсизлик ёстиғининг мавжудлигидан, уй-жойни жиҳозлашдан, барқарорлик ва ҳимояланганлик бўлганда, ер ва табиий материаллар билан ўзаро таъсирдан. Уруғ амалиётлари қулай;","от эмоций, экстрима, от активной деятельности (где вырабатывается адреналин в крови). Хороши такие занятия как готовка, организация чего-либо, танцы, физические упражнения, творчество руками, активное общение, где есть обмен эмоциями.":"ҳис-туйғулардан, экстримдан, фаол фаолиятдан (қонда адреналин ишлаб чиқариладиган). Овқат пишириш, ниманидир ташкил этиш, рақслар, жисмоний машқлар, қўл билан ижод, ҳис-туйғулар алмашинуви бўладиган фаол мулоқот каби машғулотлар яхши.","Кармическая задача.":"Кармик вазифа.","цель жизни человека.":"инсон ҳаётининг мақсади.","Специфической задачи нет, в любой непонятной ситуации один путь – духовная практика.":"Ўзига хос вазифа йўқ, ҳар қандай тушунарсиз вазиятда битта йўл — маънавий амалиёт.","Задача в себе культивировать самодостаточность и независимость, необходима работа со своим эго, избавление от гордости. Заявлять о себе миру;":"Вазифа — ўзида ўзига етарлилик ва мустақилликни тарбиялаш, ўз эго билан ишлаш, ғурурдан қутулиш зарур. Дунёга ўзи ҳақида эълон қилиш;","Цель жизни – отношения, нужно уважать мать, учиться заботиться о других, находится в состоянии гармонии;":"Ҳаёт мақсади — муносабатлар, онани ҳурмат қилиш, бошқаларга ғамхўрлик қилишни ўрганиш, уйғунлик ҳолатида бўлиш керак;","Это дети, расширение, обретение радости в жизни, необходимо учить других, брать ответственность за других;":"Бу фарзандлар, кенгайиш, ҳаётда қувонч топиш, бошқаларни ўргатиш, бошқалар учун масъулиятни олиш зарур;","Нужно привести жизнь в баланс, обязательна йога и духовная практика, обрести стабильность;":"Ҳаётни мувозанатга келтириш керак, йога ва маънавий амалиёт шарт, барқарорликка эришиш;","Обретение знания, учиться, развивать интеллект, путешествовать, работа со словом, речью;":"Билим орттириш, ўқиш, интеллектни ривожлантириш, саёҳат қилиш, сўз, нутқ билан ишлаш;","Это наслаждение, блаженство, счастье, восторг, творчество, отношения. Т.е. у человека есть всё, кроме 6, таким образом, ему нужно культивировать 6;":"Бу лаззат, саодат, бахт, завқ, ижод, муносабатлар. Яъни инсонда 6 дан бошқа ҳамма нарса бор, шу тарзда унга 6 ни ривожлантириш керак;","Развитие мудрости, йога, духовная практика;":"Доноликни ривожлантириш, йога, маънавий амалиёт;","Это работать, работать и работать, но работать на других или для других, в отличии от 1, где работа над собой;":"Бу ишлаш, ишлаш ва яна ишлаш, лекин ўз устида иш бўлган 1 дан фарқли равишда, бошқаларда ёки бошқалар учун ишлаш;","Любовь.":"Муҳаббат.","нужно работать над этой областью, ноль говорит о наличии трудностей в области любви, когда сложно завести долгие отношения или чувствуется недостаток в любви, но также он дает благословение на духовную любовь, поэтому важно учиться отношениям и выражать любовь: проходить различные курсы на эту тему, читать литературу, изучать психологию и ценности отношений;":"бу соҳа устида ишлаш керак, ноль муҳаббат соҳасида қийинчиликлар мавжудлигини, узоқ муносабатлар қуриш қийин ёки муҳаббат етишмаслиги ҳис қилинишини айтади, лекин у маънавий муҳаббатга ҳам дуо беради, шунинг учун муносабатларни ўрганиш ва муҳаббатни ифода этиш муҳим: бу мавзуда турли курслардан ўтиш, адабиёт ўқиш, муносабатлар психологияси ва қадриятларини ўрганиш;","человек может быть эгоистичен или одинок в любви, ему хочется быть номером один, и он не всегда идет на уступки, при этом он может выбирать лидера, хотя может проявляться и соперничество, для хороших отношений необходимо сначала полюбить себя, а также думать и заботится о своем партнере;":"инсон муҳаббатда худбин ёки ёлғиз бўлиши мумкин, у биринчи рақам бўлишни истайди ва доим ҳам ён бермайди, бунда у етакчини танлаши мумкин, гарчи рақобат ҳам намоён бўлиши мумкин бўлса ҳам, яхши муносабатлар учун аввал ўзини севиш, шунингдек шериги ҳақида ўйлаш ва ғамхўрлик қилиш зарур;","двойственность в отношениях: с одной стороны, стремление к любви, а с другой – неуверенность в партнере и поиск другого, даже в мыслях. Есть какое-то непостоянство и неопределенность, запутанность. Могут быть излишне заботливыми, забывая о своих потребностях, либо если в каких-то отношениях обожглись, то убегают от отношений. Также человек может воспитывать чужих детей. Потребность в отношениях - это поиск покровителя в стиле родительской любви;":"муносабатларда иккиланиш: бир томондан, муҳаббатга интилиш, бошқа томондан — шерикка ишончсизлик ва бошқасини излаш, ҳатто фикрларда ҳам. Қандайдир беқарорлик ва ноаниқлик, чалкашлик бор. Ўз эҳтиёжларини унутиб, ҳаддан ташқари ғамхўр бўлиши, ёки қандайдир муносабатларда куйган бўлса, муносабатлардан қочиши мумкин. Шунингдек инсон бировнинг фарзандларини тарбиялаши мумкин. Муносабатларга эҳтиёж — бу ота-она муҳаббати услубида ҳомий излаш;","благословение, заботливая любовь, где важно постоянство, семейность, радость и материальные блага;":"дуо, ғамхўр муҳаббат, унда доимийлик, оилавийлик, қувонч ва моддий неъматлар муҳим;","странная любовь, много вожделения, не могут насытиться, а с другой стороны, бывают очень стабильные и практичные отношения, где в паре мало чувств и близости, но очень хорошо в материальном плане; также могут быть духовные отношения: люди находятся на одной волне, хорошо друг друга понимают, имеют общую цель личного развития, умеют чувствовать друг друга;":"ғалати муҳаббат, кўп шаҳват, тўя олмайди, бошқа томондан эса, жуфтликда ҳис ва яқинлик кам, лекин моддий жиҳатдан жуда яхши бўлган жуда барқарор ва амалий муносабатлар бўлади; шунингдек маънавий муносабатлар бўлиши мумкин: одамлар бир тўлқинда, бир-бирини яхши тушунади, шахсий ривожланишнинг умумий мақсадига эга, бир-бирини ҳис қила олади;","интеллектуальная любовь (на уровне бесед и интереса; важно, чтобы человек был на одной волне), свобода в любви (человек не терпит каких-то уз, которые ограничивают его свободу);":"интеллектуал муҳаббат (суҳбатлар ва қизиқиш даражасида; инсоннинг бир тўлқинда бўлиши муҳим), муҳаббатдаги эркинлик (инсон унинг эркинлигини чеклайдиган қандайдир ришталарга тоқат қилмайди);","романтика и чувственность в любви, важны сексуальные отношения, трепетность, внешняя идиллия;":"муҳаббатда романтика ва ҳиссиётлилик, жинсий муносабатлар, ҳаяжон, ташқи идиллия муҳим;","стабильные отношения на уровне мистической духовной любви (как будто с прошлой жизни), либо связь только на уровне тела, холодность и неприступность;":"мистик маънавий муҳаббат даражасидаги барқарор муносабатлар (гўё ўтган ҳаётдан), ёки фақат тана даражасидаги алоқа, совуқлик ва яқинлаштирмаслик;","серьезный подход, важно доверие, рациональность и практичность. В отношениях могут казаться безэмоциональными, у них любовь проявляется в виде поступков и реальных дел, в плюсе - это крепкая пара.":"жиддий ёндашув, ишонч, рационаллик ва амалийлик муҳим. Муносабатларда ҳиссиз туюлиши мумкин, уларда муҳаббат қилмишлар ва ҳақиқий ишлар кўринишида намоён бўлади, плюсда — бу мустаҳкам жуфтлик.","Деньги.":"Пул.","как приходят деньги, через какую область, какая планета на это влияет.":"пул қандай, қайси соҳа орқали келади, бунга қайси сайёра таъсир қилади.","Хорошие деньги вы обычно зарабатываете самостоятельно. Великолепный вариант — открытие собственного бизнеса.":"Яхши пулни одатда мустақил топасиз. Ажойиб вариант — ўз бизнесингизни очиш.","Какие таланты вам помогут вырасти в доходах?":"Қайси истеъдодлар даромадларда ўсишингизга ёрдам беради?","Лидерство, инициативность, независимость, новаторство":"Етакчилик, ташаббускорлик, мустақиллик, новаторлик","Человек может занимать должности, связанные с государством и органами власти. Подходят все профессий, связанные с менеджментом, управлением;":"Инсон давлат ва ҳокимият органлари билан боғлиқ лавозимларни эгаллаши мумкин. Менежмент, бошқарув билан боғлиқ барча касблар мос келади;","Символизирует совместное управление финансами. Это значит, что хорошего заработка вам можно достичь через сотрудничество с другими людьми.":"Молияни биргаликда бошқаришни англатади. Бу яхши даромадга бошқа одамлар билан ҳамкорлик орқали эришиш мумкинлигини билдиради.","Сотрудничество, дипломатичность, художественный вкус, обаятельность, служение другим (помогать, наставлять, спасать, воспитывать, отдавать, лечить, учить). Хороша работа с женщинами":"Ҳамкорлик, дипломатлик, бадиий дид, жозиба, бошқаларга хизмат қилиш (ёрдам бериш, йўл кўрсатиш, қутқариш, тарбиялаш, бериш, даволаш, ўргатиш). Аёллар билан ишлаш яхши","Считается одним из денежных чисел. Ваша задача в совершенстве познать финансовые инструменты, научится вести бюджет, ставить финансовые цели и инвестировать. Остерегайтесь бездумных трат и жадности.":"Пул сонларидан бири ҳисобланади. Сизнинг вазифангиз — молиявий воситаларни мукаммал билиш, бюджет юритиш, молиявий мақсадлар қўйиш ва сармоя киритишни ўрганиш. Ўйламасдан сарфлаш ва очкўзликдан эҳтиёт бўлинг.","Дар слова, креативность, оптимизм, умение вдохновлять других":"Сўз иқтидори, креативлик, оптимизм, бошқаларни илҳомлантира олиш","Хорошие сферы деятельности это: дети, образование, финансы;":"Яхши фаолият соҳалари: болалар, таълим, молия;","Позволяет своему обладателю обрести финансовую стабильность. Вы умеете правильно распоряжаться заработанным, разумно вкладывать деньги и экономить. Но не забывайте иногда потратить лишнее на себя. Может быть нестабильность: то периоды богатства, то – нехватка денег, но это только когда вы сами не занимаетесь формированием своей финансовой устойчивости.":"Эгасига молиявий барқарорликка эришишга имкон беради. Сиз топилганни тўғри тасарруф этишни, пулни оқилона киритишни ва тежашни биласиз. Лекин баъзан ўзингизга ортиқча сарфлашни унутманг. Беқарорлик бўлиши мумкин: гоҳ бойлик даврлари, гоҳ пул етишмаслиги, лекин бу фақат ўзингиз молиявий барқарорлигингизни шакллантириш билан шуғулланмаганингизда.","Стабильность, структурность, методичность, дисциплинированность Подходит сфера эзотерики;":"Барқарорлик, тузилмалилик, услубийлик, интизомлилик. Эзотерика соҳаси мос келади;","Самое нестабильное число богатства. Периоды финансовых взлётов неизменно чередуются с падениями. Ситуацию можно изменить, если научиться правильно распоряжаться имеющимся: перед тем, как тратить или вкладывать куда-то крупную сумму, просчитайте все риски, подумайте, действительно ли это вам нужно, какую выгоду эта сделка может принести. Избегайте кутежа, необдуманных трат, грамотно расставляйте приоритеты, обдумывайте, что можно купить прямо сейчас, а что — подождёт.":"Бойликнинг энг беқарор сони. Молиявий кўтарилиш даврлари ўзгармас равишда тушишлар билан алмашади. Агар бор нарсани тўғри тасарруф этишни ўргансангиз, вазиятни ўзгартириш мумкин: катта суммани сарфлаш ёки қаергадир киритишдан олдин барча хавфларни ҳисобланг, бу сизга ҳақиқатан керакми, бу битим қандай фойда келтириши мумкинлигини ўйланг. Айш-ишрат, ўйламасдан сарфлашдан сақланинг, устуворликларни тўғри белгиланг, ҳозир нима сотиб олиш мумкин, нима эса — кутиши мумкинлигини ўйланг.","Какие таланты вам помогут вырасти в доходах? Коммуникабельность, гибкость, адаптация, активность, любознательность Деньги приходят через знания, есть потенциал создать много источников дохода":"Қайси истеъдодлар даромадларда ўсишингизга ёрдам беради? Киришимлилик, мослашувчанлик, мослашиш, фаоллик, қизиқувчанлик. Пул билимлар орқали келади, кўплаб даромад манбаларини яратиш салоҳияти бор","Вам можно смело тратить крупные суммы для обеспечения всем необходимым тем, кто вам дорог, но не забывайте и о себе. Также у вас есть «денежная интуиция», которая всегда будет подсказывать, как лучше распорядиться имеющимися финансами и где можно удачно подзаработать.":"Сизга азиз бўлганларни керакли ҳамма нарса билан таъминлаш учун катта суммаларни бемалол сарфлашингиз мумкин, лекин ўзингизни ҳам унутманг. Шунингдек сизда бор молияни қандай яхшироқ тасарруф этиш ва қаерда омадли қўшимча пул топиш мумкинлигини доим айтиб турадиган «пул интуицияси» бор.","Чувство стиля и цвета, забота о других, доброе сердце, романтичность":"Услуб ва ранг ҳисси, бошқаларга ғамхўрлик, меҳрибон юрак, романтиклик","Ориентир на сферы роскоши, творчества, красоты, женщин,отношения мужчины и женщины;":"Ҳашамат, ижод, гўзаллик, аёллар, эркак ва аёл муносабатлари соҳаларига йўналиш;","Семерка не материальное число, вы как будто не от мира сего, а с другой планеты. Чтобы приходили деньги нужно обязательно ставить цели, сколько нужно и особенно на что пойдут эти деньги.":"Еттилик моддий сон эмас, сиз гўё бу дунёдан эмас, бошқа сайёрадансиз. Пул келиши учун албатта мақсадлар қўйиш керак, қанча керак ва айниқса бу пул нимага кетади.","Какие таланты вам помогут вырасти в доходах? Страсть к поиску знаний и фактов, наблюдательность, проницательность, экспертность Это число связано с духовностью, поэтому деньги могут приходить через духовность, преподавание духовности, передачу знаний, область психологии, эзотерики, йоги, передача мудрости другим. Также деньги могут приходить мистическим образом, например, нашли деньги, либо кто-то дал, пожертвовал.":"Қайси истеъдодлар даромадларда ўсишингизга ёрдам беради? Билим ва фактларни излашга эҳтирос, кузатувчанлик, зийраклик, экспертлик. Бу сон маънавият билан боғлиқ, шунинг учун пул маънавият, маънавиятни ўқитиш, билим етказиш, психология, эзотерика, йога соҳаси, доноликни бошқаларга етказиш орқали келиши мумкин. Шунингдек пул мистик тарзда, масалан, пул топиб олиш ёки кимдир берган, ҳадя қилган тарзда келиши мумкин.","Число богатства. Начертание цифры 8 напоминает по своей форме бесконечность. Стоит активно вкладывать деньги в собственное развитие, обучение, личные интересы, иногда потребуется время — однако результат вас порадует, Вселенная обязательно отблагодарит вас за личностный рост хорошей наградой.":"Бойлик сони. 8 рақамининг ёзилиши шакли бўйича чексизликни эслатади. Пулни ўз ривожланишингиз, ўқиш, шахсий қизиқишларга фаол киритиш керак, баъзан вақт керак бўлади — лекин натижа сизни қувонтиради, Коинот шахсий ўсиш учун сизга албатта яхши мукофот билан миннатдорлик билдиради.","Какие таланты вам помогут вырасти в доходах? Эффективность, выдержка, масштабное видение, организаторские способности Возможны ограничение в деньгах, но если хорошо работать создавать систему постуступления денег и не зацикливаться на них, то на жизнь будет хватать достаточно, т.к. Сатурн награждает щедро за труд;":"Қайси истеъдодлар даромадларда ўсишингизга ёрдам беради? Самарадорлик, бардош, кенг кўламли қараш, ташкилотчилик қобилиятлари. Пулда чекловлар бўлиши мумкин, лекин агар яхши ишласангиз, пул тушиш тизимини яратсангиз ва унга қотиб қолмасангиз, ҳаётга етарлича етади, чунки Сатурн меҳнат учун саховат билан мукофотлайди;","Деньги предназначены для благотворительности и создания лучшего мира. Деньгами нужно распоряжаться мудро, т.к. вы можете то сорить деньгами, то наоборот вообще не на что не тратить.":"Пул хайрия ва яхшироқ дунё яратиш учун мўлжалланган. Пулни доно тасарруф этиш керак, чунки сиз гоҳ пулни сочишингиз, гоҳ аксинча умуман ҳеч нарсага сарфламаслигингиз мумкин.","Сострадание, мудрость, чувство вкуса, глобальное видение":"Ҳамдардлик, донолик, дид ҳисси, глобал қараш","Деньги приходят энергичным способом через спорт, сферу социальной активности, через лидерскую природу (например, организацию чего-либо).":"Пул ғайратли усул билан — спорт, ижтимоий фаоллик соҳаси, етакчилик табиати (масалан, ниманидир ташкил этиш) орқали келади.","Заботливость, внимательность.":"Ғамхўрлик, эътиборлилик.","на сколько человек заботливый и внимательный по отношению к остальным, но также проявление этого и к нему.":"инсон бошқаларга нисбатан қанчалик ғамхўр ва эътиборли, шунингдек буларнинг унга нисбатан намоён бўлиши.","неумение строить отношения и проявлять заботу, сдержанность, человек не любит готовить и кормить других, либо человек готов помогать другим, но забывает о себе, такое самопожертвование, он готов на все ради других;":"муносабатлар қура олмаслик ва ғамхўрлик кўрсата олмаслик, вазминлик, инсон овқат пиширишни ва бошқаларни боқишни ёқтирмайди, ёки инсон бошқаларга ёрдам беришга тайёр, лекин ўзини унутади, шундай фидойилик, у бошқалар учун ҳамма нарсага тайёр;","человек может чувствовать одиночество, может быть трудности в общении со старшими мужчинами, для него важно учится устанавливать контакт с людьми, отказываться от гордыни и чрезмерного эгоизма, либо от своей неуверенности в себе и не перекладывать ответственность;":"инсон ёлғизликни ҳис қилиши мумкин, катта эркаклар билан мулоқотда қийинчиликлар бўлиши мумкин, унга одамлар билан алоқа ўрнатишни ўрганиш, кибр ва ҳаддан ташқари худбинликдан, ёки ўзига ишончсизликдан воз кечиш ва масъулиятни юкламаслик муҳим;","нехватка заботы и дефицит внимания, элемент одиночества. Всегда где бы ни появлялся 0, это означает духовную практику. Если забота 0, то через духовную практику вы ощутите заботу, заботу Бога на себе. Таким образом, можно это гармонизировать;":"ғамхўрлик етишмаслиги ва эътибор танқислиги, ёлғизлик элементи. 0 қаерда пайдо бўлмасин, доим бу маънавий амалиётни англатади. Агар ғамхўрлик 0 бўлса, маънавий амалиёт орқали ғамхўрликни, Худонинг ғамхўрлигини ўзингизда ҳис қиласиз. Шу тарзда буни уйғунлаштириш мумкин;","ни о ком не заботятся и не чувствуют заботу от других (1 – Солнце само в себе);":"ҳеч кимга ғамхўрлик қилмайди ва бошқалардан ғамхўрлик ҳис қилмайди (1 — Қуёш ўз-ўзида);","много заботы, поддержки получает человек, и также сам готов поддержать и помогать другому, выслушать его; любит принимать гостей;":"инсон кўп ғамхўрлик, қўллаб-қувватлаш олади, шунингдек ўзи ҳам бошқани қўллаб-қувватлаш ва ёрдам беришга, уни тинглашга тайёр; меҳмон кутишни яхши кўради;","человек – наставник, в зависимости от гуны либо он или его вдохновляют, либо он или на него давят;":"инсон — устоз, гунага қараб ё у илҳомлантиради ёки уни илҳомлантиришади, ё у босим ўтказади ёки унга босим ўтказишади;","очень странная забота, она как бы и есть, но её не почувствуешь, тоже самое в отношении их;":"жуда ғалати ғамхўрлик, у гўё бор, лекин уни ҳис қилмайсан, уларга нисбатан ҳам худди шундай;","человек не привязан к людям, для него на первом месте будут стоять другие вещи (например, его развитие), поэтому есть рассеянность и малое проявление заботы в отношении к другим людям, сам он свободолюбивый человек;":"инсон одамларга боғланмаган, у учун биринчи ўринда бошқа нарсалар (масалан, унинг ривожланиши) туради, шунинг учун бошқа одамларга нисбатан паришонлик ва ғамхўрликнинг кам намоён бўлиши бор, ўзи эркинликни севувчи инсон;","очень внимательная забота, ласка, трепетность, в минусе могут “задушить” заботой":"жуда эътиборли ғамхўрлик, эркалаш, ҳаяжон, минусда ғамхўрлик билан «бўғиши» мумкин","Возможности.":"Имкониятлар.","Возможности в жизни или возможности кармы. Сфера возможностей, куда применить способности.":"Ҳаётдаги имкониятлар ёки карма имкониятлари. Қобилиятларни қаерда қўллаш мумкинлиги — имкониятлар соҳаси.","человек сам кузнец своего счастья, он сам отвечает за все события в своей жизни. Важна публичность и проявление, нельзя быть в тени. Можно состоять в сообществах, где много единомышленников, либо создать свой клуб по интересам, участвовать в проектах, направленных на социальную деятельность, активно продвигаться в социальных сетях: показывать себя миру, проводить прямые эфиры, прокачивать свой профессионализм;":"инсон ўз бахтининг темирчиси, у ўз ҳаётидаги барча воқеалар учун ўзи жавоб беради. Оммавийлик ва намоён бўлиш муҳим, сояда бўлиш мумкин эмас. Кўплаб ҳамфикрлар бор жамоаларда бўлиш ёки ўз қизиқишлар клубини яратиш, ижтимоий фаолиятга йўналтирилган лойиҳаларда қатнашиш, ижтимоий тармоқларда фаол ривожланиш мумкин: ўзини дунёга кўрсатиш, жонли эфирлар ўтказиш, профессионаллигини ошириш;","возможности приходят через отношения; когда можно помогать и поддерживать других, создавать совместные проекты, сотрудничать с другими, особенно это касается женщин; стоит развивать доверие к людям, к миру и Богу, творчески подходить к любому делу;":"имкониятлар муносабатлар орқали келади; бошқаларга ёрдам бериш ва қўллаб-қувватлаш, биргаликдаги лойиҳалар яратиш, бошқалар, айниқса аёллар билан ҳамкорлик қилиш мумкин бўлганда; одамларга, дунёга ва Худога ишончни ривожлантириш, ҳар қандай ишга ижодий ёндашиш керак;","очень много возможностей, когда человек расширяет свои сферы жизни; главное, не быть в болоте, не допускать застоя. Особенно важно расширять такие сферы как образование, финансы, духовное развития;":"инсон ҳаёт соҳаларини кенгайтирганда жуда кўп имкониятлар; асосийси — ботқоқда бўлмаслик, турғунликка йўл қўймаслик. Айниқса таълим, молия, маънавий ривожланиш каби соҳаларни кенгайтириш муҳим;","возможности приходят через йогу, эзотерику и духовный путь, через поиск себя, самопознание и саморазвитие. А также когда вы осуществляете самые смелые мечты, используя свой ум. Плюс все, что связано с иностранным (путешествия, работа, учеба, семья), также дает вам дополнительные возможности;":"имкониятлар йога, эзотерика ва маънавий йўл орқали, ўзини излаш, ўзини англаш ва ўз-ўзини ривожлантириш орқали келади. Шунингдек ақлингиздан фойдаланиб, энг жасур орзуларни амалга оширганингизда. Бундан ташқари, чет эл билан боғлиқ ҳамма нарса (саёҳатлар, иш, ўқиш, оила) ҳам сизга қўшимча имкониятлар беради;","возможности приобретаются из общения, когда много контактов, много позитивных знакомств, когда есть обучение и передача знаний, есть путешествия, поездки, туры с единомышленниками;":"имкониятлар мулоқотдан, алоқалар кўп, ижобий танишувлар кўп бўлганда, ўқиш ва билим етказиш бўлганда, ҳамфикрлар билан саёҳатлар, сафарлар, турлар бўлганда орттирилади;","возможности приходят от женщин, от отношений, красоты, роскоши, творчества. Главное, остерегайтесь искушений - привязанность к чувственным желаниям;":"имкониятлар аёллардан, муносабатлардан, гўзаллик, ҳашамат, ижоддан келади. Асосийси, васвасалардан — ҳиссий истакларга боғланишдан эҳтиёт бўлинг;","возможности приходят через йогу, эзотерику и духовный путь, через поиск себя, саморефлексию и анализ. Рекомендовано посещать психолога или коуча, чтобы в уме разложить все по полочкам, убрать комплексы;":"имкониятлар йога, эзотерика ва маънавий йўл орқали, ўзини излаш, ўзини мушоҳада қилиш ва таҳлил орқали келади. Ақлда ҳаммасини жой-жойига қўйиш, комплексларни олиб ташлаш учун психолог ёки коучга бориш тавсия этилади;","есть ограничения в возможностях, которые убираются через труд, ответственность, упорство и дисциплину. Важно понимать: все, что в вашей жизни происходит - это опыт, который дает внутреннюю трансформацию и мудрость. Чаще задавайте себе вопрос: а что судьба хочет от меня? Старайтесь больше улыбаться и расслабляться. Эзотерические знания помогут глубже понять себя и дать объяснение событиям жизни;":"имкониятларда чекловлар бор, улар меҳнат, масъулият, қатъият ва интизом орқали олиб ташланади. Тушуниш муҳим: ҳаётингизда бўлаётган ҳамма нарса — ички трансформация ва донолик берадиган тажриба. Ўзингизга тез-тез савол беринг: тақдир мендан нима истайди? Кўпроқ жилмайишга ва бўшашишга ҳаракат қилинг. Эзотерик билимлар ўзингизни чуқурроқ тушунишга ва ҳаёт воқеаларига изоҳ беришга ёрдам беради;","возможности приходят, когда вы реализовываете смелые цели и мечты, проявляете бесстрашие, силу воли, защищаете себя и других. Когда есть настрой на победу, доведение дел до результата, твердость и проявление лидерских качеств. Чем больше вы вкладываете свою энергию во что-то, тем больше у вас будет возможностей. Это дает постоянное улучшение качества жизни и достижение новых высот, не замечая преград на своем пути.":"имкониятлар жасур мақсад ва орзуларни амалга оширганингизда, қўрқмаслик, ирода кучини намоён қилганингизда, ўзингизни ва бошқаларни ҳимоя қилганингизда келади. Ғалабага кайфият, ишларни натижага етказиш, қатъийлик ва етакчилик фазилатларининг намоён бўлиши бўлганда. Энергиянгизни нимагадир қанчалик кўп киритсангиз, имкониятларингиз шунчалик кўп бўлади. Бу йўлингиздаги тўсиқларни пайқамай, ҳаёт сифатининг доимий яхшиланиши ва янги чўққиларга эришишни беради.","Мировоззрение.":"Дунёқараш.","это образ мышления, как человек будет смотреть на мир.":"бу фикрлаш тарзи, инсон дунёга қандай қарайди.","западная нумерология трактует 0 в положительном качестве как совершенство, то есть человек с таким мировоззрением должен смотреть на мир через духовное совершенство, он знает, что все единое и целое, он видит суть. Но другая крайность 0 – это когда нет мировоззрения у человека, то есть он может быть ведомым, необходимо заниматься духовной практикой, чтобы получить совершенное мировоззрение;":"ғарб нумерологияси 0 ни ижобий сифатда мукаммаллик сифатида талқин қилади, яъни бундай дунёқарашли инсон дунёга маънавий мукаммаллик орқали қараши керак, у ҳамма нарса ягона ва яхлит эканини билади, моҳиятни кўради. Лекин 0 нинг бошқа ҳаддан ошиши — инсонда дунёқараш йўқлиги, яъни у эргашувчи бўлиши мумкин, мукаммал дунёқарашга эга бўлиш учун маънавий амалиёт билан шуғулланиш зарур;","нужно быть лидером, чего-то достигать, стать первым и лучшим, заявлять о себе;":"етакчи бўлиш, нимагадир эришиш, биринчи ва энг яхши бўлиш, ўзи ҳақида эълон қилиш керак;","все должно быть гармонично, все должны находиться в отношениях и дружбе, важна романтика, взаимодействие с природой;":"ҳамма нарса уйғун бўлиши керак, ҳамма муносабатлар ва дўстликда бўлиши керак, романтика, табиат билан ўзаро таъсир муҳим;","призма мудрости, философии, денежного мышления, радости;":"донолик, фалсафа, пул фикрлаши, қувонч призмаси;","человеку нравится работать с подсознанием, он увлечен эзотерикой и психологией, нетрадиционными способами самопознания, а также духовными практиками, понимает, что в мире есть что-то большее, чем материальное существование; в гуне невежества - человек погружен в иллюзии, держится за свои страхи, тяга к шоу-бизнесу и хайпу;":"инсонга онг ости билан ишлаш ёқади, у эзотерика ва психология, ўзини англашнинг ноанъанавий усуллари, шунингдек маънавий амалиётларга берилган, дунёда моддий мавжудликдан каттароқ нимадир борлигини тушунади; жаҳолат гунасида — инсон иллюзияларга ботган, қўрқувларига ёпишади, шоу-бизнес ва хайпга интилиш;","человек сфокусирован на своем развитие, желании познать все, ему важна свобода и разнообразие;":"инсон ўз ривожланишига, ҳаммасини билиш истагига эътибор қаратган, унга эркинлик ва хилма-хиллик муҳим;","человек ориентирован на творческое развитие, на получение удовольствий от жизни, на важность отношений;":"инсон ижодий ривожланишга, ҳаётдан завқ олишга, муносабатларнинг муҳимлигига йўналган;","либо взгляд духовного человека и мудреца - отшельника, и здесь глубина познаний, приверженность к старым традициям (прошлому), закрытость, либо в невежестве желание уйти от реальности посредством алкоголя/наркотиков;":"ё маънавий инсон ва донишманд-зоҳиднинг қараши, бу ерда билимлар чуқурлиги, эски анъаналарга (ўтмишга) содиқлик, ёпиқлик, ё жаҳолатда алкоголь/гиёҳвандлик орқали ҳақиқатдан кетиш истаги;","практический склад ума: нужно трудиться, работать, служить другим, быть ответственным и дисциплинированным.":"амалий ақл: меҳнат қилиш, ишлаш, бошқаларга хизмат қилиш, масъулиятли ва интизомли бўлиш керак.","п январь":"т январь","ЯНВАРЬ:":"ЯНВАРЬ:","п февраль":"т февраль","Февраль":"Февраль","ФЕВРАЛЬ:":"ФЕВРАЛЬ:","п март":"т март","Март":"Март","МАРТ:":"МАРТ:","п апрель":"т апрель","Апрель":"Апрель","АПРЕЛЬ:":"АПРЕЛЬ:","п май":"т май","Май":"Май","МАЙ:":"МАЙ:","п июнь":"т июнь","Июнь":"Июнь","ИЮНЬ:":"ИЮНЬ:","п июль":"т июль","ИЮЛЬ:":"ИЮЛЬ:","п август":"т август","Август":"Август","АВГУСТ:":"АВГУСТ:","п сентябрь":"т сентябрь","Сентябрь":"Сентябрь","СЕНТЯБРЬ:":"СЕНТЯБРЬ:","п октябрь":"т октябрь","Октябрь":"Октябрь","ОКТЯБРЬ:":"ОКТЯБРЬ:","п ноябрь":"т ноябрь","Ноябрь":"Ноябрь","НОЯБРЬ:":"НОЯБРЬ:","п декабрь":"т декабрь","Декабрь":"Декабрь","ДЕКАБРЬ:":"ДЕКАБРЬ:","Значение месяца:":"Ойнинг маъноси:","Месяц активных действий, осуществления планов, можно начинать что-то новое: работу, дружбу, увлечение; нужно подчеркивать свою индивидуальность; в этот месяц придётся рассчитывать на себя.":"Фаол ҳаракатлар, режаларни амалга ошириш ойи, янги нарса: иш, дўстлик, қизиқишни бошлаш мумкин; ўз индивидуаллигингизни таъкидлаш керак; бу ойда ўзингизга таянишга тўғри келади.","Нужно не позволять эмоциям выходить из под контроля, хорошо общаться, заботиться, больше времени проводить с семьёй.":"Ҳис-туйғуларнинг назоратдан чиқишига йўл қўймаслик, яхши мулоқот қилиш, ғамхўрлик қилиш, оила билан кўпроқ вақт ўтказиш керак.","Можно изучать что-то или обучать кого-то, заниматься бизнесом, больше проводить время с детьми, устраивать праздники.":"Ниманидир ўрганиш ёки кимнидир ўргатиш, бизнес билан шуғулланиш, болалар билан кўпроқ вақт ўтказиш, байрамлар уюштириш мумкин.","Благоприятный месяц для духовной практики, поездок за границу, хорошо начинать или продолжать здоровый образ жизни в любом качестве.":"Маънавий амалиёт, чет элга сафарлар учун қулай ой, ҳар қандай сифатда соғлом турмуш тарзини бошлаш ёки давом эттириш яхши.","Хороший месяц для новых возможностей или перемен, путешествий, поездок, знакомств, изучения чего-либо, но нужно избегать хаоса и суетливости.":"Янги имкониятлар ёки ўзгаришлар, саёҳатлар, сафарлар, танишувлар, ниманидир ўрганиш учун яхши ой, лекин хаос ва ғимирлашдан сақланиш керак.","Хорошо заниматься домашними делами, творчеством, прекрасным, посвящать себя больше любви и отношениям.":"Уй ишлари, ижод, гўзаллик билан шуғулланиш, ўзини кўпроқ муҳаббат ва муносабатларга бағишлаш яхши.","Месяц даёт возможность уединения, погружения в самоанализ, лучше не нагружать себя работой, а всё же изучать сложные предметы, эзотерику.":"Ой ёлғизлик, ўзини таҳлил қилишга шўнғиш имкониятини беради, ўзингизни иш билан юкламаган яхшироқ, лекин барибир мураккаб фанлар, эзотерикани ўрганинг.","Нужно действовать организованно и эффективно, брать дополнительную ответственность, служение.":"Уюшқоқ ва самарали ҳаракат қилиш, қўшимча масъулият олиш, хизмат қилиш керак.","Активность, спорт, достижение целей, нужно избегать вспыльчивости.":"Фаоллик, спорт, мақсадларга эришиш, жаҳлдорликдан сақланиш керак.","Число дживы:":"Джива сони:","Активные, целеустремленные личности; у них уникальная точка зрения, они умеют защищать и аргументировать свою позицию; они коммуникабельны, легко знакомятся с людьми; требовательны к другим и выстраивают свои границы; к критике относятся тяжело; активисты и передовики; любят новшество и экстрим. В работе ценят эффективность; легко строят карьеру, без личностного роста испытывают апатию, подавленность, неудовлетворенность. Они лидеры в отношениях; независимы. Их девиз: «Сам, в одиночку, за собой!»":"Фаол, мақсадга интилувчан шахслар; уларда ноёб нуқтаи назар бор, улар ўз позициясини ҳимоя қилиш ва асослашни билади; киришимли, одамлар билан осон танишади; бошқаларга талабчан ва ўз чегараларини қуради; танқидга оғир муносабатда бўлади; фаоллар ва илғорлар; янгилик ва экстримни яхши кўради. Ишда самарадорликни қадрлайди; карьерани осон қуради, шахсий ўсишсиз бефарқлик, тушкунлик, қониқмасликни бошдан кечиради. Улар муносабатларда етакчи; мустақил. Уларнинг шиори: «Ўзим, ёлғиз, ўзим учун!»","Творческий характер: врожденные художники, романтики, внимательные к деталям. Слабые стороны: нерешительность, высокая потребность в поддержке из-за внешнего мира, так как зависимы от мнения родственников или друзей. Люди часто бывают слишком эмоциональными, в то же время они очень доброжелательны и готовы помочь ближнему. Их девиз: «Второй, за кем-то, подстраиваюсь!»":"Ижодий характер: туғма рассомлар, романтиклар, тафсилотларга эътиборли. Заиф томонлари: қатъиятсизлик, ташқи дунё туфайли қўллаб-қувватлашга юқори эҳтиёж, чунки қариндошлар ёки дўстларнинг фикрига боғлиқ. Одамлар кўпинча ҳаддан ташқари ҳиссиётли бўлади, айни пайтда улар жуда хайрихоҳ ва яқинига ёрдам беришга тайёр. Уларнинг шиори: «Иккинчи, кимнингдир ортидан, мослашаман!»","Сильные духом, энергичные, коммуникабельные, с активной жизненной позицией и уверенностью в своей правоте; у них хорошее чувство юмора; они всегда чем-то заняты, любят обучать и обучаться. Хорошее творческое самовыражение, им сопутствует удача и благосостояние. Их девиз: «Расширяю, забочусь о младших, самовыражаюсь!»":"Руҳан кучли, ғайратли, киришимли, фаол ҳаётий позиция ва ўз ҳақлигига ишонч билан; уларда яхши юмор ҳисси бор; улар доим нима биландир банд, ўргатишни ва ўрганишни яхши кўради. Яхши ижодий ўзини ифода этиш, уларга омад ва фаровонлик ҳамроҳ. Уларнинг шиори: «Кенгайтираман, кичикларга ғамхўрлик қиламан, ўзимни ифода этаман!»","В положительной сфере эти люди дисциплинированы, методичны, усердны, надежны и продуктивны. В негативе проявляется лень, саморазрушение, склонность к зависимостям, страхи. У них много желаний. Таким людям нравится эзотерика, иностранные земли. Могут быть хорошими художниками, но у них бунтарский нрав, и они могу переходить из крайности в крайность. Их девиз: «Необычность!»":"Ижобий соҳада бу одамлар интизомли, услубий, тиришқоқ, ишончли ва самарали. Салбийда дангасалик, ўз-ўзини вайрон қилиш, қарамликларга мойиллик, қўрқувлар намоён бўлади. Уларда истаклар кўп. Бундай одамларга эзотерика, чет юртлар ёқади. Яхши рассом бўлиши мумкин, лекин уларда исёнкор феъл бор ва улар бир ҳаддан бошқасига ўтиши мумкин. Уларнинг шиори: «Ғайриоддийлик!»","Изменчиизменчивый характер. Сообразительные и интеллектуальные, азартные, гибкие, в то же время ранимые и чувствительные люди. Они очень коммуникабельны, душа компании, оптимистичны, ценят деловые качества и отношения; опыт и знания эффективнее всего набирают в путешествиях. Знают все, но неглубоко. Любят зарабатывать деньги; они хорошие торговцы и ораторы, у них вся жизнь как игра. Их девиз: «Играю, стремительно думаю и делаю!»":"Ўзгарувчан характер. Зийрак ва интеллектуал, завқли, мослашувчан, айни пайтда озор топувчан ва сезгир одамлар. Улар жуда киришимли, даврабоши, оптимистик, ишбилармонлик фазилатлари ва муносабатларни қадрлайди; тажриба ва билимларни саёҳатларда энг самарали тўплайди. Ҳаммасини билади, лекин чуқур эмас. Пул топишни яхши кўради; улар яхши савдогар ва нотиқлар, уларнинг бутун ҳаёти ўйиндек. Уларнинг шиори: «Ўйнайман, тез ўйлайман ва қиламан!»","Утонченность и артистизм. Такие люди любят быть в центре внимания и жить в комфорте, имеют изысканный вкус: красота и наслаждения идут вперед. Также им важны отношения, творчество, семья, обучение и воспитание. Их девиз: «Роскошь и красота!»":"Нафислик ва артистизм. Бундай одамлар диққат марказида бўлишни ва қулайликда яшашни яхши кўради, нафис дидга эга: гўзаллик ва лаззатлар олдинда боради. Шунингдек уларга муносабатлар, ижод, оила, ўқиш ва тарбия муҳим. Уларнинг шиори: «Ҳашамат ва гўзаллик!»","Мудрые, обладающие экстрасенсорными способностями, проницательные. Они занимаются самопознанием, часто бывают непредсказуемы; у них развита отрешенность, им нравится уединение; они достигают высокого духовного уровня, либо могут пойти на дно общества – есть такая крайность. Они свято верят в свою правоту, и это мешает им в жизни. Их девиз: «Изучаю и постигаю жизнь!»":"Доно, экстрасенсор қобилиятларга эга, зийрак. Улар ўзини англаш билан шуғулланади, кўпинча олдиндан айтиб бўлмайди; уларда дунёдан узоқлашиш ривожланган, уларга ёлғизлик ёқади; улар юксак маънавий даражага етади ёки жамият тубига тушиши мумкин — шундай ҳаддан ошиш бор. Улар ўз ҳақлигига муқаддас ишонади ва бу уларга ҳаётда халақит беради. Уларнинг шиори: «Ҳаётни ўрганаман ва англайман!»","Ответственны, верны долгу или обещанию; они качественно выполняют работу, трудолюбивы и усердны; могут создать свой бизнес. События у них в жизни происходят медленно для того, чтобы они развивали терпение. Их девиз: «Ответственность и трудолюбие!»":"Масъулиятли, бурч ёки ваъдага содиқ; ишни сифатли бажаради, меҳнатсевар ва тиришқоқ; ўз бизнесини яратиши мумкин. Уларнинг ҳаётида воқеалар сабр ривожлантиришлари учун секин юз беради. Уларнинг шиори: «Масъулият ва меҳнатсеварлик!»","Импульсивны и решительны, по духу это спортсмены. Они независимы и обладают силой воли; у них есть склонность к риску. В негативе они проявляют сильный гнев. Их девиз: «Достижение к цели и сила!»":"Импульсив ва қатъиятли, руҳан спортчилар. Улар мустақил ва ирода кучига эга; уларда таваккалга мойиллик бор. Салбийда улар кучли ғазаб кўрсатади. Уларнинг шиори: «Мақсадга эришиш ва куч!»","число дхармы":"дхарма сони","Человек должен стать лидером, научиться брать инициативу. Солнце всем озаряет путь – необходимо взять ответственность за все, что в жизни происходит. Это означает, что никто не виноват в том, что происходит в его жизни; нельзя винить и жаловаться: человек – венец творения. Обязательно нужно обращать внимание на время, ценить его, делать стоящие дела каждый день. Решить проблему с эгоизмом, в этом две крайности: либо неуверенность, либо самоуверенность. Необходимо научиться поддерживать хорошие отношения с отцом и с мужским миром в целом, иначе могут быть проблемы в личной жизни. ПРИЗВАНИЕ человека с числом 1 - служить как ЛИДЕР и раскрывать лидерские качества":"Инсон етакчи бўлиши, ташаббусни олишни ўрганиши керак. Қуёш ҳаммага йўлни ёритади — ҳаётда бўлаётган ҳамма нарса учун масъулиятни олиш зарур. Бу унинг ҳаётида бўлаётган нарсада ҳеч ким айбдор эмаслигини англатади; айблаш ва шикоят қилиш мумкин эмас: инсон — яратилишнинг тожи. Вақтга албатта эътибор бериш, уни қадрлаш, ҳар куни арзийдиган ишлар қилиш керак. Худбинлик муаммосини ҳал қилиш, бунда икки ҳаддан ошиш бор: ё ишончсизлик, ё ўзига ортиқча ишониш. Ота ва умуман эркаклар дунёси билан яхши муносабатларни сақлашни ўрганиш зарур, акс ҳолда шахсий ҳаётда муаммолар бўлиши мумкин. 1 сонли инсоннинг ДАЪВАТИ — ЕТАКЧИ сифатида хизмат қилиш ва етакчилик фазилатларини очиш","Служить как лидер - значит, учитывать интересы других при достижении своих целей, не причинять неудобство, стремиться к взаимодействию и сотрудничеству. Если ваше число дхармы – единица, но вы до сих пор не ощущаете себя лидером, нужно проанализировать ситуацию. Что мешает вам достигать целей и вести за собой людей?":"Етакчи сифатида хизмат қилиш — ўз мақсадларига эришишда бошқаларнинг манфаатларини ҳисобга олиш, ноқулайлик туғдирмаслик, ўзаро таъсир ва ҳамкорликка интилишни англатади. Агар дхарма сонингиз — бир бўлса, лекин сиз ҳалигача ўзингизни етакчи сифатида ҳис қилмасангиз, вазиятни таҳлил қилиш керак. Мақсадларга эришишингизга ва одамларни ортингиздан эргаштиришингизга нима халақит беради?","Для человека задача создать гармоничные отношения, а также заботиться о других. Для женщин нужно развивать женские и материнские качества, обязательно выйти замуж; если же она уйдет в карьеру, то будут очень сильные беспокойства. Для мужчин необходимо развить уважение ко всем женщинам. Для всех требуется развивать хорошие отношения с матерью. Очень важно держать ум в балансе: изучать психологию, знать психологические программы, как они устроены в человеке, т.е. стать психологом в первую очередь для себя. ГЛАВНЫЙ ПРИНЦИП: Используйте в работе свою природную способность чувствовать, сочувствовать, откликаться на эмоции других людей, умение позаботиться, накормить и защитить, создать атмосферу уюта.":"Инсон учун вазифа — уйғун муносабатлар яратиш, шунингдек бошқаларга ғамхўрлик қилиш. Аёллар учун аёллик ва оналик фазилатларини ривожлантириш, албатта турмушга чиқиш керак; агар у карьерага кетса, жуда кучли хавотирлар бўлади. Эркаклар учун барча аёлларга ҳурматни ривожлантириш зарур. Ҳамма учун она билан яхши муносабатларни ривожлантириш талаб этилади. Ақлни мувозанатда сақлаш жуда муҳим: психологияни ўрганиш, психологик дастурларни, улар инсонда қандай тузилганини билиш, яъни аввало ўзи учун психолог бўлиш. АСОСИЙ ТАМОЙИЛ: Ишда ўзингизнинг ҳис қилиш, ҳамдард бўлиш, бошқа одамларнинг ҳис-туйғуларига жавоб бериш табиий қобилиятингиздан, ғамхўрлик қилиш, боқиш ва ҳимоя қилиш, қулайлик муҳитини яратиш маҳоратингиздан фойдаланинг.","Человеку нужно учить людей, делиться своими знаниями, опытом, навыками. Он должен быть наставником: принимать и давать советы. Этому человеку необходимо постоянно двигаться вперед, расширяться. Юпитер отвечает за детей, поэтому нужно проявлять внимание детям. Здесь же важно взять на себя организацию семейной жизни, проявлять инициативу, обязательно быть честным. Нужно обрести стабильность, надежность в материальной сфере, достичь финансового благополучия. ГЛАВНЫЕ ПРИНЦИПЫ:":"Инсонга одамларни ўргатиш, билимлари, тажрибаси, кўникмалари билан бўлишиш керак. У устоз бўлиши керак: маслаҳатларни қабул қилиши ва бериши. Бу инсонга доим олдинга ҳаракатланиш, кенгайиш зарур. Юпитер фарзандлар учун жавоб беради, шунинг учун фарзандларга эътибор кўрсатиш керак. Бу ерда оилавий ҳаётни ташкил этишни ўз зиммасига олиш, ташаббус кўрсатиш, албатта ҳалол бўлиш муҳим. Моддий соҳада барқарорлик, ишончлиликка эришиш, молиявий фаровонликка етиш керак. АСОСИЙ ТАМОЙИЛЛАР:","Используйте в работе все свои знания, мудрость. То есть все то, чему вы обучались не должны быть пассивным грузом, это нужно использовать, как минимум для повышения качества своей жизни, как максимум для помощи людям. Не учитесь «просто так». Используйте принцип расширения в профессии. То есть если чувствуете, что где то уперлись в потолок, ищите возможности «видеть шире». Расширить сеть территориально, расширить ассортимент услуг, товаров, изменить концепцию, ориентироваться на работу с другими людьми. Т.е всегда старайтесь выходить за рамки узкого круга.":"Ишда барча билимларингиз, донолигингиздан фойдаланинг. Яъни ўрганган ҳамма нарсангиз пассив юк бўлмаслиги керак, ундан камида ҳаёт сифатингизни ошириш учун, кўпи билан одамларга ёрдам бериш учун фойдаланиш керак. «Шунчаки» ўқиманг. Касбда кенгайиш тамойилидан фойдаланинг. Яъни қаердадир шифтга тақалганингизни ҳис қилсангиз, «кенгроқ кўриш» имкониятларини изланг. Тармоқни ҳудудий кенгайтириш, хизматлар, товарлар ассортиментини кенгайтириш, концепцияни ўзгартириш, бошқа одамлар билан ишлашга йўналиш. Яъни доим тор доирадан чиқишга ҳаракат қилинг.","Жизнь человека должна быть чистой; важен контакт с природой; минимум искусственных вещей, иначе будет возобладать иллюзия: Раху может очень сильно тянуть вниз. Такому человеку обязательно нужно заниматься познанием жизни через духовность, йогу, тонкие законы мира. Это не вопрос «хочу или не хочу», а вопрос жизни и смерти. Перед ним стоит задача – быть стабильным и планировать свою жизнь, развить и реализовать себя, проработав все страхи. Люди с числом ПРИЗВАНИЯ 4 прекрасно находят себя в амбициозных и новаторских компаниях, занимаются новыми технологиями, изобретениями.Они заботятся об экологии, бережно относятся ко всему живому, привлекают внимание к глобальным объектам, и именно в этом их ждет развитие. Также их жизнь может быть связанна с чем-то иностранным (знания, работа, дом, семья)":"Инсоннинг ҳаёти тоза бўлиши керак; табиат билан алоқа муҳим; сунъий нарсалар минимал, акс ҳолда иллюзия устун келади: Раҳу жуда кучли пастга тортиши мумкин. Бундай инсонга албатта ҳаётни маънавият, йога, дунёнинг нозик қонунлари орқали англаш билан шуғулланиш керак. Бу «хоҳлайманми ё йўқми» масаласи эмас, балки ҳаёт ва мамот масаласи. Унинг олдида вазифа турибди — барқарор бўлиш ва ҳаётини режалаштириш, барча қўрқувларни ишлаб чиқиб, ўзини ривожлантириш ва рўёбга чиқариш. ДАЪВАТ сони 4 бўлган одамлар шуҳратпараст ва новатор компанияларда ўзини ажойиб топади, янги технологиялар, ихтиролар билан шуғулланади. Улар экология ҳақида ғамхўрлик қилади, барча тирик мавжудотларга эҳтиёткор муносабатда бўлади, глобал объектларга эътибор жалб қилади ва айнан шунда уларни ривожланиш кутади. Шунингдек уларнинг ҳаёти чет эл билан (билимлар, иш, уй, оила) боғлиқ бўлиши мумкин","Нужно развивать знания, необходимо приобретать новые способности и раскрывать новые возможности. Человек познает жизнь, мир и свободу, поэтому обязательно нужно учиться самоорганизации и ответственности. Для него свобода приобретается через знания – важно избегать хаоса в жизни, а развивать внимательность и концентрацию, учиться коммуникабельности и давать образование другим. Ему нравится познавать жизнь и мир вокруг, тянет к переменам и ко всему новому. Прекрасная речь, коммуникабельность и хорошее чувство юмора - помогают вести переговоры, налаживать связи, заниматься продажами, рекламой и передавать свой опыт и знания другим. У таких людей сильно развиты логика, интеллект и аналитическое мышление. Они обладают хорошей памятью и математическими способностями. Поэтому могут найти и раскрыть свой потенциал в эзотерике, например, астрологии или нумерологии":"Билимларни ривожлантириш, янги қобилиятлар орттириш ва янги имкониятларни очиш зарур. Инсон ҳаётни, дунёни ва эркинликни англайди, шунинг учун албатта ўзини ташкил қилиш ва масъулиятни ўрганиш керак. У учун эркинлик билимлар орқали орттирилади — ҳаётда хаосдан қочиш, эътиборлилик ва диққатни жамлашни ривожлантириш, киришимлиликни ўрганиш ва бошқаларга таълим бериш муҳим. Унга ҳаётни ва атрофдаги дунёни англаш ёқади, ўзгаришларга ва барча янги нарсаларга интилади. Ажойиб нутқ, киришимлилик ва яхши юмор ҳисси музокаралар олиб боришга, алоқалар ўрнатишга, савдо, реклама билан шуғулланишга ва тажриба ва билимларини бошқаларга етказишга ёрдам беради. Бундай одамларда мантиқ, интеллект ва таҳлилий фикрлаш кучли ривожланган. Улар яхши хотира ва математик қобилиятларга эга. Шунинг учун салоҳиятини эзотерикада, масалан, астрология ёки нумерологияда топиши ва очиши мумкин","Нужно учиться создавать вокруг себя пространство прекрасного, любви и красоты. Хорошо применять творческие способности, обрести верность в отношениях, внутреннюю чистоту. Необходимо научиться контролю секса, а также регулировать стремление к наслаждениям, т.к. у человека могут быть желания с чувством пере-: переедание, пересыпание и пр. Мужчинам важно научиться уважать женщин. Главная задача людей с числом призвания 6 - чувствовать и создавать красоту в разных сферах –стиль, прически, одежда, украшения, духи, цветы, красивый интерьер, уют и чистота в доме, гармония и красота на работе, реализация себя в творчестве":"Атрофида гўзаллик, муҳаббат ва чиройлилик маконини яратишни ўрганиш керак. Ижодий қобилиятларни қўллаш, муносабатларда садоқат, ички софликка эришиш яхши. Жинсий назоратни ўрганиш, шунингдек лаззатларга интилишни тартибга солиш зарур, чунки инсонда ортиқча ҳис билан истаклар бўлиши мумкин: ортиқча овқатланиш, ортиқча ухлаш ва бошқалар. Эркакларга аёлларни ҳурмат қилишни ўрганиш муҳим. Даъват сони 6 бўлган одамларнинг асосий вазифаси — турли соҳаларда гўзалликни ҳис қилиш ва яратиш — услуб, соч турмаклари, кийим, безаклар, атирлар, гуллар, чиройли интерьер, уйда қулайлик ва тозалик, ишда уйғунлик ва гўзаллик, ўзини ижодда рўёбга чиқариш","Это число отвечают за все непонятное, невидимое и окутанное тайной. В жизни это проявляется через мудрость прошлого опыта, поэтому такой человек всегда стремится к трансформации сознания. Его задача обрести мудрость через опыт, а опыт приходит именно через изменение своего состояния. Для такого числа обязателен путь духовности, йоги, развитии интуиции – максимальная концентрация развития на этом. Человек в этой жизни решает, с Богом он или нет. Этого человека может интересовать наука за пределами материального. Также важно проработать комплексы, проводить самоанализ. Обычно такие люди хотят познать себя и выбирают путь йоги, эзотерики, психологии, развивают интуицию, идут по пути духовности к философскому пониманию жизни, меняют себя и свой характер, иногда это приводит их к отречению от мира":"Бу сон барча тушунарсиз, кўринмас ва сир билан ўралган нарсалар учун жавоб беради. Ҳаётда бу ўтмиш тажрибасининг донолиги орқали намоён бўлади, шунинг учун бундай инсон доим онг трансформациясига интилади. Унинг вазифаси — тажриба орқали донолик орттириш, тажриба эса айнан ўз ҳолатини ўзгартириш орқали келади. Бундай сон учун маънавият, йога, интуицияни ривожлантириш йўли шарт — ривожланишни максимал шунга жамлаш. Инсон бу ҳаётда у Худо биланми ё йўқми ҳал қилади. Бу инсонни моддийдан ташқаридаги фан қизиқтириши мумкин. Шунингдек комплексларни ишлаб чиқиш, ўзини таҳлил қилиш муҳим. Одатда бундай одамлар ўзини англашни истайди ва йога, эзотерика, психология йўлини танлайди, интуицияни ривожлантиради, ҳаётни фалсафий тушунишга маънавият йўлидан боради, ўзини ва характерини ўзгартиради, баъзан бу уларни дунёдан воз кечишга олиб келади","Человеку нужно трудиться, причем работа может быть без вознаграждения, вернее, вознаграждение будет большим, но позже. Т. е. человеку важно трудиться ради процесса. Он должен научиться контролировать себя, быть скромным, дисциплинированным, ответственным, исполнительным и развивать терпение. Такому человеку нужно уважать традиции и все старинное. У таких людей талант в систематизации, они терпеливы, дисциплинированны и обладают отличными исполнительными и организаторскими способностями. Люди с числом 8 хорошо понимают причинно-следственные связи и законы кармы. Они знают, что определенные поступки всегда приводят к каким-то последствиям. ПРИЗВАНИЕ ЧИСЛА 8 - это талант в систематизации и создании структуры во всех сферах жизни. Поэтому таким людям важно соблюдать дисциплину в отношениях и в работе, искать баланс между работой и отдыхом – уметь расслабляться. 8ка – масштабное число. У них получается воплощать в жизнь даже сложные проекты, выжимать максимум из своих ресурсов. Их главные принципы жизни: эффективность, статусность, масштабность. Им нужно прорабатывать страхи и ограничивающие привычки. Это можно сделать через медитации, психологию, индивидуальный коучинг и эзотерику. Это помогает им увидеть возможности, которые они могут реализовать в своей жизни. Главное для них рекомендация - ценить все, то что им удалось сделать.":"Инсонга меҳнат қилиш керак, бунда иш мукофотсиз бўлиши мумкин, тўғрироғи, мукофот катта бўлади, лекин кейинроқ. Яъни инсонга жараён учун меҳнат қилиш муҳим. У ўзини назорат қилишни, камтар, интизомли, масъулиятли, ижрочи бўлишни ўрганиши ва сабрни ривожлантириши керак. Бундай инсонга анъаналар ва барча қадимий нарсаларни ҳурмат қилиш керак. Бундай одамларда тизимлаштириш истеъдоди бор, улар сабрли, интизомли ва ажойиб ижрочилик ва ташкилотчилик қобилиятларига эга. 8 сонли одамлар сабаб-оқибат боғланишлари ва карма қонунларини яхши тушунади. Улар маълум қилмишлар доим қандайдир оқибатларга олиб келишини билади. 8 СОНИНИНГ ДАЪВАТИ — ҳаётнинг барча соҳаларида тизимлаштириш ва тузилма яратиш истеъдоди. Шунинг учун бундай одамларга муносабатларда ва ишда интизомга риоя қилиш, иш ва дам олиш ўртасида мувозанат излаш — бўшаша олиш муҳим. 8 — кенг кўламли сон. Улар ҳатто мураккаб лойиҳаларни ҳам ҳаётга татбиқ этишни, ресурсларидан максимумни олишни уддалайди. Уларнинг асосий ҳаёт тамойиллари: самарадорлик, мавқе, кенг кўламлилик. Уларга қўрқувлар ва чекловчи одатларни ишлаб чиқиш керак. Буни медитациялар, психология, индивидуал коучинг ва эзотерика орқали қилиш мумкин. Бу уларга ҳаётида амалга ошириши мумкин бўлган имкониятларни кўришга ёрдам беради. Улар учун асосий тавсия — қилишга муяссар бўлган ҳамма нарсани қадрлаш.","Человеку нужно развивать силу воли, целеустремленность, смелость и храбрость; защищать тех, кто не может за себя постоять; следить за соблюдением законов. Им обязательно нужно выбрасывать свою энергию в спорт или в творчество, т.к. если эту огненную энергию не направить в положительное русло, то она может разрушить все, наподобие взрыва. Поэтому можно направить на различные идеи, на спорт, на учебы, на общественные мероприятия – необходимо увеличивать темп жизни. Для мужчин необходимо устанавливать нормативы и рекорды, т.е. побеждать самого себя. Они всегда отстаивают свои личные границы, защищают тех, кто не может за себя постоять, следят за соблюдением закона.Это лидеры и хорошие организаторы, они легко ведут за собой других, склонны к героическим поступкам, хотят побеждать и выигрывать. ГЛАВНЫЙ ПРИНЦИП: Используйте в работе свою смелость, инициативность, свою внутреннюю, либо физическую силу, настойчивость, отстаивайте свои права. Продвигайте свои идеи, инициативы, начинания. Будьте «быстрее, выше, сильнее».":"Инсонга ирода кучи, мақсадга интилувчанлик, жасорат ва мардликни ривожлантириш; ўзини ҳимоя қила олмайдиганларни ҳимоя қилиш; қонунларга риоя этилишини кузатиш керак. Уларга энергияни албатта спорт ёки ижодга чиқариш керак, чунки агар бу оловли энергия ижобий ўзанга йўналтирилмаса, у портлашдек ҳамма нарсани вайрон қилиши мумкин. Шунинг учун турли ғоялар, спорт, ўқиш, ижтимоий тадбирларга йўналтириш мумкин — ҳаёт суръатини ошириш зарур. Эркаклар учун меъёрлар ва рекордлар ўрнатиш, яъни ўзини енгиш зарур. Улар доим шахсий чегараларини ҳимоя қилади, ўзини ҳимоя қила олмайдиганларни ҳимоя қилади, қонунга риоя этилишини кузатади. Булар етакчилар ва яхши ташкилотчилар, бошқаларни осон ортидан эргаштиради, қаҳрамонона қилмишларга мойил, ғалаба қозонишни ва ютишни истайди. АСОСИЙ ТАМОЙИЛ: Ишда жасоратингиз, ташаббускорлигингиз, ички ёки жисмоний кучингиз, қатъиятингиздан фойдаланинг, ҳуқуқларингизни ҳимоя қилинг. Ғояларингиз, ташаббусларингиз, бошланган ишларингизни илгари суринг. «Тезроқ, баландроқ, кучлироқ» бўлинг.","число кармы":"карма сони","Обстоятельства в жизни человека будут направлены на тестирование его эго. Такой человек будет воспринимать события очень лично, все через призму своего эгоизма. Часто он будет воспринимать это как то, что его эго будет подвержено унижению и оскорблению, поэтому могут быть обиды. Но на самом деле задача кармы направлена на то, чтобы воспитать его эго. Также такому человеку нужно учиться отношениям.":"Инсон ҳаётидаги ҳолатлар унинг эгосини синашга йўналтирилган бўлади. Бундай инсон воқеаларни жуда шахсий, ҳаммасини худбинлиги призмаси орқали қабул қилади. Кўпинча у буни эгоси камситиш ва ҳақоратга учраётгандек қабул қилади, шунинг учун хафаликлар бўлиши мумкин. Лекин аслида карманинг вазифаси унинг эгосини тарбиялашга йўналтирилган. Шунингдек бундай инсонга муносабатларни ўрганиш керак.","У людей Солнца будет стремление к славе и известности, они будут занимать положение в обществе, и их будут многие знать. Они будут отстаивать свою позицию: не склонны к компромиссам, хотят, чтобы все крутилось вокруг них.":"Қуёш одамларида шуҳрат ва машҳурликка интилиш бўлади, улар жамиятда мавқе эгаллайди ва уларни кўпчилик билади. Улар ўз позициясини ҳимоя қилади: муросага мойил эмас, ҳамма нарса уларнинг атрофида айланишини истайди.","Обстоятельства жизни могут делать их одинокими, так как они сами будут сжигать все вокруг них, как Солнце. Хотя такие люди хотят светить всем, командовать и управлять, но сами будут чувствовать себя одинокими. Это хорошо для карьеры и для того, чтобы быть начальником.":"Ҳаёт ҳолатлари уларни ёлғиз қилиши мумкин, чунки улар Қуёшдек атрофдаги ҳамма нарсани ўзлари куйдиради. Гарчи бундай одамлар ҳаммага нур сочиш, буйруқ бериш ва бошқаришни истаса ҳам, ўзлари ёлғиз ҳис қилади. Бу карьера ва бошлиқ бўлиш учун яхши.","Вся жизнь будет строиться на отношениях. Так как два раза в месяц природа Луны меняется, поэтому в жизни этого человека будут двойственные ситуации: то взлеты, то падения; то неопределенности, то какие-то ситуации неизвестности. Поэтому на протяжении всей жизни будет острая необходимость выбирать, что и как сделать. Всегда будет выбор, но такому человеку необходимо принять решение, а это тяжело. Поэтому появляется стрессовое состояние, но задача его в том, чтобы научиться принимать решения.":"Бутун ҳаёт муносабатларга қурилади. Ойнинг табиати ойда икки марта ўзгаргани учун бу инсоннинг ҳаётида иккиёқлама вазиятлар бўлади: гоҳ кўтарилишлар, гоҳ тушишлар; гоҳ ноаниқликлар, гоҳ қандайдир номаълумлик вазиятлари. Шунинг учун бутун ҳаёт давомида нимани ва қандай қилишни танлаш ўткир зарурати бўлади. Доим танлов бўлади, лекин бундай инсонга қарор қабул қилиш зарур, бу эса оғир. Шунинг учун стресс ҳолати пайдо бўлади, лекин унинг вазифаси — қарор қабул қилишни ўрганиш.","С одной стороны, эти люди постоянно стремятся к стабильности в семье, но с другой – и к новым отношениям. Обстоятельства жизни складываются так, что они зависят от кого-либо или чего-либо: если никого рядом нет, то чувствуют себя плохо. Женщина ощущает себя незащищенной, а мужчина обвиняет близких, чтобы защитить себя.":"Бир томондан, бу одамлар доим оилада барқарорликка, бошқа томондан — янги муносабатларга ҳам интилади. Ҳаёт ҳолатлари шундай кечадики, улар кимгадир ёки нимагадир боғлиқ бўлади: ёнида ҳеч ким бўлмаса, ўзини ёмон ҳис қилади. Аёл ўзини ҳимоясиз ҳис қилади, эркак эса ўзини ҳимоя қилиш учун яқинларини айблайди.","Для таких людей важны вопросы материнства: у женщин могут быть проблемы с детьми и матерью, у мужчин – в отношениях с матерью в первую очередь. Все эти отношения нужно налаживать.":"Бундай одамлар учун оналик масалалари муҳим: аёлларда фарзандлар ва она билан муаммолар, эркакларда — аввало она билан муносабатларда бўлиши мумкин. Бу муносабатларнинг барчасини созлаш керак.","Они хорошие психологи, чувствуют переживания других, и к ним все время будут идти за помощью.":"Улар яхши психологлар, бошқаларнинг кечинмаларини ҳис қилади ва уларга доим ёрдам сўраб келишади.","Важные события будут происходить вокруг детей: либо у пары не будет детей, либо их будет слишком много, либо проблемы будут у самих детей. Обстоятельства будут складываться так, что такой человек будет учиться сам или учить других. Даже женщина может быть наставником для мужа, он будет советоваться у нее. Эти люди будут постоянно расширять круг знакомых, друзей. У них всегда будут деньги, и это может быть проблемой, так как все будут просить их. Такой человек все время расширяется и двигается вперед. Он решает проблемы, поэтому может быть много ответственности. Юпитер – это Гуру, который помогает другим.Человек может занимать видное положение в жизни: это может быть и бизнес, и наука, и обучение, и наставничество. Могут приходить ситуации, когда на нем будет лежать ответственность за других людей, – это самые лучшие обстоятельства для него. Кроме того, у таких людей будет много направлений деятельности, даже что-то могут делать параллельно. Важно, что если у людей с этим числом кармы что-то связано с Богом, то это будет играть существенную роль в жизни.":"Муҳим воқеалар фарзандлар атрофида юз беради: ё жуфтликда фарзанд бўлмайди, ё улар жуда кўп бўлади, ё фарзандларнинг ўзида муаммолар бўлади. Ҳолатлар шундай кечадики, бундай инсон ўзи ўқийди ёки бошқаларни ўргатади. Ҳатто аёл ҳам эри учун устоз бўлиши мумкин, у ундан маслаҳат сўрайди. Бу одамлар доим танишлар, дўстлар доирасини кенгайтиради. Уларда доим пул бўлади, бу муаммо бўлиши мумкин, чунки ҳамма улардан сўрайди. Бундай инсон доим кенгаяди ва олдинга ҳаракатланади. У муаммоларни ҳал қилади, шунинг учун масъулият кўп бўлиши мумкин. Юпитер — бошқаларга ёрдам берадиган Гуру. Инсон ҳаётда кўзга кўринган мавқе эгаллаши мумкин: бу бизнес ҳам, фан ҳам, ўқитиш ҳам, устозлик ҳам бўлиши мумкин. Унинг зиммасида бошқа одамлар учун масъулият бўладиган вазиятлар келиши мумкин — бу у учун энг яхши ҳолатлар. Бундан ташқари, бундай одамларда кўплаб фаолият йўналишлари бўлади, ҳатто нимадир параллел қилиши мумкин. Муҳими, агар бу карма сонига эга одамларда нимадир Худо билан боғлиқ бўлса, бу ҳаётда муҳим роль ўйнайди.","События и обстоятельства жизни складываются нелогично и как-то необычно. Поэтому нужно учиться принимать ситуации, хотя могут быть и ситуации, которые сложно понять, но их цель, чтобы встряхнуть и избавить человека от иллюзии. Такому человеку нельзя бунтовать. Ему необходимо обязательно прорабатывать страхи.":"Ҳаёт воқеалари ва ҳолатлари номантиқий ва қандайдир ғайриоддий кечади. Шунинг учун вазиятларни қабул қилишни ўрганиш керак, гарчи тушуниш қийин бўлган вазиятлар ҳам бўлиши мумкин бўлса ҳам, лекин уларнинг мақсади — инсонни силкитиш ва иллюзиядан халос қилиш. Бундай инсонга исён қилиш мумкин эмас. Унга албатта қўрқувларни ишлаб чиқиш зарур.","Также в любом случае должна быть духовная практика: это даст стабильность в жизни. Если ее не будет, то события могут породить отчаяние., разочарование в людях, либо склонность к какой-либо зависимости.":"Шунингдек ҳар қандай ҳолатда маънавий амалиёт бўлиши керак: бу ҳаётда барқарорлик беради. Агар у бўлмаса, воқеалар умидсизлик, одамлардан ҳафсаласизлик ёки қандайдир қарамликка мойиллик туғдириши мумкин.","Жизнь складывается так, что все зависит от этих людей, они должны стать самостоятельными. Те проблемы, которые возникают в жизни, нужно решать самим.":"Ҳаёт шундай кечадики, ҳамма нарса бу одамларга боғлиқ, улар мустақил бўлиши керак. Ҳаётда пайдо бўладиган муаммоларни ўзлари ҳал қилиши керак.","Это число очень хорошо для бизнеса, обучения, политической деятельности.В жизни всего будет много: и работы, и деятельности, зачастую и несколько семей, детей.":"Бу сон бизнес, ўқитиш, сиёсий фаолият учун жуда яхши. Ҳаётда ҳамма нарса кўп бўлади: иш ҳам, фаолият ҳам, кўпинча бир нечта оила, фарзандлар ҳам.","Они обязательно в жизни столкнутся с тем, что будут учить других. У таких людей много связей, много движения в жизни, им сложно быть на одном месте. Часто и много меняют в своей жизни, в том числе и профессии. В целом вся их жизнь полна перемен.":"Улар ҳаётда албатта бошқаларни ўргатишга дуч келади. Бундай одамларда алоқалар кўп, ҳаётда ҳаракат кўп, уларга бир жойда бўлиш қийин. Ҳаётида кўпинча ва кўп нарсани, жумладан касбларни ҳам ўзгартиради. Умуман уларнинг бутун ҳаёти ўзгаришларга тўла.","Вся жизнь посвящена поиску богатства, роскоши, наслаждений и отношений. Такие люди привлекательны, стремятся к комфорту, часто ведут активную светскую жизнь. Они любят следить за своим телом: диеты, косметологи, фитнес и т.д. Эти люди хотят долго жить. Их привлекает искусство, музыка, красота, творчество. Они хорошо находят контакт с людьми. Но им необходимо научиться контролировать свои чувства. Очень важный аспект жизни – отдых и развлечения.":"Бутун ҳаёт бойлик, ҳашамат, лаззатлар ва муносабатларни излашга бағишланган. Бундай одамлар жозибали, қулайликка интилади, кўпинча фаол дунёвий ҳаёт кечиради. Улар танасини кузатишни яхши кўради: парҳезлар, косметологлар, фитнес ва ҳ.к. Бу одамлар узоқ яшашни истайди. Уларни санъат, мусиқа, гўзаллик, ижод жалб қилади. Одамлар билан алоқани яхши топади. Лекин уларга ҳисларини назорат қилишни ўрганиш зарур. Ҳаётнинг жуда муҳим жиҳати — дам олиш ва кўнгилочар машғулотлар.","Очень много непредсказуемых и непонятных событий по меркам современного мира: Кету – таинственная планета. Цель жизни – осознание жизни и культивирование непривязанности к ней. Такие люди обладают сильной интуицией, часто снятся вещие сны. Им нужно заниматься йогой, общаться с мудрецами. Им нужна духовная жизнь, чтобы прогрессировать, иначе эта склонность к мистицизму может привести их к низшим гунам.":"Замонавий дунё ўлчовлари бўйича жуда кўп олдиндан айтиб бўлмайдиган ва тушунарсиз воқеалар: Кету — сирли сайёра. Ҳаёт мақсади — ҳаётни англаш ва унга боғланмасликни ривожлантириш. Бундай одамлар кучли интуицияга эга, кўпинча ҳақиқий тушлар кўради. Уларга йога билан шуғулланиш, донишмандлар билан мулоқот қилиш керак. Ривожланиш учун уларга маънавий ҳаёт керак, акс ҳолда мистицизмга бу мойиллик уларни қуйи гуналарга олиб бориши мумкин.","Жизнь – это сплошной труд: тут и дисциплина, и работа, и ответственность, и надежность, и аскетизм, и терпение. Если этого нет, нужно обязательно развивать.":"Ҳаёт — бутунлай меҳнат: бу ерда интизом ҳам, иш ҳам, масъулият ҳам, ишончлилик ҳам, зоҳидлик ҳам, сабр ҳам. Агар бу бўлмаса, албатта ривожлантириш керак.","Проблемы могут быть и в отношениях, так как Сатурн не любит сантименты: он готов работать, что-то делать, но в отношениях несильно мягок. Сатурн – это стабильность, то есть у них либо стабильно хорошо, либо стабильно плохо. Этим людям нужно обязательно иметь резервы или деньги, как подушку безопасности. Очень медленно все происходит в жизни, особенно затягивается хорошее. Зачастую все размеренно и последовательно. Это нужно учесть и не гнаться за какими-то быстрыми переменами. Такие люди могу быть отличными бизнесменами, когда есть стратегия и план, а также по капельке в день они делают свое дело.":"Муаммолар муносабатларда ҳам бўлиши мумкин, чунки Сатурн сентиментларни ёқтирмайди: у ишлашга, нимадир қилишга тайёр, лекин муносабатларда унчалик юмшоқ эмас. Сатурн — бу барқарорлик, яъни уларда ё барқарор яхши, ё барқарор ёмон. Бу одамларга албатта хавфсизлик ёстиғи сифатида заҳиралар ёки пулга эга бўлиш керак. Ҳаётда ҳамма нарса жуда секин юз беради, айниқса яхшилик чўзилади. Кўпинча ҳаммаси бир маромда ва изчил. Буни ҳисобга олиш ва қандайдир тез ўзгаришлар ортидан қувмаслик керак. Бундай одамлар стратегия ва режа бўлганда, шунингдек кунига томчилаб ўз ишини қилганда ажойиб бизнесменлар бўлиши мумкин.","Очень сильная энергия. У таких людей активная, насыщенная, полная действий жизнь.":"Жуда кучли энергия. Бундай одамларда фаол, бой, ҳаракатларга тўла ҳаёт.","Однако в их жизни могут быть агрессия, аварии, операции, травмы. Это энергия Марса, если она чрезмерна, то нужно быть осторожными, т.к. может перерасти в негатив.":"Бироқ уларнинг ҳаётида тажовуз, авариялар, операциялар, жароҳатлар бўлиши мумкин. Бу Марс энергияси, агар у ҳаддан ташқари бўлса, эҳтиёт бўлиш керак, чунки салбийликка айланиши мумкин.","Успех в спорте, особенно борьбе. Любые боевые искусства для таких людей хороши.":"Спортда, айниқса курашда муваффақият. Бундай одамлар учун ҳар қандай жанг санъатлари яхши.","Есть артистические склонности, способности к танцам, искусству. Обязательно им нужно искать, куда же им можно выразить свою энергию. Могут быть экстремалами; у них эмоциональный характер. Это очень темпераментные люди. Зачастую это активисты, организаторы, могут быть военными; часто могут примкнуть к какому-то социальному движению: их тянет туда, где что-то происходит.":"Артистик майллар, рақс, санъатга қобилиятлар бор. Уларга энергиясини қаерга ифода этиш мумкинлигини албатта излаш керак. Экстремаллар бўлиши мумкин; уларда ҳиссиётли характер. Булар жуда темпераментли одамлар. Кўпинча булар фаоллар, ташкилотчилар, ҳарбий бўлиши мумкин; кўпинча қандайдир ижтимоий ҳаракатга қўшилиши мумкин: уларни нимадир бўлаётган жойга тортади.","Число проблем":"Муаммолар сони","старые значения:":"эски маънолар:","доп вопросы:":"қўшимча саволлар:","Солнце - планета, которая светит ВСЕМ, она яркая и привлекает к себе внимание. Задача человека с числом проблем 1 - обрести уверенность в себе, повысить самооценку и научиться заявлять о себе миру. Возможны две крайности: 1️) у такого человека: сниженная самооценка, неуверенность; нерешительность, сомнения, страхи; склонность откладывать дела \"на потом\"; стремление перекладывать ответственность на других и искать виноватых; 2️) такой человек: имеет неадекватно завышенную самооценку; горделив; не признаёт авторитетов; эгоистичен, не умеет просить помощи, зацикленность на себе. Человеку нужно правильно относиться к критике в свой адрес.":"Қуёш — ҲАММАГА нур сочадиган сайёра, у ёрқин ва эътиборни жалб қилади. Муаммолар сони 1 бўлган инсоннинг вазифаси — ўзига ишонч топиш, ўзини баҳолашни ошириш ва дунёга ўзи ҳақида эълон қилишни ўрганиш. Икки ҳаддан ошиш бўлиши мумкин: 1️) бундай инсонда: паст ўзини баҳолаш, ишончсизлик; қатъиятсизлик, шубҳалар, қўрқувлар; ишларни «кейинга» қолдиришга мойиллик; масъулиятни бошқаларга юклаш ва айбдорларни излашга интилиш; 2️) бундай инсон: адекват бўлмаган ошириб юборилган ўзини баҳолашга эга; мағрур; обрўларни тан олмайди; худбин, ёрдам сўрашни билмайди, ўзига қотиб қолган. Инсонга ўз манзилига қаратилган танқидга тўғри муносабатда бўлиш керак.","Солнце также является воплощением МУЖСКОГО начала.⠀Поэтому нужно проанализировать, как у вас складываются отношения с отцом, с тем, кто имеет к вам статус отца, правительством и мужчинами в целом. Нет ли в вас стремления доминировать, конкурировать с мужчинами, особенно в агрессивной форме? Все корни этих проблем произрастают из отношений с отцом. Прошлые обиды и травмы стоит прорабатывать с помощью психолога. Важно постараться максимально выровнять эти отношения.":"Қуёш шунингдек ЭРКАК бошланғичининг тимсоли ҳисобланади. Шунинг учун ота, сизга нисбатан ота мақомига эга бўлган киши, ҳукумат ва умуман эркаклар билан муносабатларингиз қандай кечаётганини таҳлил қилиш керак. Сизда ҳукмронлик қилиш, эркаклар билан, айниқса тажовузкор шаклда рақобатлашиш истаги йўқми? Бу муаммоларнинг барча илдизлари ота билан муносабатлардан ўсади. Ўтмишдаги хафаликлар ва жароҳатларни психолог ёрдамида ишлаб чиқиш керак. Бу муносабатларни максимал текислашга ҳаракат қилиш муҳим.","Женщинам с таким числом проблемы обязательно научиться уважать мужчин. Иначе они не смогут оказывать супругу должную поддержку, либо будут проявляться как демонстративно независимые, надменные, выдвигающие чересчур завышенные требования к партнеру, отчего и с обустройством личной жизни может не ладится.":"Бундай муаммолар сонига эга аёлларга албатта эркакларни ҳурмат қилишни ўрганиш керак. Акс ҳолда улар турмуш ўртоғига керакли қўллаб-қувватлашни кўрсата олмайди, ёки намойишкорона мустақил, такаббур, шерикка ҳаддан ташқари юқори талаблар қўядиган бўлиб намоён бўлади, шу сабабли шахсий ҳаётни жиҳозлаш ҳам чиқмаслиги мумкин.","Здесь может быть проблема проявления себя в обществе, то есть человек может постоянно искать, чем же ему заняться, как он может себя проявить, но тут как раз нужно искать себя самому, специально предпринимать шаги.":"Бу ерда жамиятда ўзини намоён қилиш муаммоси бўлиши мумкин, яъни инсон доим нима билан шуғулланиш, ўзини қандай намоён қилишни излаши мумкин, лекин бу ерда айнан ўзини ўзи излаш, махсус қадамлар қўйиш керак.","Также Солнце связано со ВРЕМЕНЕМ. Обратите внимание, как вы распоряжаетесь своим временем: как и когда вы просыпаетесь и засыпаете; опаздываете ли вы на встречи; делаете ли вы всё вовремя. Решить имеющиеся сложности можно с помощью тайм-менеджмента. Учитесь вставать рано утром и практиковать Сурья Намаскар, а ложиться не позднее 22-23 часов. Старайтесь выполнять свои обещания и брать на себя ответственность. Учитесь всё успевать и не тратить своё время попусту.":"Шунингдек Қуёш ВАҚТ билан боғлиқ. Вақтингизни қандай тасарруф этишингизга эътибор беринг: қандай ва қачон уйғонасиз ва ухлайсиз; учрашувларга кечикасизми; ҳаммасини ўз вақтида қиласизми. Мавжуд қийинчиликларни тайм-менежмент ёрдамида ҳал қилиш мумкин. Эрта тонгда туришни ва Сурья Намаскарни амалда қўллашни, ётишни эса 22-23 дан кечиктирмасликни ўрганинг. Ваъдаларингизни бажаришга ва масъулиятни ўз зиммангизга олишга ҳаракат қилинг. Ҳаммасига улгуришни ва вақтингизни беҳуда сарфламасликни ўрганинг.","Также ценно вести дневник благодарности (благодарить, а не искать виноватых), ставить цели (это помогает проявлению себя в обществе), а также заниматься благотворительностью.":"Шунингдек шукр кундалигини юритиш (айбдорларни излаш эмас, шукр қилиш), мақсадлар қўйиш (бу жамиятда ўзини намоён қилишга ёрдам беради), шунингдек хайрия билан шуғулланиш қимматли.","Основная проблема человека состоит вокруг его эго: либо неуверенность в себе, либо сильная гордыня и проявленный эгоизм, возможна даже зацикленность на себе. Человеку нужно правильно относиться к критике в свой адрес.":"Инсоннинг асосий муаммоси унинг эгоси атрофида: ё ўзига ишончсизлик, ё кучли кибр ва намоён бўлган худбинлик, ҳатто ўзига қотиб қолиш бўлиши мумкин. Инсонга ўз манзилига қаратилган танқидга тўғри муносабатда бўлиш керак.","Зачастую люди с такой проблемой перекладывают ответственность на других, ищут того, кто виноват.":"Кўпинча бундай муаммоли одамлар масъулиятни бошқаларга юклайди, айбдорни излайди.","У этих людей может быть проблема с отцом, и надо иметь хорошие отношения с влиятельными людьми, а также с теми, кто по отношению к ним имеет статус отца. Стараться максимально выровнять эти отношения.":"Бу одамларда ота билан муаммо бўлиши мумкин, нуфузли одамлар, шунингдек уларга нисбатан ота мақомига эга бўлганлар билан яхши муносабатда бўлиш керак. Бу муносабатларни максимал текислашга ҳаракат қилиш.","Женщинам с таким числом проблемы обязательно научиться уважать мужчин.":"Бундай муаммолар сонига эга аёлларга албатта эркакларни ҳурмат қилишни ўрганиш керак.","Человеку с этим числом проблемы необходимо соблюдать режим дня. Солнце отвечает за время: всегда рано и точно восход, всегда вовремя закат. Поэтому такому человеку нужно посвящать дела, связанные с Солнцем: ранний подъем, йогический комплекс Сурья-намаскар.":"Бу муаммолар сонига эга инсонга кун тартибига риоя қилиш зарур. Қуёш вақт учун жавоб беради: доим эрта ва аниқ чиқиш, доим ўз вақтида ботиш. Шунинг учун бундай инсонга Қуёш билан боғлиқ ишларни бағишлаш керак: эрта туриш, Сурья-намаскар йога мажмуаси.","Ценно вести дневник благодарности (благодарить, а не искать виноватых), ставить цели (это помогает проявлению себя в обществе), а также заниматься благотворительностью.":"Шукр кундалигини юритиш (айбдорларни излаш эмас, шукр қилиш), мақсадлар қўйиш (бу жамиятда ўзини намоён қилишга ёрдам беради), шунингдек хайрия билан шуғулланиш қимматли.","1)Луна отвечает за психику, нервную систему. Человек может все время придумывать причины для беспокойства. Ему очень важно успокаивать свой ум и умиротворяться, необходимо делать паузу в делах, проверять, как чувствует себя ум, какие эмоции сейчас испытывает, научиться жить в настоящем, то есть не думать о прошлом и будущем, а фиксировать себя в моменте.":"1)Ой руҳият, асаб тизими учун жавоб беради. Инсон доим хавотир учун сабаблар ўйлаб топиши мумкин. Унга ақлини тинчлантириш ва осойишталикка келиш жуда муҳим, ишларда танаффус қилиш, ақл ўзини қандай ҳис қилаётганини, ҳозир қандай ҳис-туйғуларни бошдан кечираётганини текшириш, ҳозирги ҳолатда яшашни ўрганиш, яъни ўтмиш ва келажак ҳақида ўйламай, ўзини лаҳзада қайд этиш зарур.","Полезны практики для успокоения ума: медитации, мантры, терапевтические письма, пение, рисование. Очень полезны водные процедуры, все, что связанно с водой: пить воду, плавать, смотреть на воду, принимать ванну даже несколько раз в день и подолгу. Благоприятно слушать спокойную музыку, шум моря и дождя; увлекаться творческими занятиями.":"Ақлни тинчлантириш амалиётлари фойдали: медитациялар, мантралар, терапевтик мактублар, қўшиқ, расм чизиш. Сув муолажалари, сув билан боғлиқ ҳамма нарса жуда фойдали: сув ичиш, сузиш, сувга қараш, ҳатто кунига бир неча марта ва узоқ ванна қабул қилиш. Хотиржам мусиқа, денгиз ва ёмғир шовқинини тинглаш; ижодий машғулотларга берилиш қулай.","2)Луна отвечает за сферу отношений. Именно в этой сфере у такого человека накопилось наибольшее количество проблем. Важно начать решать эти проблемы не в одиночку, а с кем-либо в паре. Лично я всегда направляю таких людей к психологу, потому что все мы родом из детства.":"2)Ой муносабатлар соҳаси учун жавоб беради. Айнан бу соҳада бундай инсонда энг кўп миқдорда муаммолар тўпланган. Бу муаммоларни ёлғиз эмас, кимдир билан жуфтликда ҳал қила бошлаш муҳим. Шахсан мен доим бундай одамларни психологга йўналтираман, чунки ҳаммамиз болаликдан келамиз.","3)Луна - это женское начало. Поэтому возможны проблемы с женщинами или с матерью. Важно взаимодействовать с женщинами, мамой, старшими женщинами, посещать различные группы, участвовать в различных практиках. Если у сына число проблемы 2, то мать должна помочь установить хорошие отношения с ним.":"3)Ой — аёл бошланғичи. Шунинг учун аёллар ёки она билан муаммолар бўлиши мумкин. Аёллар, она, катта аёллар билан ўзаро муносабатда бўлиш, турли гуруҳларга бориш, турли амалиётларда қатнашиш муҳим. Агар ўғилнинг муаммолар сони 2 бўлса, она у билан яхши муносабатлар ўрнатишга ёрдам бериши керак.","4)Забота. Очень важно научиться проявлять заботу, развивать свою материнскую часть, способность чувствовать и строить отношения . Если пока нет своих детей - полезно проводить различные занятия с детьми.":"4)Ғамхўрлик. Ғамхўрлик кўрсатишни, ўз оналик қисмини, ҳис қилиш ва муносабатлар қуриш қобилиятини ривожлантиришни ўрганиш жуда муҳим. Агар ҳали ўз фарзандлари бўлмаса — болалар билан турли машғулотлар ўтказиш фойдали.","5)Выбор. Из-за склонности к повышенному беспокойству ума такому человеку сложно делать выбор: как простой, так и более сложный. Очень важно учиться выбирать, не перекладывая эту ответственность на других людей.":"5)Танлов. Ақлнинг кучайган хавотирга мойиллиги туфайли бундай инсонга танлов қилиш қийин: оддий ҳам, мураккаброқ ҳам. Бу масъулиятни бошқа одамларга юкламай, танлашни ўрганиш жуда муҳим.","6)Самоощущение. Необходимо учиться чувствовать себя, осознавать собственные желания и предпочтения - а чего хотите именно вы?":"6)Ўзини ҳис қилиш. Ўзини ҳис қилишни, ўз истаклари ва афзалликларини англашни ўрганиш зарур — айнан сиз нимани истайсиз?","Главная рекомендация: это гармонизировать внутреннее спокойствие, быть в настоящем моменте и учиться науке взаимоотношений.":"Асосий тавсия: ички хотиржамликни уйғунлаштириш, ҳозирги лаҳзада бўлиш ва ўзаро муносабатлар илмини ўрганиш.","Перед людьми стоит проблема в сфере отношений, там накопилось наибольшее количество негативной кармы. Но есть нюанс: 2 означает, что решать проблему нужно с кем-то. Таким образом, если человек живет один или одна, то он не сможет решить эту проблему: ему нужно делать это в паре.":"Одамлар олдида муносабатлар соҳасида муаммо турибди, у ерда энг кўп миқдорда салбий карма тўпланган. Лекин бир нозик жиҳат бор: 2 муаммони кимдир билан ҳал қилиш кераклигини англатади. Шу тарзда, агар инсон ёлғиз яшаса, у бу муаммони ҳал қила олмайди: унга буни жуфтликда қилиш керак.","Могут быть проблемы с психикой, какие-то беспокойства или нестабильность ума. Эти люди могут также все время придумывать причины для беспокойства.":"Руҳият билан муаммолар, қандайдир хавотирлар ёки ақл беқарорлиги бўлиши мумкин. Бу одамлар шунингдек доим хавотир учун сабаблар ўйлаб топиши мумкин.","Здесь же возможны проблемы с женщинами или с матерью. Человеку важно научиться проявлять заботу, материнство, способность чувствовать и строить отношения. Ему необходимо делать паузу в делах, проверять, как чувствует себя ум, нужно научить жить в настоящем, то есть не думать о прошлом, будущем, а фиксировать себя, где он сейчас.":"Бу ерда аёллар ёки она билан муаммолар бўлиши мумкин. Инсонга ғамхўрлик, оналик, ҳис қилиш ва муносабатлар қуриш қобилиятини кўрсатишни ўрганиш муҳим. Унга ишларда танаффус қилиш, ақл ўзини қандай ҳис қилаётганини текшириш, ҳозирги ҳолатда яшашни ўрганиш, яъни ўтмиш, келажак ҳақида ўйламай, ўзини ҳозир қаерда бўлса, шу ерда қайд этиш керак.","Очень полезны водные процедуры, все, что связанно с водой: пить воду, плавать, смотреть на воду, принимать ванну даже несколько раз в день и подолгу.":"Сув муолажалари, сув билан боғлиқ ҳамма нарса жуда фойдали: сув ичиш, сузиш, сувга қараш, ҳатто кунига бир неча марта ва узоқ ванна қабул қилиш.","Благоприятно слушать спокойную музыку, шум моря и дождя; увлекаться творческими занятиями. Скорее всего, в его жизни будет стоять какой-то постоянный выбор, и так как есть беспокойства ума, ему нужно научиться принимать решения, все веско и хорошо обдумав.":"Хотиржам мусиқа, денгиз ва ёмғир шовқинини тинглаш; ижодий машғулотларга берилиш қулай. Эҳтимол, унинг ҳаётида қандайдир доимий танлов туради, ақл хавотирлари бўлгани учун унга ҳаммасини асосли ва яхши ўйлаб, қарор қабул қилишни ўрганиш керак.","Число 3 связано с: обучением; наставничеством; передачей знаний и опыта; благосостоянием. Человек должен развиваться, приобретать знания и мудрость, понимать, как устроена жизнь, как надо поступать в этой жизни правильно. Учиться принимать и давать добрые советы, поэтому важно обучать ненавязчиво, не рубить с плеча, а вдохновлять, чтобы другой наполнился энергией для действия. Таким образом, нужно стать совершенным консультантом, который не давит, а воодушевляет.":"3 сони: ўқиш; устозлик; билим ва тажриба етказиш; фаровонлик билан боғлиқ. Инсон ривожланиши, билим ва донолик орттириши, ҳаёт қандай тузилганини, бу ҳаётда қандай тўғри йўл тутиш кераклигини тушуниши керак. Яхши маслаҳатларни қабул қилиш ва беришни ўрганиш, шунинг учун ортиқча бўлмай ўргатиш, кесиб гапирмай, бошқаси ҳаракат учун энергия билан тўлиши учун илҳомлантириш муҳим. Шу тарзда босим ўтказмайдиган, балки руҳлантирадиган мукаммал маслаҳатчи бўлиш керак.","Этому человеку нужно избегать интеллектуальной гордыни, здесь также возможен блок применения на практике того, что человек узнал. Кроме того, нужно искоренять критику других и ощущение собственной правоты.":"Бу инсонга интеллектуал кибрдан сақланиш керак, бу ерда шунингдек инсон билганини амалда қўллаш блоки бўлиши мумкин. Бундан ташқари, бошқаларни танқид қилиш ва ўз ҳақлиги ҳиссини йўқотиш керак.","Человеку с этим числом проблем очень важно наладить свои отношения с деньгами, иначе это может трансформироваться в чрезмерную жадность или транжирство, а именно: бесконтрольные денежные траты; застревания в бесконечных кредитах и в состоянии \"выживания\". Одна из задач, которая будет стоять перед человеком в этой жизни, это благосостояние, т.е. улучшение своего материального состояния. Нужно наладить гармоничные отношения с деньгами. Неправильные отношения с деньгами это желание владеть ими, жадность, желание быстро потратить. Хорошее отношение с деньгами это: уважение к ним; принятие, что это инструмент для реализации целей; осознание, что деньги представляют собой неиссякаемый поток, мир изобилен; знать, как правильно распределять бюджет; учиться инвестированию; заниматься благотворительностью.":"Бу муаммолар сонига эга инсонга пул билан муносабатларини созлаш жуда муҳим, акс ҳолда бу ҳаддан ташқари очкўзлик ёки исрофгарчиликка айланиши мумкин, айнан: назоратсиз пул сарфлаш; чексиз кредитлар ва «омон қолиш» ҳолатида қотиб қолиш. Бу ҳаётда инсон олдида турадиган вазифалардан бири — фаровонлик, яъни моддий аҳволини яхшилаш. Пул билан уйғун муносабатларни созлаш керак. Пул билан нотўғри муносабатлар — уларга эгалик қилиш истаги, очкўзлик, тез сарфлаш истаги. Пул билан яхши муносабат: уларга ҳурмат; бу мақсадларни амалга ошириш воситаси эканини қабул қилиш; пул битмас оқим эканини, дунё тўкин эканини англаш; бюджетни тўғри тақсимлашни билиш; сармоя киритишни ўрганиш; хайрия билан шуғулланиш.","Тройка также связана с речью и с самовыражением. Важно раскрывать свой творческий потенциал и работать над своим стремлением привлекать к себе внимание. Полезно заниматься творчеством, отслеживая, чтобы это было не из эгоизма, а созидательно. Человеку можно идти в актёрское мастерство, пение, художественные направления.":"Учлик шунингдек нутқ ва ўзини ифода этиш билан боғлиқ. Ижодий салоҳиятни очиш ва ўзига эътибор жалб қилиш интилиши устида ишлаш муҳим. Бу худбинликдан эмас, бунёдкорона бўлишини кузатиб, ижод билан шуғулланиш фойдали. Инсонга актёрлик маҳорати, қўшиқ, бадиий йўналишларга бориш мумкин.","Также число 3 связано с детьми и другими \"младшими\". Такому человеку важна забота о младших: как о детях, так и о тех, кто нуждается в его советах и поддержке. У него могут возникать трудности с зачатием, в отношениях с детьми и их воспитанием. Тройка означает, что ребёнок будет инструментом, с помощью которого этот человек может решить главную проблему своей жизни. Поэтому нужно заниматься с детьми; если нет своих, то с другими: можно что-то жертвовать, помогать им.":"Шунингдек 3 сони болалар ва бошқа «кичиклар» билан боғлиқ. Бундай инсонга кичикларга: болаларга ҳам, унинг маслаҳатлари ва қўллаб-қувватловига муҳтожларга ҳам ғамхўрлик муҳим. Унда ҳомиладорлик, болалар билан муносабатлар ва уларни тарбиялашда қийинчиликлар пайдо бўлиши мумкин. Учлик бола бу инсон ҳаётининг асосий муаммосини ҳал қила оладиган восита бўлишини англатади. Шунинг учун болалар билан шуғулланиш керак; агар ўзиники бўлмаса, бошқалар билан: нимадир ҳадя қилиш, уларга ёрдам бериш мумкин.","Человеку-3 важно: осознать, зачем ему нужны дети; увидеть свои страхи, связанные с родительством; работать над отношениями с детьми; анализировать своё общение с ними; помогать другим детям, если нет своих. Также 3 говорит в целом о младших, может быть такое, что у человека нет своих детей и даже нет желания, но он может заботиться о других людях, помогать советами, учить. Он вкладывает в других людей, которые по отношению к нему младшие, свою заботу и проявляет себя как наставник.":"3-инсонга муҳим: фарзандлар унга нима учун кераклигини англаш; ота-оналик билан боғлиқ қўрқувларини кўриш; болалар билан муносабатлар устида ишлаш; улар билан мулоқотини таҳлил қилиш; агар ўзиникилари бўлмаса, бошқа болаларга ёрдам бериш. Шунингдек 3 умуман кичиклар ҳақида гапиради, инсоннинг ўз фарзандлари ва ҳатто истаги бўлмаслиги мумкин, лекин у бошқа одамларга ғамхўрлик қилиши, маслаҳатлар билан ёрдам бериши, ўргатиши мумкин. У унга нисбатан кичик бўлган бошқа одамларга ғамхўрлигини киритади ва ўзини устоз сифатида намоён қилади.","Человек должен развиваться, приобретать знания и мудрость. Ему необходимо знать законы жизни, понимать и использовать их. Учиться принимать и давать советы, поэтому важно обучать ненавязчиво, не рубить с плеча, а вдохновлять, чтобы другой наполнился энергией для действия.Таким образом, быть совершенным консультантом, который не давит, а воодушевляет.":"Инсон ривожланиши, билим ва донолик орттириши керак. Унга ҳаёт қонунларини билиш, тушуниш ва улардан фойдаланиш зарур. Маслаҳатларни қабул қилиш ва беришни ўрганиш, шунинг учун ортиқча бўлмай ўргатиш, кесиб гапирмай, бошқаси ҳаракат учун энергия билан тўлиши учун илҳомлантириш муҳим. Шу тарзда босим ўтказмайдиган, балки руҳлантирадиган мукаммал маслаҳатчи бўлиш.","Этому человеку нужно избегать интеллектуальной гордыни, здесь также возможен блок применения на практике того, что человек узнал.Кроме того, искоренять критику других и ощущение собственной правоты.Одна из задач, которая будет стоять перед человеком в этой жизни, это благосостояние, т.е. улучшение своего благосостояния. Но нужно наладить гармоничные отношения с деньгами, иначе это может превратиться в жадность. Другая задача – это дети. У человека с числом проблемы 3 очень часто нет детей. Но иногда, если есть дети, то с ними огромные проблемы. Тройка означает, что ребёнок будет инструментом, с помощью которого этот человек может решить главную проблему своей жизни. Поэтому нужно заниматься с детьми; если нет своих, то с другими: можно что-то жертвовать, помогать им. Обязательно развивать творческий потенциал и избавляться от мании величия.":"Бу инсонга интеллектуал кибрдан сақланиш керак, бу ерда шунингдек инсон билганини амалда қўллаш блоки бўлиши мумкин. Бундан ташқари, бошқаларни танқид қилиш ва ўз ҳақлиги ҳиссини йўқотиш. Бу ҳаётда инсон олдида турадиган вазифалардан бири — фаровонлик, яъни фаровонлигини яхшилаш. Лекин пул билан уйғун муносабатларни созлаш керак, акс ҳолда бу очкўзликка айланиши мумкин. Бошқа вазифа — фарзандлар. Муаммолар сони 3 бўлган инсонда жуда кўпинча фарзанд бўлмайди. Лекин баъзан, фарзандлар бўлса, улар билан улкан муаммолар бўлади. Учлик бола бу инсон ҳаётининг асосий муаммосини ҳал қила оладиган восита бўлишини англатади. Шунинг учун болалар билан шуғулланиш керак; агар ўзиники бўлмаса, бошқалар билан: нимадир ҳадя қилиш, уларга ёрдам бериш мумкин. Ижодий салоҳиятни албатта ривожлантириш ва улуғворлик маниясидан қутулиш.","Как говорить о числе проблем 3 девушке, у которой нет семьи, но она хочет? В этом числе есть проблемы, связанные с рождением детей.":"Оиласи бўлмаган, лекин истайдиган қизга муаммолар сони 3 ҳақида қандай гапириш керак? Бу сонда фарзанд кўриш билан боғлиқ муаммолар бор.","Число проблемы – это то, что нужно решить человеку. По 3 много разных направлений, в том числе и взаимодействие с детьми, поэтому нужно сказать человеку, что его задача стремиться к общению с детьми (своими, чужими), их обучению. Семья, дети появляются в определенное время, которое можно также посмотреть по периоду, году жизни человека. И все-таки необходимо рассматривать дату целиком, сопоставляя все расчеты, как это сделать, будет рассказано к концу курса.":"Муаммолар сони — инсон ҳал қилиши керак бўлган нарса. 3 бўйича кўплаб турли йўналишлар, жумладан болалар билан ўзаро муносабат ҳам бор, шунинг учун инсонга унинг вазифаси болалар (ўзиники, бировники) билан мулоқотга, уларни ўқитишга интилиш эканини айтиш керак. Оила, фарзандлар маълум вақтда пайдо бўлади, уни ҳам инсон ҳаётининг даври, йили бўйича кўриш мумкин. Бироқ барибир барча ҳисобларни солиштириб, санани бутунлигича кўриб чиқиш зарур, буни қандай қилиш курс охирига келиб айтиб берилади.","При консультировании людей пользуемся принципом «не навреди». Поэтому нужно подавать информацию с положительной стороны, чтобы вдохновлять и мотивировать людей. Если есть неуверенность в чем-то, сомнения, этого лучше не говорить совсем. Когда появляются проблемы, острые моменты в карте, необходимо проговаривать клиенту их с точки зрения задач, которые он должен решить, но в зависимости от того, если у него на это сейчас ресурсы, актуально ли для него это в данный момент. То есть консультация должна быть направлена на рост человека.":"Одамларга маслаҳат беришда «зарар етказма» тамойилидан фойдаланамиз. Шунинг учун одамларни илҳомлантириш ва рағбатлантириш учун маълумотни ижобий томондан тақдим этиш керак. Агар нимададир ишончсизлик, шубҳалар бўлса, буни умуман айтмаган яхшироқ. Картада муаммолар, ўткир лаҳзалар пайдо бўлганда, уларни мижозга у ҳал қилиши керак бўлган вазифалар нуқтаи назаридан айтиш керак, лекин унда ҳозир бунинг учун ресурслар бор-йўқлиги, бу ҳозирги пайтда у учун долзарбми-йўқми — бунга боғлиқ. Яъни маслаҳат инсоннинг ўсишига йўналтирилган бўлиши керак.","Раху — неоднозначная планета, связанная с подсознанием. В негативном ключе она проявляется как: страхи; фобии; повышенная чувствительность и возбудимость; ограничения и тревоги; внутренние блоки; фантазии и иллюзии.":"Раҳу — онг ости билан боғлиқ ноаниқ сайёра. Салбий тарзда у қуйидагича намоён бўлади: қўрқувлар; фобиялар; кучайган сезгирлик ва қўзғалувчанлик; чекловлар ва хавотирлар; ички блоклар; хаёллар ва иллюзиялар.","Люди с числом проблем 4 могут любить азартные игры, быть пристрастными к алкоголю, долго зависать в социальных сетях, иметь 100 каналов на ТВ или даже много спать. Человек может не чувствовать грани, и ему нужны острые ощущения. Задача — обратить на это внимание и вовремя привести свою жизнь в гармонию.":"Муаммолар сони 4 бўлган одамлар қимор ўйинларини яхши кўриши, алкоголга мойил бўлиши, ижтимоий тармоқларда узоқ қотиб қолиши, телевизорда 100 та каналга эга бўлиши ёки ҳатто кўп ухлаши мумкин. Инсон чегарани ҳис қилмаслиги мумкин ва унга ўткир ҳислар керак. Вазифа — бунга эътибор бериш ва ҳаётини ўз вақтида уйғунликка келтириш.","Людям с числом проблем 4 стоит: научиться трезво оценивать любую ситуацию; меньше витать в облаках, не погружаться в мир иллюзий — они будут мешать на пути к успеху и отвлекать на дела, которые на самом деле не важны; обращаться к психологу, если в жизни людей преследуют страхи, внутренние блоки и тревоги; контролировать желания, особенно искусственные: социальные сети, азартные игры, алкоголь, и избавиться от дурных привычек; заменить искусственные вещи на натуральные: в одежде, питании и других сферах жизни;поддерживать чистоту в доме; больше находиться на природе, если есть возможность — даже переехать за город; научиться правильному планированию, определению главных задач. Начните с простейших целей: записывайте их на бумаге и с лёгкостью достигайте — только после этого переходите к более сложным; учить иностранные языки — у вас в этом талант! Важно путешествовать, исследовать новые места; развивать свою духовную практику.":"Муаммолар сони 4 бўлган одамларга керак: ҳар қандай вазиятни ҳушёр баҳолашни ўрганиш; булутларда камроқ сузиш, иллюзиялар дунёсига шўнғимаслик — улар муваффақият йўлида халақит беради ва аслида муҳим бўлмаган ишларга чалғитади; агар ҳаётда одамларни қўрқувлар, ички блоклар ва хавотирлар таъқиб қилса, психологга мурожаат қилиш; истакларни, айниқса сунъийларини назорат қилиш: ижтимоий тармоқлар, қимор ўйинлари, алкоголь, ва ёмон одатлардан қутулиш; сунъий нарсаларни табиийларига алмаштириш: кийим, овқатланиш ва ҳаётнинг бошқа соҳаларида; уйда тозаликни сақлаш; табиатда кўпроқ бўлиш, имкони бўлса — ҳатто шаҳар ташқарисига кўчиш; тўғри режалаштиришни, асосий вазифаларни аниқлашни ўрганиш. Энг оддий мақсадлардан бошланг: уларни қоғозга ёзинг ва осонлик билан эришинг — фақат шундан кейин мураккаброқларига ўтинг; чет тилларини ўрганиш — сизда бунга истеъдод бор! Саёҳат қилиш, янги жойларни тадқиқ қилиш, маънавий амалиётингизни ривожлантириш муҳим.","Что я подразумеваю под духовной практикой? Это осознание себя как вечной души, самоисследование.":"Маънавий амалиёт деганда нимани назарда тутаман? Бу ўзини абадий руҳ сифатида англаш, ўзини тадқиқ қилиш.","Этому помогает: Аффирмации, Аутотренинг, Медитация, Созерцание природы, Благотворительность, Аскеза (ограничение себя в комфорте), Бескорыстная деятельность, Пост, молитва, паломничество;, Пожертвования святым людям;, Чтение священных книг, общение со святыми;, Созерцание и поклонение алтарю;, Служение в храмах; Есть освященную пищу;Следование духовным праздникам.":"Бунга ёрдам беради: Аффирмациялар, Аутотренинг, Медитация, Табиатни мушоҳада қилиш, Хайрия, Зоҳидлик (ўзини қулайликда чеклаш), Беғараз фаолият, Рўза, дуо, зиёрат;, Муқаддас одамларга эҳсон;, Муқаддас китобларни ўқиш, авлиёлар билан мулоқот;, Меҳробни мушоҳада қилиш ва унга сиғиниш;, Ибодатхоналарда хизмат; Муқаддасланган овқатни ейиш; Маънавий байрамларга амал қилиш.","Помните: следовать рекомендациям нужно постоянно, чтобы число проблем не мешало вам в достижении главной жизненной цели. В случае с четвёркой — чтобы Раху не проявлялась отрицательно.":"Ёдда тутинг: муаммолар сони асосий ҳаётий мақсадга эришишингизга халақит бермаслиги учун тавсияларга доимий амал қилиш керак. Тўртлик ҳолатида — Раҳу салбий намоён бўлмаслиги учун.","Проблемы, связанные со страхами, фобиями, фантазиями, иллюзиями, какие-то внутренние проблемы, блоки. Также надо контролировать желания, особенно искусственные, например, алкоголь, игры, долгое зависание в социальных сетях, наличие 100 каналов в телевизоре. То есть здесь человек может не чувствовать грани, и ему нужны острые ощущения.":"Қўрқувлар, фобиялар, хаёллар, иллюзиялар, қандайдир ички муаммолар, блоклар билан боғлиқ муаммолар. Шунингдек истакларни, айниқса сунъийларини, масалан, алкоголь, ўйинлар, ижтимоий тармоқларда узоқ қотиб қолиш, телевизорда 100 та канал мавжудлигини назорат қилиш керак. Яъни бу ерда инсон чегарани ҳис қилмаслиги мумкин ва унга ўткир ҳислар керак.","Задача такого человека – полная трансформация сознания, что так дальше жить нельзя. И тут ключевую роль играет духовность. Ему нужно избавиться от дурных привычек и искусственных вещей, наладить контакт с природой.":"Бундай инсоннинг вазифаси — онгнинг тўлиқ трансформацияси, бундай яшаб бўлмаслигини англаш. Ва бу ерда маънавият асосий роль ўйнайди. Унга ёмон одатлар ва сунъий нарсалардан қутулиш, табиат билан алоқани созлаш керак.","У этого человека может быть талант в иностранных языках, и ему постоянно хочется куда-то уехать.":"Бу инсонда чет тилларига истеъдод бўлиши мумкин ва у доим қаергадир кетишни истайди.","Важно научиться правильно ставить цели и достигать их; нужно работать со своими страхи и снимать искусственные блоки.":"Мақсадларни тўғри қўйиш ва уларга эришишни ўрганиш муҳим; қўрқувлари билан ишлаш ва сунъий блокларни олиб ташлаш керак.","Пятёрка отвечает за: свободу; интеллект, анализ; эмоции.":"Бешлик: эркинлик; интеллект, таҳлил; ҳис-туйғулар учун жавоб беради.","Человеку с этим числом проблем нужно: развивать свои интеллектуальные способности, быть любознательным, путешествовать. Ему важно чувствовать внутреннюю свободу - это свобода от ограничений и установок. Например:":"Бу муаммолар сонига эга инсонга керак: интеллектуал қобилиятларини ривожлантириш, қизиқувчан бўлиш, саёҳат қилиш. Унга ички эркинликни ҳис қилиш муҳим — бу чекловлар ва ўрнатмалардан эркинлик. Масалан:","- свобода выбирать, какие мысли, чувства, состояния проживать, как свой опыт; - свобода принимать свободу выбора других людей; - свобода быть самим собой: проявлять свою индивидуальность и харизму, позволяя другим людям выражать свою уникальность и неповторимость;- свобода быть честным с собой и другими людьми;- свобода осознавать ответственность за свою жизнь и реализацию всех своих желаний;- свобода жить из сердца;":"- қандай фикрлар, ҳислар, ҳолатларни ўз тажрибаси сифатида бошдан кечиришни танлаш эркинлиги; - бошқа одамларнинг танлаш эркинлигини қабул қилиш эркинлиги; - ўзи бўлиш эркинлиги: бошқа одамларга ўз ноёблиги ва такрорланмаслигини ифода этишга имкон бериб, ўз индивидуаллиги ва харизмасини намоён қилиш; - ўзи ва бошқа одамлар билан ҳалол бўлиш эркинлиги; - ўз ҳаёти ва барча истакларини амалга ошириш учун масъулиятни англаш эркинлиги; - юракдан яшаш эркинлиги;","Человеку важно 👉всё время обучаться, приобретать нужные для жизни знания и навыки; 👉учиться чувствовать и любить жизнь, получать новые впечатления, быть в динамике. Человеку с числом проблем 5 следует избегать однообразия, и в этом ему также могут помочь путешествия 👉владеть своими эмоциями: давать им волю в моменты счастья и держать в узде, чтобы не допустить истерик и капризов, не обидеть близких. Из-за слабых умений в контроле над эмоциями люди с эти числом проблем часто бывают зажаты и боятся вообще проявлять какие-либо чувства; 👉следить за привычками. Люди с этим числом проблем могут пытаться заедать или запивать проявления своих эмоций. На это нужно обратить внимание и, как я уже сказала, учиться контролировать своё внутреннее состояние; 👉развивать дар речи, навыки общения, учиться чувствовать и понимать людей. Для этого хорошо подходят различные сферы коммуникации: телевидение, радио, журналистика, ведение блога.":"Инсонга муҳим 👉доим ўқиш, ҳаёт учун керакли билим ва кўникмаларни орттириш; 👉ҳис қилишни ва ҳаётни севишни, янги таассуротлар олишни, динамикада бўлишни ўрганиш. Муаммолар сони 5 бўлган инсонга бир хилликдан сақланиш керак, бунда унга саёҳатлар ҳам ёрдам бериши мумкин 👉ҳис-туйғуларини бошқариш: бахт лаҳзаларида уларга эрк бериш ва жазавалар ва инжиқликларга йўл қўймаслик, яқинларни хафа қилмаслик учун жиловда ушлаш. Ҳис-туйғулар устидан назорат маҳоратлари заиф бўлгани учун бу муаммолар сонига эга одамлар кўпинча қисилган бўлади ва умуман қандайдир ҳисларни намоён қилишдан қўрқади; 👉одатларни кузатиш. Бу муаммолар сонига эга одамлар ҳис-туйғуларининг намоён бўлишини еб ёки ичиб босишга уриниши мумкин. Бунга эътибор бериш ва, айтганимдек, ички ҳолатни назорат қилишни ўрганиш керак; 👉нутқ иқтидори, мулоқот кўникмаларини ривожлантириш, одамларни ҳис қилиш ва тушунишни ўрганиш. Бунинг учун турли коммуникация соҳалари: телевидение, радио, журналистика, блог юритиш яхши мос келади.","Помните, что всё в жизни должно быть экологично и в меру. Умейте чувствовать грани и избегать крайностей.":"Ёдда тутинг, ҳаётда ҳамма нарса экологик ва меъёрида бўлиши керак. Чегараларни ҳис қила билинг ва ҳаддан ошишлардан сақланинг.","Приобретение разных знаний и навыков в жизни; это то, что позволяет человеку что-то уметь делать; это также означает, что человек должен развивать в себе интеллектуальные способности, кроме того, важна работа с речью (поскольку он либо молчун, либо болтун, сплетник).":"Ҳаётда турли билим ва кўникмаларни орттириш; бу инсонга нимадир қила олишга имкон берадиган нарса; бу шунингдек инсон ўзида интеллектуал қобилиятларни ривожлантириши кераклигини англатади, бундан ташқари, нутқ билан ишлаш муҳим (чунки у ё камгап, ё сергап, ғийбатчи).","Ещё одна особенность такого человека, что он должен культивировать в себе чувство свободы, стремиться в жизни к чувству внутренней свободы .":"Бундай инсоннинг яна бир хусусияти — у ўзида эркинлик ҳиссини ривожлантириши, ҳаётда ички эркинлик ҳиссига интилиши керак.","Ему нужно научиться общаться с людьми, контактировать с ними, учиться чувствовать и понимать людей. СМИ очень хорошо подходят для людей с числом проблемы 5.":"Унга одамлар билан мулоқот қилишни, улар билан алоқада бўлишни, одамларни ҳис қилиш ва тушунишни ўрганиш керак. ОАВ муаммолар сони 5 бўлган одамлар учун жуда яхши мос келади.","Шестёрка указывает на испытание любовью. У любви всегда есть две грани: любовь к другим и любовь к себе. Если это ваше число проблем, то предстоят трудности в отношениях с окружающими и с собой. Давайте рассмотрим каждую грань отдельно:":"Олтилик муҳаббат синовини кўрсатади. Муҳаббатнинг доим икки қирраси бор: бошқаларга муҳаббат ва ўзига муҳаббат. Агар бу сизнинг муаммолар сонингиз бўлса, атрофдагилар ва ўзингиз билан муносабатларда қийинчиликлар бўлади. Келинг, ҳар бир қиррани алоҳида кўриб чиқамиз:","1) людям с ЧП-6 тяжело любить и принимать себя. Они испытывают жалость к себе, часто ощущают себя нелюбимыми, много отдают и ничего не просят взамен.":"1) МС-6 бўлган одамларга ўзини севиш ва қабул қилиш оғир. Улар ўзига раҳм-шафқат ҳис қилади, кўпинча ўзини севилмагандек ҳис қилади, кўп беради ва эвазига ҳеч нарса сўрамайди.","Я советую вам: чаще баловать и хвалить себя; вырабатывать здоровый эгоизм; принимать себя; создавать любовь: насыщайте себя и окружение гармонией и теплом;":"Сизга маслаҳат бераман: ўзингизни тез-тез эркаланг ва мақтанг; соғлом худбинликни ишлаб чиқинг; ўзингизни қабул қилинг; муҳаббат яратинг: ўзингизни ва атрофингизни уйғунлик ва илиқлик билан тўйинтиринг;","2) испытание любовью может заключаться в сложностях с партнером или в общении с окружающими. Близкие могут быть эгоистичными, неверными, могут предавать и обманывать. Но помните: это ВАШ урок. Извлекайте пользу и учитесь на ошибках. Мои рекомендации: развивайте верность и уважение к партнёру; учитесь гармонии в общении; обозначьте границы: обсуждайте \"можно\" и \"нельзя\" в отношениях; принимайте других такими, какие они есть.":"2) муҳаббат синови шерик билан ёки атрофдагилар билан мулоқотдаги қийинчиликларда бўлиши мумкин. Яқинлар худбин, бевафо бўлиши, хиёнат қилиши ва алдаши мумкин. Лекин ёдда тутинг: бу СИЗНИНГ сабоғингиз. Фойда чиқаринг ва хатолардан ўрганинг. Менинг тавсияларим: шерикка садоқат ва ҳурматни ривожлантиринг; мулоқотда уйғунликни ўрганинг; чегараларни белгиланг: муносабатларда «мумкин» ва «мумкин эмас»ни муҳокама қилинг; бошқаларни қандай бўлса шундайлигича қабул қилинг.","Какая бы грань испытания любовью ни выпала, занимайтесь творчеством, уделяйте внимание красоте. Вам некомфортно находиться в некрасивом месте, тем более жить в нём. Поддерживайте чистоту, следите за внешностью, обустраивайте домашний уют.":"Муҳаббат синовининг қайси қирраси тушмасин, ижод билан шуғулланинг, гўзалликка эътибор беринг. Сизга хунук жойда бўлиш, айниқса унда яшаш ноқулай. Тозаликни сақланг, ташқи кўринишни кузатинг, уй қулайлигини яратинг.","Число проблем 6 также связано с удовольствиями. Знакома вам сильная привязанность к еде, алкоголю, сексуальным отношениям? Усмиряйте жадность, контролируйте удовольствия, иначе вы потеряете контроль над собой.":"Муаммолар сони 6 шунингдек завқлар билан боғлиқ. Сизга овқат, алкоголь, жинсий муносабатларга кучли боғланиш таниш эмасми? Очкўзликни жиловланг, завқларни назорат қилинг, акс ҳолда ўзингиз устидан назоратни йўқотасиз.","В крайних случаях шестёрка проявляется как склонность к чёрной магии, агрессии, неразборчивости в отношениях. \"Любить из-за выгоды\" и \"выходить замуж по расчету\" - главные ошибки тех, кто провалил испытание любовью. Любить нужно от сердца.":"Чекка ҳолатларда олтилик қора сеҳрга мойиллик, тажовуз, муносабатларда танламасликда намоён бўлади. «Фойда учун севиш» ва «ҳисоб-китоб билан турмушга чиқиш» — муҳаббат синовидан ўта олмаганларнинг асосий хатолари. Юракдан севиш керак.","Человек стремится к наслаждениям (в том числе и сексуальным), причем делает это жадно.":"Инсон лаззатларга (жумладан жинсийларга ҳам) интилади, бунда буни очкўзлик билан қилади.","У такого человека есть сильная привязанность к совершенству и красоте. Например, он приехал в какую-то гостиницу отдыхать, и там некрасиво. Для него это будет ужасно – он не сможет там жить.":"Бундай инсонда мукаммаллик ва гўзалликка кучли боғланиш бор. Масалан, у дам олиш учун қандайдир меҳмонхонага келди, у ер эса хунук. У учун бу даҳшатли бўлади — у ерда яшай олмайди.","Очень важно развивать верность и уважение к женщинам, соответственно, женщинам то же самое – к мужчинам.":"Аёлларга садоқат ва ҳурматни ривожлантириш жуда муҳим, мос равишда аёлларга ҳам худди шундай — эркакларга.","У людей с числом проблемы 6 главное то, что они должны созидать любовь, любовь к себе и другим. Необходимо быть удовлетворенным тем, что есть.":"Муаммолар сони 6 бўлган одамларда асосийси — улар муҳаббатни, ўзига ва бошқаларга муҳаббатни бунёд этиши керак. Бор нарсадан қониқиш зарур.","Здесь должно быть развитие творчества. Для этих людей значимо везде наводить красоту, ухаживать за внешностью, культивировать чистоту и целомудрие.":"Бу ерда ижоднинг ривожланиши бўлиши керак. Бу одамлар учун ҳамма жойда гўзаллик яратиш, ташқи кўринишга қараш, тозалик ва иффатни ривожлантириш аҳамиятли.","На консультациях и при проведении расчетов я заметила, что 7️ редко появляется как число проблем. Кету - планета без головы, своего рода \"хвост\". Поэтому люди с семёркой чаще полагаются не на разум, а на интуицию. 7️ отвечает за: духовное развитие; самопознание; интуицию; мудрость.":"Маслаҳатларда ва ҳисоблар ўтказишда 7️ муаммолар сони сифатида кам пайдо бўлишини пайқадим. Кету — бошсиз сайёра, ўзига хос «дум». Шунинг учун еттилик одамлар кўпинча ақлга эмас, интуицияга таянади. 7️: маънавий ривожланиш; ўзини англаш; интуиция; донолик учун жавоб беради.","Такие люди получают знания извне, в течении жизни нарабатывают ценный духовный опыт. Это можно усилить, следуя моим рекомендациям.":"Бундай одамлар билимларни ташқаридан олади, ҳаёт давомида қимматли маънавий тажриба орттиради. Буни тавсияларимга амал қилиб кучайтириш мумкин.","Если ваше число проблем 7, то:":"Агар муаммолар сонингиз 7 бўлса:","💫задайтесь главными вопросами: \"Для чего я живу?\", \"Какая моя главная задача?\";":"💫асосий саволларни беринг: «Мен нима учун яшайман?», «Менинг асосий вазифам нима?»;","💫проработайте жизненную цель (число судьбы);":"💫ҳаётий мақсадни (тақдир сонини) ишлаб чиқинг;","💫каждый день учитесь новому, набирайтесь духовного опыта;":"💫ҳар куни янгиликни ўрганинг, маънавий тажриба орттиринг;","💫доверяйте интуиции и развивайте её;":"💫интуицияга ишонинг ва уни ривожлантиринг;","💫работайте над своими комплексами, развивайте чувство собственного достоинства.":"💫комплексларингиз устида ишланг, ўз қадр-қиммат ҳиссини ривожлантиринг.","Зацикленность и нерешительность могут привести к депрессиям и унынию. Если вам нужно принять решение - делайте это быстро, иначе растянете на годы простейший шаг, а потом будете корить себя за это.":"Қотиб қолиш ва қатъиятсизлик депрессия ва тушкунликка олиб келиши мумкин. Агар сизга қарор қабул қилиш керак бўлса — буни тез қилинг, акс ҳолда энг оддий қадамни йилларга чўзасиз, кейин эса бунинг учун ўзингизни койийсиз.","Ваш путь - духовное самопознание. Ваше положение в жизни уникально, научитесь чувствовать и принимать его.":"Сизнинг йўлингиз — маънавий ўзини англаш. Ҳаётдаги ҳолатингиз ноёб, уни ҳис қилишни ва қабул қилишни ўрганинг.","Это работа над своими комплексами; есть какая-то маниакальность – излишняя зацикленность на чем-либо, т.е. могут что-то долго обдумывать; присутствует и склонность к интоксикациям. Нужно избегать депрессий.":"Бу комплекслар устида иш; қандайдир маниакаллик — нимагадир ортиқча қотиб қолиш бор, яъни нимадир узоқ ўйлаши мумкин; интоксикацияларга мойиллик ҳам мавжуд. Депрессиялардан қочиш керак.","Таким людям необходимо хорошо проработать цель жизни, развивать мудрость. Обязательна духовная практика в жизни, они могут приобрести очень сильный духовный опыт.":"Бундай одамларга ҳаёт мақсадини яхши ишлаб чиқиш, доноликни ривожлантириш зарур. Ҳаётда маънавий амалиёт шарт, улар жуда кучли маънавий тажриба орттириши мумкин.","Люди с числом проблем 8 в прошлой жизни отлынивали от работы, ленились. Поэтому в этой жизни им предстоит: много трудиться; преодолевать трудности; научиться действовать; принимать на себя ответственность; научиться жить в материальном мире: понять финансовые, управленческие и трудовые вопросы; найти баланс духовного и материального.":"Муаммолар сони 8 бўлган одамлар ўтган ҳаётда ишдан бўйин товлаган, дангасалик қилган. Шунинг учун бу ҳаётда уларга керак бўлади: кўп меҳнат қилиш; қийинчиликларни енгиш; ҳаракат қилишни ўрганиш; масъулиятни ўз зиммасига олиш; моддий дунёда яшашни ўрганиш: молиявий, бошқарув ва меҳнат масалаларини тушуниш; маънавий ва моддий мувозанатини топиш.","В отношении с деньгами людям с числом проблем 8 важно не быть жадными, не проводить манипуляций. Любую власть следует использовать осторожно, с умом.":"Пул билан муносабатда муаммолар сони 8 бўлган одамларга очкўз бўлмаслик, манипуляциялар қилмаслик муҳим. Ҳар қандай ҳокимиятдан эҳтиёткорлик билан, ақл билан фойдаланиш керак.","Число проблем 8 подталкивает к духовному развитию. Уделяйте время духовным практикам, развивайте интуицию. Как я уже сказала выше, здесь нужно найти баланс между духовной и материальной сферами жизни.":"Муаммолар сони 8 маънавий ривожланишга ундайди. Маънавий амалиётларга вақт ажратинг, интуицияни ривожлантиринг. Юқорида айтганимдек, бу ерда ҳаётнинг маънавий ва моддий соҳалари ўртасида мувозанат топиш керак.","Кроме того, у этого человека должно быть серьезное отношение к жизни, но при этом ему нужно избавляться от напряжения: это может забирать силы и приносить уныние. Людям с восьмёркой полезно заниматься своим телом: снимать напряжение в мышцах с помощью йоги, гимнастики, плавания или массажей. Вам предстоит бОльшую часть жизни работать и трудиться, поэтому важно следить за здоровьем.":"Бундан ташқари, бу инсонда ҳаётга жиддий муносабат бўлиши керак, лекин бунда унга тарангликдан қутулиш керак: бу кучларни олиб кетиши ва тушкунлик келтириши мумкин. Саккизлик одамларга танаси билан шуғулланиш фойдали: йога, гимнастика, сузиш ёки массажлар ёрдамида мушаклардаги тарангликни олиб ташлаш. Сизга ҳаётнинг каттароқ қисмида ишлаш ва меҳнат қилиш керак бўлади, шунинг учун саломатликни кузатиш муҳим.","Избегайте уныния, никогда не опускайте руки. Для этого я советую:":"Тушкунликдан сақланинг, ҳеч қачон қўлни туширманг. Бунинг учун маслаҳат бераман:","✅прописать для себя и каждый день повторять аффирмации;":"✅ўзингиз учун аффирмациялар ёзинг ва ҳар куни такрорланг;","✅вести дневник успеха, гордиться своими достижениями;":"✅муваффақият кундалигини юритинг, ютуқларингиз билан фахрланинг;","✅подкреплять себя радостью;":"✅ўзингизни қувонч билан қувватлантиринг;","✅жить ближе к природе, в солнечном месте - подпитываться витамином D.":"✅табиатга яқинроқ, қуёшли жойда яшанг — D витамини билан озиқланинг.","Человеку нужно трудиться, потому что в прошлых жизнях он очень мало работал, как-то отлынивал, а в этой жизни ему надо работать и, скорее всего, работать как волонтером, трудится в широком смысле этого слова. Надо прилагать большие усилия, научиться структурировать, быть полезным обществу. Кроме того, у этого человека должно быть серьезное отношение к жизни, но при этом ему нужно избавляться от напряжения: это может забирать силы и приносить уныние. И здесь хорошо подойдет деятельность, связанная с телом, которая как раз избавит от этого напряжения: всяческие массажи, гимнастика, плаванье. Также благоприятно прописывать различные аффирмации – это будет забирать уныние и давать импульс для трудолюбия.":"Инсонга меҳнат қилиш керак, чунки ўтган ҳаётларда у жуда кам ишлаган, қандайдир бўйин товлаган, бу ҳаётда эса унга ишлаш ва, эҳтимол, волонтёр сифатида ишлаш, бу сўзнинг кенг маъносида меҳнат қилиш керак. Катта саъй-ҳаракат қилиш, тузилмалашни ўрганиш, жамиятга фойдали бўлиш керак. Бундан ташқари, бу инсонда ҳаётга жиддий муносабат бўлиши керак, лекин бунда унга тарангликдан қутулиш керак: бу кучларни олиб кетиши ва тушкунлик келтириши мумкин. Ва бу ерда айнан шу тарангликдан халос қиладиган тана билан боғлиқ фаолият яхши мос келади: турли массажлар, гимнастика, сузиш. Шунингдек турли аффирмацияларни ёзиш қулай — бу тушкунликни олиб кетади ва меҳнатсеварлик учун туртки беради.","Таким людям важно жить там, где больше солнца.":"Бундай одамларга қуёш кўпроқ бўлган жойда яшаш муҳим.","Нужно обращать на все сферы жизни, рекомендована духовная практика.":"Ҳаётнинг барча соҳаларига эътибор бериш керак, маънавий амалиёт тавсия этилади.","У нумерологов я встречала разные трактовки этого числа проблем. Кто-то говорит, что 0 - это обнуление и все усилия в жизни будут давать нулевой результат. Кто-то пишет, что это пустота - у человека нет проблем. А кто-то уверяет, что проблемы идут сразу из всех сфер жизни. Кому верить? За свою практику я сделала огромное количество расчётов, и число проблем встречается довольно часто. О чём же НА САМОМ ДЕЛЕ оно говорит? ноль имеет форму круга, бесконечности, у него нет конца. Здесь заложен большой резерв. Человек может раскрыть потенциал, если будет внимательно следить за значением числа, держать его в плюсе.":"Нумерологларда бу муаммолар сонининг турли талқинларини учратганман. Кимдир 0 — бу нолга тушириш ва ҳаётдаги барча саъй-ҳаракатлар нол натижа беради дейди. Кимдир бу бўшлиқ — инсонда муаммо йўқ деб ёзади. Кимдир эса муаммолар ҳаётнинг барча соҳаларидан бирданига келади деб ишонтиради. Кимга ишониш керак? Амалиётим давомида улкан миқдорда ҳисоблар қилдим ва муаммолар сони анча тез-тез учрайди. У АСЛИДА нима ҳақида гапиради? ноль доира, чексизлик шаклига эга, унинг охири йўқ. Бу ерда катта заҳира мужассам. Агар инсон сон маъносини диққат билан кузатса, уни плюсда ушлаб турса, салоҳиятни оча олади.","Ноль в минусе: опустошает; негативно влияет на судьбу, стимулирует проявление негативных характеристик в дате рождения; гоняет человека по кругу одних и тех же проблем; склонность к разрушению себя: алкоголь, сигареты.":"Минусдаги ноль: бўшатади; тақдирга салбий таъсир қилади, туғилган санадаги салбий хусусиятларнинг намоён бўлишини рағбатлантиради; инсонни бир хил муаммолар доирасида айлантиради; ўзини вайрон қилишга мойиллик: алкоголь, сигареталар.","Ноль в плюсе означает отсутствие преград. Я всегда советую избегать разрушительных вещей, пагубных привычек и зависимостей, чтобы числа не уходили в минус.":"Плюсдаги ноль тўсиқларнинг йўқлигини англатади. Мен доим сонлар минусга кетмаслиги учун вайронкор нарсалар, зарарли одатлар ва қарамликлардан сақланишни маслаҳат бераман.","Если ваше число проблем - 0, то:":"Агар муаммолар сонингиз — 0 бўлса:","✅углубитесь в духовные практики - они помогут выйти из круга проблем и достичь высших целей в жизни;":"✅маънавий амалиётларга чуқурлашинг — улар муаммолар доирасидан чиқишга ва ҳаётда олий мақсадларга эришишга ёрдам беради;","✅служите благому делу, помогайте людям":"✅эзгу ишга хизмат қилинг, одамларга ёрдам беринг","✅счастье будет тесно связано с возможностью посвятить себя крупномасштабным целям, служить всему человечеству.":"✅бахт ўзини кенг кўламли мақсадларга бағишлаш, бутун инсониятга хизмат қилиш имконияти билан яқин боғлиқ бўлади.","Указывает на то, что проблема не понятная, как будто внезапное обнуление, т.е. неясно, что улучшать. Поэтому нужно обращать внимание на все сферы жизни, особенно здесь рекомендована духовная практика.":"Муаммо тушунарсиз эканини, гўё тўсатдан нолга тушириш, яъни нимани яхшилаш ноаниқ эканини кўрсатади. Шунинг учун ҳаётнинг барча соҳаларига эътибор бериш керак, айниқса бу ерда маънавий амалиёт тавсия этилади.","циклы жизни":"ҳаёт цикллари","Обретение собственной независимости, отстаивание границ. Такого человека будет обуревать желание постоянно как-то себя выражать через одежду, внешний вид. Он будет становиться более самодостаточным и независящим от мнения окружающих. Также человек начнет ставить себя на первое место, в нем будет расти эгоизм и эгоцентризм.":"Ўз мустақиллигига эришиш, чегараларни ҳимоя қилиш. Бундай инсонни ўзини доим қандайдир кийим, ташқи кўриниш орқали ифода этиш истаги қамраб олади. У ўзига етарлироқ ва атрофдагиларнинг фикрига боғлиқ бўлмаган бўлиб боради. Шунингдек инсон ўзини биринчи ўринга қўя бошлайди, унда худбинлик ва эгоцентризм ўсади.","Эмоциональный и чувствительный период. Человек становиться впечатлительным, чутким, заботливым, мягким.":"Ҳиссиётли ва сезгир давр. Инсон таъсирчан, сезгир, ғамхўр, юмшоқ бўлиб қолади.","В Ведической астрологии Луна – это самая главная планета, потому что это наш ум и психика – от состояния нашего ума и мыслей зависит все. Поэтому в период Луны человек становится очень уязвимым: остро чувствует происходящие события, часто меняется настроение, принимает близко к сердцу какие-то даже мелкие проблемы.":"Ведик астрологияда Ой — энг асосий сайёра, чунки бу бизнинг ақл ва руҳиятимиз — ҳамма нарса ақлимиз ва фикрларимиз ҳолатига боғлиқ. Шунинг учун Ой даврида инсон жуда заиф бўлиб қолади: бўлаётган воқеаларни ўткир ҳис қилади, кайфияти тез-тез ўзгаради, ҳатто қандайдир майда муаммоларни ҳам яқин олади.","Обучение, развитие, поиск духовного пути, увеличение благосостояния. Сам период Юпитера хороший для начала новых направлений в жизни, создания бизнеса, формирования отношений. Если человек еще занимается саморазвитием, духовными практиками, то позитивные плоды этого цикла могут значительно увеличиться. В этом периоде необходимо обязательно заботиться о детях, о младших.":"Ўқиш, ривожланиш, маънавий йўлни излаш, фаровонликни ошириш. Юпитер даврининг ўзи ҳаётда янги йўналишларни бошлаш, бизнес яратиш, муносабатларни шакллантириш учун яхши. Агар инсон яна ўз-ўзини ривожлантириш, маънавий амалиётлар билан шуғулланса, бу циклнинг ижобий самаралари сезиларли ошиши мумкин. Бу даврда фарзандлар, кичикларга албатта ғамхўрлик қилиш зарур.","Период успеха, славы, огромных возможностей и, в то же время, иллюзий, соблазнов, авангардность, вредные привычки, не уёмные желания. Нужна стабильность и духовная практика.":"Муваффақият, шуҳрат, улкан имкониятлар ва айни пайтда иллюзиялар, васвасалар, авангардлик, зарарли одатлар, жиловсиз истаклар даври. Барқарорлик ва маънавий амалиёт керак.","Активный и легкий период, прибыль, общение, путешествия, иностранные языки, в негативе — нервозность, истощение, ссоры с друзьями и родственниками, неразумные решения.":"Фаол ва енгил давр, фойда, мулоқот, саёҳатлар, чет тиллари, салбийда — асабийлик, толиқиш, дўстлар ва қариндошлар билан жанжаллар, оқилона бўлмаган қарорлар.","Наслаждения, общение и развитие отношений во всех сферах. Она олицетворяет собой чувства, эмоции, ее основная задача (в случае благоприятного положения) – дать опыт чувственного наслаждения. Однако важно знать, что когда Венера что-то дает, она не будет думать за человека о последствиях его желаний. В этот цикл появляются женские качества, физическая привлекательность, популярность. В негативе — уменьшение доходов, ссоры в отношениях, расставания и разводы, лень.":"Лаззатлар, мулоқот ва барча соҳаларда муносабатларнинг ривожланиши. У ҳислар, ҳис-туйғуларни ифода этади, унинг асосий вазифаси (қулай жойлашувда) — ҳиссий лаззат тажрибасини бериш. Бироқ Венера нимадир берганда, у инсон ўрнига унинг истакларининг оқибатлари ҳақида ўйламаслигини билиш муҳим. Бу циклда аёллик фазилатлари, жисмоний жозиба, машҳурлик пайдо бўлади. Салбийда — даромадлар камайиши, муносабатларда жанжаллар, айрилиқлар ва ажралишлар, дангасалик.","Время аналитики и погружения в свой внутренний мир, некая пассивность, период откровений и жизненных уроков. Цель периода Кету — напомнить человеку об истинных целях жизни, так как в погоне за финансами и работой человек может забывать знания, веру, вечную природу души. В цикле Кету склоняет человека к психологии, астрологии, эзотерике, мистике. Может потянуть в святые места, к духовной жизни. Кету может склонять к отречению от материального мира, потери интереса к удовольствиям и наслаждениям. Обязательно нужно искать в этот период смысл жизни, иначе Кету может проявиться в невежестве, как поиск на дне стакана, алкоголизм или другие одурманивающие вещества. Поэтому нужна духовная практика.":"Таҳлил ва ички дунёга шўнғиш вақти, қандайдир пассивлик, ваҳийлар ва ҳаётий сабоқлар даври. Кету даврининг мақсади — инсонга ҳаётнинг ҳақиқий мақсадларини эслатиш, чунки молия ва иш ортидан қувиб, инсон билимлар, эътиқод, руҳнинг абадий табиатини унутиши мумкин. Циклда Кету инсонни психология, астрология, эзотерика, мистикага мойил қилади. Муқаддас жойларга, маънавий ҳаётга тортиши мумкин. Кету моддий дунёдан воз кечишга, завқлар ва лаззатларга қизиқишни йўқотишга мойил қилиши мумкин. Бу даврда албатта ҳаёт маъносини излаш керак, акс ҳолда Кету жаҳолатда стакан тубидан излаш, алкоголизм ёки бошқа маст қилувчи моддалар сифатида намоён бўлиши мумкин. Шунинг учун маънавий амалиёт керак.","Высокий авторитет человека и большой прогресс в работе, трудолюбие. Успех в накоплении финансовых средств. В этот период человек может стать сдержанным и строгим, серьезным, аскетичным, придирчивым, помешанным на дисциплине. Может остро чувствоваться одиночество, депрессивность и различные страхи. В этот период все будет медленно.":"Инсоннинг юқори обрўси ва ишда катта тараққиёт, меҳнатсеварлик. Молиявий маблағлар жамғаришда муваффақият. Бу даврда инсон вазмин ва қаттиққўл, жиддий, зоҳид, эътирозчи, интизомга берилган бўлиб қолиши мумкин. Ёлғизлик, депрессивлик ва турли қўрқувлар ўткир ҳис қилиниши мумкин. Бу даврда ҳамма нарса секин бўлади.","Разгар активности и карьерного всплеска. У человека возрастает уверенность, вспыльчивость, упрямство, появляется желание заняться спортом.":"Фаоллик ва карьера кўтарилишининг авжи. Инсонда ишонч, жаҳлдорлик, қайсарлик ошади, спорт билан шуғулланиш истаги пайдо бўлади.","+ Позитивный Марс – это смелость, энергичность, логика, сила воли. Человек будет хотеть командовать, управлять, завоевывать. Благоприятно, если человек связан с медициной, особенно с хирургией, спортом, управлением, инструментами и механикой, а также с бизнесом.":"+ Ижобий Марс — бу жасорат, ғайратлилик, мантиқ, ирода кучи. Инсон буйруқ бериш, бошқариш, забт этишни истайди. Агар инсон тиббиёт, айниқса жарроҳлик, спорт, бошқарув, асбоблар ва механика, шунингдек бизнес билан боғлиқ бўлса, қулай.","– В негативе Марс будет проявлять агрессивность, неорганизованность, вспыльчивость, конфликтность.":"– Салбийда Марс тажовузкорлик, уюшмаганлик, жаҳлдорлик, низоликни намоён қилади.","по годам,что делать":"йиллар бўйича, нима қилиш керак","*ставить цели; *увеличивать уверенность; * брать ответственность за кого-то ; * попусту не тратить время, соблюдать режим дня; * налаживать отношения с отцом.":"*мақсадлар қўйиш; *ишончни ошириш; * кимдир учун масъулиятни олиш; * вақтни беҳуда сарфламаслик, кун тартибига риоя қилиш; * ота билан муносабатларни созлаш.","* благотворительность, забота ; * изучение психологии и ума ; * отношения с мамой ; * женские клубы":"* хайрия, ғамхўрлик; * психология ва ақлни ўрганиш; * она билан муносабатлар; * аёллар клублари","Юпитер":"Юпитер","* лучший год ; * повышение уровня мудрости (духовность, законы мира) ; * благосостояние ; * забота о детях.":"* энг яхши йил; * донолик даражасини ошириш (маънавият, дунё қонунлари); * фаровонлик; * фарзандларга ғамхўрлик.","Раху":"Раҳу","* планировать жизнь, структуру и последовательность жизни ; * эзотерика, йога, духовные практики ; * исключить искусственные вещи":"* ҳаётни, ҳаётнинг тузилмаси ва изчиллигини режалаштириш; * эзотерика, йога, маънавий амалиётлар; * сунъий нарсаларни истисно қилиш","Меркурий":"Меркурий","* образование, книги, интеллект; * внимательность и концентрация; * все упорядочить; * избавляться от старых вещей; * развивать речь":"* таълим, китоблар, интеллект; * эътиборлилик ва диққатни жамлаш; * ҳаммасини тартибга солиш; * эски нарсалардан қутулиш; * нутқни ривожлантириш","Венера":"Венера","* отношения ; * творческое развитие ; * повышение комфорта в жизни ; * избавляться от плохих привязанностей":"* муносабатлар; * ижодий ривожланиш; * ҳаётда қулайликни ошириш; * ёмон боғланишлардан қутулиш","Кету":"Кету","* духовное развитие ; * эзотерика ; * раскрытие личности ; * общение с духовными людьми.":"* маънавий ривожланиш; * эзотерика; * шахсиятни очиш; * маънавий одамлар билан мулоқот.","Сатурн":"Сатурн","* нужно трудиться, не ленится ; * терпение, серьезность ; * дисциплина, последовательность ; * тайм менеджмент ; * аскеза для тела (уважение старших, поклоны) ума (чувства и эмоции) и речи (не болтовня).":"* меҳнат қилиш, дангасалик қилмаслик керак; * сабр, жиддийлик; * интизом, изчиллик; * тайм-менежмент; * тана (катталарга ҳурмат, таъзимлар), ақл (ҳислар ва ҳис-туйғулар) ва нутқ (сергапликсиз) учун зоҳидлик.","Марс":"Марс","* для бизнеса, для личностного роста ; * спорт ; * внимательность на дороге ; * отдача энергии.":"* бизнес учун, шахсий ўсиш учун; * спорт; * йўлда эътиборлилик; * энергия бериш.","1 ый психотип Брахман.":"1-психотип Браҳман.","Они постигают суть вещей. Они не могут существовать без книг, у них постоянный информационный голод и научный склад ума. Они получают и передают знания.":"Улар нарсаларнинг моҳиятини англайди. Улар китобларсиз мавжуд бўла олмайди, уларда доимий маълумот очлиги ва илмий ақл бор. Улар билим олади ва етказади.","В минусе: Гордость, не принимают советов, знают все лучше других, аферы – сильный разум.":"Минусда: Ғурур, маслаҳатларни қабул қилмайди, ҳаммасини бошқалардан яхшироқ билади, фирибгарликлар — кучли ақл.","Кшатрий – тот, кто защищает от боли.":"Кшатрий — оғриқдан ҳимоя қиладиган.","Любят управлять, создавать структуру, расставлять все на места. У них есть внутренний стержень и чувство собственного достоинства. У них огромный организаторский потенциал. Они готовы принимать решения, приводить людей к результату, они несут ответственность за людей за коллектив.":"Бошқаришни, тузилма яратишни, ҳаммасини жой-жойига қўйишни яхши кўради. Уларда ички ўзак ва ўз қадр-қиммати ҳисси бор. Уларда улкан ташкилотчилик салоҳияти бор. Улар қарор қабул қилишга, одамларни натижага олиб боришга тайёр, одамлар учун, жамоа учун масъулиятни кўтаради.","В минусе: Использование силы для разрушения, гнев и гордость.":"Минусда: Кучдан вайрон қилиш учун фойдаланиш, ғазаб ва ғурур.","Отвечают за торговлю и обмен. Они снабжают, распределяет и обеспечивают. Занимаются банковским делом. Они коммуникабельные, предприимчивые, гибкие, дипломатичные, могут из любой ситуации извлечь прибыль. Их задача заниматься благотворительностью.":"Савдо ва айирбошлаш учун жавоб беради. Улар таъминлайди, тақсимлайди ва етказиб беради. Банк иши билан шуғулланади. Улар киришимли, ишбилармон, мослашувчан, дипломатик, ҳар қандай вазиятдан фойда чиқара олади. Уларнинг вазифаси хайрия билан шуғулланиш.","В минусе : Хитрость и обман, жульничество, жадность, накопление денег.":"Минусда: Айёрлик ва алдов, фирибгарлик, очкўзлик, пул жамғариш.","Творцы, ремесленники, мастера, служащие, рабочие. Обожают свое дело, делают что-то руками. У них огромный творческий потенциал. Трудно принимают решение, поэтому им нужно руководство., Они служат другим.":"Ижодкорлар, ҳунармандлар, усталар, хизматчилар, ишчилар. Ўз ишини жуда яхши кўради, қўли билан нимадир қилади. Уларда улкан ижодий салоҳият бор. Қарорни қийин қабул қилади, шунинг учун уларга раҳбарлик керак. Улар бошқаларга хизмат қилади.","В минусе : Лень, человек, который делает что-то из под палки, склонность к одурманивающим веществам, сентиментальный, обидчивый.":"Минусда: Дангасалик, нимадир таёқ остида қиладиган инсон, маст қилувчи моддаларга мойиллик, сентиментал, аразчи.","Интегральное число":"Интеграл сон","•уважать отца, мужа, начальника":"•ота, эр, бошлиқни ҳурмат қилиш","•жить в соответствии с режимом дня":"•кун тартибига мувофиқ яшаш","•развивать самодисциплину, великодушие, чувство собственного достоинства":"•ўзини интизомга солиш, олижаноблик, ўз қадр-қиммати ҳиссини ривожлантириш","•посещать храм":"•ибодатхонага бориш","•делать пожертвование по воскресениям духовным людям и организациям":"•якшанба кунлари маънавий одамлар ва ташкилотларга эҳсон қилиш","•почитание матери, дарить подарки маме и старшим женщинам":"•онани эъзозлаш, онага ва катта аёлларга совғалар қилиш","•психоанализ, медитации, духовная практика":"•психоанализ, медитациялар, маънавий амалиёт","•общение и забота о детях (особенно до 4х лет)":"•болалар билан мулоқот ва уларга ғамхўрлик (айниқса 4 ёшгача)","•внимательное отношение к поступкам и словам, чтобы не доставлять беспокойства другим":"•бошқаларни безовта қилмаслик учун қилмишлар ва сўзларга эътиборли муносабат","•желание перемен в сознании":"•онгда ўзгаришлар истаги","•учеба и преподавание актуальных знаний":"•долзарб билимларни ўқиш ва ўқитиш","•зачатие и забота о детях":"•ҳомиладорлик ва болаларга ғамхўрлик","•чтение духовных книг и слушание лекции":"•маънавий китоблар ўқиш ва маърузалар тинглаш","•служение и забота о учителях":"•устозларга хизмат ва ғамхўрлик","• развитие смелости и бесстрашия перед страхами":"• жасорат ва қўрқувлар олдида қўрқмасликни ривожлантириш","• отказ от одурманивающих средств":"• маст қилувчи воситалардан воз кечиш","• общаться с иностранцами, изучать иностранные языки и другие культуры":"• чет элликлар билан мулоқот қилиш, чет тиллари ва бошқа маданиятларни ўрганиш","• избегать слишком сильных впечатлений":"• ҳаддан ташқари кучли таассуротлардан сақланиш","•чтение нравственных книг":"•ахлоқий китоблар ўқиш","•учиться красиво и вдохновенно говорить":"•чиройли ва илҳом билан гапиришни ўрганиш","•общение со студентами, благоприятно жертвовать студентам для их дальнейшего образования":"•талабалар билан мулоқот, талабаларга кейинги таълими учун эҳсон қилиш қулай","•изучение и анализ, лучше изучать наследие мудрецов":"•ўрганиш ва таҳлил, донишмандлар меросини ўрганган яхшироқ","•ставить цель и жить в соответствии с ней":"•мақсад қўйиш ва унга мувофиқ яшаш","•развитие творческих способностей":"•ижодий қобилиятларни ривожлантириш","•общение с женщинами":"•аёллар билан мулоқот","•наслаждаться пищей, одеждой, общением с людьми в гуне благости":"•эзгулик гунасида овқат, кийим, одамлар билан мулоқотдан завқланиш","•воспитывать в себе утонченность и чувствительность, чуткость и способность любить":"•ўзида нафислик ва сезгирлик, ҳамдардлик ва сева олиш қобилиятини тарбиялаш","•супружеская верность на всех уровнях":"•барча даражаларда эр-хотинлик садоқати","•психоанализ":"•психоанализ","•посещение отдаленных, спокойных храмов и мест паломничества":"•узоқ, тинч ибодатхоналар ва зиёрат жойларига бориш","•общение с отреченными, умудренными опытом людьми (монахами, старцами)":"•дунёдан воз кечган, тажриба орттирган донишманд одамлар (роҳиблар, пирлар) билан мулоқот","•ведение дневника":"•кундалик юритиш","•работа с комплексами и запретами":"•комплекслар ва тақиқлар билан ишлаш","•учиться избавляться от ненужных вещей":"•кераксиз нарсалардан қутулишни ўрганиш","•развитие дисциплины и пунктуальности":"•интизом ва аниқликни ривожлантириш","•избегать эмоциональных всплесков, стрессовых и напряженный ситуаций":"•ҳиссий портлашлар, стрессли ва таранг вазиятлардан сақланиш","•давать себе и другим обеты и обещания":"•ўзига ва бошқаларга назрлар ва ваъдалар бериш","•заниматься йогой":"•йога билан шуғулланиш","•делать подарки и подношения духовным людям":"•маънавий одамларга совғалар ва назрлар қилиш","•занятия спортом, развитие силы и воли":"•спорт билан шуғулланиш, куч ва иродани ривожлантириш","•ахимса – жизнь без насилия":"•ахимса — зўравонликсиз ҳаёт","•защита слабых (женщин, стариков, детей, неразумных людей)":"•заифларни (аёллар, қариялар, болалар, ақлсиз одамлар) ҳимоя қилиш","•рациональное мышление, здравомыслие":"•рационал фикрлаш, соғлом фикр","•необходима разумная и гибкая дисциплина на всех уровнях жизни":"•ҳаётнинг барча даражаларида оқилона ва мослашувчан интизом зарур","Варны:":"Варналар:","Дживы":"Джива","Кармы":"Карма","Брахман – это 3,6":"Браҳман — бу 3,6","Кшатрий 1,9.":"Кшатрий 1,9.","Вайшья 2,5":"Вайшья 2,5","Шудра 4,7,8.":"Шудра 4,7,8.","1(число дживы);":"1(джива сони);","2(число дживы);":"2(джива сони);","3(число дживы);":"3(джива сони);","4(число дживы);":"4(джива сони);","5(число дживы);":"5(джива сони);","6(число дживы);":"6(джива сони);","7(число дживы);":"7(джива сони);","8(число дживы);":"8(джива сони);","9(число дживы);":"9(джива сони);","1(месяц);":"1(ой);","2(месяц);":"2(ой);","3(месяц);":"3(ой);","4(месяц);":"4(ой);","5(месяц);":"5(ой);","6(месяц);":"6(ой);","7(месяц);":"7(ой);","8(месяц);":"8(ой);","9(месяц);":"9(ой);","1(год);":"1(йил);","2(год);":"2(йил);","3(год);":"3(йил);","4(год);":"4(йил);","5(год);":"5(йил);","6(год);":"6(йил);","7(год);":"7(йил);","8(год);":"8(йил);","9(год);":"9(йил);","1(число кармы);":"1(карма сони);","2(число кармы);":"2(карма сони);","3(число кармы);":"3(карма сони);","4(число кармы);":"4(карма сони);","5(число кармы);":"5(карма сони);","6(число кармы);":"6(карма сони);","7(число кармы);":"7(карма сони);","8(число кармы);":"8(карма сони);","9(число кармы);":"9(карма сони);","(Число Дживы)":"(Джива сони)","(Месяц)":"(Ой)","(Год)":"(Йил)","(Число Кармы)":"(Карма сони)","Брахман:":"Браҳман:","переделать цвет 3":"3-рангни ўзгартириш","-если это значение то цветом 3":"-агар бу қиймат бўлса, 3-ранг билан","сделала":"бажардим","-если это значение то цветом 2":"-агар бу қиймат бўлса, 2-ранг билан","-если это значение то цветом 1":"-агар бу қиймат бўлса, 1-ранг билан","147 – дает фундамент того, на сколько человек себя чувствует в мире стабильно.":"147 — инсон ўзини дунёда қанчалик барқарор ҳис қилишининг пойдеворини беради.","Это самоидентификация, возможность и мудрость.":"Бу ўзини аниқлаш, имконият ва донолик.","258 – дает способность достигать целей.":"258 — мақсадларга эришиш қобилиятини беради.","Это ум и отношения, интеллект, трудолюбие и реализация.":"Бу ақл ва муносабатлар, интеллект, меҳнатсеварлик ва рўёбга чиқиш.","369 – дает линию расширения, развития, увеличения.":"369 — кенгайиш, ривожланиш, ўсиш чизиғини беради.","Это реализация идей, материальная поддержка и энергия для действий.":"Бу ғояларни амалга ошириш, моддий қўллаб-қувватлаш ва ҳаракатлар учун энергия.","123 – способность строить и реализовывать планы.":"123 — режалар қуриш ва амалга ошириш қобилияти.","654 – хорошо для материального благосостояния":"654 — моддий фаровонлик учун яхши","789 – возможность преодолеть трудности":"789 — қийинчиликларни енгиш имконияти","159 – самое лучшее для успеха.":"159 — муваффақият учун энг яхшиси.","Это сам человек и его ответственность за жизнь, интеллект, связи, гибкость, решимость и энергия.":"Бу инсоннинг ўзи ва унинг ҳаёт учун масъулияти, интеллект, алоқалар, мослашувчанлик, қатъият ва энергия.","357 – для развития интеллектуальной деятельности":"357 — интеллектуал фаолиятни ривожлантириш учун","2 – 4 - Интуитивные способности":"2 – 4 - Интуитив қобилиятлар","2 – 6 - Отношения и благосостояние":"2 – 6 - Муносабатлар ва фаровонлик","6 – 8 - Деньги, бизнес, успех.":"6 – 8 - Пул, бизнес, муваффақият.","4 – 8 - Желания, трудолюбие, успех":"4 – 8 - Истаклар, меҳнатсеварлик, муваффақият","Дает фундамент того, на сколько человек себя чувствует в мире стабильно. Это самоидентификация, возможность и мудрость.":"Инсон ўзини дунёда қанчалик барқарор ҳис қилишининг пойдеворини беради. Бу ўзини аниқлаш, имконият ва донолик.","Дает способность достигать целей. Это ум и отношения, интеллект, трудолюбие и реализация.":"Мақсадларга эришиш қобилиятини беради. Бу ақл ва муносабатлар, интеллект, меҳнатсеварлик ва рўёбга чиқиш.","Дает линию расширения, развития, увеличения. Это реализация идей, материальная поддержка и энергия для действий.":"Кенгайиш, ривожланиш, ўсиш чизиғини беради. Бу ғояларни амалга ошириш, моддий қўллаб-қувватлаш ва ҳаракатлар учун энергия.","Говорит о том, что человек может строить планы и способен их достичь.":"Инсон режалар қура олиши ва уларга эриша олишини айтади.","Это сознание человека, инициатива, ум, планирование и расширение.":"Бу инсоннинг онги, ташаббус, ақл, режалаштириш ва кенгайиш.","Хорошее сочетание для материального благосостояния. Это расширение, возможности, интеллект, бизнес, предприимчивость, комфорт и деньги.":"Моддий фаровонлик учун яхши уйғунлик. Бу кенгайиш, имкониятлар, интеллект, бизнес, ишбилармонлик, қулайлик ва пул.","Дает возможность преодолеть трудности.":"Қийинчиликларни енгиш имкониятини беради.","Это мудрость, проницательность, труд, дисциплина, продвижение, стабильность и энергия для преодолений.":"Бу донолик, зийраклик, меҳнат, интизом, илгарилаш, барқарорлик ва енгиш учун энергия.","Самое лучшее для успеха. Это сам человек и его ответственность за жизнь, интеллект, связи, гибкость, решимость и энергия.":"Муваффақият учун энг яхшиси. Бу инсоннинг ўзи ва унинг ҳаёт учун масъулияти, интеллект, алоқалар, мослашувчанлик, қатъият ва энергия.","Очень хорошее для развития интеллектуальной деятельности. Это расширение, знание, мудрость, интеллект, разнообразие жизни, общение, проницательность.":"Интеллектуал фаолиятни ривожлантириш учун жуда яхши. Бу кенгайиш, билим, донолик, интеллект, ҳаётнинг хилма-хиллиги, мулоқот, зийраклик.","2 – 4 -Интуитивные способности":"2 – 4 -Интуитив қобилиятлар","2 – 6 -Отношения и благосостояние":"2 – 6 -Муносабатлар ва фаровонлик","4-8 -Желания, трудолюбие, успех":"4-8 -Истаклар, меҳнатсеварлик, муваффақият","возраст:":"ёш:","СОВМЕСТИМОСТЬ:":"МОСЛИК:","ЧЖП партнёра":"Шерикнинг ДЖС","Год партнёра":"Шерикнинг йили","Месяц партнёра":"Шерикнинг ойи","день партнера":"шерикнинг куни","Число противоречий":"Зиддиятлар сони","Число союза":"Иттифоқ сони","про":"про","ворт":"ворт","фбл":"фбл","пдло":"пдло","фо":"фо","пижрфл":"пижрфл","ылтои":"ылтои","сть":"сть","ЬОРУ":"ЬОРУ","па":"па","то":"то","торм":"торм","б":"б","ьрм":"ьрм","с":"с","ч":"ч","д":"д","Число Дхармы":"Дхарма сони","Рекомендации":"Тавсиялар","Уделяйте больше внимания своим финансам и избегайте тратить деньги на бессмысленные шоу, покупать дорогие подарки или одалживать деньги другим. Не стоит играть в финансовые авантюры. Не принимайте поспешных решений, так как они могут привести к неудачам.":"Молиянгизга кўпроқ эътибор беринг ва пулни маъносиз шоуларга сарфлаш, қиммат совғалар сотиб олиш ёки бошқаларга қарз беришдан сақланинг. Молиявий таваккалчиликларга кирманг. Шошилинч қарорлар қабул қилманг, чунки улар омадсизликларга олиб келиши мумкин.","Соблюдайте целибат:":"Целибатга риоя қилинг:","– от любых «слишком», «чересчур»":"– ҳар қандай «ҳаддан ташқари», «ортиқча»дан","– лени":"– дангасаликдан","– тщеславия, эгоизма":"– шуҳратпарастлик, худбинликдан","– безответственности":"– масъулиятсизликдан","– жадности, радости от страданий других людей":"– очкўзлик, бошқа одамларнинг азобларидан қувонишдан","– обида на других":"– бошқаларга хафаликдан","– враждебность/отчуждение":"– душманлик/бегоналашишдан","– высокомерие":"– кибрдан","– неуважение к отцу и мужчинам в целом":"– ота ва умуман эркакларга ҳурматсизликдан","– длительный гнев":"– узоқ давом этадиган ғазабдан","– беззаботность.":"– бепарволикдан.","– Не будьте пассивны и нерешительны":"– Пассив ва қатъиятсиз бўлманг","– не бойтесь влюбиться":"– севиб қолишдан қўрқманг","– научитесь быть независимым и не жертвовать своим временем ради помощи другим, когда это вредит вам":"– мустақил бўлишни ва бошқаларга ёрдам бериш учун вақтингизни сизга зарар етказганда қурбон қилмасликни ўрганинг","– доводите дела до конца, даже когда теряете вдохновение":"– илҳомни йўқотганингизда ҳам ишларни охирига етказинг","– придерживайтесь только собственных решений и выбора":"– фақат ўз қарорларингиз ва танловингизга амал қилинг","– не заходите в глубокие водоемы и не окунайтесь":"– чуқур сув ҳавзаларига кирманг ва шўнғиманг","– начните медитировать, чтобы успокоить неспокойный ум":"– безовта ақлни тинчлантириш учун медитация қила бошланг","– научитесь не поддаваться влиянию людей, которые вам льстят, и говорить «нет» тем, кто груб":"– сизга хушомад қиладиган одамлар таъсирига берилмасликни ва қўполларга «йўқ» дейишни ўрганинг","– прислушивайтесь к тому, что требует и хочет есть ваше тело, и следуйте этому":"– танангиз нимани талаб қилаётганини ва нимани ейишни истаётганини тингланг ва унга амал қилинг","– будьте внимательны к дружбе с противоположным полом. Однако люди с числом 2 эмоциональны и чувствительны и склонны тратить энергию впустую, когда эмоционально возбуждены":"– қарама-қарши жинс билан дўстликда эътиборли бўлинг. Бироқ 2 сонли одамлар ҳиссиётли ва сезгир бўлиб, ҳиссий қўзғалганда энергияни беҳуда сарфлашга мойил","– избегайте принятия эмоциональных решений":"– ҳиссий қарорлар қабул қилишдан сақланинг","– Избегайте обществ людей с низкими вибрациями":"– Паст тебранишли одамлар жамиятидан сақланинг","– контролируйте свой темперамент":"– темпераментингизни назорат қилинг","– создавайте подушку безопасности на будущее":"– келажак учун хавфсизлик ёстиғи яратинг","– избегайте переедания и употребления тяжелой или слишком острой пищи. Печенью управляет Юпитер и является покровителем людей с числом 3. Эти люди используют энергию печени, поэтому следует избегать тяжелой для печени пищи":"– ортиқча овқатланиш ва оғир ёки ўта аччиқ овқатни истеъмол қилишдан сақланинг. Жигарни Юпитер бошқаради ва у 3 сонли одамларнинг ҳомийси. Бу одамлар жигар энергиясидан фойдаланади, шунинг учун жигар учун оғир овқатдан сақланиш керак","– контролируйте гнев, страсть и чувствительность":"– ғазаб, эҳтирос ва сезгирликни назорат қилинг","– избегайте чрезмерного оптимизма и амбициозности":"– ҳаддан ташқари оптимизм ва шуҳратпарастликдан сақланинг","– не пугайтесь незначительных трудностей":"– арзимас қийинчиликлардан қўрқманг","– будьте терпеливы":"– сабрли бўлинг","– помните о своих автократических тенденциях в доме и давайте свободу другим членам семьи":"– уйдаги автократик майлларингизни ёдда тутинг ва оиланинг бошқа аъзоларига эркинлик беринг","– дорожите своим спутником жизни":"– ҳаёт ҳамроҳингизни қадрланг","– работайте над избавлением от гордыни":"– кибрдан қутулиш устида ишланг","– не зарабатывайте деньги незаконным путем":"– пулни ноқонуний йўл билан топманг","– путешествуйте, когда чувствуете себя плохо или находитесь в сложной ситуации":"– ўзингизни ёмон ҳис қилганда ёки мураккаб вазиятда бўлганингизда саёҳат қилинг","– знайте, когда нужно расслабиться и не брать на себя больше работы или ответственности, чем вы способны выполнить.":"– қачон бўшашиш кераклигини ва бажара оладиганингиздан ортиқ иш ёки масъулиятни олмасликни билинг.","– Избегайте ненужных споров":"– Кераксиз баҳслардан сақланинг","– вырабатывайте лояльное отношение к жизни и больше доверяйте людям":"– ҳаётга содиқ муносабатни ишлаб чиқинг ва одамларга кўпроқ ишонинг","– чаще будьте спокойны":"– тез-тез хотиржам бўлинг","– учитесь понимать других":"– бошқаларни тушунишни ўрганинг","– откажитесь от эгоизма и научитесь оказывать бескорыстную услугу":"– худбинликдан воз кечинг ва беғараз хизмат кўрсатишни ўрганинг","– избегайте ненужных расходов и откладывайте деньги на черный день или на пенсию":"– кераксиз харажатлардан сақланинг ва қора кун ёки пенсия учун пул жамғаринг","– научитесь быстро принимать самостоятельные решения":"– тез мустақил қарорлар қабул қилишни ўрганинг","– не критикуйте других":"– бошқаларни танқид қилманг","– умейте не давать ложных надежд и обещаний и старайтесь быть более откровенным и уметь говорить «нет», когда вы не можете сделать что-то для других, вместо того чтобы говорить «да» и ничего не делать":"– ёлғон умидлар ва ваъдалар бермасликни билинг ва очиқроқ бўлишга ва бошқалар учун нимадир қила олмаганингизда «ҳа» деб ҳеч нарса қилмаслик ўрнига «йўқ» дея олишга ҳаракат қилинг","– не доверять другим слепо":"– бошқаларга кўр-кўрона ишонмаслик","– избегайте одиночества, самоотключения от реальности и бесцельных путешествий":"– ёлғизлик, ҳақиқатдан ўзини узиш ва мақсадсиз саёҳатлардан сақланинг","– умейте медитировать и делать успокаивающие упражнения":"– медитация қилиш ва тинчлантирувчи машқлар бажаришни билинг","– Цените свое чувство юмора и веселый характер":"– Юмор ҳисси ва қувноқ характерингизни қадрланг","– во время злости, не будьте саркастичны":"– жаҳлингиз чиққанда истеҳзоли бўлманг","– научитесь не быть чрезмерно критичным":"– ҳаддан ташқари танқидий бўлмасликни ўрганинг","– избегайте стрессов, учащенного сердцебиения и нервных срывов":"– стресслар, юрак тез уриши ва асаб бузилишларидан сақланинг","– не сторонитесь детей, не избегайте веселья":"– болалардан узоқлашманг, кўнгилхушликдан қочманг","– научитесь замедляться, не спешить, не суетиться":"– секинлашишни, шошилмасликни, ғимирламасликни ўрганинг","– не будьте осуждающими":"– қораловчи бўлманг","– научитесь спокойствию и неподвижности ума из бесконечной медитации":"– чексиз медитациядан ақлнинг хотиржамлиги ва ҳаракатсизлигини ўрганинг","– будьте терпеливее с семьей и друзьями":"– оила ва дўстлар билан сабрлироқ бўлинг","– избегайте фатализма, будьте добры к другим":"– фатализмдан сақланинг, бошқаларга меҳрибон бўлинг","– делайте массаж тела не менее двух раз в неделю, чтобы укрепить нервы и улучшить обмен веществ":"– асабларни мустаҳкамлаш ва моддалар алмашинувини яхшилаш учун ҳафтада камида икки марта тана массажи қилинг","– занимайтесь ручным трудом, например, садоводством, чтобы успокоить беспокойный ум. Относитесь к друзьям и цените других":"– безовта ақлни тинчлантириш учун қўл меҳнати, масалан, боғдорчилик билан шуғулланинг. Дўстларга муносабатда бўлинг ва бошқаларни қадрланг","– Не будьте ленивыми":"– Дангаса бўлманг","– не будьте удобным и говорите «нет», когда вам хочется доверяй, но проверяй, не будь легковерным, но научись доверять людям, которые того стоят":"– қулай бўлманг ва хоҳлаганингизда «йўқ» денг; ишон, лекин текшир, соддадил бўлма, лекин бунга арзийдиган одамларга ишонишни ўрган","– работайте медленнее и работайте лучше. Избегайте излишнего напора, так как это разрушает проекты":"– секинроқ ва яхшироқ ишланг. Ортиқча тазйиқдан сақланинг, чунки бу лойиҳаларни вайрон қилади","– избегайте чрезмерной важности и эмоциональной привязанности к сексуальным партнерам":"– жинсий шерикларга ортиқча аҳамият бериш ва ҳиссий боғланишдан сақланинг","– избегайте мести":"– қасосдан сақланинг","– избегайте вредных привычек, так как они быстро вызывают привыкание":"– зарарли одатлардан сақланинг, чунки улар тез қарамлик туғдиради","– избегайте неверности и большого количества любовников":"– хиёнат ва кўп ошиқлардан сақланинг","– хорошо проводите время и организуйте свою жизнь":"– вақтни яхши ўтказинг ва ҳаётингизни ташкил қилинг","– создайте подушку безопасности.":"– хавфсизлик ёстиғи яратинг.","– Прежде чем браться за проект, тщательно вникните в его суть":"– Лойиҳага киришишдан олдин унинг моҳиятини синчиклаб тушуниб олинг","– умейте тщательно оценивать ситуации":"– вазиятларни синчиклаб баҳолашни билинг","– будьте открыты к переменам и уважайте прошлое, если перемены произошли":"– ўзгаришларга очиқ бўлинг ва агар ўзгаришлар юз берган бўлса, ўтмишни ҳурмат қилинг","– умейте быть самодостаточным и независимым":"– ўзига етарли ва мустақил бўлишни билинг","– избегайте смотреть на жизнь сквозь розовые очки":"– ҳаётга пушти кўзойнак орқали қарашдан сақланинг","– не становиться сентиментальным или слишком вовлеченным в чувства других людей":"– сентиментал бўлмаслик ёки бошқа одамларнинг ҳисларига ҳаддан ташқари аралашиб кетмаслик","– учитесь избегать суетливости и беспокойства":"– ғимирлаш ва хавотирдан сақланишни ўрганинг","– избегайте зависимости":"– қарамликдан сақланинг","– выработайте уважительное и дружелюбное отношение к партнеру, к мужу и жене, которые помогают вам расти и освобождают вас от бытовых проблем":"– сизга ўсишга ёрдам берадиган ва маиший муаммолардан халос қиладиган шерик, эр ва хотинга ҳурматли ва дўстона муносабатни ишлаб чиқинг","– избегайте водных видов спорта, глубоководных и лодочных прогулок":"– сув спорт турлари, чуқур сувда ва қайиқда сайрлардан сақланинг","– умейте расслабляться и вносить изменения последовательно, а не резко.":"– бўшашишни ва ўзгаришларни кескин эмас, изчил киритишни билинг.","– Научитесь делегировать то, что вам не по силам или не нравится":"– Кучингиз етмайдиган ёки ёқмайдиган нарсани вакил қилишни ўрганинг","– доверяйте нужным людям и своему ближайшему окружению":"– керакли одамларга ва энг яқин атрофингизга ишонинг","– научитесь четко и конкретно выражать свои взгляды, не ввязываясь в бессмысленные споры":"– маъносиз баҳсларга аралашмай, қарашларингизни аниқ ва конкрет ифода этишни ўрганинг","– узнавайте и расширяйте круг своих друзей, которые могут способствовать вашему росту, а не замыкаться в собственной скорлупе":"– ўз қобиғингизга ёпилиб олмай, ўсишингизга ёрдам бера оладиган дўстлар доирасини таниб олинг ва кенгайтиринг","– избегайте мстительности":"– қасоскорликдан сақланинг","– умейте улыбаться и наслаждаться моментом":"– жилмайишни ва лаҳзадан завқланишни билинг","– будьте активны и избегайте депрессии, пассивности и длительной изоляции":"– фаол бўлинг ва депрессия, пассивлик ва узоқ ажралишдан сақланинг","– будьте терпимы и дружелюбны, не срывайте злость на людях":"– бағрикенг ва дўстона бўлинг, жаҳлингизни одамларга сочманг","– избегайте вредных веществ":"– зарарли моддалардан сақланинг","– прислушивайтесь к советам тех, кто воплощает то, к чему вы стремитесь":"– сиз интилаётган нарсани ўзида мужассам этганларнинг маслаҳатларига қулоқ солинг","– умейте быть здесь и сейчас и выходить из прошлого на своих условиях":"– шу ерда ва ҳозир бўлишни ва ўтмишдан ўз шартларингиз бўйича чиқишни билинг","– уважайте своего партнера":"– шеригингизни ҳурмат қилинг","– путешествуйте":"– саёҳат қилинг","– не сплетничайте":"– ғийбат қилманг","– стремитесь быть другом и вкладывайте больше энергии в собственное духовное развитие.":"– дўст бўлишга интилинг ва ўз маънавий ривожланишингизга кўпроқ энергия киритинг.","– Избегайте мыслей о провокациях и мести":"– Иғволар ва қасос ҳақидаги фикрлардан сақланинг","– избегайте гордыни, лицемерия, зависти и критики":"– кибр, иккиюзламачилик, ҳасад ва танқиддан сақланинг","– развивайте в себе спокойствие и мужество":"– ўзингизда хотиржамлик ва жасоратни ривожлантиринг","– не совершайте необдуманных поступков, чтобы самоутвердиться":"– ўзингизни тасдиқлаш учун ўйламасдан қилмишлар қилманг","– не жалуйтесь, не критикуйте и не сплетничайте о коллегах или партнерах. Любите своего партнера, установите мир в своей домашней жизни и прощайте ошибки":"– ҳамкасблар ёки шериклар ҳақида шикоят қилманг, танқид қилманг ва ғийбат қилманг. Шеригингизни севинг, уй ҳаётингизда тинчлик ўрнатинг ва хатоларни кечиринг","– избегайте хирургического вмешательства":"– жарроҳлик аралашувидан сақланинг","– живите медленно и неторопливо":"– секин ва шошилмай яшанг","– улыбайтесь":"– жилмайинг","– уважайте других, избегайте конфликтов":"– бошқаларни ҳурмат қилинг, низолардан сақланинг","– избегайте нестабильных ситуаций":"– беқарор вазиятлардан сақланинг","– будьте дисциплинированы, соблюдайте порядок":"– интизомли бўлинг, тартибга риоя қилинг","– тщательно проверяйте свои документы":"– ҳужжатларингизни синчиклаб текширинг","– избегайте трех главных врагов: гнева, высокомерия и агрессии":"– учта асосий душмандан сақланинг: ғазаб, кибр ва тажовуз","– поощряйте общительность":"– киришимлиликни рағбатлантиринг","– цените юмор":"– юморни қадрланг","– избегайте вредных веществ.":"– зарарли моддалардан сақланинг.","Значения Числа дхармы":"Дхарма сонининг маънолари","Задача души – быть лидером.1 Солнце – это король, отец, начальник, менеджер, вокруг которого все вращаются, а он никого не выбирая светит для всех одинаково. Вы должны научиться брать на себя ответственность за себя и за других, не обвиняя никого в своих неудачах. Мужчинам особенно необходимо научиться брать на себя ответственность за свои семьи и группы, которые от них зависят. Женщины должны, по крайней мере, нести ответственность за себя и своих детей. Если они это сделают, то успех в жизни будет гарантирован.":"Руҳнинг вазифаси — етакчи бўлиш. 1 Қуёш — бу ҳамма атрофида айланадиган шоҳ, ота, бошлиқ, менежер, у эса ҳеч кимни танламай, ҳаммага бир хил нур сочади. Сиз ҳеч кимни омадсизликларингизда айбламай, ўзингиз ва бошқалар учун масъулиятни олишни ўрганишингиз керак. Эркакларга айниқса ўз оилалари ва уларга боғлиқ гуруҳлар учун масъулиятни олишни ўрганиш зарур. Аёллар ҳеч бўлмаганда ўзи ва фарзандлари учун масъулиятни кўтариши керак. Агар улар буни қилса, ҳаётда муваффақият кафолатланади.","Вы не должны переделывать других, подавлять их, обвинять их в своих проблемах, потому что вы сами их создали, позволив им случиться. Вы должны быть полны уверенности в себе, но при этом избегать эгоизма и высокомерия. Хороший способ проработки – вставать рано с солнцем, иметь хорошие отношения с отцом и начальником и принимать все решения самостоятельно, не перекладывая ответственность на других. Научитесь выполнять свои обещания и обязательства, не поддаваясь влиянию чужого мнения. Будьте благородным, щедрым и жизнерадостным человеком, который не делит людей по статусу или категориям, который светится и любит всех людей. Научитесь быть искренним и уважительным. Быть благодарным всем и вся за то, что у вас уже есть. Развивать чувство собственного достоинства, не унижаясь ради выгоды. Научитесь использовать только вещи, а не людей, иметь целеустремленность и реализовывать все, что вы хотите, не сходя со своего пути. Научитесь руководить, не наказывая и не причиняя вреда другим или себе, быть решительным и проявлять себя, несмотря на очевидную выгоду.":"Сиз бошқаларни қайта ясамаслигингиз, уларни бостирмаслигингиз, уларни муаммоларингизда айбламаслигингиз керак, чунки уларнинг содир бўлишига йўл қўйиб, уларни ўзингиз яратгансиз. Сиз ўзингизга ишончга тўла бўлишингиз, лекин бунда худбинлик ва кибрдан сақланишингиз керак. Ишлаб чиқишнинг яхши усули — қуёш билан эрта туриш, ота ва бошлиқ билан яхши муносабатда бўлиш ва масъулиятни бошқаларга юкламай, барча қарорларни мустақил қабул қилиш. Бировнинг фикри таъсирига берилмай, ваъдалар ва мажбуриятларингизни бажаришни ўрганинг. Одамларни мавқе ёки тоифаларга бўлмайдиган, нур сочадиган ва барча одамларни севадиган олижаноб, саховатли ва ҳаётсевар инсон бўлинг. Самимий ва ҳурматли бўлишни ўрганинг. Бор нарсангиз учун ҳамма ва ҳамма нарсадан миннатдор бўлиш. Фойда учун ўзини камситмай, ўз қадр-қиммати ҳиссини ривожлантириш. Одамлардан эмас, фақат нарсалардан фойдаланишни, мақсадга интилувчанликка эга бўлишни ва йўлингиздан тоймай, истаган ҳамма нарсани амалга оширишни ўрганинг. Бошқаларни ёки ўзингизни жазоламай ва зарар етказмай раҳбарлик қилишни, аниқ фойдага қарамай қатъиятли бўлиш ва ўзингизни намоён қилишни ўрганинг.","Будьте профессионалом. Таким образом, вас не будет беспокоить то, что говорят, и вы всегда будете уверены в себе. Любите себя таким, какой вы есть. Умейте быть счастливым с самим собой. В жизни бывают моменты, когда вы одиноки. Если вы умеете быть счастливым, независимо от внешнего мира, все встанет на свои места. Обратите внимание, что внешний мир – это отражение вашего подсознания, а это значит, что вы вольны выбирать, как жить дальше, выбирая правильные действия и реакции.":"Профессионал бўлинг. Шу тарзда сизни нима дейишлари безовта қилмайди ва сиз доим ўзингизга ишончли бўласиз. Ўзингизни қандай бўлсангиз шундайлигича севинг. Ўзингиз билан бахтли бўлишни билинг. Ҳаётда ёлғиз бўладиган пайтлар бўлади. Агар ташқи дунёдан қатъи назар бахтли бўлишни билсангиз, ҳаммаси жой-жойига тушади. Эътибор беринг, ташқи дунё — онг остингизнинг акси, бу эса тўғри ҳаракатлар ва реакцияларни танлаб, қандай яшашни эркин танлашингиз мумкинлигини англатади.","Задача души – научиться строить отношения, желательно со всеми людьми, каждым растением и деревом, а также со всеми животными в целом, в гармонии. Луна связана с эмоциями, чувствами, психологией, пониманием и состраданием. Для женщин с этим числом Дхармы при выборе между карьерой и любовью, или карьерой и отношениями, или работой и семьей лучше выбрать отношения и семью. Можно выбрать карьеру, если они ощущают что не могут не делать что-то в области глубин психики, эзотерики и чувствуют внутренний зов к проявленности в социуме по этим темам, а также у них уже вероятно должен быть ребенок (желательно). Для незамужних девушек важно найти хорошего мужа, быть в отношениях с гармоничным мужчиной и не вкладывать всю себя в карьерные достижения, чтобы жизнь была сбалансированной.":"Руҳнинг вазифаси — муносабатлар қуришни, яхшиси барча одамлар, ҳар бир ўсимлик ва дарахт, шунингдек умуман барча ҳайвонлар билан уйғунликда ўрганиш. Ой ҳис-туйғулар, ҳислар, психология, тушуниш ва ҳамдардлик билан боғлиқ. Бу Дхарма сонига эга аёллар учун карьера ва муҳаббат, ёки карьера ва муносабатлар, ёки иш ва оила ўртасида танлашда муносабатлар ва оилани танлаган яхшироқ. Агар улар руҳият чуқурликлари, эзотерика соҳасида нимадир қилмасликка қодир эмаслигини ҳис қилса ва бу мавзулар бўйича жамиятда намоён бўлишга ички даъватни сезса, шунингдек уларда эҳтимол аллақачон фарзанд бўлиши керак (яхшиси), карьерани танлаш мумкин. Турмушга чиқмаган қизлар учун ҳаёт мувозанатли бўлиши учун яхши эр топиш, уйғун эркак билан муносабатда бўлиш ва бутун ўзини карьера ютуқларига киритмаслик муҳим.","Девушки могут иметь низкую самооценку и думать, что они должны терпеть плохое отношение и дефицит, что они не могут брать деньги за свою работу или услуги. Они могут жертвовать собой там, где это не нужно, и делать это постоянно. Мужчинам важно научиться быть в гармонии со своими женами, подругами и всеми остальными женщинами в окружении, и тогда в их карьере все будет хорошо. Ладить с матерями, маленькими детьми, котятами и собаками, изучать психологию, узнавать о подсознании, пытаться понять свои чувства и дру- гих людей, уравновешивать свой разум и эмоции, обращаться к психологу, чтобы разрешить свои страхи и сомнения, и очень хорошо заботиться и понимать других – это хорошая трени- ровка. Ключевое слово здесь – «партнерство». Делайте правильный выбор, избавьтесь от сомнений, принимайте другого человека таким, какой он есть, научитесь отдавать в отношениях, но с достоинством. Отпустите ожидания и постарайтесь не быть эмоциональным. Иначе возникнут еще большие ожидания, которые могут не оправдаться, и вы будете разочарованы. Поступая так, вы сможете быть независимыми в отношениях. Помните о доверии, если вам изменяют, ваше доверие к другому человеку уменьшится, и вы извлечете из этого урок, а если это происходит постоянно, сделайте вывод, а не убеждайте себя, что так и должно быть. Даже если вы еще не влюблены, научитесь быть довольными собой и всегда стремитесь быть с парт- нером, другом или человеком, который находится в равновесии с вами во всем, что вы делаете. Научитесь контролировать свои эмоции и жить на 100%, не подавляя их. Живите от своего сердца, слушайте себя и живите легко. Научитесь чувствовать и ощущать, а не думать. Прислушивайтесь к своей интуиции и развивайте ее. Стремитесь к миру и покою, будьте матерью, если не для своих детей, то для всех, кто вас окружает. Не пейте кофе и алкоголь. Делайте все качественно и по расписанию. Пейте много воды в день и живите у воды или чаще ходите к ней.":"Қизлар паст ўзини баҳолашга эга бўлиши ва ёмон муносабат ва танқисликка чидашлари кераклигини, иши ёки хизматлари учун пул ола олмасликларини ўйлаши мумкин. Улар керак бўлмаган жойда ўзини қурбон қилиши ва буни доим қилиши мумкин. Эркакларга хотинлари, дугоналари ва атрофидаги барча бошқа аёллар билан уйғунликда бўлишни ўрганиш муҳим, шунда уларнинг карьерасида ҳаммаси яхши бўлади. Оналар, кичик болалар, мушукчалар ва итлар билан чиқишиш, психологияни ўрганиш, онг ости ҳақида билиш, ўзининг ва бошқа одамларнинг ҳисларини тушунишга уриниш, ақл ва ҳис-туйғуларни мувозанатлаш, қўрқув ва шубҳаларни ҳал қилиш учун психологга мурожаат қилиш ва бошқаларга жуда яхши ғамхўрлик қилиш ва тушуниш — яхши машқ. Бу ердаги калит сўз — «шериклик». Тўғри танлов қилинг, шубҳалардан қутулинг, бошқа инсонни қандай бўлса шундайлигича қабул қилинг, муносабатларда беришни, лекин қадр-қиммат билан ўрганинг. Кутишларни қўйиб юборинг ва ҳиссиётли бўлмасликка ҳаракат қилинг. Акс ҳолда оқланмаслиги мумкин бўлган янада катта кутишлар пайдо бўлади ва сизнинг ҳафсалангиз пир бўлади. Шундай йўл тутиб, муносабатларда мустақил бўла оласиз. Ишонч ҳақида ёдда тутинг, агар сизга хиёнат қилишса, бошқа инсонга ишончингиз камаяди ва сиз бундан сабоқ чиқарасиз, агар бу доим юз берса, ўзингизни шундай бўлиши керак деб ишонтирмай, хулоса чиқаринг. Ҳатто ҳали севиб қолмаган бўлсангиз ҳам, ўзингиздан мамнун бўлишни ўрганинг ва доим қилаётган ҳамма нарсангизда сиз билан мувозанатда бўлган шерик, дўст ёки инсон билан бўлишга интилинг. Ҳис-туйғуларингизни назорат қилишни ва уларни бостирмай, 100% яшашни ўрганинг. Юрагингиздан яшанг, ўзингизни тингланг ва енгил яшанг. Ўйлаш эмас, ҳис қилиш ва сезишни ўрганинг. Интуициянгизга қулоқ солинг ва уни ривожлантиринг. Тинчлик ва осойишталикка интилинг, ўз фарзандларингиз учун бўлмаса, атрофингиздаги ҳамма учун она бўлинг. Қаҳва ва алкоголь ичманг. Ҳаммасини сифатли ва жадвал бўйича қилинг. Кунига кўп сув ичинг ва сув ёнида яшанг ёки унга тез-тез боринг.","Работа души заключается в том, чтобы учиться, учить, передавать знания. Управляемое Юпитером, число 3 – это учитель, гуру и ученик. Вам необходимо постоянно двигаться вперед, стремиться, учиться, практиковаться, применять или передавать полученные знания, разви- вать свои навыки, набираться опыта и делиться всем этим с другими. Это энергия расширения, взрослых детей, мужей, денег, поэтому важно постоянно расширять свое мировоззрение, зани- маться самоанализом, расти морально и духовно, путешествовать и расширять свои границы, знакомиться с другими культурами, воспитывать детей, брать студентов, улучшать материаль- ное благосостояние своей семьи, помогать другим и заниматься благотворительностью.":"Руҳнинг иши ўқиш, ўргатиш, билим етказишдан иборат. Юпитер бошқарадиган 3 сони — бу ўқитувчи, гуру ва шогирд. Сизга доим олдинга ҳаракатланиш, интилиш, ўқиш, амалиёт қилиш, олинган билимларни қўллаш ёки етказиш, кўникмаларингизни ривожлантириш, тажриба орттириш ва буларнинг барчаси билан бошқалар билан бўлишиш зарур. Бу кенгайиш, катта фарзандлар, эрлар, пул энергияси, шунинг учун дунёқарашингизни доим кенгайтириш, ўзини таҳлил қилиш билан шуғулланиш, ахлоқий ва маънавий ўсиш, саёҳат қилиш ва чегараларингизни кенгайтириш, бошқа маданиятлар билан танишиш, фарзандлар тарбиялаш, шогирдлар олиш, оилангизнинг моддий фаровонлигини яхшилаш, бошқаларга ёрдам бериш ва хайрия билан шуғулланиш муҳим.","В качестве проработки посещайте различные курсы, финансовые курсы, получайте выс- шее образование, обучайте людей (назидайте), уважайте всех учителей, все культуры, все религии и не занимайтесь проповедничеством. Им нужно передавать знания и развивать философское понимание жизни. Для мужчин важно быть хорошим мужем и поддерживать благосостояние семьи. Для женщин важно поддерживать хорошую атмосферу в семье и цело- мудрие. Верьте в высокое. Всегда стремитесь к здоровому оптимизму, уважайте себя, не крити- куйте и научитесь честно выражать свои мысли. Всегда выбирайте «взрослую», а не «детскую» или «родительскую» позицию. Осознавайте все процессы, находящиеся под вашим контролем, не причиняя вреда себе и другим, и при необходимости оказывайте внешнее и внутреннее влияние.":"Ишлаб чиқиш сифатида турли курслар, молиявий курсларга боринг, олий таълим олинг, одамларни ўргатинг (насиҳат қилинг), барча ўқитувчилар, барча маданиятлар, барча динларни ҳурмат қилинг ва воизлик билан шуғулланманг. Уларга билим етказиш ва ҳаётни фалсафий тушунишни ривожлантириш керак. Эркаклар учун яхши эр бўлиш ва оила фаровонлигини сақлаш муҳим. Аёллар учун оиладаги яхши муҳит ва иффатни сақлаш муҳим. Юксакка ишонинг. Доим соғлом оптимизмга интилинг, ўзингизни ҳурмат қилинг, танқид қилманг ва фикрларингизни ҳалол ифода этишни ўрганинг. Доим «болалар» ёки «ота-она» позицияси эмас, «катталар» позициясини танланг. Ўзингиз ва бошқаларга зарар етказмай, назоратингиз остидаги барча жараёнларни англанг ва керак бўлганда ташқи ва ички таъсир кўрсатинг.","Задача души – понять смысл жизни, законы тонких планов и божественную суть. Раху – это теневая мистическая энергия. Ваша задача – познать тайны мира через оккультные науки, медитацию и йогу. Развивайте свою интуицию, полностью трансформируйте свое сознание, почувствуйте связь с божественным и в то же время будьте реалистами. Если перестать пребывать в иллюзиях и обмане, избавиться от ложных ожиданий, научиться понимать свои истинные желания, быть экологически сознательным, жить и действовать чисто и упорядоченно, реализм помогает в жизни, а самопознание помогает увидеть себя в новом свете.":"Руҳнинг вазифаси — ҳаёт маъноси, нозик режалар қонунлари ва илоҳий моҳиятни тушуниш. Раҳу — соя мистик энергия. Сизнинг вазифангиз — оккульт фанлар, медитация ва йога орқали дунё сирларини англаш. Интуициянгизни ривожлантиринг, онгингизни бутунлай ўзгартиринг, илоҳий билан алоқани ҳис қилинг ва айни пайтда реалист бўлинг. Агар иллюзиялар ва алдовда бўлишни тўхтатсангиз, сохта кутишлардан қутулсангиз, ҳақиқий истакларингизни тушунишни ўргансангиз, экологик онгли бўлсангиз, тоза ва тартибли яшаб ва ҳаракат қилсангиз, реализм ҳаётда ёрдам беради, ўзини англаш эса ўзингизни янги нурда кўришга ёрдам беради.","Включите в свою жизнь больше естественных вещей и откажитесь от искусственных и лишних. Будьте в гармонии с природой и избавьтесь от вредных привычек. Важно также научиться всегда и во всем видеть положительное и помогать в этом другим. Будьте благодарны и довольны тем, что у вас есть. Контролируйте свои желания и не позволяйте им доходить до безумия и разрушать вашу жизнь. Эта энергия расширяется и всегда порождает новые желания. Поэтому проверяйте свои желания на истинность, важно, ваши они или навязанные, от навязанных вещей нет ни процветания, ни радости. Не привязывайтесь ни к чему, чтобы иметь все. Ешьте здоровую пищу. Часто, если вы что-то меняете, не разобравшись в себе, вы создадите новые проблемы и целую цепь проблем. Вы должны знать, как работать над собой и использовать все возможные способы, чтобы измениться к лучшему и стать более эффективным во всех сферах своей жизни. Перейдя на новый уровень, вы сможете улучшить качество своей жизни.":"Ҳаётингизга кўпроқ табиий нарсаларни киритинг ва сунъий ва ортиқчаларидан воз кечинг. Табиат билан уйғунликда бўлинг ва зарарли одатлардан қутулинг. Шунингдек доим ва ҳамма нарсада ижобийни кўришни ва бунда бошқаларга ёрдам беришни ўрганиш муҳим. Бор нарсангиз учун миннатдор ва мамнун бўлинг. Истакларингизни назорат қилинг ва уларнинг телбаликкача етиб, ҳаётингизни вайрон қилишига йўл қўйманг. Бу энергия кенгаяди ва доим янги истаклар туғдиради. Шунинг учун истакларингизни ҳақиқийликка текширинг, улар сизникими ёки тиқиштирилганми муҳим, тиқиштирилган нарсалардан на гуллаб-яшнаш, на қувонч бор. Ҳамма нарсага эга бўлиш учун ҳеч нарсага боғланманг. Соғлом овқат енг. Кўпинча, агар ўзингизни тушунмай нимадир ўзгартирсангиз, янги муаммолар ва бутун бир муаммолар занжирини яратасиз. Сиз ўз устингизда қандай ишлашни ва яхши томонга ўзгариш ва ҳаётингизнинг барча соҳаларида самаралироқ бўлиш учун барча мумкин бўлган усуллардан фойдаланишни билишингиз керак. Янги даражага ўтиб, ҳаёт сифатингизни яхшилай оласиз.","Задача души – учиться и получать новые и новые знания, быть свободным от всего, быть непривязанным. Управляемый Меркурием, 5 (Граха Буддха) – это просветление, разум. Вам необходимо быть духовно и умственно пробужденным и познать суть мироздания на основе практических знаний. Изучайте то, что вам нравится, не бойтесь что-то менять в своей жизни и быть легким ветром. Со временем вы придете к божественным знаниям, в соответствии с вашим уровнем духовного развития. В процессе постоянного обучения вы будете расти и обретете свободу. Если вы научитесь применять полученные знания и делиться ими, они закрепятся.":"Руҳнинг вазифаси — ўқиш ва янгидан-янги билимлар олиш, ҳамма нарсадан эркин бўлиш, боғланмаган бўлиш. Меркурий бошқарадиган 5 (Граҳа Буддҳа) — бу маърифат, ақл. Сизга маънавий ва ақлий уйғонган бўлиш ва амалий билимлар асосида коинот моҳиятини англаш зарур. Сизга ёққан нарсани ўрганинг, ҳаётингизда нимадир ўзгартиришдан ва енгил шамол бўлишдан қўрқманг. Вақт ўтиб маънавий ривожланиш даражангизга мувофиқ илоҳий билимларга келасиз. Доимий ўқиш жараёнида ўсасиз ва эркинликка эришасиз. Агар олинган билимларни қўллашни ва улар билан бўлишишни ўргансангиз, улар мустаҳкамланади.","Умейте иногда отвлекаться от своих мыслей, чтобы не нервничать. Сохраняйте спокойствие и идите вперед. Навстречу новым знаниям. Умейте не расфокусироваться, не делать все сразу и не заканчивать ничего, даже по прихоти. Будьте последовательны в своих действиях. Если вы общительны и имеете хорошие связи, вы найдете новые возможности для развития. Покупайте книги и пишите свои собственные. Мыслите ясно и стремитесь видеть общую картину.":"Асабийлашмаслик учун баъзан фикрларингиздан чалғишни билинг. Хотиржамликни сақланг ва олдинга юринг. Янги билимлар томон. Тарқалмасликни, ҳаммасини бирданига қилмасликни ва ҳатто инжиқлик билан ҳам ҳеч нарсани тугатмай қолдирмасликни билинг. Ҳаракатларингизда изчил бўлинг. Агар киришимли бўлсангиз ва яхши алоқаларга эга бўлсангиз, ривожланиш учун янги имкониятлар топасиз. Китоблар сотиб олинг ва ўзингизникини ёзинг. Равшан фикрланг ва умумий манзарани кўришга интилинг.","Научитесь планировать и разрабатывать стратегию, как двигаться вперед и вырабатывайте структурированную и связную речь, не выбрасывая из нее отдельные части и фрагменты. Научитесь слушать других и слышать, что они хотят сказать. Стремитесь найти свою жизненную цель и разрабатывать стратегии для ее достижения. Научиться видеть более широкую перспективу. Улучшайте память, развивайте чувства юмора и умение переключаться с проблем на что-то более позитивное может очень помочь вам в жизни. Умение смеяться над собой, быть вежливым и принимать других людей обеспечит вам крепкие нервы и спокойный ум. Будьте глобально ориентированным, найдите и следуйте своему жизненному вектору и будьте беззаботным. Хорошо иметь несколько источников дохода, научиться быть незахламленным и ценить то, что у вас уже есть, даже если вы переключились на что-то новое. Расхламляйтесь как можно чаще. Все, что мы храним, занимает место в нашем подсознании, не тратьте на это свою энергию.":"Режалаштиришни ва олдинга қандай ҳаракатланиш стратегиясини ишлаб чиқишни ўрганинг ва ундан алоҳида қисм ва бўлакларни ташлаб юбормай, тузилмалашган ва изчил нутқни ишлаб чиқинг. Бошқаларни тинглашни ва улар нима демоқчи эканини эшитишни ўрганинг. Ҳаётий мақсадингизни топишга ва унга эришиш стратегияларини ишлаб чиқишга интилинг. Кенгроқ истиқболни кўришни ўрганиш. Хотирани яхшилаш, юмор ҳиссини ривожлантириш ва муаммолардан ижобийроқ нарсага ўтиш маҳорати ҳаётда сизга жуда ёрдам бериши мумкин. Ўзингиз устидан кула билиш, хушмуомала бўлиш ва бошқа одамларни қабул қилиш сизга мустаҳкам асаблар ва хотиржам ақлни таъминлайди. Глобал йўналган бўлинг, ҳаётий векторингизни топинг ва унга эргашинг ва бепарво бўлинг. Бир нечта даромад манбаига эга бўлиш, тўлдирилмаган бўлишни ўрганиш ва янги нарсага ўтган бўлсангиз ҳам, бор нарсани қадрлаш яхши. Иложи борича тез-тез тартибга келтиринг. Сақлаётган ҳамма нарсамиз онг остимизда жой эгаллайди, бунга энергиянгизни сарфламанг.","Задача души – познать смысл жизни через тантру, удовольствие и секс. 6 управляется Венерой (Граха Шукрачарья – «следующий жизньи») – планетой любви, желания и удовольствия. Вам нужно научиться контролировать свою сексуальную энергию, направлять ее в нужное русло, трансформировать, если необходимо, в новое качество, нечто более священное, перестать быть рабом похоти и неистового желания. Тогда вы обретете больше осознанности и зрелости и станете более успешными в жизни и в отношениях.":"Руҳнинг вазифаси — тантра, лаззат ва жинсий яқинлик орқали ҳаёт маъносини англаш. 6 ни Венера (Граҳа Шукрачарья) — муҳаббат, истак ва лаззат сайёраси бошқаради. Сизга жинсий энергиянгизни назорат қилишни, уни керакли ўзанга йўналтиришни, керак бўлса уни янги сифатга, муқаддасроқ нарсага ўзгартиришни, шаҳват ва жиловсиз истакнинг қули бўлишни тўхтатишни ўрганиш керак. Шунда кўпроқ онглилик ва етукликка эришасиз ва ҳаётда ва муносабатларда муваффақиятлироқ бўласиз.","Практикуйте различные практики сексуальной энергии, такие как тантра, женские практики и женские круги. Будьте решительны и продолжайте совершать добрые дела, несмотря ни на что. Любите без привязанности, поскольку цель любви – сделать вашего партнера счастли- вее с вами, чем он был бы без вас.":"Тантра, аёллар амалиётлари ва аёллар доиралари каби жинсий энергиянинг турли амалиётларини қўлланг. Қатъиятли бўлинг ва ҳар нарсага қарамай эзгу ишлар қилишда давом этинг. Боғланмай севинг, чунки муҳаббатнинг мақсади — шеригингизни сиз билан сизсиз бўлганидан бахтлироқ қилиш.","Обеспечьте дом, комфортную жизнь и счастье для себя и своих близких. Мужчинам: научиться приносить радость и удовольствие своей женщине и строить долгосрочные отношения. Всем: перестаньте обвинять своего партнера и прекратите «любовь», которая груба, насмешлива и служит лишь для видимости. Научитесь сострадать всему и всем, говорить мягко, медленно, непринужденно, как будто вас все это возвышает, и умейте быть благодарными за все, что у вас есть, и за все, что вы еще хотите и должны иметь. Сделайте себя красивой. Но не ориентируйтесь на внешность. Теоретически это так же важно, как внутренний мир и сексуальность. Возможно, вы больше ориентированы на количество, чем на качество, но ваша задача – качество с одним партнером.":"Ўзингиз ва яқинларингиз учун уй, қулай ҳаёт ва бахтни таъминланг. Эркакларга: аёлига қувонч ва лаззат келтиришни ва узоқ муддатли муносабатлар қуришни ўрганиш. Ҳаммага: шеригингизни айблашни тўхтатинг ва қўпол, масхараомуз ва фақат кўз-кўз учун хизмат қиладиган «муҳаббат»ни тўхтатинг. Ҳамма нарсага ва ҳаммага ҳамдард бўлишни, гўё буларнинг барчаси сизни юксалтираётгандек юмшоқ, секин, табиий гапиришни ўрганинг ва бор ҳамма нарсангиз учун ва яна истаган ва эга бўлишингиз керак бўлган ҳамма нарса учун миннатдор бўлишни билинг. Ўзингизни чиройли қилинг. Лекин ташқи кўринишга йўналманг. Назарий жиҳатдан бу ички дунё ва шаҳвоният каби муҳим. Эҳтимол, сиз сифатдан кўра миқдорга кўпроқ йўналгансиз, лекин сизнинг вазифангиз — битта шерик билан сифат.","Умейте шутить, но не высмеивайте никого. В качестве проработки – научитесь насла- ждаться жизнью и всем, что у вас есть и еще будет, творите, занимайтесь искусством, общайтесь с искусством, красотой, девушками, женским полом. Девушкам: будьте сами девушкой, красивой, привлекательной и находящейся в гармонии с миром и собой. Раскройте свои таланты.":"Ҳазиллашишни билинг, лекин ҳеч кимни масхара қилманг. Ишлаб чиқиш сифатида — ҳаётдан ва бор ва яна бўладиган ҳамма нарсадан завқланишни ўрганинг, ижод қилинг, санъат билан шуғулланинг, санъат, гўзаллик, қизлар, аёл жинси билан мулоқот қилинг. Қизларга: ўзингиз қиз, чиройли, жозибали ва дунё ва ўзингиз билан уйғунликда бўлинг. Истеъдодларингизни очинг.","Задача души – трансформация сознания. 7 управляется Кету – это теневая мистическая планета, как и Раху (4). Вам необходимо трансформировать свое мировоззрение, исследовать все, к чему вы прикасаетесь вдоль и поперек, и развивать свою интуицию. Вам необходимо осознать свою божественную сущность. Духовные и мистические пути – это ваши пути. Занимайтесь йогой, спиритизмом, энергетическими практиками и медитацией. Живите от своего сердца, а не от внешнего окружения. Становясь ближе к Богу, вы развиваетесь.":"Руҳнинг вазифаси — онг трансформацияси. 7 ни Кету бошқаради — бу Раҳу (4) каби соя мистик сайёра. Сизга дунёқарашингизни ўзгартириш, тегинган ҳамма нарсангизни бўйлама ва кўндаланг тадқиқ қилиш ва интуициянгизни ривожлантириш зарур. Сизга ўзингизнинг илоҳий моҳиятингизни англаш зарур. Маънавий ва мистик йўллар — сизнинг йўлларингиз. Йога, спиритизм, энергетик амалиётлар ва медитация билан шуғулланинг. Ташқи атрофдан эмас, юрагингиздан яшанг. Худога яқинлашиб, сиз ривожланасиз.","Не привязывайтесь ни к чему, стремитесь к мудрости, будьте мудрыми, решительными и дисциплинированными, в вас заключена огромная внутренняя сила. Стремитесь к большей глубине понимания бытия, духовной истины и компетентности. Откажитесь от консерватизма. Концентрация на духовном обогатит материальное, а не наоборот. Избавьтесь от вредных привычек и успокойте ум. Воспитайте в себе любовь к уединению. Научитесь понимать, что бесполезно нервничать, если вы не можете повлиять на ситуацию. Творец, Высшая сила, контролирует все, а вы могущественны, но не настолько. Судите о ситуациях, руководствуясь здравым смыслом и без эмоций. Связь с Богом через медитацию и йогу поможет вам избежать путаницы в жизни и понять, зачем вы здесь.":"Ҳеч нарсага боғланманг, доноликка интилинг, доно, қатъиятли ва интизомли бўлинг, сизда улкан ички куч мужассам. Борлиқ, маънавий ҳақиқат ва салоҳиятни тушунишнинг каттароқ чуқурлигига интилинг. Консерватизмдан воз кечинг. Маънавийга эътибор моддийни бойитади, аксинча эмас. Зарарли одатлардан қутулинг ва ақлни тинчлантиринг. Ўзингизда ёлғизликка муҳаббатни тарбияланг. Вазиятга таъсир кўрсата олмасангиз, асабийлашиш бефойда эканини тушунишни ўрганинг. Яратувчи, Олий куч ҳамма нарсани назорат қилади, сиз эса қудратлисиз, лекин бунчалик эмас. Вазиятлар ҳақида соғлом фикр ва ҳис-туйғусиз ҳукм чиқаринг. Медитация ва йога орқали Худо билан алоқа ҳаётда чалкашликлардан қочишга ва бу ерда нима учун эканингизни тушунишга ёрдам беради.","Задача души – это труд. 8 – число, которым управляет Сатурн (Шани – бог справедли- вости). Вам нужно трудиться как пчела до глубокой старости, не привязываясь к результатам или вознаграждению. Так вы добьетесь успеха и не будете ломать себе голову, глядя на мир и не видя возможностей. Занимайтесь карма-йогой. Судьба будет испытывать вас на прочность, потому что вы внутри имеете стальной внутренний стержень и несгибаемы, научитесь справляться с трудностями и преодолевать любые препятствия, не ломаясь. Главное – включить себя в процесс и получить от него кайф, тогда результат придет логичным образом.":"Руҳнинг вазифаси — бу меҳнат. 8 — Сатурн (Шани — адолат худоси) бошқарадиган сон. Сизга натижалар ёки мукофотга боғланмай, чуқур кексаликкача асаларидек меҳнат қилиш керак. Шу тарзда муваффақиятга эришасиз ва дунёга қараб, имкониятларни кўрмай, бошингизни қотирмайсиз. Карма-йога билан шуғулланинг. Тақдир сизни мустаҳкамликка синайди, чунки сизнинг ичингизда пўлат ички ўзак бор ва сиз эгилмассиз, қийинчиликлар билан уддалашни ва синмай ҳар қандай тўсиқларни енгишни ўрганинг. Асосийси — ўзингизни жараёнга киритиш ва ундан завқ олиш, шунда натижа мантиқий равишда келади.","Следуйте традициям и уважайте то, что веками создавали ваши предки. Научитесь принимать рациональные и просчитанные решения, а не эмоциональные. Учитесь самоконтролю и воздержанию, смирению и скромности, распорядку, управлению временем, ритуалам и традициям. Лень разрушительна для вас и ведет к депрессии и унынию. В любви научитесь думать не только о любви, а о том также что останется, когда страсть пройдет, какая основа отношений, общие интересы, даже если это холодный расчет, эмоции возникнут со временем.":"Анъаналарга эргашинг ва аждодларингиз асрлар давомида яратганни ҳурмат қилинг. Ҳиссий эмас, рационал ва ҳисобланган қарорлар қабул қилишни ўрганинг. Ўзини назорат қилиш ва тийилиш, итоаткорлик ва камтарлик, тартиб, вақтни бошқариш, маросимлар ва анъаналарни ўрганинг. Дангасалик сиз учун ҳалокатли ва депрессия ва тушкунликка олиб келади. Муҳаббатда нафақат муҳаббат ҳақида, балки эҳтирос ўтганда нима қолиши, муносабатларнинг асоси нима, умумий қизиқишлар ҳақида ҳам ўйлашни ўрганинг, ҳатто бу совуқ ҳисоб-китоб бўлса ҳам, ҳис-туйғулар вақт ўтиб пайдо бўлади.","Задача души – научиться управлять своей энергией, не быть усталой или чрезмерно активной, уметь отдыхать и расслабляться, а если вы не умеете быть в тонусе и физически активной, то научитесь этому. 9 управляет Марс (Мангала – бог войны) – это действие. Это планета воина и воительницы. Защищайте других и уязвимых, добивайтесь своих целей, никогда не сдавайтесь, когда вас постигнет неудача, вставайте и идите снова, как ребенок, который только что научился ходить. Достигайте всего, чего бы это ни стоило. Ставьте цели, они играют большую роль в вашей жизни, просто делайте это. Успех происходит от слова «успеть».":"Руҳнинг вазифаси — энергиясини бошқаришни ўрганиш, чарчаган ёки ҳаддан ташқари фаол бўлмаслик, дам олиш ва бўшашишни билиш, агар тонусда ва жисмонан фаол бўлишни билмасангиз, бунга ўрганинг. 9 ни Марс (Мангала — уруш худоси) бошқаради — бу ҳаракат. Бу жангчи эркак ва жангчи аёлнинг сайёраси. Бошқаларни ва заифларни ҳимоя қилинг, мақсадларингизга эришинг, омадсизлик келганда ҳеч қачон таслим бўлманг, эндигина юришни ўрганган боладек туриб яна юринг. Нима бўлса ҳам ҳаммасига эришинг. Мақсадлар қўйинг, улар ҳаётингизда катта роль ўйнайди, шунчаки буни қилинг. Муваффақият «улгуриш» сўзидан келади.","В жизни вам всегда нужен энтузиазм, и поддерживайте это состояние энтузиазма постоянно. Скорость играет важную роль в вашей жизни, особенно если она во благо и для успеха. У вас больше энергии, чем у кого-либо другого. Если вы не научитесь управлять ею, вы разрушите все, что видите, и самого себя. Будьте бесстрашны, практичны, решительны и верны своей цели. Откажитесь от любого насилия, как по отношению к себе, так и по отношению к другим.":"Ҳаётда сизга доим иштиёқ керак ва бу иштиёқ ҳолатини доим сақланг. Тезлик ҳаётингизда муҳим роль ўйнайди, айниқса у яхшилик учун ва муваффақият учун бўлса. Сизда ҳар кимдан кўра кўпроқ энергия бор. Агар уни бошқаришни ўрганмасангиз, кўрган ҳамма нарсани ва ўзингизни вайрон қиласиз. Қўрқмас, амалий, қатъиятли ва мақсадингизга содиқ бўлинг. Ўзингизга нисбатан ҳам, бошқаларга нисбатан ҳам ҳар қандай зўравонликдан воз кечинг.","Прекратите всякую распущенность, включая сексуальную. Избегайте жестокости. Ваша сила предназначена не для этого, а для достижения больших результатов и защиты себя и других. Не употребляйте алкоголь и чрезмерное количество мяса. Занимайтесь спортом, бегайте и делайте физические упражнения на протяжении всей жизни, это дает вам больше силы. Благодаря хорошей деятельности вы можете развивать и улучшать мир.":"Ҳар қандай бузуқликни, жумладан жинсийни ҳам тўхтатинг. Шафқатсизликдан сақланинг. Кучингиз бунинг учун эмас, катта натижаларга эришиш ва ўзингиз ва бошқаларни ҳимоя қилиш учун мўлжалланган. Алкоголь ва ортиқча миқдорда гўшт истеъмол қилманг. Бутун ҳаёт давомида спорт билан шуғулланинг, югуринг ва жисмоний машқлар қилинг, бу сизга кўпроқ куч беради. Яхши фаолият туфайли дунёни ривожлантириш ва яхшилашингиз мумкин.","Число Проблемы":"Муаммо сони","Если число основной проблемы равно «0», это говорит, прежде всего, о том, что они не знают, в чем заключается проблема. Это очень важный момент. Считается, что это очень плохо. Это происходит потому, что человек не имеет четкого понимания того, какие аспекты его жизни вызывают проблемы в каких областях. В каких областях будут проблемы, какие энергии на каких планетах нужно улучшить, над какими энергиями нужно работать и т. д. В этом и заключается основная проблема числа «0». Нигде нет конкретного объяснения. Потому что все нумерологи говорят, что когда число «0», то проблема не понятна. И в этом заключается основная проблема. Для того чтобы улучшить энергию каждой планеты, нужно работать во всех направлениях и на всех плоскостях.":"Агар асосий муаммо сони «0» га тенг бўлса, бу аввало улар муаммо нимадан иборатлигини билмаслигини айтади. Бу жуда муҳим лаҳза. Бу жуда ёмон деб ҳисобланади. Бу инсонда ҳаётининг қайси жиҳатлари қайси соҳаларда муаммолар туғдиришини аниқ тушуниш йўқлиги учун юз беради. Қайси соҳаларда муаммолар бўлади, қайси сайёраларда қайси энергияларни яхшилаш керак, қайси энергиялар устида ишлаш керак ва ҳ.к. «0» сонининг асосий муаммоси шунда. Ҳеч қаерда аниқ тушунтириш йўқ. Чунки барча нумерологлар сон «0» бўлганда муаммо тушунарсиз дейди. Ва асосий муаммо шунда. Ҳар бир сайёранинг энергиясини яхшилаш учун барча йўналишларда ва барча текисликларда ишлаш керак.","Число «1» указывает на возможность возникновения проблем по Солнцу. Например, слабое здоровье, проблемы с позвоночником, сердечно-сосудистые проблемы, неуверенность, проблемы с самоидентификацией, проблемы в отношениях с отцом или определенная гордыня, то есть человек, который чувствует, что его эго постоянно уязвлено. В этом случае необходимо развивать определенную независимость и внутреннее равновесие, и очень важно улучшить отношения с отцом. Отношения с отцом также важны, и необходимо наладить распорядок дня. Однако самая большая причина проблем – это здоровье или какие-то проблемы с эго. Поэтому очень важно, чтобы люди в первую очередь работали над этими областями.":"«1» сони Қуёш бўйича муаммолар пайдо бўлиш имкониятини кўрсатади. Масалан, заиф саломатлик, умуртқа поғонаси билан муаммолар, юрак-қон томир муаммолари, ишончсизлик, ўзини аниқлаш муаммолари, ота билан муносабатларда муаммолар ёки маълум кибр, яъни эгоси доим яраланаётганини ҳис қиладиган инсон. Бу ҳолда маълум мустақиллик ва ички мувозанатни ривожлантириш зарур ва ота билан муносабатларни яхшилаш жуда муҳим. Ота билан муносабатлар ҳам муҳим ва кун тартибини созлаш зарур. Бироқ муаммоларнинг энг катта сабаби — саломатлик ёки эго билан қандайдир муаммолар. Шунинг учун одамлар аввало бу соҳалар устида ишлаши жуда муҳим.","Если это «2», то это говорит о том, что человеку придется постоянно работать в сфере отношений на протяжении всей своей жизни. Он должен изучать психологию мужчин и женщин, различия между ними, как строить отношения и почему в отношениях возникают конфликты. Потому что проблема может заключаться в самом подходе к отношениям. То есть, человек может построить отношения неправильно, и из-за этого у него могут быть проблемы до конца жизни. Это своего рода карма. В отношениях есть счастье, есть привязанность, но он может получать от них проблемы и удары, и он может считать, что смысл его жизни заключается в его отношениях, но это не так часто. Считается, что у женщин есть гинекологические проблемы, а также психологические проблемы (неуравновешенное психическое состояние). Они могут быть не всегда психически здоровы, иметь высокий уровень тревожности и неустойчивую психику. У женщин также могут быть проблемы в отношениях с матерью. Вот основные направления.":"Агар бу «2» бўлса, бу инсон бутун ҳаёти давомида муносабатлар соҳасида доим ишлашига тўғри келишини айтади. У эркаклар ва аёллар психологиясини, улар ўртасидаги фарқларни, муносабатларни қандай қуриш ва муносабатларда нега низолар пайдо бўлишини ўрганиши керак. Чунки муаммо муносабатларга ёндашувнинг ўзида бўлиши мумкин. Яъни инсон муносабатларни нотўғри қуриши мумкин ва шу сабабли умрининг охиригача муаммоларга эга бўлиши мумкин. Бу ўзига хос карма. Муносабатларда бахт бор, боғланиш бор, лекин у улардан муаммолар ва зарбалар олиши мумкин ва у ҳаётининг маъноси муносабатларида деб ҳисоблаши мумкин, лекин бу кўпинча бундай эмас. Аёлларда гинекологик муаммолар, шунингдек психологик муаммолар (мувозанатсиз руҳий ҳолат) бор деб ҳисобланади. Улар доим ҳам руҳан соғлом бўлмаслиги, юқори хавотир даражаси ва беқарор руҳиятга эга бўлиши мумкин. Аёлларда она билан муносабатларда ҳам муаммолар бўлиши мумкин. Асосий йўналишлар шулар.","«3» считается хорошим числом проблемы, в том смысле, что его вопросы нуждаются в развитии. Он развивается, главным образом, в области повышения благосостояния, постоянного личностного роста, прогресса, продвижения вперед и развития мудрости. Также могут быть вопросы, связанные с детьми. Мужчины должны научиться принимать советы и давать рекомендации другим. Для женщин говорится, что «3» карма – это выйти замуж, и хотя могут быть проблемы с мужем, очень важно осознать этот опыт. А мужчина должен сделать счастливыми как можно больше женщин. Конечно, цель не в том, чтобы жениться на десяти женщинах. Прежде всего, это касается матерей, дочерей, жен и сестер, и он должен сделать все возможное, чтобы оказать им честь и сделать их счастливыми. Эту задачу можно решить, развивая мудрость, философию, нравственность, следование моральному закону и честность, то есть положительные качества Юпитера. Когда же вы не уделяете этому достаточно внимания, в вашей жизни могут появиться проблемы. В таких случаях «3» может принести некоторые препятствия в достижении процветания.":"«3» унинг масалалари ривожланишга муҳтож бўлиши маъносида яхши муаммо сони ҳисобланади. У асосан фаровонликни ошириш, доимий шахсий ўсиш, тараққиёт, олдинга силжиш ва донолик ривожланиши соҳасида ривожланади. Шунингдек болалар билан боғлиқ масалалар бўлиши мумкин. Эркаклар маслаҳатларни қабул қилишни ва бошқаларга тавсиялар беришни ўрганиши керак. Аёллар учун «3» карма — бу турмушга чиқиш дейилади, ва эр билан муаммолар бўлиши мумкин бўлса ҳам, бу тажрибани англаш жуда муҳим. Эркак эса иложи борича кўпроқ аёлларни бахтли қилиши керак. Албатта, мақсад ўнта аёлга уйланиш эмас. Аввало бу оналар, қизлар, хотинлар ва опа-сингилларга тегишли ва у уларга ҳурмат кўрсатиш ва уларни бахтли қилиш учун қўлидан келганини қилиши керак. Бу вазифани донолик, фалсафа, ахлоқ, ахлоқий қонунга амал қилиш ва ҳалоллик, яъни Юпитернинг ижобий фазилатларини ривожлантириш орқали ҳал қилиш мумкин. Бунга етарлича эътибор бермасангиз, ҳаётингизда муаммолар пайдо бўлиши мумкин. Бундай ҳолатларда «3» гуллаб-яшнашга эришишда баъзи тўсиқлар келтириши мумкин.","«4» – это прарабдха-карма, или какая-то особая проявленная карма, приписанная к этой жизни, и это фактически особые кармические проблемы в жизни. Раху – планета иллюзий, поэтому здесь сложнее понять кармические проблемы. Могут быть страхи, могут быть странные фантазии и мысли, непонятные желания и миражи, и человек может действовать на основе этих чувств.":"«4» — бу прарабдха-карма ёки бу ҳаётга бириктирилган қандайдир алоҳида намоён бўлган карма ва бу аслида ҳаётдаги алоҳида кармик муаммолар. Раҳу — иллюзиялар сайёраси, шунинг учун бу ерда кармик муаммоларни тушуниш қийинроқ. Қўрқувлар, ғалати хаёллар ва фикрлар, тушунарсиз истаклар ва саробларбўлиши мумкин ва инсон бу ҳислар асосида ҳаракат қилиши мумкин.","Сначала людям с проблемой 4 нужно убрать внутренние блоки, которые вызывают страх. Затем главная задача – пройти этот урок, этот путь кармических вызовов, через полную трансформацию сознания. В противном случае разум может быть потерян, и человек начнет жить максимально бессознательно. Могут также возникнуть сексуальные проблемы, оставшиеся из прошлых жизней. Все это необходимо проработать в своем сознании. Также очень важно избавиться от пагубных привычек, уменьшить контакт с искусственными вещами, больше общаться с чистой природой, землей, травой и деревьями, чаще бывать на улице и проводить время на чистом воздухе. Технологии, реклама, большие города и другие искусственные вещи – все это связано с влиянием Раху и не очень благоприятно, так как погружает нас в иллюзии.":"Аввал муаммоси 4 бўлган одамларга қўрқув туғдирадиган ички блокларни олиб ташлаш керак. Кейин асосий вазифа — бу сабоқдан, кармик чақириқларнинг бу йўлидан онгнинг тўлиқ трансформацияси орқали ўтиш. Акс ҳолда ақл йўқолиши ва инсон максимал онгсиз яшай бошлаши мумкин. Шунингдек ўтган ҳаётлардан қолган жинсий муаммолар пайдо бўлиши мумкин. Буларнинг барчасини онгингизда ишлаб чиқиш зарур. Шунингдек зарарли одатлардан қутулиш, сунъий нарсалар билан алоқани камайтириш, тоза табиат, ер, ўт ва дарахтлар билан кўпроқ мулоқот қилиш, кўчада тез-тез бўлиш ва тоза ҳавода вақт ўтказиш жуда муҳим. Технологиялар, реклама, катта шаҳарлар ва бошқа сунъий нарсалар — буларнинг барчаси Раҳу таъсири билан боғлиқ ва унчалик қулай эмас, чунки бизни иллюзияларга ботиради.","\"5\" – это число Меркурия. Часто проблема заключается в том, что обладатели Числа Проблемы \"5\" испытывают большие трудности в обучении или вообще не хотят учиться. Нет желания совершенствовать свой интеллект или манеру говорить. Могут быть проблемы с вниманием, образованием и навыками общения, а также некоторая леность. Люди с проблемой 5 должны научиться строить отношения, улучшить свои коммуникативные навыки, постоянно повышать свой интеллект, работать над своей речью, то есть научиться правильно говорить, улучшить свою внимательность, свести к минимуму беспорядок и положить все на свои места. Вы должны научиться прикладывать усилия. Очень важно не накапливать ненужные вещи, быть внимательным ко всему, что вы делаете, и сосредоточиться на этом занятии, не отвлекаясь.":"«5» — бу Меркурий сони. Кўпинча муаммо шундаки, «5» Муаммо сони эгалари ўқишда катта қийинчиликларни бошдан кечиради ёки умуман ўқишни истамайди. Интеллекти ёки гапириш услубини такомиллаштириш истаги йўқ. Эътибор, таълим ва мулоқот кўникмалари билан муаммолар, шунингдек қандайдир дангасалик бўлиши мумкин. Муаммоси 5 бўлган одамлар муносабатлар қуришни ўрганиши, коммуникатив кўникмаларини яхшилаши, интеллектини доим ошириши, нутқи устида ишлаши, яъни тўғри гапиришни ўрганиши, эътиборлилигини яхшилаши, тартибсизликни минималлаштириши ва ҳаммасини жой-жойига қўйиши керак. Сиз саъй-ҳаракат қилишни ўрганишингиз керак. Кераксиз нарсаларни тўпламаслик, қилаётган ҳамма нарсангизга эътиборли бўлиш ва чалғимай, бу машғулотга диққатни жамлаш жуда муҳим.","«6» – это Венера. Считается, что стремление к удовольствиям и жадность могут привести к проблемам. Вам нужно научиться контролировать свои эмоции и стремление к удовольствиям. Научиться быть целомудренным, что также является кармической задачей «6». Например, если такой человек изменяет, это может вызвать проблемы в его жизни. Он/она должен/должна иметь уважение к женщинам. Проблемы могут возникнуть в сфере взаимоотношений. Им нужно научиться правильно строить отношения, так как это одна из основных сфер, в которой могут возникнуть проблемы. Венерианцам необходимо развиваться на творческом уровне и стремиться довольствоваться тем, что у них есть. Им не следует излишне стремиться к определенным удовольствиям, комфорту или роскоши.":"«6» — бу Венера. Завқларга интилиш ва очкўзлик муаммоларга олиб келиши мумкин деб ҳисобланади. Сизга ҳис-туйғуларингиз ва завқларга интилишни назорат қилишни ўрганиш керак. Иффатли бўлишни ўрганиш, бу ҳам «6» нинг кармик вазифаси. Масалан, агар бундай инсон хиёнат қилса, бу унинг ҳаётида муаммолар туғдириши мумкин. У аёлларга ҳурматга эга бўлиши керак. Муаммолар ўзаро муносабатлар соҳасида пайдо бўлиши мумкин. Уларга муносабатларни тўғри қуришни ўрганиш керак, чунки бу муаммолар пайдо бўлиши мумкин бўлган асосий соҳалардан бири. Венерачиларга ижодий даражада ривожланиш ва бор нарсасидан қаноатланишга интилиш зарур. Уларга маълум завқлар, қулайлик ёки ҳашаматга ортиқча интилмаслик керак.","Если говорить о Кету, то это также один из признаков того, что вам следует поработать над своей мудростью. Как и в случае с числами Дхармы, у вас могут быть проблемы с уровнем энергии, недостаток энергии в целом или ощущение недостаточности кармических резервов. В вашей жизни не хватает стабильности, что, в свою очередь, может привести к некоторым иллюзиям. Также могут быть вопросы в сексуальном плане. Это происходит потому, что энергия кундалини – это энергия сексуального мира, и на этой основе она может вызывать кармические проблемы. Такие проблемы можно решить только с помощью духовных практик, йоги, медитации, развития мудрости, изучения священных писаний и т. д. Для этого нужно работать над духовным ростом, самопознанием и внутренним миром. Тогда проблема будет решена. В этом случае не всегда легко понять саму проблему. Это связано с тем, что она проистекает из тонкого уровня кармы.":"Кету ҳақида гапирадиган бўлсак, бу ҳам донолигингиз устида ишлашингиз кераклигининг белгиларидан бири. Дхарма сонларида бўлгани каби, сизда энергия даражаси билан муаммолар, умуман энергия етишмаслиги ёки кармик заҳиралар етишмаслиги ҳисси бўлиши мумкин. Ҳаётингизда барқарорлик етишмайди, бу эса ўз навбатида баъзи иллюзияларга олиб келиши мумкин. Шунингдек жинсий жиҳатдан масалалар бўлиши мумкин. Бу кундалини энергияси жинсий дунё энергияси бўлгани ва шу асосда кармик муаммолар туғдириши мумкинлиги учун юз беради. Бундай муаммоларни фақат маънавий амалиётлар, йога, медитация, донолик ривожланиши, муқаддас битикларни ўрганиш ва ҳ.к. ёрдамида ҳал қилиш мумкин. Бунинг учун маънавий ўсиш, ўзини англаш ва ички дунё устида ишлаш керак. Шунда муаммо ҳал бўлади. Бу ҳолда муаммонинг ўзини тушуниш доим ҳам осон эмас. Бу у карманинг нозик даражасидан келиб чиқиши билан боғлиқ.","У Сатурна могут быть разные проблемы. Чаще всего это проблемы, связанные с работой. Иногда удар судьбы, который приносит Сатурн, призван помочь человеку начать преодолевать препятствия и напрягаться. Другими словами, в жизни могут происходить события, которые заставляют человека прикладывать много усилий, то есть тяжелая работа или умственное напряжение, что ему нужно много работать, чтобы выйти из плохого состояния. Однако говорят, что лучший способ решить проблемы – это не лениться, упорно трудиться и стараться, чтобы ваша деятельность приносила пользу обществу.":"Сатурнда турли муаммолар бўлиши мумкин. Кўпинча бу иш билан боғлиқ муаммолар. Баъзан Сатурн келтирадиган тақдир зарбаси инсонга тўсиқларни енга бошлаш ва зўриқишга ёрдам бериш учун мўлжалланган. Бошқача айтганда, ҳаётда инсонни кўп саъй-ҳаракат қилишга мажбур қиладиган воқеалар, яъни оғир иш ёки ақлий таранглик юз бериши мумкин, ёмон ҳолатдан чиқиш учун унга кўп ишлаш керак. Бироқ муаммоларни ҳал қилишнинг энг яхши усули — дангасалик қилмаслик, қатъият билан меҳнат қилиш ва фаолиятингиз жамиятга фойда келтиришига ҳаракат қилиш дейишади.","Нужно стремиться выполнять любую деятельность наилучшим образом и при этом никогда не лениться. Это объясняется тем, что лень – пагубная сила и разрушает жизнь человека. С точки зрения здоровья, могут быть проблемы с позвоночником и ногами, хромота. Также, на уровне здоровья, часто существуют хронические заболевания. Но все это связано с ростом, так как Сатурн любит заставлять людей расти. Они много работают, преодолевают трудности, упорствуют и развивают в себе определенную серьезность по отношению к жизни. Каждый человек должен серьезно относиться к жизни, понимать ее и осознавать происходящее. Будьте здравомыслящим человеком. Несерьезное отношение к жизни может быть вредным. И в данном случае это очень важно. Нужно быть ответственным, не лениться и не бояться работы. Только тогда можно преодолеть все трудности.":"Ҳар қандай фаолиятни энг яхши тарзда бажаришга интилиш ва бунда ҳеч қачон дангасалик қилмаслик керак. Бу дангасалик — ҳалокатли куч ва инсон ҳаётини вайрон қилиши билан изоҳланади. Саломатлик нуқтаи назаридан умуртқа поғонаси ва оёқлар билан муаммолар, оқсоқлик бўлиши мумкин. Шунингдек саломатлик даражасида кўпинча сурункали касалликлар мавжуд. Лекин буларнинг барчаси ўсиш билан боғлиқ, чунки Сатурн одамларни ўсишга мажбур қилишни яхши кўради. Улар кўп ишлайди, қийинчиликларни енгади, қатъият кўрсатади ва ўзида ҳаётга нисбатан маълум жиддийликни ривожлантиради. Ҳар бир инсон ҳаётга жиддий муносабатда бўлиши, уни тушуниши ва бўлаётган нарсани англаши керак. Соғлом фикрли инсон бўлинг. Ҳаётга жиддий бўлмаган муносабат зарарли бўлиши мумкин. Ва бу ҳолда бу жуда муҳим. Масъулиятли бўлиш, дангасалик қилмаслик ва ишдан қўрқмаслик керак. Фақат шунда барча қийинчиликларни енгиш мумкин.","Значения личного года":"Шахсий йил маънолари","– Смягчаются проблемы прошлых лет;":"– Ўтган йиллар муаммолари юмшайди;","– появление ощущения счастья и везения в жизни;":"– ҳаётда бахт ва омад ҳисси пайдо бўлиши;","– люди вам помогают и любят вас;":"– одамлар сизга ёрдам беради ва сизни севади;","– высшие эшелоны власти и начальники поддерживают вас;":"– ҳокимиятнинг юқори доиралари ва бошлиқлар сизни қўллаб-қувватлайди;","– ощущение наполненности счастьем и здоровьем психически и физически;":"– руҳан ва жисмонан бахт ва саломатлик билан тўлганлик ҳисси;","– начало новых дел и прогресс в настоящих делах, которые будут влиять на жизнь в течении 9 лет;":"– янги ишлар бошланиши ва 9 йил давомида ҳаётга таъсир қиладиган ҳозирги ишлардаги тараққиёт;","– успех в проявлености, работе и самореализации при ответственном подходе к этому;":"– бунга масъулиятли ёндашувда намоён бўлиш, иш ва ўзини рўёбга чиқаришда муваффақият;","– будут перемены и все к лучшему;":"– ўзгаришлар бўлади ва ҳаммаси яхшиликка;","– новые нужные полезные люди в вашей жизни появляются;":"– ҳаётингизда янги керакли фойдали одамлар пайдо бўлади;","– несение ответственности где-бы то ни было без встрясок и потрясений;":"– қаерда бўлмасин силкинишлар ва ларзаларсиз масъулият кўтариш;","– возможность обрести успех, славу и известность, популярность в широких кругах общества;":"– муваффақият, шуҳрат ва машҳурлик, жамиятнинг кенг доираларида оммавийликка эришиш имконияти;","– отличный год для творчества и созидания, для конкурсов и побед;":"– ижод ва бунёдкорлик, танловлар ва ғалабалар учун ажойиб йил;","– успех в финансовых начинаниях;":"– молиявий ташаббусларда муваффақият;","– удачные покупки;":"– омадли харидлар;","– поворотный год для все творческих людей.":"– барча ижодкорлар учун бурилиш йили.","В этом году вас ожидает следующее:":"Бу йилда сизни қуйидагилар кутмоқда:","– повышение личной привлекательности":"– шахсий жозибанинг ошиши","– вы обретете новых друзей, которые будут поддерживать вас в будущем":"– келажакда сизни қўллаб-қувватлайдиган янги дўстлар орттирасиз","– меньше беспокойства и стресса":"– камроқ хавотир ва стресс","– больше эмоций, но и больше реализма":"– кўпроқ ҳис-туйғулар, лекин кўпроқ реализм ҳам","– прибыль в сфере недвижимости":"– кўчмас мулк соҳасида фойда","– новый дом или новая квартира, семья":"– янги уй ёки янги квартира, оила","– перемены в жизни":"– ҳаётдаги ўзгаришлар","– улучшение условий жизни благодаря терпению и планированию.":"– сабр ва режалаштириш туфайли турмуш шароитининг яхшиланиши.","Это год, когда люди освобождаются от ненужного беспокойства и нетерпения.":"Бу одамлар кераксиз хавотир ва сабрсизликдан озод бўладиган йил.","В этом году:":"Бу йил:","– больше знаний и практической мудрости":"– кўпроқ билим ва амалий донолик","– время завершить старые проекты":"– эски лойиҳаларни тугатиш вақти","– у вас появятся новые друзья и знакомые":"– сизда янги дўстлар ва танишлар пайдо бўлади","– принесет финансовый успех, имя и славу. У вас появится возможность более полно выразить себя. Этот год имеет особое значение для писателей и ораторов. Благодаря влиянию Юпитера они разовьют в себе честность и бесстрашие, что впоследствии может создать мно- жество проблем":"– молиявий муваффақият, ном ва шуҳрат келтиради. Сизда ўзингизни тўлиқроқ ифода этиш имконияти пайдо бўлади. Бу йил ёзувчилар ва нотиқлар учун алоҳида аҳамиятга эга. Юпитер таъсири туфайли улар ўзида ҳалоллик ва қўрқмасликни ривожлантиради, бу кейинчалик кўплаб муаммолар туғдириши мумкин","– это не лучшее время для подписания официальных документов или контрактов: оно больше подходит для бизнесменов и тех, кто так или иначе вовлечен в судебные процессы":"– бу расмий ҳужжатлар ёки шартномаларни имзолаш учун энг яхши вақт эмас: у кўпроқ бизнесменлар ва у ёки бу тарзда суд жараёнларига жалб қилинганлар учун мос келади","– подходит для создания бизнеса или нового предприятия":"– бизнес ёки янги корхона яратиш учун мос келади","– подходит для планирования и завершения работы":"– ишни режалаштириш ва тугатиш учун мос келади","– год продвижения по службе":"– хизматда кўтарилиш йили","– проверка друзей – и она определит, доверяете ли вы им.":"– дўстларни текшириш — ва у уларга ишонасизми-йўқми аниқлайди.","– завоеванный с большим трудом успех":"– катта меҳнат билан қозонилган муваффақият","– непоколебимая сила перед лицом неожиданных неприятностей и препятствий":"– кутилмаган кўнгилсизликлар ва тўсиқлар олдида бузилмас куч","– бдительность, трудолюбие и душевное спокойствие":"– ҳушёрлик, меҳнатсеварлик ва руҳий хотиржамлик","– финансовый успех, увеличение доходов, финансовая стабильность":"– молиявий муваффақият, даромадларнинг ошиши, молиявий барқарорлик","– новые деловые начинания, например, новый дом или новая квартира":"– янги ишбилармонлик ташаббуслари, масалан, янги уй ёки янги квартира","– удачный год. Ожидаются свадьбы. Если официальный брак не является необходимым или желательным, встреча со спутником жизни произойдет в этом году. У людей, состоящих в браке и не имеющих детей, появятся дети":"– омадли йил. Тўйлар кутилмоқда. Агар расмий никоҳ зарур ёки истаган бўлмаса, ҳаёт ҳамроҳи билан учрашув шу йилда юз беради. Никоҳда бўлган ва фарзанди йўқ одамларда фарзандлар пайдо бўлади","– благоприятен для построения отношений с друзьями и спутниками жизни":"– дўстлар ва ҳаёт ҳамроҳлари билан муносабатлар қуриш учун қулай","– не подходит для романтических приключений":"– романтик саргузаштлар учун мос эмас","– благоприятен для налаживания отношений с авторитетными людьми и начальством":"– обрўли одамлар ва бошлиқлар билан муносабатларни созлаш учун қулай","– благоприятен для путешествий":"– саёҳатлар учун қулай","– благоприятен для духовных поисков и религиозной деятельности.":"– маънавий излаш ва диний фаолият учун қулай.","Этот год будет:":"Бу йил:","– годом успеха и финансовой стабильности":"– муваффақият ва молиявий барқарорлик йили","– благоприятный год для бизнеса и деловых людей":"– бизнес ва ишбилармонлар учун қулай йил","– благоприятный год для международных деловых поездок и отдыха":"– халқаро иш сафарлари ва дам олиш учун қулай йил","– благоприятный для деловых партнеров":"– ишбилармон шериклар учун қулай","– будьте осторожны при произнесении речей":"– нутқлар сўзлаганда эҳтиёт бўлинг","– год, когда следует обратить внимание на «деловые контракты»":"– «ишбилармонлик шартномалари»га эътибор бериш керак бўлган йил","– благоприятный год для писателей, поэтов, актеров, артистов радио, журналистов и других работников СМИ":"– ёзувчилар, шоирлар, актёрлар, радио артистлари, журналистлар ва бошқа ОАВ ходимлари учун қулай йил","– подходит для участия в рискованной работе.":"– хавфли ишда қатнашиш учун мос келади.","Этот год принесет следующее:":"Бу йил қуйидагиларни келтиради:","– хорошие отношения с близкими родственниками, свобода от домашних хлопот":"– яқин қариндошлар билан яхши муносабатлар, уй ташвишларидан эркинлик","– вы будете благословлены романтическими отношениями и детьми":"– сиз романтик муносабатлар ва фарзандлар билан дуо оласиз","– благоприятен для дизайнеров интерьера, актеров, музыкантов, поэтов, художников, режиссеров, театральных деятелей и всех тех, кто связан с шоу-бизнесом. Также благоприятен для ювелиров и тех, кто занимается парфюмерией":"– интерьер дизайнерлари, актёрлар, мусиқачилар, шоирлар, рассомлар, режиссёрлар, театр арбоблари ва шоу-бизнес билан боғлиқ барча кишилар учун қулай. Шунингдек заргарлар ва парфюмерия билан шуғулланувчилар учун қулай","– благоприятен для траты денег на украшения, развлечения и удовольствия":"– безаклар, кўнгилочар машғулотлар ва завқларга пул сарфлаш учун қулай","– благоприятно для трудоустройства безработных":"– ишсизларни ишга жойлаштириш учун қулай","– это время когда стоит уделить внимание ювелирным украшениям, чувственным удовольствиям, мирским наслаждениям и подаркам.":"– бу заргарлик безаклари, ҳиссий завқлар, дунёвий лаззатлар ва совғаларга эътибор бериш керак бўлган вақт.","Этот год также предоставляет возможности для неожиданного богатства и повышения зарплаты.":"Бу йил шунингдек кутилмаган бойлик ва маошни ошириш учун имкониятлар беради.","– годом недоразумений и трудностей":"– тушунмовчиликлар ва қийинчиликлар йили","– год трудностей в бизнесе. Больше работы и меньше прибыли":"– бизнесда қийинчиликлар йили. Кўпроқ иш ва камроқ фойда","– год успеха в суде и судебных разбирательствах Это также год для:":"– судда ва суд жараёнларида муваффақият йили. Бу шунингдек:","– проверки друзей и соратников":"– дўстлар ва сафдошларни текшириш учун","– год избегания ненужных конфликтов":"– кераксиз низолардан қочиш йили","– посвятите энергию целительству, астрологии, тантрическим практикам, магии":"– энергияни шифокорлик, астрология, тантрик амалиётлар, сеҳрга бағишланг","– это год, чтобы пойти на риск":"– бу таваккал қилиш йили","– в этом году следует быть осторожным в личной жизни, чтобы избежать дурной славы Если вы хотите преуспеть в выбранной профессии, в этом году нужно сохранять оптимизм и не терять самообладания. Терпение и оптимизм решат все проблемы и препятствия. Это также хороший год для целителей, астрологов и тех, кто занимается оккультными науками.":"– бу йил ёмон ном чиқармаслик учун шахсий ҳаётда эҳтиёт бўлиш керак. Агар танланган касбда муваффақият қозонишни истасангиз, бу йил оптимизмни сақлаш ва ўзини йўқотмаслик керак. Сабр ва оптимизм барча муаммолар ва тўсиқларни ҳал қилади. Бу шунингдек шифокорлар, астрологлар ва оккульт фанлар билан шуғулланувчилар учун яхши йил.","– благоприятным для политиков, социальных работников и тех, кто работает в металлургической промышленности. Этот год – возможность начать новые предприятия.":"– сиёсатчилар, ижтимоий ходимлар ва металлургия саноатида ишлайдиганлар учун қулай. Бу йил — янги корхоналарни бошлаш имконияти.","– Неблагоприятен с точки зрения здоровья. Следует принять профилактические меры. Избегайте стрессов, волнений и тревог. Употребляйте больше соков и специй, которые очищают кровь и укрепляют сердце.":"– Саломатлик нуқтаи назаридан ноқулай. Профилактик чоралар кўриш керак. Стресслар, ҳаяжонлар ва хавотирлардан сақланинг. Қонни тозалайдиган ва юракни мустаҳкамлайдиган шарбатлар ва зираворларни кўпроқ истеъмол қилинг.","– благоприятен для успеха в мирских делах, следует направить свою энергию на созидание. Правильное использование энергии приносит удачу":"– дунёвий ишларда муваффақият учун қулай, энергияни бунёдкорликка йўналтириш керак. Энергиядан тўғри фойдаланиш омад келтиради","– благоприятное время для победы над врагами и выигрыша судебных дел":"– душманлар устидан ғалаба ва суд ишларида ютиш учун қулай вақт","– период независимости, опоры на собственные силы и суждения":"– мустақиллик, ўз кучи ва мулоҳазаларига таяниш даври","– хорошее время для общественной деятельности.":"– ижтимоий фаолият учун яхши вақт.","– годом завершения, успеха и удачи":"– якунлаш, муваффақият ва омад йили","– год исполнения желаний":"– истаклар амалга ошиш йили","– год самоорганизации":"– ўзини ташкил қилиш йили","– год получения желаемого от властей и правительственных учреждений. Вы также испытаете следующее:":"– ҳокимият ва давлат муассасаларидан истаганини олиш йили. Шунингдек қуйидагиларни бошдан кечирасиз:","– легкое разочарование, возможны ссоры с властями":"– енгил ҳафсаласизлик, ҳокимият билан жанжаллар бўлиши мумкин","– успех в борьбе и конкуренции":"– кураш ва рақобатда муваффақият","– общественное признание":"– жамоатчилик эътирофи","– возможно неожиданное улучшение экономических условий, например, лотерея или наследство. В этом году следует избегать сомнений и упрямства. Вложение большей энергии в духовные занятия принесет хорошие результаты в этом году.":"– иқтисодий шароитнинг кутилмаган яхшиланиши, масалан, лотерея ёки мерос бўлиши мумкин. Бу йилда шубҳалар ва қайсарликдан сақланиш керак. Маънавий машғулотларга кўпроқ энергия киритиш бу йилда яхши натижалар беради.","Варны":"Варналар","Шудры созданы из ступней Бога и общества. Самым важным для представителей этой варны является способность выживать, работать в физическом мире, производить жизнеспособное потомство, служить и подчиняться, быть прилежными, преодолевать лень, иметь дисциплину и чувство цели в своей работе. Для шудр характерно повторяющееся и привычное поведение в их трудовой деятельности, устная речь, эмоциональные выражения и образ мышления. Они чувствуют себя спокойно только в знакомой обстановке и на работе. Они твердо стоят на ногах, физически развиты, сильны, любят физическую работу, здоровы душой и телом, имеют хорошо развитые материнские и отцовские инстинкты, являются верными слугами и незаменимыми помощниками во многих делах. Они любят природу, землю, имеют наиболее развитые инстинктивные мысли, ближе других людей к земле, возделывают ее, ухаживают за ней и кормят других плодами своего труда. Их роль в обществе – ручной труд, искусство, творчество, ремесло, производство своими руками, художники и певцы. Это мистические варны, творцы. Их цвет – черный (земляной).":"Шудралар Худо ва жамиятнинг оёқ кафтларидан яратилган. Бу варна вакиллари учун энг муҳими — омон қолиш, жисмоний дунёда ишлаш, ҳаётга лаёқатли авлод бериш, хизмат қилиш ва бўйсуниш, тиришқоқ бўлиш, дангасаликни енгиш, ишида интизом ва мақсад ҳиссига эга бўлиш қобилияти. Шудралар учун меҳнат фаолиятида такрорланувчи ва одатий хулқ, оғзаки нутқ, ҳиссий ифодалар ва фикрлаш тарзи хос. Улар фақат таниш муҳитда ва ишда ўзини хотиржам ҳис қилади. Улар оёқда мустаҳкам туради, жисмонан ривожланган, кучли, жисмоний ишни яхши кўради, руҳан ва жисмонан соғлом, яхши ривожланган оналик ва оталик инстинктларига эга, содиқ хизматкорлар ва кўп ишларда ўрни босилмас ёрдамчилар ҳисобланади. Улар табиат, ерни яхши кўради, энг ривожланган инстинктив фикрларга эга, бошқа одамлардан ерга яқинроқ, уни ишлайди, унга қарайди ва бошқаларни меҳнатининг мевалари билан боқади. Уларнинг жамиятдаги роли — қўл меҳнати, санъат, ижод, ҳунар, ўз қўли билан ишлаб чиқариш, рассомлар ва қўшиқчилар. Булар мистик варналар, ижодкорлар. Уларнинг ранги — қора (тупроқ ранги).","Вайшьи – созданы из бедра Бога. Они символизируют живот общества. О вайшьях можно сказать, что они имеют сильную склонность к поиску комфорта. Это собственники, чьи личные интересы выше общественных. Люди этой варны участвуют в создании материальных и технологических основ общества. Они организуют оборот товаров, необходимых для жизни людей, формируют рабочие места и удовлетворяют потребности людей в пище, одежде и жилье. У представителей этой варны развивается чувство воли. Он может хорошо и легко браться за работу по собственному желанию, не дожидаясь внешних стимулов, и у него формируются начальные организаторские способности. Вайшью способен принимать решения относительно сферы своей деятельности. Он способен распознавать обязательства на уровне контрактов и договариваться о взаимовыгодных условиях с теми, кто в этом нуждается. Их роль заключается во взаимодействии, общении, социализации, торговле и ведении бизнеса с другими членами общества. От них рождается много богатых людей. Их цвет – желтый (золотой).":"Вайшьялар — Худонинг сонидан яратилган. Улар жамиятнинг қорнини ифода этади. Вайшьялар ҳақида айтиш мумкинки, уларда қулайлик излашга кучли мойиллик бор. Булар шахсий манфаатлари ижтимоий манфаатлардан юқори бўлган мулкдорлар. Бу варна одамлари жамиятнинг моддий ва технологик асосларини яратишда қатнашади. Улар одамлар ҳаёти учун зарур товарлар айланмасини ташкил этади, иш ўринлари шакллантиради ва одамларнинг овқат, кийим ва уй-жойга эҳтиёжларини қондиради. Бу варна вакилларида ирода ҳисси ривожланади. У ташқи рағбатларни кутмай, ўз хоҳиши билан ишга яхши ва осон киришиши мумкин ва унда бошланғич ташкилотчилик қобилиятлари шаклланади. Вайшья ўз фаолият соҳаси бўйича қарорлар қабул қилишга қодир. У шартномалар даражасида мажбуриятларни таниш ва бунга муҳтожлар билан ўзаро фойдали шартларда келишишга қодир. Уларнинг роли жамиятнинг бошқа аъзолари билан ўзаро таъсир, мулоқот, ижтимоийлашув, савдо ва бизнес юритишдан иборат. Улардан кўплаб бой одамлар туғилади. Уларнинг ранги — сариқ (олтин).","Кшатрии – созданы из рук Бога, поэтому власть в их руках. Настоящий кшатрий благороден и честен и знает цену своим словам. Он держит свое слово во всех отношениях и никогда не предает своих друзей. Его интересы основаны на интеллектуальной деятельности. Процесс признания происходит через служение обществу и предложение своих навыков. Самооценка кшатриев обусловлена их мировоззрением, чувством долга, моралью и идеологией. Это решительно властные и бесстрашные люди, призванные защищать, править и видеть перспективы. Они воины во всех качествах и руки общества – справедливость и честь, порядок и долг. Их цвет – красный.":"Кшатрийлар — Худонинг қўлларидан яратилган, шунинг учун ҳокимият уларнинг қўлида. Ҳақиқий кшатрий олижаноб ва ҳалол ва сўзларининг қадрини билади. У барча жиҳатдан сўзида туради ва ҳеч қачон дўстларига хиёнат қилмайди. Унинг манфаатлари интеллектуал фаолиятга асосланган. Эътироф жараёни жамиятга хизмат қилиш ва ўз кўникмаларини таклиф қилиш орқали юз беради. Кшатрийларнинг ўзини баҳолаши уларнинг дунёқараши, бурч ҳисси, ахлоқи ва мафкураси билан белгиланади. Булар ҳимоя қилиш, бошқариш ва истиқболларни кўришга даъват этилган қатъиян ҳукмрон ва қўрқмас одамлар. Улар барча сифатларда жангчилар ва жамиятнинг қўллари — адолат ва шараф, тартиб ва бурч. Уларнинг ранги — қизил.","Брамины (Брахманы) – созданы из уст Бога, а значит говорят то, что думает Бог. Это философы, ученые, исследователи, монахи, учителя, правители, мыслители и интеллектуалы. Брамины всегда были высшим классом, аристократами, королевскими особами и интеллектуалами – голубыми кровями. Брамин – это новый мыслитель, который создал «новую» мораль, идею, теорию или мировоззрение и утвердил их в мире. Брамины обладают гораздо более свободной волей, чем люди низших варн, и могут контролировать формирование мыслей.":"Браминлар (Браҳманлар) — Худонинг оғзидан яратилган, демак Худо ўйлаган нарсани гапиради. Булар файласуфлар, олимлар, тадқиқотчилар, роҳиблар, ўқитувчилар, ҳукмдорлар, мутафаккирлар ва зиёлилар. Браминлар доим олий табақа, аристократлар, қироллик шахслари ва зиёлилар — мовий қонлилар бўлган. Брамин — бу «янги» ахлоқ, ғоя, назария ёки дунёқарашни яратган ва уларни дунёда қарор топтирган янги мутафаккир. Браминлар қуйи варналар одамларига қараганда анча эркинроқ иродага эга ва фикрлар шаклланишини назорат қила олади.","Человек этой варны – это ученик и гуру, объединенные в одну личность. Он характеризуется служением эволюции, постоянным стремлением к гармонии и жизненной мудростью, которая регулируется его мировоззрением, чувством долга, моралью и идеологией. Его главная цель – познать Вселенную, накопить как можно больше знаний, передать их дальше и создать новые развивающиеся технологии. Говоря условно, они являются головой общества. Для них характерно много учиться и учить, передавать эти знания и сохранять их в человеческой культуре. Для них характерен белый цвет, символ чистоты и целомудрия.":"Бу варна инсони — бир шахсга бирлашган шогирд ва гуру. У эволюцияга хизмат, уйғунликка доимий интилиш ва унинг дунёқараши, бурч ҳисси, ахлоқи ва мафкураси билан тартибга солинадиган ҳаётий донолик билан тавсифланади. Унинг асосий мақсади — Коинотни англаш, иложи борича кўпроқ билим тўплаш, уни кейинга етказиш ва янги ривожланаётган технологиялар яратиш. Шартли айтганда, улар жамиятнинг бошидир. Улар учун кўп ўқиш ва ўргатиш, бу билимларни етказиш ва уларни инсоният маданиятида сақлаш хос. Улар учун поклик ва иффат рамзи бўлган оқ ранг хос.","Задач четких нет. Действуйте по совести и делайте что захочет душа. Слыште свою душу.":"Аниқ вазифалар йўқ. Виждонга кўра ҳаракат қилинг ва қалб истаганини қилинг. Қалбингизни эшитинг.","Задача души по чакре – Муладхара.":"Чакра бўйича руҳ вазифаси — Муладҳара.","Навыки:":"Кўникмалар:","– умение преодолевать жизненные трудности, находясь в радостном состоянии, при этом сохраняя спокойствие, побеждая страхи и беря ответственность за свои действия на себя, не обвиняя других ни в чем;":"– қувноқ ҳолатда бўлиб, бунда хотиржамликни сақлаб, қўрқувларни енгиб ва бошқаларни ҳеч нарсада айбламай, ҳаракатлари учун масъулиятни ўз зиммасига олиб, ҳаётий қийинчиликларни енгиш маҳорати;","– умение преодолевать сопротивление в себе самом и само-саботаж;":"– ўзидаги қаршилик ва ўз-ўзини саботажни енгиш маҳорати;","– мыслить и действовать позитивно и конструктивно;":"– ижобий ва конструктив фикрлаш ва ҳаракат қилиш;","– умение обходиться без того, чтобы ограничивать себя в семье, на работе и в обществе;":"– оилада, ишда ва жамиятда ўзини чекламай уддалаш маҳорати;","– работать над физическим телом;":"– жисмоний тана устида ишлаш;","– укреплять силу воли;":"– ирода кучини мустаҳкамлаш;","– развивать заботу о себе и других;":"– ўзига ва бошқаларга ғамхўрликни ривожлантириш;","– наработать понимание важности выполнения своих обязанностей;":"– ўз мажбуриятларини бажаришнинг муҳимлигини тушунишни ишлаб чиқиш;","– брать ответственности и соблюдать дисциплину;":"– масъулиятни олиш ва интизомга риоя қилиш;","– управлять своими инстинктами и идти в страхи.":"– инстинктларини бошқариш ва қўрқувларга бориш.","Невыполнение:":"Бажармаслик:","– постоянные неудачи;":"– доимий омадсизликлар;","– обман, предательства, потери;":"– алдов, хиёнатлар, йўқотишлар;","– закрытие возможностей;":"– имкониятларнинг ёпилиши;","– материальные проблемы.":"– моддий муаммолар.","Задача души по чакре – Свадхистхана.":"Чакра бўйича руҳ вазифаси — Свадҳистхана.","– учитесь создавать семью;":"– оила қуришни ўрганинг;","– умейте гармонично выстраивать отношения с родственниками и противоположным полом;":"– қариндошлар ва қарама-қарши жинс билан муносабатларни уйғун қуришни билинг;","– развейте гибкость в общении с людьми;":"– одамлар билан мулоқотда мослашувчанликни ривожлантиринг;","– научитесь приспосабливаться к обстоятельствам;":"– ҳолатларга мослашишни ўрганинг;","– во внутреннем мире развивайте чувственность и эмоциональный интеллект, проявляйте эмоции;":"– ички дунёда ҳиссиётлилик ва ҳиссий интеллектни ривожлантиринг, ҳис-туйғуларни намоён қилинг;","– умейте принимать и уважать людей, в частности противоположный пол;":"– одамларни, хусусан қарама-қарши жинсни қабул қилиш ва ҳурмат қилишни билинг;","– развивайте сексуальную энергию, тут у вас огромный потенциал;":"– жинсий энергияни ривожлантиринг, бу ерда сизда улкан салоҳият бор;","– умейте не поддаваться своим страстям и сиюминутным желаниям, включите тут разум;":"– эҳтирослар ва лаҳзалик истакларга берилмасликни билинг, бу ерда ақлни ёқинг;","– умейте, генерируя сексуальную энергию, переводить ее на уровень социальной реализации и духовного развития, а не просто в утехи;":"– жинсий энергия ишлаб чиқариб, уни шунчаки ҳузурга эмас, ижтимоий рўёбга чиқиш ва маънавий ривожланиш даражасига ўтказишни билинг;","– проблемы в отношениях;":"– муносабатлардаги муаммолар;","– измены;":"– хиёнатлар;","– плохие отношения с супругом/ой;":"– турмуш ўртоғи билан ёмон муносабатлар;","– жизнь забирает людей из вашего поля или даже жизни.":"– ҳаёт одамларни майдонингиздан ёки ҳатто ҳаётдан олиб кетади.","Задача души по чакре – Манипура.":"Чакра бўйича руҳ вазифаси — Манипура.","– управление своими эмоциями и эмоциональный интеллект – есть то, над чем стоит работать в первую очередь;":"– ҳис-туйғуларини бошқариш ва ҳиссий интеллект — аввало устида ишлаш керак бўлган нарса;","– больший уровень эмоционального интеллекта равно больший уровень счастья и успеха в жизни в целом;":"– ҳиссий интеллектнинг юқорироқ даражаси умуман ҳаётда бахт ва муваффақиятнинг юқорироқ даражасига тенг;","– дав излишнюю волю эмоциям вы получаете от судьбы по шапке;":"– ҳис-туйғуларга ортиқча эрк бериб, тақдирдан зарба оласиз;","– развивайте разум и интеллект; занимайтесь своим духовным развитием;":"– ақл ва интеллектни ривожлантиринг; маънавий ривожланишингиз билан шуғулланинг;","– стремитесь больше анализировать и включать логику;":"– кўпроқ таҳлил қилишга ва мантиқни ёқишга интилинг;","– творческий подход помогает вам;":"– ижодий ёндашув сизга ёрдам беради;","– навык зарабатывания денег – ключевой;":"– пул топиш кўникмаси — асосий;","– плохо для вас – отказ или обесценивание денег;":"– сиз учун ёмон — пулдан воз кечиш ёки уни қадрсизлантириш;","– изучайте законы финансового мира и денег; войдите в поток денег и живите в нем свою свободную жизнь во благо себе и всем;":"– молиявий дунё ва пул қонунларини ўрганинг; пул оқимига киринг ва унда ўзингиз ва ҳамма учун яхшилик йўлида эркин ҳаётингизни яшанг;","– поймите что при этом деньги важное, но не главное. Невыполнение:":"– бунда пул муҳим, лекин асосий эмаслигини тушунинг. Бажармаслик:","– не способность заработать или сохранить деньги;":"– пул топа олмаслик ёки сақлай олмаслик;","– не виденье пути своей социальной самореализации;":"– ижтимоий ўзини рўёбга чиқариш йўлини кўрмаслик;","– много непонимания с окружающими;":"– атрофдагилар билан кўп тушунмовчилик;","– невозможность сделать карьеру.":"– карьера қила олмаслик.","Задача души по чакре – Анахата.":"Чакра бўйича руҳ вазифаси — Анахата.","– наработка способности решать проблемы любой сложности и конструкции;":"– ҳар қандай мураккаблик ва тузилишдаги муаммоларни ҳал қилиш қобилиятини ишлаб чиқиш;","– понимание что проблема – эмоция = задача;":"– муаммо — ҳис-туйғу = вазифа эканини тушуниш;","– способность бесконечно развиваться, изучать все что интересует в жизни, любознательность;":"– чексиз ривожланиш, ҳаётда қизиқтирган ҳамма нарсани ўрганиш қобилияти, қизиқувчанлик;","– развитие в себе милосердия и сострадания;":"– ўзида марҳамат ва ҳамдардликни ривожлантириш;","– способность выходить за рамки обыденного, за рамки своих границ и мировосприятия;":"– одатийлик, ўз чегаралари ва дунёни қабул қилиш доирасидан чиқиш қобилияти;","– наработать умение сострадать всем и вся;":"– ҳамма ва ҳамма нарсага ҳамдард бўлиш маҳоратини ишлаб чиқиш;","– осмелиться жить с открытым сердцем и смотреть на жизнь и людей из своей души;":"– очиқ юрак билан яшашга ва ҳаёт ва одамларга қалбидан қарашга журъат этиш;","– наработать принятие себя, людей, жизни и красоты в этом всем;":"– ўзини, одамларни, ҳаётни ва буларнинг барчасидаги гўзалликни қабул қилишни ишлаб чиқиш;","– чтить законы любви;":"– муҳаббат қонунларини эъзозлаш;","– привносить в мир через свое творчество и действия любовь, знания и навыки. Невыполнение:":"– дунёга ижоди ва ҳаракатлари орқали муҳаббат, билим ва кўникмалар олиб кириш. Бажармаслик:","– возникшие вопросы с принятием себя, всего и всех;":"– ўзини, ҳамма нарсани ва ҳаммани қабул қилиш билан пайдо бўлган масалалар;","– изматывание себя и других одиночеством;":"– ўзини ва бошқаларни ёлғизлик билан толиқтириш;","– вход в долгие депрессивные состояния;":"– узоқ депрессив ҳолатларга кириш;","– на физике возможны заболевания сердца.":"– жисмонан юрак касалликлари бўлиши мумкин.","Задача души по чакре – Вишудха.":"Чакра бўйича руҳ вазифаси — Вишуддҳа.","– способность проявлять себя и являть миру свое творчество;":"– ўзини намоён қилиш ва дунёга ижодини кўрсатиш қобилияти;","– умение созидать новое;":"– янгиликни бунёд этиш маҳорати;","– способность самовыразиться в этот мир;":"– бу дунёга ўзини ифода этиш қобилияти;","– взять основной вектор в жизни на познание всего и вся и сотворение из пришедших в их голову идей;":"– ҳаётда асосий векторни ҳамма ва ҳамма нарсани англаш ва бошига келган ғоялардан яратишга олиш;","– основная цель в развитии – постичь знание о любви, красоте и гармонии в самом себе;":"– ривожланишдаги асосий мақсад — ўзида муҳаббат, гўзаллик ва уйғунлик ҳақидаги билимни англаш;","– способность облечь знания о красоте, гармонии и любви в слова и передать через свое творчество;":"– гўзаллик, уйғунлик ва муҳаббат ҳақидаги билимларни сўзларга ўраш ва ижоди орқали етказиш қобилияти;","– способность строить гармоничные отношения со всеми людьми и всем сущим без исключения;":"– барча одамлар ва мавжуд ҳамма нарса билан истисносиз уйғун муносабатлар қуриш қобилияти;","– мотивация себя и других людей на раскрытие своих талантов;":"– ўзини ва бошқа одамларни истеъдодларини очишга рағбатлантириш;","– супер-способность менять все вокруг с помощью слов и голоса;":"– сўзлар ва овоз ёрдамида атрофдаги ҳамма нарсани ўзгартириш супер-қобилияти;","– навыки убеждения и гипноза;":"– ишонтириш ва гипноз кўникмалари;","– сильнейшая вербальная энергия. Невыполнение:":"– энг кучли вербал энергия. Бажармаслик:","– отсутствие требований к жизни;":"– ҳаётга талабларнинг йўқлиги;","– зависимости и вредные привычки;":"– қарамликлар ва зарарли одатлар;","– отсутствие радости жизни и желания жить;":"– ҳаёт қувончи ва яшаш истагининг йўқлиги;","– на физике вопросы со зрением, слухом или кровью.":"– жисмонан кўриш, эшитиш ёки қон билан масалалар.","Задачи души по чакре – Аджна.":"Чакра бўйича руҳ вазифалари — Аджна.","– способность видеть кармические связи, с помощью понимания закона причинно-следственных связей;":"– сабаб-оқибат боғланишлари қонунини тушуниш ёрдамида кармик алоқаларни кўриш қобилияти;","– принятие и понимание законов кармы;":"– карма қонунларини қабул қилиш ва тушуниш;","– ясность ума и избавление от иллюзорности;":"– ақл равшанлиги ва иллюзорликдан халос бўлиш;","– навык чтения знаков судьбы и психики людей;":"– тақдир белгилари ва одамлар руҳиятини ўқиш кўникмаси;","– способность «читать между строк»;":"– «сатрлар орасини ўқиш» қобилияти;","– наработка способности видеть глубже и дальше чем материальный мир;":"– моддий дунёдан чуқурроқ ва узоқроқ кўриш қобилиятини ишлаб чиқиш;","– способность проходить испытания с мудростью и пониманием соблюдения законов все- ленной;":"– коинот қонунларига риоя қилишни тушуниб ва донолик билан синовлардан ўтиш қобилияти;","– открытие в себе божественных знаний, сиддх и способности проходить уроки души, помощь в этом другим людям;":"– ўзида илоҳий билимлар, сиддҳиларни очиш ва руҳ сабоқларидан ўтиш қобилияти, бунда бошқа одамларга ёрдам бериш;","– умение дать нужный и верный в ситуации совет, наставить на путь истинный и грамотно подсказать человеку, чтобы он развивался сам при этом;":"– вазиятда керакли ва тўғри маслаҳат бериш, тўғри йўлга йўналтириш ва инсонга бунда ўзи ривожланиши учун тўғри айтиб бериш маҳорати;","– умение находить выход из любых ситуаций и применять нестандартный подход к жизни. Невыполнение:":"– ҳар қандай вазиятлардан чиқиш йўлини топиш ва ҳаётга ностандарт ёндашувни қўллаш маҳорати. Бажармаслик:","– проблемы с деньгами;":"– пул билан муаммолар;","– повторение ситуаций из прошлого, из-за невозможности пройти уроки души верно сразу;":"– руҳ сабоқларидан дарҳол тўғри ўта олмаслик туфайли ўтмишдаги вазиятларнинг такрорланиши;","– ограниченное восприятие реальности и как следствие ситуативные ограничения.":"– ҳақиқатни чекланган қабул қилиш ва оқибатда вазиятли чекловлар.","Задачи души по чакре – Сахасрара.":"Чакра бўйича руҳ вазифалари — Саҳасрара.","– умение яснознать и ощущать вселенские, божественные законы и следовать им;":"– коинот, илоҳий қонунларни равшан билиш ва ҳис қилиш ва уларга эргашиш маҳорати;","– способность изучать и жить в соответствии с этими законами;":"– бу қонунларни ўрганиш ва уларга мувофиқ яшаш қобилияти;","– постоянное исследование вселенной, изучение нового в больших объёмах;":"– коинотни доимий тадқиқ қилиш, янгиликни катта ҳажмда ўрганиш;","– умейте развивать осознанность и так относиться ко всему в жизни;":"– онглиликни ривожлантиришни ва ҳаётдаги ҳамма нарсага шундай муносабатда бўлишни билинг;","– занимайтесь саморазвитием и самопознанием во всех сферах и смыслах;":"– барча соҳалар ва маъноларда ўз-ўзини ривожлантириш ва ўзини англаш билан шуғулланинг;","– вам дается многое, но и спрашивают высшие силы с вас тоже много;":"– сизга кўп нарса берилади, лекин олий кучлар сиздан ҳам кўп нарса сўрайди;","– умейте передавать чистые знания, не исказив и не дополнив их своими суждениями; Невыполнение:":"– тоза билимларни бузмай ва ўз мулоҳазаларингиз билан тўлдирмай етказишни билинг; Бажармаслик:","– потеря связи с духом, высшим Я, Высшими Силами;":"– руҳ, олий Мен, Олий Кучлар билан алоқани йўқотиш;","– потеря способности творить;":"– ижод қилиш қобилиятини йўқотиш;","– отсутствие вдохновения;":"– илҳомнинг йўқлиги;","– потеря себя внутри и снаружи.":"– ўзини ичкарида ва ташқарида йўқотиш.","Число Агама кармы":"Агама карма сони","Если ваш управитель года Агама – кармы или месяца «1»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «1» бўлса:","– завершился 9-ти летний цикл и начался период начала нового;":"– 9 йиллик цикл тугади ва янгисининг бошланиш даври бошланди;","– яркие события по сферам планеты Солнце;":"– Қуёш сайёраси соҳалари бўйича ёрқин воқеалар;","– появляется уверенность в себе и понимание своей самоценности;":"– ўзига ишонч ва ўз қадрини тушуниш пайдо бўлади;","– человек начинает проявляться в мир и от этого могут быть перемены к лучшему в каждой сфере;":"– инсон дунёга намоён бўла бошлайди ва бундан ҳар бир соҳада яхшиликка ўзгаришлар бўлиши мумкин;","– улучшение здоровья от того, что энергии и света внутри больше;":"– ичкарида энергия ва нур кўпроқ бўлганидан саломатликнинг яхшиланиши;","– плохие отношения с начальством или отцом показатель к тому, что нужно прорабатывать качества Солнца и проходить его уроки;":"– бошлиқ ёки ота билан ёмон муносабатлар Қуёш фазилатларини ишлаб чиқиш ва унинг сабоқларидан ўтиш кераклигининг кўрсаткичи;","– уважайте себя и людей;":"– ўзингизни ва одамларни ҳурмат қилинг;","– при хорошей проработке появляется куча возможностей в жизни реализоваться и достигать успеха везде;":"– яхши ишлаб чиқилганда ҳаётда рўёбга чиқиш ва ҳамма жойда муваффақиятга эришиш учун кўплаб имкониятлар пайдо бўлади;","– будьте лидером и ведите за собой, несите ответственность;":"– етакчи бўлинг ва ортингиздан эргаштиринг, масъулиятни кўтаринг;","– самостоятельная деятельность, личная и социальная реализация то, где следует ставить намерения;":"– мустақил фаолият, шахсий ва ижтимоий рўёбга чиқиш — ниятларни қўйиш керак бўлган жой;","– учитесь подчиняться без того, чтобы падала ваша самооценка;":"– ўзини баҳолашингиз тушмай бўйсунишни ўрганинг;","– гармонично светите внутренним светом всем без разделения на своих и чужих, плохих и хороших, Солнце светит всем одинаково;":"– ички нурингиз билан ҳаммага ўзимизники ва бегоналарга, ёмон ва яхшиларга бўлмай уйғун нур сочинг, Қуёш ҳаммага бир хил нур сочади;","– работайте над больным эго, изучите что такое здоровый эгоизм и приобретите его;":"– оғриқли эго устида ишланг, соғлом худбинлик нима эканини ўрганинг ва уни орттиринг;","– если не берете ответственность там, где должны взять, возникают сложности от слова Лож, Рост от слова просто;":"– агар олишингиз керак бўлган жойда масъулиятни олмасангиз, қийинчиликлар пайдо бўлади;","– синхронизируйтесь с ритмом Солнца и ваша энергия будет бить ключом.":"– Қуёш ритми билан синхронлашинг ва энергиянгиз булоқдек қайнайди.","Если ваш управитель года Агама – кармы или месяца «2»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «2» бўлса:","– отношения в этот период в приоритете;":"– бу даврда муносабатлар устувор;","– при не проработке больше сомнений и колебаний в этот период;":"– ишлаб чиқилмаганда бу даврда кўпроқ шубҳалар ва иккиланишлар;","– взлеты и падения;":"– кўтарилишлар ва тушишлар;","– сложнее чем в прошлый год принимать решения, сложнее раскрыть себя, сложнее проявиться в социум;":"– ўтган йилга қараганда қарор қабул қилиш қийинроқ, ўзини очиш қийинроқ, жамиятда намоён бўлиш қийинроқ;","– повышена эмоциональность, чувствительность, отсутствие равновесия, нестабильность, в т. ч. в отношениях;":"– кучайган ҳиссиётлилик, сезгирлик, мувозанатнинг йўқлиги, беқарорлик, жумладан муносабатларда;","– начинайте изучать психологию;":"– психологияни ўрганишни бошланг;","– проявляйте заботу к себе и людям;":"– ўзингизга ва одамларга ғамхўрлик кўрсатинг;","– уважайте и налаживайте отношения с женщинами, девушками, всем женским полом;":"– аёллар, қизлар, бутун аёл жинси билан муносабатларни ҳурмат қилинг ва созланг;","– изучайте подсознание, работайте над своим внутренним миром;":"– онг остини ўрганинг, ички дунёнгиз устида ишланг;","– стремитесь к гармонии, делайте медитации, успокаивая ум и всем тем, что вас гармонизирует;":"– уйғунликка интилинг, медитациялар қилинг, ақлни ва сизни уйғунлаштирадиган ҳамма нарса билан тинчлантиринг;","– физические болезни могут появиться от долго эмоционального напряжения;":"– жисмоний касалликлар узоқ ҳиссий тарангликдан пайдо бўлиши мумкин;","– общайтесь с матерью и родней – это прокачает вашу энергию Луны;":"– она ва қариндошлар билан мулоқот қилинг — бу Ой энергиянгизни кучайтиради;","– проработанные качества Луны дают счастье, спокойствие ума и сердца вне зависимости от внешних обстоятельств;":"– ишлаб чиқилган Ой фазилатлари ташқи ҳолатлардан қатъи назар бахт, ақл ва юрак хотиржамлигини беради;","– старайтесь общаться в социуме, пользуясь интуицией и восприимчивостью.":"– интуиция ва таъсирчанликдан фойдаланиб, жамиятда мулоқот қилишга ҳаракат қилинг.","Если ваш управитель года Агама – кармы или месяца «3»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «3» бўлса:","– это число Юпитера, период с «3» считается одним из самых лучших;":"– бу Юпитер сони, «3» ли давр энг яхшилардан бири ҳисобланади;","– много возможностей и много возможностей избежать проблем;":"– кўп имкониятлар ва муаммолардан қочиш учун кўп имкониятлар;","– период расширения всего, личных границ, территориальных, ментальных и любых других, в минусе – телесных;":"– ҳамма нарсанинг — шахсий, ҳудудий, ақлий ва бошқа ҳар қандай чегараларнинг кенгайиш даври, минусда — танадаги;","– увеличение благополучия во всех сферах, в т.ч. в материальных;":"– барча соҳаларда, жумладан моддийда ҳам фаровонликнинг ошиши;","– хорошо для семьи;":"– оила учун яхши;","– период желает доставить человеку все самое благостное;":"– давр инсонга энг эзгу нарсаларни етказишни истайди;","– важно иметь, осознать и соблюдать свои моральные законы и ценности;":"– ўз ахлоқий қонунлари ва қадриятларига эга бўлиш, уларни англаш ва риоя қилиш муҳим;","– соблюдение моральных, вселенских, земных законов влияет на то, на сколько благостно пройдет период;":"– ахлоқий, коинот, дунёвий қонунларга риоя қилиш давр қанчалик эзгу ўтишига таъсир қилади;","– много возможностей для обретения мудростей и инсайтов;":"– донолик ва инсайтлар орттириш учун кўп имкониятлар;","– рекомендовано обучаться и обучать высшим энергиям и законам;":"– олий энергиялар ва қонунларни ўрганиш ва ўргатиш тавсия этилади;","– получение философских, религиозных и духовных знаний;":"– фалсафий, диний ва маънавий билимлар олиш;","– найдите гуру, учителя или сами им будьте/станьте;":"– гуру, устоз топинг ёки ўзингиз бўлинг/бўлиб қолинг;","– уважайте учителей и авторитеты;":"– ўқитувчилар ва обрўларни ҳурмат қилинг;","– берите ответственность и защищайте все что откликается;":"– масъулиятни олинг ва акс садо берадиган ҳамма нарсани ҳимоя қилинг;","– берите под опеку кого-то, давайте наставления, когда попросят, поддерживайте, в т. ч. материально;":"– кимнидир васийликка олинг, сўралганда йўл-йўриқ беринг, қўллаб-қувватланг, жумладан моддий;","– подумайте о детях, заботьтесь о них.":"– фарзандлар ҳақида ўйланг, уларга ғамхўрлик қилинг.","Если ваш управитель года Агама – кармы или месяца «4»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «4» бўлса:","– период проявления накопленной кармы, хорошей и плохой в большой концентрации;":"– тўпланган карманинг, яхши ва ёмоннинг катта концентрацияда намоён бўлиш даври;","– если число Судьбы «4» то период будет, возможно, чуть легче, чем у остальных чисел, у «7» тоже может быть легче;":"– агар Тақдир сони «4» бўлса, давр, эҳтимол, бошқа сонлардагидан бироз енгилроқ бўлади, «7» да ҳам енгилроқ бўлиши мумкин;","– период хаотичности, которую нужно структурировать;":"– тузилмалаш керак бўлган тартибсизлик даври;","– иллюзии, привязанности, материализм, некая неадекватность;":"– иллюзиялар, боғланишлар, материализм, қандайдир ноадекватлик;","– тут можно опуститься на дно и столкнуться с зависимостями, а можно стать лидером в материальном, если соблюден баланс с духовным;":"– бу ерда тубга тушиб, қарамликларга дуч келиш мумкин, ёки маънавий билан мувозанат сақланса, моддийда етакчи бўлиш мумкин;","– много желаний, которые, исполняясь, не приносят удовольствия;":"– амалга ошганда завқ келтирмайдиган кўп истаклар;","– стремления наслаждаться бесконечно и реализовать все желания, часто даже навязанные;":"– чексиз лаззатланиш ва барча, кўпинча ҳатто тиқиштирилган истакларни амалга оширишга интилиш;","– активный период;":"– фаол давр;","– могут быть резкие повороты в жизни, взлеты и падения, дестабилизация в чем-то или во всем;":"– ҳаётда кескин бурилишлар, кўтарилишлар ва тушишлар, нимададир ёки ҳамма нарсада беқарорлашув бўлиши мумкин;","– убирайте зависимости, смотрите реалистично на все;":"– қарамликларни олиб ташланг, ҳамма нарсага реалистик қаранг;","– умейте планировать, структурировать, быть практичным, всему придавать материальную форму, в т. ч. своим идеям;":"– режалаштириш, тузилмалаш, амалий бўлиш, ҳамма нарсага, жумладан ғояларингизга моддий шакл беришни билинг;","– ставьте и достигайте свои истинные цели;":"– ҳақиқий мақсадларингизни қўйинг ва уларга эришинг;","– если ясных целей нет, то мощная энергия, которая стремится сбалансировать материальное и духовное в жизни, снесет все не устоявшееся и обратит в хаос, т. к. не знает к чему стремиться.":"– агар аниқ мақсадлар бўлмаса, ҳаётда моддий ва маънавийни мувозанатлашга интиладиган кучли энергия барқарор бўлмаган ҳамма нарсани супуриб, хаосга айлантиради, чунки нимага интилишни билмайди.","Если ваш управитель года Агама – кармы или месяца «5»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «5» бўлса:","– Меркурий – один из лучших периодов;":"– Меркурий — энг яхши даврлардан бири;","– обучение, поездки, общение, контакты, знакомства;":"– ўқиш, сафарлар, мулоқот, алоқалар, танишувлар;","– желание развития и развития интеллекта;":"– ривожланиш ва интеллектни ривожлантириш истаги;","– познавайте новое, повышайте уровень образования;":"– янгиликни англанг, таълим даражасини оширинг;","– появляется много новых друзей, связей;":"– кўплаб янги дўстлар, алоқалар пайдо бўлади;","– следите за своей речью, будьте внимательны и открыты к новому;":"– нутқингизни кузатинг, эътиборли ва янгиликка очиқ бўлинг;","– изучите влияние слов на свое поведение, т.к. слова – есть программы нашего поведения, которые ведут к поступкам, а те к событиям, а те создают жизнь.":"– сўзларнинг хулқингизга таъсирини ўрганинг, чунки сўзлар — қилмишларга олиб борадиган хулқимиз дастурлари, улар эса воқеаларга, улар эса ҳаётни яратади.","Если ваш управитель года Агама – кармы или месяца «6»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «6» бўлса:","– Венера – хорошо для отношений, комфорта, творчества и материального благополучия;":"– Венера — муносабатлар, қулайлик, ижод ва моддий фаровонлик учун яхши;","– проявляйте таланты и помогайте другим в этом;":"– истеъдодларни намоён қилинг ва бунда бошқаларга ёрдам беринг;","– не хорошо излишне привязываться к комфорту и роскоши;":"– қулайлик ва ҳашаматга ортиқча боғланиш яхши эмас;","– не портите отношения ради своего комфорта;":"– қулайлигингиз учун муносабатларни бузманг;","– увеличение желания к любовным утехам, тут важно качество, а не количество особей;":"– ишқий ҳузурларга истакнинг ошиши, бу ерда шерикларнинг миқдори эмас, сифати муҳим;","– творческое развитие;":"– ижодий ривожланиш;","– появляются возможности для развития в материальном и финансовом плане;":"– моддий ва молиявий жиҳатдан ривожланиш учун имкониятлар пайдо бўлади;","– избегайте излишков в хорошем и плохом, даже в мыслях;":"– яхши ва ёмонда, ҳатто фикрларда ҳам ортиқчаликлардан сақланинг;","– может подарить сильную влюбленность, несли привязанность будет излишней произойдет откат;":"– кучли севиб қолишни ҳадя қилиши мумкин, агар боғланиш ортиқча бўлса, орқага қайтиш юз беради;","– если храните верность партнеру, то период благоволит вам;":"– агар шерикка садоқатни сақласангиз, давр сизга хайрихоҳ;","– благоволит если уважаете и цените женский пол;":"– аёл жинсини ҳурмат қилсангиз ва қадрласангиз, хайрихоҳ;","– появится возможность спасти жизнь, либо у вас либо вам, т. к. Венера мифически воскрешала мертвых;":"– ҳаётни сақлаб қолиш имконияти — ё сизда, ё сизга пайдо бўлади, чунки Венера афсонавий тарзда ўликларни тирилтирган;","– позитивное стечение обстоятельств в этот период – норма;":"– бу даврда ҳолатларнинг ижобий мос келиши — меъёр;","– появление множества новых возможностей, от того, что человек выстраивает гармоничные контакты.":"– инсон уйғун алоқалар қургани учун кўплаб янги имкониятларнинг пайдо бўлиши.","Если ваш управитель года Агама – кармы или месяца «7»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «7» бўлса:","– Кету – сложно, кармично, духовно, улетно от материального;":"– Кету — мураккаб, кармик, маънавий, моддийдан узоқлашган;","– ощущение плавания, нестабильности, перемены, в которых сложно ориентироваться;":"– сузиш, беқарорлик, мўлжал олиш қийин бўлган ўзгаришлар ҳисси;","– запутанности;":"– чалкашликлар;","– если болезни, то они проявляются часто от отсутствия духовности и часто присутствует желание лечить их нетрадиционной медициной;":"– агар касалликлар бўлса, улар кўпинча маънавиятнинг йўқлигидан намоён бўлади ва кўпинча уларни ноанъанавий тиббиёт билан даволаш истаги мавжуд;","– увлечение интоксикантами, если не способен духовно развиваться;":"– агар маънавий ривожланишга қодир бўлмаса, интоксикантларга берилиш;","– апатия и отсутствие осознаваемых желаний;":"– бефарқлик ва англанган истакларнинг йўқлиги;","– период уединения, аскетизма, духовного развития, эзотерики и самопознания;":"– ёлғизлик, зоҳидлик, маънавий ривожланиш, эзотерика ва ўзини англаш даври;","– если нет стремления к тому, что выше строкой, то ограничения, изоляция, отречение, в которых все равно человеку придется обрести мудрость;":"– агар юқоридаги сатрдагиларга интилиш бўлмаса, чекловлар, ажралиш, воз кечиш, уларда барибир инсон донолик орттириши керак бўлади;","– избегайте излишних привязанностей, выкидывайте старое, и это не только про вещи; чем выше уровень духовности и высокая частота энергии, тем лучше период;":"– ортиқча боғланишлардан сақланинг, эскисини ташланг, бу фақат нарсалар ҳақида эмас; маънавият даражаси ва энергия частотаси қанчалик юқори бўлса, давр шунчалик яхши;","– позитивные изменения, в основном, во внутреннем мире;":"– ижобий ўзгаришлар асосан ички дунёда;","– понимание и поиск смысла жизни, найдется если не уйти в зависимости;":"– ҳаёт маъносини тушуниш ва излаш, агар қарамликларга кетилмаса, топилади;","– если погрузился во что-то, то оттуда сложно выбраться будет потом.":"– агар нимагадир шўнғиган бўлса, кейин у ердан чиқиш қийин бўлади.","Если ваш управитель года Агама – кармы или месяца «8»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «8» бўлса:","– Сатурн – карма и труд;":"– Сатурн — карма ва меҳнат;","– период приложения усилий в достижении целей, придется напрягаться, не хочешь – заставит;":"– мақсадларга эришишда саъй-ҳаракат қилиш даври, зўриқишга тўғри келади, истамасангиз — мажбур қилади;","– в этот период придется разобраться с долгами и сложностями;":"– бу даврда қарзлар ва қийинчиликлар билан шуғулланишга тўғри келади;","– если не трудиться в этот период ради своего роста, в т. ч. и материального, то судьба заставит выживать;":"– агар бу даврда ўсишингиз, жумладан моддий ўсиш учун меҳнат қилмасангиз, тақдир омон қолишга мажбур қилади;","– поставьте далекую цель и сделайте декомпозицию на более мелкие цели, и идите к ним по шагам;":"– узоқ мақсад қўйинг ва уни майдароқ мақсадларга бўлинг ва уларга қадамма-қадам боринг;","– самовольно в чем-то ограничьте себя, берите аскезы, развивайте выносливость, стойкость, свой внутренний стальной стержень – этот период дан для этого;":"– ўз ихтиёрингиз билан нимададир ўзингизни чекланг, зоҳидлик олинг, чидамлилик, бардош, ички пўлат ўзагингизни ривожлантиринг — бу давр шунинг учун берилган;","– хорошо реализовываться в бизнесе, управлении, в карьере.":"– бизнес, бошқарув, карьерада рўёбга чиқиш яхши.","Если ваш управитель года Агама – кармы или месяца «9»:":"Агар Агама-карма йили ёки ойининг бошқарувчиси «9» бўлса:","– Марс – завершение начатого, достижение конца в чем-то;":"– Марс — бошланганни якунлаш, нимададир охирига етиш;","– завершается все то, что начали 09 лет назад;":"– 9 йил олдин бошланган ҳамма нарса якунланади;","– активный, энергичный период, с преобладанием поездок, беготни по бесконечным делам;":"– сафарлар, чексиз ишлар билан чопқиллаш устун бўлган фаол, ғайратли давр;","– если не активничать, будет проявляться агрессия, вспыльчивость, конфликтность;":"– агар фаол бўлмасангиз, тажовуз, жаҳлдорлик, низолик намоён бўлади;","– занимайтесь спортом, который вам подходит, даже если этот спорт – ходьба на дальние расстояния – это уберет скисшую, нереализованную энергию в вас и даст место новой;":"– сизга мос спорт билан шуғулланинг, ҳатто бу спорт — узоқ масофаларга юриш бўлса ҳам — бу сиздаги ачиган, рўёбга чиқмаган энергияни олиб ташлайди ва янгисига жой беради;","– хороший период для бизнеса, конкуренции, экстрима, для активной социальной жизни, если не реализовываться так, период покажется более жестким;":"– бизнес, рақобат, экстрим, фаол ижтимоий ҳаёт учун яхши давр, агар шундай рўёбга чиқмасангиз, давр қаттиқроқ туюлади;","– могут произойти глобальные перемены;":"– глобал ўзгаришлар юз бериши мумкин;","– заканчивается девятилетний цикл, и с ним заканчивается какой-то промежуток жизни.":"– тўққиз йиллик цикл тугайди ва у билан ҳаётнинг қандайдир оралиғи тугайди.","Потом снова начинается «1» и начинается что-то новое или переформатированное старое;":"Кейин яна «1» бошланади ва нимадир янги ёки қайта форматланган эски нарса бошланади;","– ставьте цели, стремитесь их достичь, будьте дисциплинированнее;":"– мақсадлар қўйинг, уларга эришишга интилинг, интизомлироқ бўлинг;","– делайте что-то на благо других, тогда период пройдет более гладко;":"– бошқалар фойдасига нимадир қилинг, шунда давр силлиқроқ ўтади;","– может быть больше экстремальных ситуаций и опасностей, если человек не научился управлять своей энергией;":"– агар инсон энергиясини бошқаришни ўрганмаган бўлса, экстремал вазиятлар ва хавфлар кўпроқ бўлиши мумкин;","– ожоги, порезы, раны, пожары, все это если не уметь контролировать свою энергию;":"– куйишлар, кесилишлар, яралар, ёнғинлар, буларнинг барчаси энергиясини назорат қила олмаса;","– могут быть ссоры и испанские страсти в отношениях, с примирением в постели;":"– муносабатларда жанжаллар ва испанча эҳтирослар, тўшакда ярашиш билан бўлиши мумкин;","– часто в конце такого года, могут приходить разрушения ради обновления;":"– кўпинча бундай йилнинг охирида янгиланиш учун вайронагарчиликлар келиши мумкин;","– появляется больше энергии на действия.":"– ҳаракатлар учун кўпроқ энергия пайдо бўлади.","Гороскоп ПотенциалА":"Салоҳият гороскопи","– самоидентификация;":"– ўзини аниқлаш;","– целеустремлённость;":"– мақсадга интилувчанлик;","– опора в жизни;":"– ҳаётдаги таянч;","– способность занять свое место под солнцем;":"– қуёш остида ўз ўрнини эгаллаш қобилияти;","– уверенность в себе и в жизни в целом;":"– ўзига ва умуман ҳаётга ишонч;","– комфортное проявление в социуме и любом обществе.Человек несамостоятелен, не уверен, не проявлен, без характерный.":"– жамиятда ва ҳар қандай даврада қулай намоён бўлиш. Инсон мустақил эмас, ишончсиз, намоён бўлмаган, характерсиз.","– комфортное проявление в социуме и любом обществе.":"– жамиятда ва ҳар қандай даврада қулай намоён бўлиш.","Человек излишне самоуверенный, эгоистичный, самостоятельный, горделивый.":"Инсон ҳаддан ташқари ўзига ишонган, худбин, мустақил, мағрур.","– эмоциональная составляющая человека;":"– инсоннинг ҳиссий таркиби;","– прием и передача информации;":"– маълумотни қабул қилиш ва узатиш;","– память;":"– хотира;","– способность установить контакт с другими;":"– бошқалар билан алоқа ўрнатиш қобилияти;","– навык выстраивать взаимоотношения;":"– ўзаро муносабатлар қуриш кўникмаси;","– интуиция.":"– интуиция.","Человеку очень сложно строить отношения, также принимать и передавать информацию до какой-то степени, он может быть недостаточно уравновешенным или эмоционально нестабильным.":"Инсонга муносабатлар қуриш, шунингдек маълумотни қабул қилиш ва узатиш маълум даражада жуда қийин, у етарлича мувозанатли бўлмаслиги ёки ҳиссий беқарор бўлиши мумкин.","Человек слишком умный, гипер-эмоциональный, гипер-заботливый, зависимость от отношений и людей, излишнее погружение в сферу отношений и общения":"Инсон ҳаддан ташқари ақлли, гипер-ҳиссиётли, гипер-ғамхўр, муносабатлар ва одамларга қарамлик, муносабатлар ва мулоқот соҳасига ортиқча шўнғиш","– действия человека;":"– инсоннинг ҳаракатлари;","– цели человека, их наличие и способность двигаться к ним;":"– инсоннинг мақсадлари, уларнинг мавжудлиги ва уларга ҳаракатланиш қобилияти;","– наличие желаний у человека и готовность их исполнять;":"– инсонда истакларнинг мавжудлиги ва уларни бажаришга тайёрлик;","– если здесь все гармонично (если тройка присутствует), то, как правило, человек будет более активным, чем те, у кого троек нет;":"– агар бу ерда ҳаммаси уйғун бўлса (учлик мавжуд бўлса), одатда инсон учлиги йўқлардан фаолроқ бўлади;","– решительность;":"– қатъият;","– амбиции.":"– амбициялар.","Может быть недостаточно много желаний и человек не понимает, к чему стремиться, либо нет амбиций, которые могли бы реализовать его желания. Либо больше сложностей в достижении желаемого.":"Истаклар етарлича кўп бўлмаслиги ва инсон нимага интилишни тушунмаслиги, ёки унинг истакларини амалга ошира оладиган амбициялар йўқлиги мумкин. Ёки истаганга эришишда кўпроқ қийинчиликлар.","Человек имеет слишком много желаний и целей, а так же потенциал чтобы их достигнуть.":"Инсонда жуда кўп истак ва мақсадлар, шунингдек уларга эришиш учун салоҳият бор.","паквнне":"паквнне","– практичность и реализм;":"– амалийлик ва реализм;","– врожденный кармический потенциал;":"– туғма кармик салоҳият;","– иллюзии и желания;":"– иллюзиялар ва истаклар;","– мечтания, которые реально реализовать на практике делая что-то для этого;":"– бунинг учун нимадир қилиб, амалда ҳақиқатан амалга ошириш мумкин бўлган орзулар;","– баланс духовного и материального.":"– маънавий ва моддий мувозанати.","Человек не умеет мечтать, менее практичен, перекосы между духовным и материальным, нужно учиться балансировать это.":"Инсон орзу қилишни билмайди, камроқ амалий, маънавий ва моддий ўртасида оғишлар, буни мувозанатлашни ўрганиш керак.","Человек будет жить в иллюзиях, придуманных самим собой сказках, то есть у него будет чрезмерно много мечтаний, либо сильных желаний и недостаток практичности и реалистичности, но хороший потенциал для духовного развития.":"Инсон иллюзияларда, ўзи ўйлаб топган эртакларда яшайди, яъни унда ҳаддан ташқари кўп орзулар ёки кучли истаклар ва амалийлик ва реалистликнинг етишмаслиги бўлади, лекин маънавий ривожланиш учун яхши салоҳият.","– интеллектуальные способности;":"– интеллектуал қобилиятлар;","– трезвый анализ происходящего;":"– бўлаётган нарсани ҳушёр таҳлил қилиш;","– навык делать выводы;":"– хулоса чиқариш кўникмаси;","– генерация идей; – умение пользоваться гаджетами и средствами связи;":"– ғоялар яратиш; – гаджетлар ва алоқа воситаларидан фойдалана олиш;","– навык контактирования и взаимодействия.":"– алоқа ва ўзаро таъсир кўникмаси.","У человека изначально, в потенциале, недостаточно идей, недостаточно легко ему дается общение с другими людьми, недостаточно высокий уровень развития интеллекта.":"Инсонда дастлаб, салоҳиятда ғоялар етарли эмас, бошқа одамлар билан мулоқот унга етарлича осон келмайди, интеллект ривожланиш даражаси етарлича юқори эмас.","У человек может быть в большом информационном потоке и в большом количестве контактов, что приводит к легкомысленности, рассеянности и расфокусе на задачах. Есть вариант что он не будет пользоваться информацией на практике.":"Инсон катта маълумот оқимида ва кўп миқдордаги алоқаларда бўлиши мумкин, бу енгилтаклик, паришонлик ва вазифаларда диққатни йўқотишга олиб келади. У маълумотдан амалда фойдаланмаслиги варианти бор.","– личная жизнь;":"– шахсий ҳаёт;","– комфорт;":"– қулайлик;","– сексуальные наслаждения;":"– жинсий лаззатлар;","– благополучие, в т. ч. финансовое и материальное;":"– фаровонлик, жумладан молиявий ва моддий;","– творческие способности;":"– ижодий қобилиятлар;","– способность получать наслаждение от отношений.":"– муносабатлардан лаззат олиш қобилияти.","У человека мало потенциала ко всему выше перечисленному и все это нужно развить, используя те поля в которых есть потенциал.":"Инсонда юқорида санаб ўтилган ҳамма нарсага салоҳият кам ва буларнинг барчасини салоҳият бор майдонлардан фойдаланиб ривожлантириш керак.","Человек излишне привязан к сексу, комфорту и всему выше перечисленному, а излишества, как известно, приводят к обратному результату, включается действие равновесных сил.":"Инсон жинсий яқинлик, қулайлик ва юқорида санаб ўтилган ҳамма нарсага ҳаддан ташқари боғланган, ортиқчаликлар эса маълумки, тескари натижага олиб келади, мувозанат кучларининг таъсири ёқилади.","– аскеза, сознательная или вынужденная;":"– онгли ёки мажбурий зоҳидлик;","– сексуальные проблемы;":"– жинсий муаммолар;","– болезни, преимущественно психосоматические;":"– касалликлар, асосан психосоматик;","– препятствия;":"– тўсиқлар;","– негативные неактуальные установки;":"– салбий долзарб бўлмаган ўрнатмалар;","– духовность, эзотерика, тайны, йога;":"– маънавият, эзотерика, сирлар, йога;","– интуиция;":"– интуиция;","– мудрость;":"– донолик;","– зависимости, как способ отрешиться от физического мира и уйти к своему внутреннему Богу;":"– жисмоний дунёдан узоқлашиш ва ички Худосига кетиш усули сифатида қарамликлар;","– внимание на внутренний мир;":"– ички дунёга эътибор;","– отлет к высшим энергиям, у Кету по легенде голова отрезана, она эфирная, духовная.":"– олий энергияларга учиб кетиш, афсонага кўра Кетунинг боши кесилган, у эфир, маънавий.","У человека, то всего выше перечисленного мало.":"Инсонда юқорида санаб ўтилган ҳамма нарса кам.","Человек в излишних ограничениях ментальных, эмоциональных, которые отражаются из внутреннего мира во внешний в виде препятствий, проблем и болезней, духовные таланты, излишний отлет в высшие сферы и надо приземляться порой.":"Инсон ортиқча ақлий, ҳиссий чекловларда, улар ички дунёдан ташқи дунёга тўсиқлар, муаммолар ва касалликлар кўринишида акс этади, маънавий истеъдодлар, олий соҳаларга ортиқча учиб кетиш ва баъзан ерга тушиш керак.","– деятельность в материальном мире;":"– моддий дунёдаги фаолият;","– дальние высокие материальные цели на жизнь;":"– ҳаёт учун узоқ юксак моддий мақсадлар;","– практичность;":"– амалийлик;","– ответственность, в т. ч. за ближний круг;":"– масъулият, жумладан яқин доира учун;","– бизнес;":"– бизнес;","– деловое сотрудничество с миром;":"– дунё билан ишбилармонлик ҳамкорлиги;","– уверенность и силы, за счет своих реальных заслуг;":"– ўзининг ҳақиқий хизматлари ҳисобига ишонч ва кучлар;","– трудолюбие;":"– меҳнатсеварлик;","– результативность.":"– натижадорлик.","У человека мало сил для реализации целей, нет ответственности и ее надо наработать, нет трудолюбия, если мама в детстве не научила.":"Инсонда мақсадларни амалга ошириш учун кучлар кам, масъулият йўқ ва уни ишлаб чиқиш керак, агар она болаликда ўргатмаган бўлса, меҳнатсеварлик йўқ.","Человек сам себе создает проблемы излишней серьезностью, а излишний потенциал вреден, как известно. Нужно уравновесить это, распределить обязанности, делегировать.":"Инсон ортиқча жиддийлик билан ўзига муаммолар яратади, ортиқча салоҳият эса маълумки зарарли. Буни мувозанатлаш, мажбуриятларни тақсимлаш, вакил қилиш керак.","– наличие энергопотенциала;":"– энергия салоҳиятининг мавжудлиги;","– цели;":"– мақсадлар;","– целеустремленность;":"– мақсадга интилувчанлик;","– физическая сила и духовная, если ее сублимировать из физической;":"– жисмоний куч ва жисмонийдан сублимация қилинса, маънавий куч;","– вдохновение и решительность;":"– илҳом ва қатъият;","– лояльность к риску;":"– таваккалга содиқлик;","– сила воли;":"– ирода кучи;","– сила намерения;":"– ният кучи;","– конфликтность, если физическая энергия не сливается в дела, цели, спорт или экстрим.":"– агар жисмоний энергия ишлар, мақсадлар, спорт ёки экстримга сарфланмаса, низолик.","У человека всего выше перечисленного и надо наработать, открыть кундалини и заняться телом.":"Инсонда юқорида санаб ўтилган ҳамма нарса кам ва уни ишлаб чиқиш, кундалинини очиш ва тана билан шуғулланиш керак.","Человек бездумно, сумасшедше энергичный и так же пользуется своей энергией, надо учиться ей управлять или переводить на духовные сферы и активность в целях.":"Инсон ўйламасдан, телбаларча ғайратли ва энергиясидан ҳам шундай фойдаланади, уни бошқаришни ёки маънавий соҳаларга ва мақсадлардаги фаолликка ўтказишни ўрганиш керак.","Ваше направление – успех во всем. Солнце. Вам стоит реализовать себя везде где пожелается вашей душе, все будет вас толкать к этому.":"Сизнинг йўналишингиз — ҳамма нарсада муваффақият. Қуёш. Сизга қалбингиз истаган ҳамма жойда ўзингизни рўёбга чиқариш керак, ҳамма нарса сизни бунга туртади.","У женщины – брать ответственность, как минимум, за детей, быть лидером, помня о том что ты женщина, быть уверенной.":"Аёлда — ҳеч бўлмаганда фарзандлар учун масъулиятни олиш, аёл эканини ёдда тутиб етакчи бўлиш, ишончли бўлиш.","У мужчины – ответственность за свою жизнь, семью, компанию, ситуации в жизни, быть лидером.":"Эркакда — ўз ҳаёти, оиласи, компанияси, ҳаётдаги вазиятлар учун масъулият, етакчи бўлиш.","Дарите радость и счастье, покажите пример радостного, сильного пути – так вы встраива- етесь во вселенную как ее недостающий пазл и несетесь вместе с ней к высотам. Это описание вашего жизненного пути. Знайте свои ХОЧУ – это для вас ключевое, а чтобы их знать нужно предотвратить слив энергии на нецелевые для вашей жизни дела, чужие цели и неистинные навязанные желания.":"Қувонч ва бахт ҳадя қилинг, қувноқ, кучли йўл намунасини кўрсатинг — шу тарзда коинотга унинг етишмаётган пазли сифатида кириб оласиз ва у билан бирга чўққиларга шошасиз. Бу ҳаёт йўлингизнинг тавсифи. ИСТАЙМАН ларингизни билинг — бу сиз учун асосий, уларни билиш учун эса энергиянинг ҳаётингиз учун мақсадсиз ишларга, бировнинг мақсадлари ва ҳақиқий бўлмаган тиқиштирилган истакларга оқиб кетишининг олдини олиш керак.","Должны быть очень четкие цели в жизни, четкие действия, понимание, что сейчас нужно делать, что делать потом, к чему стремиться, осознать свои желания. Человек должен уважать свое время, стараться не тратить его попусту. Ты либо растешь либо деградируешь, либо живешь либо умираешь, середины в движении по пути не бывает ни у кого. Вот ваш пример пути покажет как нужно проявляться и реализовываться в жизни людям.":"Ҳаётда жуда аниқ мақсадлар, аниқ ҳаракатлар, ҳозир нима қилиш, кейин нима қилиш, нимага интилиш кераклигини тушуниш, истакларини англаш бўлиши керак. Инсон ўз вақтини ҳурмат қилиши, уни беҳуда сарфламасликка ҳаракат қилиши керак. Сен ё ўсасан, ё таназзулга учрайсан, ё яшайсан, ё ўласан, йўлда ҳаракатда ўрталиқ ҳеч кимда бўлмайди. Мана сизнинг йўл намунангиз одамларга ҳаётда қандай намоён бўлиш ва рўёбга чиқишни кўрсатади.","Ваше направление – ощущения, интуиция, взаимоотношения. Создайте отношения и семью, которая будет примером для общества и ей будут восхищаться. Луна. Отношения есть со всеми и всем и это ваша задача показать пример как можно взаимодействовать гармонично что с деньгами, что с партнером, что с семьей, что с врагами, которых у вас по сути не должно быть либо они становятся вашими почитателями вскоре.":"Сизнинг йўналишингиз — ҳислар, интуиция, ўзаро муносабатлар. Жамият учун намуна бўладиган ва ундан ҳайратланадиган муносабатлар ва оила яратинг. Ой. Муносабатлар ҳамма ва ҳамма нарса билан бор ва пул билан ҳам, шерик билан ҳам, оила билан ҳам, сизда моҳиятан бўлмаслиги керак бўлган ёки тез орада мухлисларингизга айланадиган душманлар билан ҳам уйғун ўзаро таъсир қилиш мумкинлигининг намунасини кўрсатиш — сизнинг вазифангиз.","Развивайте заботливость, мягкость, нежность, инь, женскую энергию, чувственность, отзывчивость, помогайте людям. Когда мужчина будучи уверенно мужественным способен включить себе гармоничный инь (у каждого человека есть и инь и ян) – он будет светиться как святой.":"Ғамхўрлик, юмшоқлик, нозиклик, инь, аёл энергияси, ҳиссиётлилик, ҳамдардликни ривожлантиринг, одамларга ёрдам беринг. Эркак ишончли эркакча бўлиб, ўзида уйғун иньни ёқа олганда (ҳар бир инсонда ҳам инь, ҳам ян бор) — у авлиёдек нур сочади.","Ваша интуиция способна помочь решить задачи другим или дать совет. Советы даем прошенные и за деньги, сами не лезем к людям.":"Интуициянгиз бошқаларнинг вазифаларини ҳал қилишга ёрдам беришга ёки маслаҳат беришга қодир. Маслаҳатларни сўралганда ва пулга берамиз, одамларга ўзимиз аралашмаймиз.","Вам важно изучать психологию: психологию личности, психологию семейных отношений, и уметь слушать, развивать навыки слушания, чтобы помогать близким и друзьям, людям которые вас окружают. Помогать в жизненном пути, давать правильные советы. Это одна из главных задач ваших – так вы встраиваетесь во вселенную как ее недостающий пазл и несетесь вместе с ней к высотам. И вообще – это жизненный путь, который всегда связан с партнерством. Поэтому важно, чтобы рядом был человек, с которым вы будете вместе идти к какой- то цели.":"Сизга психологияни ўрганиш муҳим: шахс психологияси, оилавий муносабатлар психологияси, ва тинглай билиш, яқинлар ва дўстлар, сизни ўраб турган одамларга ёрдам бериш учун тинглаш кўникмаларини ривожлантириш. Ҳаёт йўлида ёрдам бериш, тўғри маслаҳатлар бериш. Бу асосий вазифаларингиздан бири — шу тарзда коинотга унинг етишмаётган пазли сифатида кириб оласиз ва у билан бирга чўққиларга шошасиз. Ва умуман — бу доим шериклик билан боғлиқ ҳаёт йўли. Шунинг учун ёнингизда қандайдир мақсад сари бирга борадиган инсон бўлиши муҳим.","Женщинам важно быть и ощущать себя женщиной, быть в инь – состоянии или в гармонии. Развивайте мягкость, гибкость, чувствительность, интуицию. Очень важно познавать себя, так вы будете знать и других, развить способность к равновесию, чуткости, психологической стабильности. Вам помогут занятия йогой или медитациями, которые способствуют умиротворению и психологическому балансу. Ваше состояние – то, что дает людям исцеление в любом плане жизни.":"Аёлларга аёл бўлиш ва ўзини аёл ҳис қилиш, инь ҳолатида ёки уйғунликда бўлиш муҳим. Юмшоқлик, мослашувчанлик, сезгирлик, интуицияни ривожлантиринг. Ўзингизни англаш жуда муҳим, шу тарзда бошқаларни ҳам биласиз, мувозанат, сезгирлик, психологик барқарорлик қобилиятини ривожлантирасиз. Сизга осойишталик ва психологик мувозанатга ёрдам берадиган йога ёки медитация машғулотлари ёрдам беради. Сизнинг ҳолатингиз — одамларга ҳаётнинг ҳар қандай жиҳатида шифо берадиган нарса.","Ваше направление – энергия лидера, похожая на 1, но только на 3 все равняются как на просветителя, учителя, пример культуры и духовности, оптимизма. Юпитер. Вы – лидер, который передает знания, советник.":"Сизнинг йўналишингиз — 1 га ўхшаш етакчи энергияси, лекин фақат 3 га ҳамма маърифатчи, устоз, маданият ва маънавият, оптимизм намунаси сифатида тенглашади. Юпитер. Сиз — билим етказадиган етакчи, маслаҳатчи.","Вам нужно развивать мудрость, всегда учиться и практиковать те навыки, которые изучили, постоянно повышать уровень квалификации и передавать знания. Чем бы вы не были заняты – нужно быть экспертом в этом на сто процентов.":"Сизга доноликни ривожлантириш, доим ўқиш ва ўрганган кўникмаларни амалда қўллаш, доим малака даражасини ошириш ва билим етказиш керак. Нима билан банд бўлмасангиз — бунда юз фоиз эксперт бўлиш керак.","Еще момент вашего пути – это расширение. Избегайте утечки сил на не нужное и прокрастинации, потому что ваша задача открывать новые горизонты сначала себе, а потом другим. Стоит быть всегда готовым к тому чтобы дать дельный совет и оказать помощь знаниями, для этого нужно расширяться и учиться, учить других, при этом двигаясь постоянно в новое в своей сфере.":"Йўлингизнинг яна бир жиҳати — бу кенгайиш. Кераксиз нарсага куч оқиб кетиши ва кечиктиришдан сақланинг, чунки сизнинг вазифангиз янги уфқларни аввал ўзингизга, кейин бошқаларга очиш. Доим фойдали маслаҳат беришга ва билим билан ёрдам кўрсатишга тайёр бўлиш керак, бунинг учун кенгайиш ва ўқиш, бошқаларни ўргатиш, бунда ўз соҳангизда доим янгиликка ҳаракатланиш керак.","В семье это тоже работает – чем больше семья, детей, тем вернее для вас, если территория, то большая и перспективная. Если зарабатываете деньги – много зарабатывайте. Нужно получить некий опыт «у меня всего много и это классно». Умейте это делать и показать другим на своем опыте.":"Оилада ҳам бу ишлайди — оила, фарзандлар қанчалик кўп бўлса, сиз учун шунчалик тўғри, агар ҳудуд бўлса, катта ва истиқболли. Агар пул топсангиз — кўп топинг. «Менда ҳамма нарса кўп ва бу ажойиб» деган тажрибани олиш керак. Буни қилишни ва бошқаларга ўз тажрибангизда кўрсатишни билинг.","Самый разрушающий фактор – это вести какой-то аморальный образ жизни. Отсутствие морали и нравственности глобально разрушает жизнь «3». Вас это разрушает глобально, не так как другие числа.":"Энг вайронкор омил — қандайдир ахлоқсиз ҳаёт тарзини юритиш. Ахлоқ ва одобнинг йўқлиги «3» ҳаётини глобал вайрон қилади. Бу сизни бошқа сонлардагидек эмас, глобал вайрон қилади.","Ваше направление – вам нужно иметь очень четкие желания, сильные желания, которые будут вас вдохновлять двигаться, для этого они должны быть истинно вашими, а не навязанными. Раху. Ваша задача – бесконечный рост и развитие, баланс духовного и материального, без перекосов. Это реализация желаний без обязательного деления опытом или наставления других. Вам стоит в своей жизни много чего реализовать.":"Сизнинг йўналишингиз — сизга жуда аниқ истаклар, ҳаракатланишга илҳомлантирадиган кучли истаклар бўлиши керак, бунинг учун улар тиқиштирилган эмас, ҳақиқатан сизники бўлиши керак. Раҳу. Сизнинг вазифангиз — чексиз ўсиш ва ривожланиш, оғишларсиз маънавий ва моддий мувозанати. Бу тажриба билан бўлишиш ёки бошқаларга йўл кўрсатиш шартисиз истакларни амалга ошириш. Ҳаётингизда кўп нарсани амалга оширишингиз керак.","Важна практичность, стойкость, четкий структурированный план действий, потому что внимание может рассеиваться, увлекаться. Есть риск недоделывать проекты и дела из-за этого, а вам такое не допустимо. Ваше число заставляет вас интересоваться всем и побольше.":"Амалийлик, бардош, аниқ тузилмалашган ҳаракат режаси муҳим, чунки эътибор тарқалиши, берилиб кетиши мумкин. Шу сабабли лойиҳалар ва ишларни охирига етказмаслик хавфи бор, сизга эса бу мумкин эмас. Сонингиз сизни ҳамма нарсага ва кўпроқ қизиқишга мажбур қилади.","Ваш основной инструмент – практичность и развитие концентрации за счет какой-то последовательности действий, планирования жизни и планомерного роста. Раху – объединяет два мира – материю и духовный, поэтому важно иметь четкие намерения и силу воли чтобы дойти до конца и не улететь в духовный перекос, мечты, иллюзии и токсичные вещества.":"Сизнинг асосий воситангиз — амалийлик ва қандайдир ҳаракатлар изчиллиги, ҳаётни режалаштириш ва режали ўсиш ҳисобига диққатни жамлашни ривожлантириш. Раҳу икки дунёни — материя ва маънавийни бирлаштиради, шунинг учун охиригача бориш ва маънавий оғиш, орзулар, иллюзиялар ва заҳарли моддаларга учиб кетмаслик учун аниқ ниятлар ва ирода кучига эга бўлиш муҳим.","Тонкий мир познания, психологии, эзотерики, духовных знаний, нумерологии, астрологии, религиоведения, йоги, медитации – всего, что связано с внутренними глубинными реализациями – вы обретаете силу через глубину самопознания, изучение законов Вселенной, священные книги, какую-то мудрость, глубинные психологические паттерны поведения.":"Англаш, психология, эзотерика, маънавий билимлар, нумерология, астрология, диншунослик, йога, медитациянинг нозик дунёси — ички чуқур рўёбга чиқишлар билан боғлиқ ҳамма нарса — сиз ўзини англаш чуқурлиги, Коинот қонунларини ўрганиш, муқаддас китоблар, қандайдир донолик, чуқур психологик хулқ андозалари орқали куч топасиз.","Также можно реализоваться очень хорошими бизнес-тренерами. Через самопознание вам предстоит реализовать себя во внешнем мире, поэтому какие-то бизнес-проекты очень важно реализовывать, но их нужно реализовывать на основе понимания законов этого мира. Поэтому важны эзотерические направления, но в то же время и материальное развитие, материальное расширение. Гармония и баланс духовного и материи, связка их для одного дела.":"Шунингдек жуда яхши бизнес-мураббий сифатида рўёбга чиқиш мумкин. Ўзини англаш орқали сизга ташқи дунёда ўзингизни рўёбга чиқаришга тўғри келади, шунинг учун қандайдир бизнес-лойиҳаларни амалга ошириш жуда муҳим, лекин уларни бу дунё қонунларини тушуниш асосида амалга ошириш керак. Шунинг учун эзотерик йўналишлар муҳим, лекин айни пайтда моддий ривожланиш, моддий кенгайиш ҳам. Маънавий ва материянинг уйғунлиги ва мувозанати, уларни бир иш учун боғлаш.","Умейте делать перепросмотр жизни, переоценку ценностей и трансформацию пройденного пути в новое и актуальное, чтобы всегда быть на коне, на волне, в тренде и тд.":"Доим отда, тўлқинда, трендда ва ҳ.к. бўлиш учун ҳаётни қайта кўриб чиқишни, қадриятларни қайта баҳолашни ва босиб ўтилган йўлни янги ва долзарб нарсага ўзгартиришни билинг.","Ваше направление – свобода и стремление к ней. Меркурий. Передвигайтесь, путешествуйте. Вам нужны перемены, разные места, меньше привязанностей, чувство безграничности.":"Сизнинг йўналишингиз — эркинлик ва унга интилиш. Меркурий. Ҳаракатланинг, саёҳат қилинг. Сизга ўзгаришлар, турли жойлар, камроқ боғланишлар, чексизлик ҳисси керак.","Важно также обучение. Важна информированность и количество информации. Хорошо заниматься СМИ, маркетингом, туризмом, деятельностью, где можно много контактировать, что-то рассказывать. Не те глубокие наставления как у числа 3, а больше как экскурсии, что- то интересное рассказывать, что помогает людям расширить кругозор.":"Ўқиш ҳам муҳим. Хабардорлик ва маълумот миқдори муҳим. ОАВ, маркетинг, туризм, кўп алоқа қилиш, нимадир ҳикоя қилиш мумкин бўлган фаолият билан шуғулланиш яхши. 3 сонидагидек чуқур насиҳатлар эмас, кўпроқ экскурсиялар каби, одамларга дунёқарашни кенгайтиришга ёрдам берадиган қизиқарли нарсаларни ҳикоя қилиш.","Развивайте интеллект и адекватность, рациональность. Развивайте способность отличать хорошее от плохого.":"Интеллект ва адекватлик, рационалликни ривожлантиринг. Яхшини ёмондан фарқлаш қобилиятини ривожлантиринг.","Ваше направление – творчество, эстетика, красота, искусство, любовь и качество. Венера. Нужно реализоваться в любви, но не количественно, а качественно с одним партнером. Важен контакт с противоположным полом, близость, чувство любви, настоящей любви и верности. Верность на всех уровнях, даже в мыслях. Различие с 2 в том, что тем нужно создать семью, а вам ощущать любовь с партнером.":"Сизнинг йўналишингиз — ижод, эстетика, гўзаллик, санъат, муҳаббат ва сифат. Венера. Муҳаббатда рўёбга чиқиш керак, лекин миқдорий эмас, битта шерик билан сифатли. Қарама-қарши жинс билан алоқа, яқинлик, муҳаббат ҳисси, ҳақиқий муҳаббат ва садоқат муҳим. Барча даражаларда, ҳатто фикрларда ҳам садоқат. 2 дан фарқи шундаки, уларга оила яратиш, сизга эса шерик билан муҳаббатни ҳис қилиш керак.","Умейте выстроить гармоничные взаимоотношения, для этого интересуйтесь психологией отношений, разницей мужчин и женщин. В идеале быть Гуру отношений и помогать в этом людям.":"Уйғун ўзаро муносабатлар қуришни билинг, бунинг учун муносабатлар психологияси, эркаклар ва аёллар фарқига қизиқинг. Идеалда муносабатлар Гуруси бўлиш ва бунда одамларга ёрдам бериш.","Еще момент – творческая реализация, чистота на всех уровнях, красота, комфорт, твор- ческая проявленость, вдохновение, актерство.":"Яна бир жиҳат — ижодий рўёбга чиқиш, барча даражаларда тозалик, гўзаллик, қулайлик, ижодий намоён бўлиш, илҳом, актёрлик.","Ваше направление – быть лучшими знатоками эзотерических направлений: психологии, эзотерики, астрологии, таро, парапсихологии, ясновидения и всего, что с этим связано. Кету. Также можете быть сыщиками, или у вас может быть очень сильная интуиция. 7 – это энер- гия схожа с 4, это Раху и Кету. У вас может быть повышенная чувствительность к затмению, к коридорам затмения, как и у 4, вы можете чувствовать сильные колебания и становиться более эмоциональными. Эти периоды для 7 является благоприятны в том, чтобы трансформировать свою жизнь, создать какие-то конкретные изменения.":"Сизнинг йўналишингиз — эзотерик йўналишларнинг: психология, эзотерика, астрология, таро, парапсихология, каромат ва бу билан боғлиқ ҳамма нарсанинг энг яхши билимдонлари бўлиш. Кету. Шунингдек изқувар бўлишингиз ёки жуда кучли интуицияга эга бўлишингиз мумкин. 7 — бу 4 га ўхшаш энергия, бу Раҳу ва Кету. Сизда 4 даги каби тутилишга, тутилиш коридорларига юқори сезгирлик бўлиши мумкин, кучли тебранишларни ҳис қилишингиз ва ҳиссиётлироқ бўлишингиз мумкин. Бу даврлар 7 учун ҳаётини ўзгартириш, қандайдир аниқ ўзгаришлар яратиш учун қулай.","Ваш жизненный путь должен обязательно быть основан на духовных ценностях. Потому как 7 – это, в минусе – потери и лишения материального характера, взлеты и падения, а с другой стороны – это глубокая самореализация в духовном плане.":"Ҳаёт йўлингиз албатта маънавий қадриятларга асосланиши керак. Чунки 7 — бу минусда моддий хусусиятдаги йўқотишлар ва маҳрумликлар, кўтарилишлар ва тушишлар, бошқа томондан эса — маънавий жиҳатдан чуқур ўзини рўёбга чиқариш.","Вы можете быть очень хорошими инструкторами по йоге, заниматься глубокими медитациями, быть серьезными духовными и религиозными деятелями. Можете быть очень хорошими астрологами, нумерологами, психологами. Вы способны отлично реализовать себя в этих областях.":"Сиз жуда яхши йога инструкторлари бўлишингиз, чуқур медитациялар билан шуғулланишингиз, жиддий маънавий ва диний арбоблар бўлишингиз мумкин. Жуда яхши астрологлар, нумерологлар, психологлар бўлишингиз мумкин. Сиз бу соҳаларда ўзингизни аъло рўёбга чиқаришга қодирсиз.","Если же человек в этом не реализуется, для него может быть опасность злоупотребления алкоголя или каких-то наркотиков, потому что 7 может стягивать вниз.":"Агар инсон бунда рўёбга чиқмаса, унинг учун алкоголь ёки қандайдир гиёҳвандликни суиистеъмол қилиш хавфи бўлиши мумкин, чунки 7 пастга тортиши мумкин.","Найдите глубинный смысл жизни, умейте понимать что вы делаете в этом мире, важно обрести смысл существования и познать глубинную мудрость. Без этого велика вероятность рассеивать свое внимание.":"Ҳаётнинг чуқур маъносини топинг, бу дунёда нима қилаётганингизни тушунишни билинг, мавжудлик маъносини топиш ва чуқур доноликни англаш муҳим. Бусиз эътиборни тарқатиш эҳтимоли катта.","У вас может быть развит «пофигизм», т.о. вы можете не обращать внимания на какие- то мелочи, которые для других имеют значение, из-за чего возможны конфликты в отношениях. Вам необходимо быть более внимательным к деталям, быть ответственным к тем вещам, за которые вы отвечаете и стараться исполнять свои обещания.":"Сизда «бепарволик» ривожланган бўлиши мумкин, шу тарзда бошқалар учун аҳамиятга эга бўлган қандайдир майда нарсаларга эътибор бермаслигингиз мумкин, шу сабабли муносабатларда низолар бўлиши мумкин. Сизга тафсилотларга эътиборлироқ бўлиш, жавоб берадиган нарсаларингизга масъулиятли бўлиш ва ваъдаларингизни бажаришга ҳаракат қилиш зарур.","Развивайте чувствительность, сострадание, восприимчивость, учитесь слышать других людей и умейте понимать их жизненные проблемы, помогайте им по их запросу, но не без него.":"Сезгирлик, ҳамдардлик, таъсирчанликни ривожлантиринг, бошқа одамларни эшитишни ўрганинг ва уларнинг ҳаётий муаммоларини тушунишни билинг, уларга сўрови бўйича ёрдам беринг, лекин сўровсиз эмас.","Ваше направление – это труд. Сатурн. Чтобы обладать успехом в жизни, вы должны быть трудолюбивы, стать квалифицированным специалистом в своей области деятельности и очень любить то, чем вы занимаетесь, стараться приносить окружающему миру как можно больше пользы. Учитесь таким качествам как: терпение, трудолюбие, дисциплина, аскетизм, то есть умейте ограничивать себя в чем-то сознательно, иначе этим займется сама жизнь.":"Сизнинг йўналишингиз — бу меҳнат. Сатурн. Ҳаётда муваффақиятга эга бўлиш учун меҳнатсевар бўлишингиз, фаолият соҳангизда малакали мутахассис бўлишингиз ва шуғулланаётган ишингизни жуда севишингиз, атрофдаги дунёга иложи борича кўпроқ фойда келтиришга ҳаракат қилишингиз керак. Қуйидаги фазилатларни ўрганинг: сабр, меҳнатсеварлик, интизом, зоҳидлик, яъни нимададир ўзингизни онгли чеклашни билинг, акс ҳолда бу билан ҳаётнинг ўзи шуғулланади.","Для вас ограничения проходят менее болезненно, чем для других чисел. Вы способны достигнуть небывалых высот, стать мощным руководителем и управленцем.":"Сиз учун чекловлар бошқа сонлардагига қараганда камроқ оғриқли ўтади. Сиз эшитилмаган чўққиларга эришишга, кучли раҳбар ва бошқарувчи бўлишга қодирсиз.","Чем более сконцентрированный, сфокусированный на цели образ жизнь вы ведете, тем больше у вас прогресса и достижений. Включайте в свою жизнь планирование, структуриро- вание, стратегии.":"Қанчалик жамланган, мақсадга йўналган ҳаёт тарзини юритсангиз, тараққиёт ва ютуқларингиз шунчалик кўп. Ҳаётингизга режалаштириш, тузилмалаш, стратегияларни киритинг.","Вы склонны нести все на себе, перетруждаться, поэтому учитесь делегировать свои обязанности, тем кто может сделать это лучше вас или вы просто не хотите чем-либо сами заниматься.":"Сиз ҳаммасини ўз зиммангизда кўтаришга, ортиқча меҳнат қилишга мойилсиз, шунинг учун мажбуриятларингизни буни сиздан яхшироқ қила оладиганларга ёки нима биландир ўзингиз шуғуллангингиз келмаганда вакил қилишни ўрганинг.","Ваше направление – постоянное движение, активность, что-то организуйте, станьте воинами за добро и справедливость, занимайтесь спортом, наполняйте свою жизнь событиями и движением вперед к целям, старайтесь развивать свое тело и мышцы, силу. Марс. Это чистая энергия как она есть.":"Сизнинг йўналишингиз — доимий ҳаракат, фаоллик, нимадир ташкил қилинг, эзгулик ва адолат учун жангчи бўлинг, спорт билан шуғулланинг, ҳаётингизни воқеалар ва мақсадлар сари олдинга ҳаракат билан тўлдиринг, танангиз ва мушакларингиз, кучингизни ривожлантиришга ҳаракат қилинг. Марс. Бу қандай бўлса шундай тоза энергия.","У вас много сил и их нужно куда – то вкладывать, можно вплоть до изнеможения (вы быстро восстановитесь). Старайтесь делать что-то полезное для общества.":"Сизда кўп куч бор ва уни қаергадир киритиш керак, ҳолдан тойгунча мумкин (сиз тез тикланасиз). Жамият учун фойдали нимадир қилишга ҳаракат қилинг.","Контролируйте ярость и гнев, не ревнуйте, старайтесь меньше испытывать раздражение, обиды. От этого всего нужно избавляться и стараться брать на себя ответственность за те события и ситуации, на которые вы можете обижаться. Осознавайте свои эмоции. Учитесь быть в равновесии и умиротворении.":"Жаҳл ва ғазабни назорат қилинг, рашк қилманг, камроқ асабийлашишга, хафа бўлишга ҳаракат қилинг. Буларнинг барчасидан қутулиш ва хафа бўлиши мумкин бўлган воқеалар ва вазиятлар учун масъулиятни ўз зиммангизга олишга ҳаракат қилиш керак. Ҳис-туйғуларингизни англанг. Мувозанат ва осойишталикда бўлишни ўрганинг.","Будьте внимательны в отношениях, там часто горят итальянские страсти, могут быть конфликты и проблемы в личной жизни. Работайте над собой.":"Муносабатларда эҳтиёт бўлинг, у ерда кўпинча итальянча эҳтирослар ёнади, шахсий ҳаётда низолар ва муаммолар бўлиши мумкин. Ўз устингизда ишланг.","Вам свойственно мыслить как организатор, вы сначала определите кто может сделать дело вместе с вами или за вас, прежде, чем приступить самому к исполнению. Вы все организуете как лидер.":"Сизга ташкилотчи каби фикрлаш хос, ўзингиз ижрога киришишдан олдин аввал ким сиз билан ёки сизнинг ўрнингизга ишни қила олишини аниқлайсиз. Сиз ҳаммасини етакчи сифатида ташкил қиласиз.","Вы можете стать очень активным, если у вас есть цель и даже вставать вместе с солнцем по утру, чтобы скорее реализовать задуманное. Вы начинаете с импульса и большого желания, определяете ответственных за каждое мероприятие, идя к поставленной цели.":"Агар мақсадингиз бўлса, жуда фаол бўлишингиз ва ҳатто режалаганингизни тезроқ амалга ошириш учун эрталаб қуёш билан бирга туришингиз мумкин. Сиз туртки ва катта истакдан бошлайсиз, қўйилган мақсад сари бориб, ҳар бир тадбир учун масъулларни аниқлайсиз.","Вы можете держать свое слово если вам это сейчас выгодно или для того, чтобы получить признание. Вам свойственно быть благодарным и благородным, делать с жизнерадостностью и упорством, так что вас ничто не остановит, если вы что-то для себя решили.":"Агар бу ҳозир сизга фойдали бўлса ёки эътироф олиш учун сўзингизда тура оласиз. Сизга миннатдор ва олижаноб бўлиш, ҳаётсеварлик ва қатъият билан қилиш хос, шундай қилиб, агар ўзингиз учун нимадир ҳал қилган бўлсангиз, сизни ҳеч нарса тўхтатмайди.","Если что-то долго не случается, иногда у вас может вообще отпадать желание что-либо делать и потом вы можете безответственно подходить к делу и зависеть от мнения других людей, причём вообще любых людей.":"Агар нимадир узоқ юз бермаса, баъзан сизда умуман нимадир қилиш истаги йўқолиши мумкин ва кейин ишга масъулиятсиз ёндашишингиз ва бошқа одамларнинг, умуман ҳар қандай одамларнинг фикрига боғлиқ бўлишингиз мумкин.","Если вы не знаете, что нужно делать вы склонны изобрести велосипед либо следовать стратегиям других людей, которые уже принесли успех им, но это не всегда срабатывает, т.к. чужой успех основан на талантах этих людей, а не на ваших собственных.":"Агар нима қилиш кераклигини билмасангиз, велосипед ихтиро қилишга ёки уларга аллақачон муваффақият келтирган бошқа одамларнинг стратегияларига эргашишга мойилсиз, лекин бу доим ҳам ишламайди, чунки бировнинг муваффақияти ўзингизникига эмас, ўша одамларнинг истеъдодларига асосланган.","Вы стараетесь руководить так, чтобы было сделано, проконтролировать все. Хотите чтобы все было в лучшем виде, чтобы это было идеально, ярко, чтобы вас и ваш проект заметили, чтобы это было супер-пупер. Вы используете все самое лучшее для этого, можете ориентироваться на то, чему учил вас отец, либо начальник. Либо относитесь к своему делу как ваш отец.":"Сиз бажарилиши учун раҳбарлик қилишга, ҳаммасини назорат қилишга ҳаракат қиласиз. Ҳаммаси энг яхши кўринишда, идеал, ёрқин бўлишини, сизни ва лойиҳангизни пайқашларини, бу супер бўлишини истайсиз. Бунинг учун энг яхши ҳамма нарсадан фойдаланасиз, отангиз ёки бошлиғингиз ўргатган нарсага йўналишингиз мумкин. Ёки ишингизга отангиз каби муносабатда бўласиз.","Когда делаете хотите быть в центре внимания и получить его, и также сами можете уделять слишком много внимания доходя до того, что начинаете давить и сжигать своим вниманием так, что у людей не остается места для проявления их талантов и вообще себя. Не делайте так, не нарушайте свободу воли и выбора каждого человека.":"Қилаётганингизда диққат марказида бўлишни ва уни олишни истайсиз, шунингдек ўзингиз ҳам ҳаддан ташқари кўп эътибор беришингиз мумкин, одамларда истеъдодлари ва умуман ўзини намоён қилиш учун жой қолмайдиган даражада эътиборингиз билан босим ўтказиб, куйдира бошлашгача етасиз. Бундай қилманг, ҳар бир инсоннинг ирода ва танлов эркинлигини бузманг.","Для вас характерно подойти попросить кого-то сделать что нужно. Вы будете искать того, кто вам подскажет как сделать то, что требуется. У вас часто возникают сомнения в выборе, вы слушаете интуицию, а если нет, то выбор может быть ошибочным.":"Сизга кимдандир керакли нарсани қилишни сўрашга бориш хос. Сиз талаб қилинган нарсани қандай қилишни айтиб берадиган кишини излайсиз. Сизда танловда кўпинча шубҳалар пайдо бўлади, интуицияни тинглайсиз, агар тингламасангиз, танлов хато бўлиши мумкин.","У вас всегда всё меняется, подходы к делу плавают. Вы опираетесь на интуицию и опыт, опираетесь на свои эмоции или можете сделать что-то на эмоциях. Вам нужно подходить к делу тогда, когда эмоциональная волна уже прошла вы, потому что вы можете просто перехотеть это делать. Также вы можете спросить маму или спрашивать женщин что делать и привлекать женский пол к каким-то делам, вы можете делать очень заботливо, очень нежно, покровительствующе, по-матерински, что-то делать, вникая в душу тех, кто будет в этом деле участвовать. Вы делаете то, что идёт из души.":"Сизда доим ҳамма нарса ўзгаради, ишга ёндашувлар сузиб юради. Сиз интуиция ва тажрибага, ҳис-туйғуларингизга таянасиз ёки нимадир ҳис-туйғулар таъсирида қилишингиз мумкин. Сизга ишга ҳиссий тўлқин ўтиб кетганда киришиш керак, чунки шунчаки буни қилгингиз келмай қолиши мумкин. Шунингдек онангиздан сўрашингиз ёки аёллардан нима қилишни сўрашингиз ва аёл жинсини қандайдир ишларга жалб қилишингиз мумкин, сиз жуда ғамхўрлик билан, жуда нозик, ҳомийлик қилиб, оналарча, бу ишда қатнашадиганларнинг қалбига кириб, нимадир қилишингиз мумкин. Сиз қалбдан келадиган нарсани қиласиз.","Также могут быть периоды, когда вы то делаете, то не делаете, то хочется, то вообще не хочется делать и подход к делу зависит от вашего настроения.":"Шунингдек гоҳ қиладиган, гоҳ қилмайдиган, гоҳ истайдиган, гоҳ умуман қилгиси келмайдиган даврлар бўлиши мумкин ва ишга ёндашув кайфиятингизга боғлиқ.","Вы способны делать спокойно, миролюбиво, с чувственностью, чтобы это нравилось всем, делать очень вежливо, дружелюбно, бывает что не можете собраться с мыслями и вообще определиться, что вам нужно делать сейчас. Вы очень волнуетесь, боитесь начинать что-то делать, вдруг это может не получится, и вы не начинаете, чтобы не тратить силы зря. У вас бывают истерики в том, чтобы начать что-то делать, потому что у вас базовая эмоция – это страх, вы можете делать что-то из страха. У вас может быть сильная привязанность к тому, что вы делаете и прежде чем начать делать вам нужно выпить кофе или алкоголь.":"Сиз хотиржам, тинчликсеварлик билан, ҳиссиётлилик билан, ҳаммага ёқадиган қилиб, жуда хушмуомала, дўстона қилишга қодирсиз, баъзан фикрларингизни йиғиб, умуман ҳозир нима қилишингиз кераклигини аниқлай олмайсиз. Сиз жуда ҳаяжонланасиз, нимадир қилишни бошлашдан қўрқасиз, бирдан чиқмай қолиши мумкин деб, кучни беҳуда сарфламаслик учун бошламайсиз. Сизда нимадир қилишни бошлашда жазавалар бўлади, чунки сизнинг асосий ҳис-туйғунгиз — қўрқув, нимадир қўрқувдан қилишингиз мумкин. Сизда қилаётган нарсангизга кучли боғланиш бўлиши мумкин ва қилишни бошлашдан олдин сизга қаҳва ёки алкоголь ичиш керак.","Бывает вы много суетитесь, становитесь мнительным, забываете что хотели сделать или запоминаете, но при эмоциональном потрясении. Может быть много беспокойств насчёт начала дела, но если вы делаете всё качественно и в соответствии с регламентом, а то и с партнером, то ощущаете умиротворение. Вы знаете интуитивно, что нужно делать, чтобы это было дружелюбно ко всему и без вреда для каждого.":"Баъзан кўп ғимирлайсиз, шубҳаланувчан бўлиб қоласиз, нима қилмоқчи бўлганингизни унутасиз ёки эслаб қоласиз, лекин ҳиссий ларзада. Иш бошлаш ҳақида кўп хавотирлар бўлиши мумкин, лекин агар ҳаммасини сифатли ва регламентга мувофиқ, ҳатто шерик билан қилсангиз, осойишталикни ҳис қиласиз. Сиз ҳамма нарсага дўстона ва ҳар бирига зарарсиз бўлиши учун нима қилиш кераклигини интуитив биласиз.","Вы будете подходить к делу экспертно. Вам люди будут стремиться помогать, ученики или те, кому вы давали советы сами предлагают помощь. Вы смотрите на авторитеты смотрите на успешные проекты, которые уже реализовались, берёте наставничества для того чтоб начать, либо сами наставляете, учите кого-то что-то делать и они делают. Либо вы сами учитесь и потом передаёте эти знания в свое дело, применяете их, возможно, вы вкладываете очень большие деньги, если это необходимо проекту.":"Сиз ишга экспертларча ёндашасиз. Сизга одамлар ёрдам беришга интилади, шогирдлар ёки сиз маслаҳат берганлар ўзлари ёрдам таклиф қилади. Сиз обрўларга қарайсиз, аллақачон амалга ошган муваффақиятли лойиҳаларга қарайсиз, бошлаш учун устозлик оласиз, ёки ўзингиз йўл кўрсатасиз, кимнидир нимадир қилишга ўргатасиз ва улар қилади. Ёки ўзингиз ўқийсиз ва кейин бу билимларни ишингизга етказасиз, уларни қўллайсиз, эҳтимол, агар лойиҳага зарур бўлса, жуда катта пул киритасиз.","Вы предпочитаете, чтобы проекты были реализованы на широкую аудиторию, чтоб проекты были глобальные, чтобы всегда можно было как-то расширить свои границы, чтобы проект можно было расширить, чтобы дело было мировым или как можно больше людей вовлекалось в него, чтобы дело было социальным. Бывает такое, что именно для вас формируются новые профессии в компаниях где вы работаете. На определённом уровне развития, вы подходите к делу духовно и в соответствии с божественными законами, можете быть идеологом какого-то дела, философски подходите или ориентируетесь на успех иностранных компаний.":"Сиз лойиҳалар кенг аудиторияга амалга оширилишини, лойиҳалар глобал бўлишини, доим қандайдир чегараларингизни кенгайтириш мумкин бўлишини, лойиҳани кенгайтириш мумкин бўлишини, иш жаҳоний бўлишини ёки иложи борича кўпроқ одам унга жалб қилинишини, иш ижтимоий бўлишини афзал кўрасиз. Баъзан айнан сиз учун ишлаётган компанияларингизда янги касблар шаклланади. Ривожланишнинг маълум даражасида сиз ишга маънавий ва илоҳий қонунларга мувофиқ ёндашасиз, қандайдир ишнинг мафкурачиси бўлишингиз, фалсафий ёндашишингиз ёки чет эл компаниялари муваффақиятига йўналишингиз мумкин.","Вы можете иногда очень пессимистично подходить к делу, а иногда со здоровым оптимизмом, ну либо чрезмерным оптимизмом, но очень искусственным, скажем так. Можете спорить очень много, если у вас не хватает знаний или нет уважения к тем людям, с которыми вы работаете. Вы можете поучать других, но лучше быть наставником, когда вас об этом попросили. Часто вы подходите ко всему с уважением, особенно если в деле старшие или авторитетные люди, опираетесь на моральную и духовную составляющую.":"Сиз баъзан ишга жуда пессимистик, баъзан эса соғлом оптимизм билан, ёки ҳаддан ташқари оптимизм билан, лекин жуда сунъий, деб айтайлик, ёндашишингиз мумкин. Агар билимингиз етмаса ёки бирга ишлаётган одамларга ҳурматингиз бўлмаса, жуда кўп баҳслашишингиз мумкин. Бошқаларга насиҳат қилишингиз мумкин, лекин сиздан буни сўраганда устоз бўлган яхшироқ. Кўпинча ҳамма нарсага ҳурмат билан ёндашасиз, айниқса ишда катта ёки обрўли одамлар бўлса, ахлоқий ва маънавий таркибга таянасиз.","Вы подходите к делу очень непредсказуемо, всегда все по разному, в зависимости от обстоятельств, вы можете пытаться делать что-то, чтобы это управляло массами людей. Иногда вы находитесь в некой иллюзии или в неком самообмане и вам необходимо быть максимально реалистичным для того, чтобы реализовать дела.":"Сиз ишга жуда олдиндан айтиб бўлмайдиган, ҳолатларга қараб доим турлича ёндашасиз, оммани бошқариши учун нимадир қилишга уринишингиз мумкин. Баъзан қандайдир иллюзияда ёки ўзини алдашда бўласиз ва ишларни амалга ошириш учун сизга максимал реалист бўлиш зарур.","У вас всегда большущие желания относительно чего либо и вы пытаетесь их удовлетворить, и причём не разбираясь ваше желание это истинно или нет. У вас прошёл импульс и вы сразу это делаете, в итоге не получаете какого-то удовлетворения своих желаний.":"Сизда доим нимагадир нисбатан улкан истаклар бор ва сиз уларни, бунда истагингиз ҳақиқийми-йўқми тушунмай, қондиришга уринасиз. Сизда туртки ўтди ва дарҳол буни қиласиз, натижада истакларингиздан қандайдир қониқиш олмайсиз.","Вы также действуете по принципу расширения, пытаетесь делать так, чтобы что-то было большим, чтобы имело принцип развития. У вас есть какой встроенный внутренний оптимизм относительно подхода к делу и вы можете делать с некой жадностью, прям цепляться и для того, чтобы начать какое-то дело вам приходится очень хорошо над собой поработать.":"Сиз шунингдек кенгайиш тамойили бўйича ҳаракат қиласиз, нимадир катта бўлиши, ривожланиш тамойилига эга бўлиши учун қилишга уринасиз. Сизда ишга ёндашувга нисбатан қандайдир ички оптимизм ўрнатилган ва қандайдир очкўзлик билан, ёпишиб қилишингиз мумкин ва қандайдир ишни бошлаш учун ўз устингизда жуда яхши ишлашингизга тўғри келади.","Вы можете делать что-то искусственно, что-то не по-настоящему, как бы делая вид и потом все случается самым неожиданным образом. У вас очень много неожиданностей в начале при подходе к делу не зависящих от вас.":"Сиз нимадир сунъий, ҳақиқий бўлмаган тарзда, гўё кўринишини қилиб қилишингиз мумкин ва кейин ҳаммаси энг кутилмаган тарзда юз беради. Сизда ишга ёндашишда бошида сизга боғлиқ бўлмаган жуда кўп кутилмаган ҳодисалар бор.","Можете и наоборот стремится к большой естественности и предпочтения всего натурального, можете понимать интуитивно, что нужно делать и когда. При подходе к делу можете проверить все на картах Таро, астрологии, нумерологии или любом другом эзотерическом способе. Иногда вы можете последовать какой-то идее, не обращая внимания на реальное положение вещей и можете манипулировать другими людьми или пытаться что-то там использовать, какую-то магию, сверхъестественные силы и тд.":"Аксинча, катта табиийликка ва табиий ҳамма нарсани афзал кўришга интилишингиз, нимани ва қачон қилишни интуитив тушунишингиз мумкин. Ишга ёндашишда ҳаммасини Таро карталари, астрология, нумерология ёки бошқа ҳар қандай эзотерик усулда текширишингиз мумкин. Баъзан ҳақиқий ҳолатга эътибор бермай, қандайдир ғояга эргашишингиз ва бошқа одамларни манипуляция қилишингиз ёки у ерда нимадир, қандайдир сеҳр, ғайритабиий кучлар ва ҳ.к.дан фойдаланишга уринишингиз мумкин.","Вам очень хорошо при начале дела опираться на оккультные науки, на нумерологию, на интуицию, таро или астрологию, для того чтобы у вас был успех дела и чёткое понимание того, что происходит.":"Сизга иш бошлашда ишнинг муваффақияти ва нима бўлаётганини аниқ тушуниш учун оккульт фанлар, нумерология, интуиция, таро ёки астрологияга таяниш жуда яхши.","Вы подходите к делу с девизом «Легки на подъем», можете расфокусироваться, переключаться и не доделывать, либо очень умно и учитывая степень своей свободы. Договариваетесь, подписываете контракты или документы.":"Сиз ишга «Енгил кўтариладиган» шиори билан ёндашасиз, диққатни йўқотишингиз, алмашишингиз ва охирига етказмаслигингиз, ёки жуда ақлли ва эркинлигингиз даражасини ҳисобга олиб ёндашишингиз мумкин. Келишасиз, шартномалар ёки ҳужжатларни имзолайсиз.","Подходите к делу очень разумно, смотрите на современные тенденции, что сейчас важно новому поколению, стараетесь учиться постоянно, сами много рассказывайте тем, кто связан с вами в этом деле. Много контактируйте прежде, чем начать, наводите контакты и связи для этого. Бывает контакты и связи приводят к тому, что у вас появляется идея для чего- то нового, подход зависит от круга общения, всегда разный. Прежде чем начать можете спросить братьев сестер и собираете информацию прежде чем что-то начать делать. Бывает начинаете несколько дел одновременно, делаете с интересом, и записываете все в блокноты, либо в какие-то заметки. Ориентируйтесь по каким-то книгам и можете делать особо не вникая в суть, немного поверхностно.":"Ишга жуда оқилона ёндашасиз, замонавий тенденцияларга, ҳозир янги авлод учун нима муҳимлигига қарайсиз, доим ўқишга ҳаракат қиласиз, бу ишда сиз билан боғлиқ бўлганларга ўзингиз кўп гапириб берасиз. Бошлашдан олдин кўп алоқа қилинг, бунинг учун алоқалар ва боғланишлар ўрнатинг. Баъзан алоқалар ва боғланишлар сизда янги нарса учун ғоя пайдо бўлишига олиб келади, ёндашув мулоқот доирасига боғлиқ, доим турлича. Бошлашдан олдин ака-ука, опа-сингиллардан сўрашингиз мумкин ва нимадир қилишни бошлашдан олдин маълумот йиғасиз. Баъзан бир вақтнинг ўзида бир нечта ишни бошлайсиз, қизиқиш билан қиласиз ва ҳаммасини блокнотларга ёки қандайдир қайдларга ёзасиз. Қандайдир китоблар бўйича мўлжал оласиз ва моҳиятига унчалик кирмай, бироз юзаки қилишингиз мумкин.","Часто можете продавать свои идеи для того, чтобы другие начали их делать, а вы получили какую-либо выгоду. Очень сильно можете анализировать все прежде, чем начать делать. Делаете все очень логично, быстро схватываете суть того, что необходимо сделать, для того чтобы реализовать дела. Находите со всеми общий язык и способны объяснять людям, которые с вами работают сложные вещи простым доступным языком.":"Кўпинча бошқалар уларни қила бошлаши ва сиз қандайдир фойда олишингиз учун ғояларингизни сотишингиз мумкин. Қилишни бошлашдан олдин ҳаммасини жуда кучли таҳлил қилишингиз мумкин. Ҳаммасини жуда мантиқий қиласиз, ишларни амалга ошириш учун нима қилиш кераклигининг моҳиятини тез илғайсиз. Ҳамма билан тил топишасиз ва сиз билан ишлайдиган одамларга мураккаб нарсаларни оддий тушунарли тилда тушунтиришга қодирсиз.","Подходите к делу очень здравомысленно, и одновременно где-то несерьезно, где-то можно пошутить. Быстро адаптируетесь к меняющимся обстоятельствам при начале дела, бывает такое, что включается хитрость и вы пытаетесь сделать что-то только из своей выгоды. Используете свой интеллект, при этом может быть суетливость. В начале дела хотите манипулировать другими людьми, бывает такое, что начинайте дела и когда у вас все проваливается в самом начале вы не извлекаете из этого никакого урока, ничего не меняете и можете обвинять при этом других людей в своих проблемах. Если вы никак не успокаиваете свой мозг, то можете стать очень импульсивным и нервным.":"Ишга жуда соғлом фикр билан ва айни пайтда қаердадир жиддий эмас, қаердадир ҳазиллашиш мумкин тарзда ёндашасиз. Иш бошлашда ўзгарувчан ҳолатларга тез мослашасиз, баъзан айёрлик ёқилади ва фақат ўз фойдангиз учун нимадир қилишга уринасиз. Интеллектингиздан фойдаланасиз, бунда ғимирлаш бўлиши мумкин. Иш бошида бошқа одамларни манипуляция қилишни истайсиз, баъзан ишларни бошлайсиз ва ҳаммаси бошидаёқ барбод бўлганда, бундан ҳеч қандай сабоқ чиқармайсиз, ҳеч нарсани ўзгартирмайсиз ва бунда муаммоларингизда бошқа одамларни айблашингиз мумкин. Агар миянгизни ҳеч қандай тинчлантирмасангиз, жуда импульсив ва асабий бўлиб қолишингиз мумкин.","Вы делаете то, что вам нравится, делаете творчески, с искусством, красиво визуально и чтобы это вызывало восхищение и похвалу у людей. Вы можете просить или нанять кого- то, приобщить к делу.":"Сиз ёққан нарсани қиласиз, ижодий, санъат билан, визуал чиройли ва одамларда ҳайрат ва мақтов уйғотадиган қилиб қиласиз. Кимнидир сўрашингиз ёки ёллашингиз, ишга жалб қилишингиз мумкин.","Делаете так, чтобы всем было в кайф и вам было в кайф, в первую очередь делаете из своих чувств, которые вы испытываете сейчас или когда-либо испытывали, ассоциируя с этим делом. На вас влияет семья и близкие, а когда вы что-то начинаете делать, вы учитываете их потребности, старайтесь сделать так, чтобы всем было комфортно, чтобы дело приносило удовольствие. Вы хотите упаковать все так, чтобы было красиво и дорого, чтобы можно было за большие деньги это реализовать. Вы можете делать некачественно, а количественно, но это никогда не приводит к особому результату, поэтому вам необходимо делать качественно и сконцентрировать усилия на одном подходе.":"Ҳаммага завқ бўладиган ва сизга завқ бўладиган қилиб қиласиз, аввало ҳозир бошдан кечираётган ёки қачондир бошдан кечирган, бу иш билан боғлаган ҳисларингиздан келиб чиқиб қиласиз. Сизга оила ва яқинлар таъсир қилади, нимадир қила бошлаганингизда уларнинг эҳтиёжларини ҳисобга оласиз, ҳаммага қулай бўлиши, иш завқ келтириши учун ҳаракат қиласиз. Сиз ҳаммасини чиройли ва қиммат бўлиши, катта пулга сотиш мумкин бўлиши учун қадоқлашни истайсиз. Сиз сифатсиз, миқдорий қилишингиз мумкин, лекин бу ҳеч қачон алоҳида натижага олиб келмайди, шунинг учун сизга сифатли қилиш ва саъй-ҳаракатларни битта ёндашувга жамлаш зарур.","Вы можете делать что-то под влиянием женского пола, подруг либо делать для женщин, что-то делать, чтобы вовлекать девушек в процессы или просто делать что-либо по-женски. Можете начинать дела так, что делаете в зависимости от того, насколько вам чувственно кайфово, насколько вы наслаждаетесь. И если перестали наслаждаться, то вы перестаете это делать. Вы можете пытаться манипулировать другими людьми, не хотеть видеть суть того, что создаете или подходить к делу с любовью, с хорошим чувством прекрасного, с чувством юмора и делать харизматичный проект.":"Сиз нимадир аёл жинси, дугоналар таъсирида қилишингиз ёки аёллар учун қилишингиз, қизларни жараёнларга жалб қилиш учун нимадир қилишингиз ёки шунчаки нимадир аёлларча қилишингиз мумкин. Ишларни сизга ҳиссий жиҳатдан қанчалик завқли, қанчалик лаззатланаётганингизга қараб қиладиган тарзда бошлашингиз мумкин. Ва агар лаззатланишни тўхтатсангиз, буни қилишни тўхтатасиз. Сиз бошқа одамларни манипуляция қилишга уринишингиз, яратаётган нарсангизнинг моҳиятини кўришни истамаслигингиз ёки ишга муҳаббат билан, гўзалликнинг яхши ҳисси билан, юмор ҳисси билан ёндашиб, харизматик лойиҳа қилишингиз мумкин.","Для других людей вы непонятно как делаете, делаете интуитивно, очень странно, все зависит от вашего состояния сейчас.":"Бошқа одамлар учун сиз тушунарсиз тарзда қиласиз, интуитив, жуда ғалати қиласиз, ҳаммаси ҳозирги ҳолатингизга боғлиқ.","Стремитесь сделать через духовность или из какой-то космической информации, непонятной никому, возможно, через новые технологии, через компьютерные, через электронику, что-то делать используя гаджеты и использовать новинки техники, использовать программирование. Вы делаете интуитивно, в одиночку.":"Маънавият орқали ёки ҳеч кимга тушунарсиз қандайдир космик маълумотдан, эҳтимол, янги технологиялар, компьютер, электроника орқали, гаджетлардан фойдаланиб нимадир қилишга ва техника янгиликларидан фойдаланишга, дастурлашдан фойдаланишга интиласиз. Сиз интуитив, ёлғиз қиласиз.","Когда ничего не получается начать, вы можете гневаться и проявлять импульсивное поведение. У вас перед началом чего-либо могут быть большие страхи или вообще, вы боитесь что-либо начать, потому что вы боитесь что-то менять в своей жизни и иногда настолько, что это может быть доходить того, что вы уже практически на самом дне, но при этом вы ничего не делаете для того, чтобы выйти оттуда.":"Ҳеч нарсани бошлаш уддаланмаганда, ғазабланишингиз ва импульсив хулқ кўрсатишингиз мумкин. Сизда нимадир бошлашдан олдин катта қўрқувлар бўлиши ёки умуман нимадир бошлашдан қўрқишингиз мумкин, чунки ҳаётингизда нимадир ўзгартиришдан қўрқасиз ва баъзан шунчаликки, бу сиз деярли тубда бўлишингизга етиши мумкин, лекин бунда у ердан чиқиш учун ҳеч нарса қилмайсиз.","Вы можете делать что-то отрекаясь от всех или что-то делать испытывая при этом резкие перепады настроения. Либо наоборот, подходить к делу очень консервативно и так, что до вас не донести, что это уже не работает.":"Сиз ҳаммадан воз кечиб нимадир қилишингиз ёки бунда кайфиятнинг кескин ўзгаришларини бошдан кечириб, нимадир қилишингиз мумкин. Ёки аксинча, ишга жуда консерватив ва сизга бу энди ишламаслигини етказиб бўлмайдиган тарзда ёндашишингиз мумкин.","Вы можете начинать делать с чрезмерной самоуверенностью, которая потом сменяется неуверенностью в себе.":"Сиз ҳаддан ташқари ўзига ишонч билан қила бошлашингиз мумкин, у кейин ўзига ишончсизлик билан алмашади.","Вы не знаете, что делать, не знаете какую роль вы занимаете, или что-то начинаете делать, что может приводить к саморазрушению либо вреду для других людей.":"Нима қилишни билмайсиз, қандай ролни эгаллаётганингизни билмайсиз ёки ўз-ўзини вайрон қилиш ёки бошқа одамларга зарарга олиб келиши мумкин бўлган нимадир қила бошлайсиз.","Вы можете делать что-то из большого консерватизма, который уже не работает и защищать те идеи, которые уже устарели, а также можете подходить с решительностью, мудростью и дисциплиной, с внутренней силой и абсолютно не бояться каких-либо перемен.":"Сиз энди ишламайдиган катта консерватизмдан нимадир қилишингиз ва аллақачон эскирган ғояларни ҳимоя қилишингиз, шунингдек қатъият, донолик ва интизом билан, ички куч билан ёндашишингиз ва қандайдир ўзгаришлардан мутлақо қўрқмаслигингиз мумкин.","У вас могут вообще отсутствовать страхи и появляется такая безбашенность. Вы видите проницательно то, к чему приведёт это дело и вам желательно всегда при начале какого-то дела поработать над собой и использовать оккультные знания, использовать нумерологию, астрологию либо любые другие, позаниматься йогой, чтобы у вас было глубинное понимание того, что вы будете делать.":"Сизда умуман қўрқувлар йўқ бўлиши ва шундай бошибошдоқлик пайдо бўлиши мумкин. Сиз бу иш нимага олиб келишини зийраклик билан кўрасиз ва сизга қандайдир иш бошлашда доим ўз устингизда ишлаш ва нима қилишингизни чуқур тушуниш учун оккульт билимлардан, нумерология, астрология ёки бошқа ҳар қандайидан фойдаланиш, йога билан шуғулланиш маъқул.","Вы делаете основательно, расчетливо, все распланировано, по полочкам, в режиме, в тайм менеджменте, очень трудолюбиво.":"Сиз пухта, ҳисоб-китоб билан, ҳаммаси режалаштирилган, жой-жойига қўйилган, режимда, тайм-менежментда, жуда меҳнатсеварлик билан қиласиз.","Подходите к делу считая, что все очень тяжело, вам вообще тяжело что-то начинать. Зная, что затянется надолго, вы всегда планируете. Вы делаете что-то, что будет служить долгое время, опираетесь на законы. Вы делаете то, что должны и будь что будет.":"Ишга ҳаммаси жуда оғир деб ҳисоблаб ёндашасиз, сизга умуман нимадир бошлаш оғир. Узоққа чўзилишини билиб, доим режалаштирасиз. Сиз узоқ вақт хизмат қиладиган нимадир қиласиз, қонунларга таянасиз. Сиз қилишингиз керак бўлган нарсани қиласиз ва нима бўлса бўлсин.","Порой вы смотрите на начало проекта пессимистично и обязательно все с холодным расчётом, без эмоций и как взрослый человек или даже как дедушка с большим опытом. Вы стараетесь не делать зря и посвящаете день и ночь своему делу.":"Баъзан лойиҳа бошланишига пессимистик ва албатта ҳаммасини совуқ ҳисоб-китоб билан, ҳис-туйғусиз ва катта инсон ёки ҳатто катта тажрибали бобо каби қарайсиз. Беҳуда қилмасликка ҳаракат қиласиз ва кечаю кундуз ишингизга бағишлайсиз.","Вы можете начинать дела с чрезмерной организованностью и четкостью во всём, слишком серьезно ко всему относиться и имеете внутри большое напряжение, не умеете расслабиться и впадаете даже в депрессии либо глубочайшее уныние, появляется пустота в душе и из этой пустоты вы как отталкивайтесь от дна и начинаете что-то делать.":"Сиз ишларни ҳамма нарсада ҳаддан ташқари уюшқоқлик ва аниқлик билан бошлашингиз, ҳамма нарсага ҳаддан ташқари жиддий муносабатда бўлишингиз ва ичингизда катта тарангликка эга бўлишингиз, бўшашишни билмаслигингиз ва ҳатто депрессия ёки энг чуқур тушкунликка тушишингиз мумкин, қалбда бўшлиқ пайдо бўлади ва бу бўшлиқдан сиз гўё тубдан итарилиб, нимадир қила бошлайсиз.","В начале какого-то дела вы можете общаться с людьми, которые связаны с вашим делом, как с какими-то механизмами, которые вообще не имеют каких-то чувств, а могут только функцию выполнять. Это не верно.":"Қандайдир иш бошида сиз ишингиз билан боғлиқ одамлар билан умуман қандайдир ҳисларга эга бўлмаган, фақат функцияни бажара оладиган қандайдир механизмлар каби мулоқот қилишингиз мумкин. Бу тўғри эмас.","Вы можете быть подозрительными и делать осторожно, верно высчитывая все возможные события, делать чтоб было надёжно и проявлять лидерские качества и ответственность, холодный расчёт, уверенность и четкость.":"Сиз шубҳаланувчан бўлишингиз ва барча мумкин бўлган воқеаларни тўғри ҳисоблаб, эҳтиёткорлик билан қилишингиз, ишончли бўлиши учун қилишингиз ва етакчилик фазилатлари ва масъулият, совуқ ҳисоб-китоб, ишонч ва аниқликни намоён қилишингиз мумкин.","Вы можете сделать что-то исключительно свое, соединяя весь свой прошлый опыт воедино.":"Сиз бутун ўтмиш тажрибангизни бирлаштириб, фақат ўзингизникини қилишингиз мумкин.","Вы делаете активно, предприимчиво, стремитесь доделать до конца, чтобы не висели гештальты, можете сделать из всего бизнес, делаете самостоятельно, энергично с запалом.":"Сиз фаол, ишбилармонлик билан қиласиз, гештальтлар осилиб қолмаслиги учун охиригача етказишга интиласиз, ҳамма нарсадан бизнес қилишингиз мумкин, мустақил, ғайратли, жўшқинлик билан қиласиз.","Могут возникать конфликты, вы начинаете какое-то дело и всегда боретесь за что-то, соперничаете с кем-то внутри себя либо снаружи, пытаетесь быть первым, лидировать, физически много делать, опираясь на самого себя. Велика опасность не заканчивать дела из-за того, что перегорел. Вы делаете только для того чтобы добиться цели, а сам результат уже вам неважен, главное что добился цели и смог.":"Низолар пайдо бўлиши мумкин, сиз қандайдир иш бошлайсиз ва доим нима учундир курашасиз, кимдир билан ичингизда ёки ташқарида рақобатлашасиз, биринчи бўлишга, етакчилик қилишга, ўзингизга таяниб жисмонан кўп қилишга уринасиз. Куйиб кетганингиз туфайли ишларни тугатмаслик хавфи катта. Сиз фақат мақсадга эришиш учун қиласиз, натижанинг ўзи эса сизга энди муҳим эмас, асосийси мақсадга эришдингиз ва уддаладингиз.","Делаете с большой силой воли и бесстрашием, опираетесь на энтузиазм, делаете практично и решительно с четким, сильным, логическим мышлением, умеете воплощать вообще любые идеи, которые только пришли в голову.":"Катта ирода кучи ва қўрқмаслик билан қиласиз, иштиёққа таянасиз, аниқ, кучли, мантиқий фикрлаш билан амалий ва қатъиятли қиласиз, бошга келган умуман ҳар қандай ғояларни амалга оширишни биласиз.","При начале любого дела может быть агрессивность по отношению к вашему окружению, может быть гнев либо вы делаете жестко и безжалостно. Когда делаете, то следуете механизмам, схемам и пользуетесь техническими средствами. Можете подходить к делу дисциплинированно и быть хорошим руководителем.":"Ҳар қандай иш бошида атрофингизга нисбатан тажовузкорлик бўлиши, ғазаб бўлиши ёки қаттиқ ва шафқатсиз қилишингиз мумкин. Қилаётганингизда механизмлар, схемаларга эргашасиз ва техник воситалардан фойдаланасиз. Ишга интизомли ёндашишингиз ва яхши раҳбар бўлишингиз мумкин.","Солнце – руководить. Вы будете стараться найти человека, который сможет сделать работу за вас под вашим началом и контролем. Вы будете делать ярко, оригинально, творчески, всегда учитывая свои желания и то, в каком свете выставляет вас этот метод. Вы будете делать так, чтобы получить признание и всеобщее внимание. Ясно осмысливаете методы, ситуацию и потом делаете креативно, так чтобы выделиться. Можете делать с большой импульсивностью и быть чрезмерно активным, если желаете материальных благ. Если обещаете, сделаете, чтобы не опозориться. Делаете так, чтобы это принесло вам власть и признание. В самых плохих случаях, можете приказывать и наслаждаться страданиями других, контролировать их и использовать в своих целях, подавляя их волю (нельзя!). Гневаетесь если не получается, можете унывать от этого, вести себя высокомерно и без уважения к мужскому полу и начальникам. В самых прекрасных случаях ставите цель и идете к ней с ясным пониманием ситуации. Уважаете всех людей и их яркость. Руководите без наказаний.":"Қуёш — раҳбарлик қилиш. Сиз сизнинг бошчилигингиз ва назоратингиз остида ишни сизнинг ўрнингизга қила оладиган инсонни топишга ҳаракат қиласиз. Сиз ёрқин, ўзига хос, ижодий, доим истакларингизни ва бу усул сизни қандай нурда кўрсатишини ҳисобга олиб қиласиз. Сиз эътироф ва умумий эътиборни олиш учун қиласиз. Усуллар, вазиятни равшан англайсиз ва кейин ажралиб туриш учун креатив қиласиз. Агар моддий неъматлар истасангиз, катта импульсивлик билан қилишингиз ва ҳаддан ташқари фаол бўлишингиз мумкин. Агар ваъда қилсангиз, шарманда бўлмаслик учун қиласиз. Бу сизга ҳокимият ва эътироф келтириши учун қиласиз. Энг ёмон ҳолатларда буйруқ беришингиз ва бошқаларнинг азобларидан лаззатланишингиз, уларни назорат қилишингиз ва иродасини бостириб, ўз мақсадларингизда фойдаланишингиз мумкин (мумкин эмас!). Чиқмаса ғазабланасиз, бундан тушкунликка тушишингиз, кибр билан ва эркак жинси ва бошлиқларга ҳурматсиз ўзингизни тутишингиз мумкин. Энг ажойиб ҳолатларда мақсад қўясиз ва унга вазиятни равшан тушуниб борасиз. Барча одамларни ва уларнинг ёрқинлигини ҳурмат қиласиз. Жазоларсиз раҳбарлик қиласиз.","Луна. Вы будете просить кого-то что-то сделать для вас, при этом заботливо будете с этим человеком общаться. Может возникать страх делать все самому, потому что вы не уверены и часто с первого раза ошибаетесь в том, каким образом делать. В процессе могут быть сильные стрессы и даже истерики. Вам обязательно нужен партнер или муж, или родственник, чтобы вы были спокойны. Дела ведете как мамочка, которая заботится о своем дитя. Бывает полностью зависите от внешних обстоятельств и вам даже хорошо показывать свои слабости и уповать на свое положение – вам это всегда приносит результат. В процессе можете пить много воды, а если в стрессе, то кофе или побаловаться алкоголем. В процессе реализации можете помнить только то, что эмоционально вас возбудило в лучшем или не очень смысле. Если вы привыкли слушать себя, то память отличная на все. Может возникать большая мнительность и суетливость, тут вам поможет партнер от которого вы сможете отталкиваться в принятии решений. Стараетесь, чтобы всем было хорошо, комфортно, часто не можете сказать «Нет» тем, кто доставляет вам проблемы. Можете как «мама» уступать свое первенство в проекте, отдавая лидерство другому, а сами остаетесь на вторых ролях. Если вы делаете в одиночку, вам сложно понять, что нужно делать из-за постоянных беспокойств. Нужен партнер и знание себя + психологии людей. Используйте свою интуицию, она у вас очень сильная.":"Ой. Сиз кимдандир сиз учун нимадир қилишни сўрайсиз, бунда бу инсон билан ғамхўрлик билан мулоқот қиласиз. Ҳаммасини ўзингиз қилиш қўрқуви пайдо бўлиши мумкин, чунки ишончсизсиз ва кўпинча биринчи мартада қандай қилишда хато қиласиз. Жараёнда кучли стресслар ва ҳатто жазавалар бўлиши мумкин. Хотиржам бўлишингиз учун сизга албатта шерик ёки эр, ёки қариндош керак. Ишларни боласига ғамхўрлик қиладиган онадек юритасиз. Баъзан ташқи ҳолатларга бутунлай боғлиқсиз ва сизга ҳатто заифликларингизни кўрсатиш ва аҳволингизга умид қилиш яхши — бу сизга доим натижа келтиради. Жараёнда кўп сув ичишингиз, стрессда эса қаҳва ёки бироз алкоголь ичишингиз мумкин. Амалга ошириш жараёнида фақат сизни яхши ёки унчалик яхши бўлмаган маънода ҳиссий қўзғатган нарсани эслашингиз мумкин. Агар ўзингизни тинглашга одатланган бўлсангиз, хотира ҳамма нарсага аъло. Катта шубҳаланувчанлик ва ғимирлаш пайдо бўлиши мумкин, бу ерда сизга қарор қабул қилишда таяна оладиган шерик ёрдам беради. Ҳаммага яхши, қулай бўлишига ҳаракат қиласиз, кўпинча сизга муаммо келтирадиганларга «Йўқ» дея олмайсиз. «Она» каби лойиҳада биринчиликни бериб, етакчиликни бошқасига бериб, ўзингиз иккинчи ролларда қолишингиз мумкин. Агар ёлғиз қилсангиз, доимий хавотирлар туфайли нима қилиш кераклигини тушуниш қийин. Шерик ва ўзингизни + одамлар психологиясини билиш керак. Интуициянгиздан фойдаланинг, у сизда жуда кучли.","Юпитер. Руководствуется знанием. Вы будете просить помочь тех людей, кто находится на обучение или на наставничестве у вас, кому вы даете советы и рекомендации. Поручаете дела своим детям, часто бывает к вам сами приходят люди и спрашивают «что я могу для тебя сделать?», появляются люди, которые сами хотят вам помочь сделать. Любите делать чужими руками и обставить все так, чтобы люди сделали за вас. Философски подходите к делу и всегда видите, где нужно расширить территорию или коллектив увеличить, чтобы успех был самым высшим. Делаете с уважением ко всем, с высокой моралью, милосердием и добротой.":"Юпитер. Билим билан бошқарилади. Сиз ўқишда ёки устозлигингизда бўлганлар, маслаҳат ва тавсиялар берадиганлардан ёрдам сўрайсиз. Ишларни фарзандларингизга топширасиз, кўпинча сизга одамлар ўзлари келиб «сен учун нима қила оламан?» деб сўрайди, ўзлари сизга қилишда ёрдам беришни истайдиган одамлар пайдо бўлади. Бировнинг қўли билан қилишни ва одамлар сизнинг ўрнингизга қилиши учун ҳаммасини ташкил қилишни яхши кўрасиз. Ишга фалсафий ёндашасиз ва муваффақият энг юқори бўлиши учун қаерда ҳудудни кенгайтириш ёки жамоани кўпайтириш кераклигини доим кўрасиз. Ҳаммага ҳурмат, юксак ахлоқ, марҳамат ва меҳрибонлик билан қиласиз.","В самых плохих случаях, наблюдается аморальщина, фанатичное следование правилам, догматизм, пустые споры, поучаете и лезете там, где вас не ждут. Следуете правилам, совсем не понимая их сути.":"Энг ёмон ҳолатларда ахлоқсизлик, қоидаларга фанатик эргашиш, ақидапарастлик, бўш баҳслар кузатилади, насиҳат қиласиз ва сизни кутмаган жойга аралашасиз. Қоидаларга уларнинг моҳиятини умуман тушунмай эргашасиз.","Раху. Делать непредсказуемо, сомневаясь во всем либо все хорошо планировать и действовать практично, исходя из плана. Делаете, балансируя между материальным и духовным, пользуетесь компьютерами, любите сделать иллюзию в деле или шоу, а может даже и обмануть и сделать дело с двойным дном. Выносливо и всегда стремясь вперед, потому что если этого нет, вы непременно откатываетесь назад. Находите выход из любой ситуации и видите суть ситуации и людей, читаете между строк. В самых плохих случаях, запивает все алкоголем, закуривает и тд. все свои дела, можете оскорблять в процессе, делать грязно, криминально, жестоко и с манипуляциями.":"Раҳу. Олдиндан айтиб бўлмайдиган тарзда, ҳамма нарсага шубҳа қилиб қилиш ёки ҳаммасини яхши режалаштириш ва режадан келиб чиқиб амалий ҳаракат қилиш. Моддий ва маънавий ўртасида мувозанат сақлаб қиласиз, компьютерлардан фойдаланасиз, ишда ёки шоуда иллюзия яратишни, ҳатто алдашни ва икки тубли иш қилишни ҳам яхши кўрасиз. Чидамли ва доим олдинга интилиб, чунки агар бу бўлмаса, албатта орқага қайтасиз. Ҳар қандай вазиятдан чиқиш йўлини топасиз ва вазият ва одамларнинг моҳиятини кўрасиз, сатрлар орасини ўқийсиз. Энг ёмон ҳолатларда ҳамма ишларини алкоголь билан ювади, чекади ва ҳ.к., жараёнда ҳақорат қилишингиз, ифлос, жиноий, шафқатсиз ва манипуляциялар билан қилишингиз мумкин.","Меркурий. Вы будете договариваться, чтобы с кем-то что-то сделать, либо будете продавать идею. Вы руководствуетесь знаниями и получаемой информацией, от последнего часто может все меняться. Логически и рационально все отсматриваете, анализируете выгоду, запоминаете и применяете свои знания на практике, а если их не хватает, то параллельно с делами вы учитесь новому и внедряете. Для дел приходится много ездить и много общаться, контактировать, знакомиться и пользоваться связями. Вы видите ситуацию целиком и методы к ней тоже. Применяете юмор для разбавления атмосферы и чтобы было весело и легко. В плохих случаях проявления меркурия вы можете суетиться, расфокусироваться и не довести ничего до логического конца. Можете заниматься пустой болтовней, все забывать, делать поверхностно и нервно.":"Меркурий. Сиз кимдир билан нимадир қилиш учун келишасиз ёки ғояни сотасиз. Сиз билимлар ва олинаётган маълумот билан бошқариласиз, охиргисидан кўпинча ҳамма нарса ўзгариши мумкин. Ҳаммасини мантиқий ва рационал кўриб чиқасиз, фойдани таҳлил қиласиз, эслаб қоласиз ва билимларингизни амалда қўллайсиз, агар улар етмаса, ишлар билан параллел янгиликни ўрганасиз ва жорий этасиз. Ишлар учун кўп юриш ва кўп мулоқот қилиш, алоқа қилиш, танишиш ва алоқалардан фойдаланишга тўғри келади. Сиз вазиятни бутунлигича ва унга усулларни ҳам кўрасиз. Муҳитни юмшатиш ва қувноқ ва енгил бўлиши учун юмордан фойдаланасиз. Меркурийнинг ёмон кўринишларида ғимирлашингиз, диққатни йўқотишингиз ва ҳеч нарсани мантиқий охирига етказмаслигингиз мумкин. Бўш гап билан шуғулланишингиз, ҳаммасини унутишингиз, юзаки ва асабий қилишингиз мумкин.","Венера. Вы найдёте того, кто будет работать за вас. Если дело не нравится не будете утруждаться, а будете просить кого-то. Если решили сами делать, то часто делаете своими руками. Часто те кого вы попросили сделать, будут счастливы потрудиться для вас и получат удовольствие. Вы предпочитаете делать спокойно, уравновешенно, медленно, практично и умеете трудиться долго и упорно. Умеете ждать для осуществления своих идей и планов. Пользуетесь своими талантами, когда делаете и желательно, чтобы вокруг вас всегда была хорошая атмосфера, красота, комфорт и дороговизна. Цветы и сладости. Вы эстет, который знает истинную цену вещам. Сотрудничаете мирно, в удовольствие, элегантно и обаятельно. Хотите, чтобы процесс приносил радость и удовольствие вам. В плохих случаях проявления Венеры, вы можете быть излишне материалистичным, жадным, упрямым, инертным, когда понимаешь, что нужно, но не делаешь это, можете не прощать ошибки людям, не принимать новые методы и вообще забить на все, уходя в свои удовольствия.":"Венера. Сиз сизнинг ўрнингизга ишлайдиган кишини топасиз. Агар иш ёқмаса, ўзингизни қийнамайсиз, кимнидир сўрайсиз. Агар ўзингиз қилишга қарор қилсангиз, кўпинча ўз қўлингиз билан қиласиз. Кўпинча сиз қилишни сўраганлар сиз учун меҳнат қилишдан бахтли бўлади ва завқ олади. Сиз хотиржам, мувозанатли, секин, амалий қилишни афзал кўрасиз ва узоқ ва қатъият билан меҳнат қилишни биласиз. Ғоя ва режаларингизни амалга ошириш учун кутишни биласиз. Қилаётганингизда истеъдодларингиздан фойдаланасиз ва атрофингизда доим яхши муҳит, гўзаллик, қулайлик ва қимматлик бўлиши маъқул. Гуллар ва ширинликлар. Сиз нарсаларнинг ҳақиқий қадрини биладиган эстетсиз. Тинч, завқ билан, нафис ва жозибали ҳамкорлик қиласиз. Жараён сизга қувонч ва завқ келтиришини истайсиз. Венеранинг ёмон кўринишларида ҳаддан ташқари материалист, очкўз, қайсар, инерт бўлишингиз, керак эканини тушуниб, лекин қилмаслигингиз, одамларга хатоларни кечирмаслигингиз, янги усулларни қабул қилмаслигингиз ва умуман ҳамма нарсага қўл силтаб, ўз завқларингизга кетишингиз мумкин.","Кету. Вы будете действовать самостоятельно, своими усилиями, будете трудиться и делать это непредсказуемо, непонятно для других («как он это сделал?», «каким-то мистическим образом»), опираться на новые технологии, использовать их активно и активно используете программирование и электронику, гаджеты. Можете методы доставать из медитаций и энергетических практик, а также делать все интуитивно без четкого плана, в потоке.":"Кету. Сиз мустақил, ўз саъй-ҳаракатларингиз билан ҳаракат қиласиз, меҳнат қиласиз ва буни олдиндан айтиб бўлмайдиган, бошқалар учун тушунарсиз тарзда қиласиз («у буни қандай қилди?», «қандайдир мистик тарзда»), янги технологияларга таянасиз, улардан фаол фойдаланасиз ва дастурлаш ва электроника, гаджетлардан фаол фойдаланасиз. Усулларни медитациялар ва энергетик амалиётлардан олишингиз, шунингдек ҳаммасини аниқ режасиз, оқимда интуитив қилишингиз мумкин.","Сатурн. Вы будете вкалывать как папа Карло, упорно трудиться, делать все своими руками, можете быть руководителем и согласовывать договора, все делать расчетливо и опираться на цифры, логику и анализ. Вы трудоголик и вам можно научиться делегировать кое – какие процессы. Действуете основательно, целеустремленно, настойчиво, с присущей вам самодисциплиной, выносливостью и терпением. Умеете добиваться целей с помощью стратегии и исполнять трудную работу, где прогресс постепенный и нужно терпение. В плохих случаях вы очень недоверчивы, высокомерны, бессердечны, пессимистичны, консервативны и лишены чувства юмора, способны пройти по головам для достижения или становитесь фаталистически настроены.":"Сатурн. Сиз Карло ота каби тинимсиз ишлайсиз, қатъият билан меҳнат қиласиз, ҳаммасини ўз қўлингиз билан қиласиз, раҳбар бўлишингиз ва шартномаларни келишишингиз, ҳаммасини ҳисоб-китоб билан қилишингиз ва рақамлар, мантиқ ва таҳлилга таянишингиз мумкин. Сиз ишга берилган инсонсиз ва сизга баъзи жараёнларни вакил қилишни ўрганиш мумкин. Пухта, мақсадга интилувчан, қатъият билан, ўзингизга хос ўзини интизомга солиш, чидамлилик ва сабр билан ҳаракат қиласиз. Стратегия ёрдамида мақсадларга эришишни ва тараққиёт аста-секин бўлган ва сабр керак бўлган оғир ишни бажаришни биласиз. Ёмон ҳолатларда сиз жуда ишонмайдиган, кибрли, бераҳм, пессимистик, консерватив ва юмор ҳиссидан маҳрум бўласиз, эришиш учун бошлар устидан юришга қодирсиз ёки фаталистик кайфиятга тушасиз.","Марс. Вы будете предприимчивы и активны в делах. Вы делаете, чтобы быть гордым за свое произведение. Процессы все энергичные, завершая одно дело, тут же за другое беретесь. Быстро подхватываете все новое и прогрессивное, занимаете лидерские позиции и инициируете многие процессы. Мотивацией может быть соревнование или конкуренция, вы стремитесь делать независимо и самостоятельно, умеете пойти на риск и выиграть. В самых плохих случаях вы становитесь импульсивны, раздражительны, грубы, резки, агрессивны, не терпите руководства над собой и не умеете подчиняться. Можете руководствоваться только своими соображениями, не обращая внимание на мнение и желания других, непременно настаиваете на своем, стремитесь подчинить себе всех, не зависимо от их желания.":"Марс. Сиз ишларда ишбилармон ва фаол бўласиз. Сиз ўз асарингиз билан фахрланиш учун қиласиз. Жараёнларнинг барчаси ғайратли, бир ишни тугатиб, дарҳол бошқасига киришасиз. Барча янги ва илғор нарсаларни тез илиб оласиз, етакчилик позицияларини эгаллайсиз ва кўплаб жараёнларни бошлаб берасиз. Мотивация мусобақа ёки рақобат бўлиши мумкин, сиз мустақил ва ўзингиз қилишга интиласиз, таваккал қилиш ва ютишни биласиз. Энг ёмон ҳолатларда сиз импульсив, жиззаки, қўпол, кескин, тажовузкор бўласиз, устингиздан раҳбарликка тоқат қилмайсиз ва бўйсунишни билмайсиз. Бошқаларнинг фикри ва истакларига эътибор бермай, фақат ўз мулоҳазаларингиз билан бошқарилишингиз, албатта ўзингизникини талаб қилишингиз, уларнинг истагидан қатъи назар, ҳаммани ўзингизга бўйсундиришга интилишингиз мумкин.","Это служение воли других людей, служить эгоизму других, энергии другого человека, лидерству другого человека, желание быть с лидером рядом, удовлетворять потребности других – заряжает. Восхваление другого человека наполняет вас самих. Фокус на другом, а не на себе.":"Бу бошқа одамларнинг иродасига хизмат қилиш, бошқаларнинг худбинлигига, бошқа инсоннинг энергиясига, бошқа инсоннинг етакчилигига хизмат қилиш, етакчи ёнида бўлиш истаги, бошқаларнинг эҳтиёжларини қондириш — қувватлантиради. Бошқа инсонни мақташ сизнинг ўзингизни тўлдиради. Эътибор ўзингизга эмас, бошқага қаратилган.","Ноль тут говорит о том, что определенного источника у вас нет. Вас могут заряжать препятствия и трудности, и вам самой/му нужно выбирать свои источники энергии. Нужно найти того человека, кто в этом деле эксперт и у кого так в жизни в плане ресурса, как вы хотели бы себе. Нужно выбрать себе самой и развить себя самой в плане пополнения ресурса. Еще энергии либо много, либо нет почти.":"Бу ерда ноль сизда аниқ манба йўқлигини айтади. Сизни тўсиқлар ва қийинчиликлар қувватлантириши мумкин ва сизга энергия манбаларингизни ўзингиз танлашингиз керак. Бу ишда эксперт бўлган ва ҳаётида ресурс жиҳатидан ўзингизга истагандек бўлган инсонни топиш керак. Ресурсни тўлдириш жиҳатидан ўзингиз учун ўзингиз танлаш ва ўзингизни ўзингиз ривожлантириш керак. Яна энергия ё кўп, ё деярли йўқ.","Вас заряжает Солнце. Солнце – это отец, сын, сцена, сознание, восприятие, начальство, способность выразить себя на людях, самоценность, собственное достоинство, духовное лидерство, харизма, яркость, проявленость – все это заряжает на 1000 процентов. Творческое самовыражение, яркая индивидуальность, независимость, уверенность в себе, внимание людей, нахождение на сцене и в центре внимания. Способность отвечать за свою жизнь и жизнь своих близких и подчиненных, тех что под вашим крылом. Известность, героизм, смелость и бесстрашие, умение руководить, снисходительность к ошибкам, великодушие к конкурентам и противникам,":"Сизни Қуёш қувватлантиради. Қуёш — бу ота, ўғил, саҳна, онг, идрок, бошлиқлар, одамлар олдида ўзини ифода этиш қобилияти, ўз қадри, ўз қадр-қиммати, маънавий етакчилик, харизма, ёрқинлик, намоён бўлиш — буларнинг барчаси 1000 фоизга қувватлантиради. Ижодий ўзини ифода этиш, ёрқин индивидуаллик, мустақиллик, ўзига ишонч, одамлар эътибори, саҳнада ва диққат марказида бўлиш. Ўз ҳаёти ва яқинлари ва қўл остидагилар, қанотингиз остидагиларнинг ҳаёти учун жавоб бериш қобилияти. Шуҳрат, қаҳрамонлик, жасорат ва қўрқмаслик, раҳбарлик қила олиш, хатоларга кечиримлилик, рақиблар ва мухолифларга олижаноблик,","умение вдохновлять и вести за собой. Режим дня с рассветом солнца вставать и с закатом успокаиваться от активной деятельности.":"илҳомлантириш ва ортидан эргаштира олиш. Қуёш чиқиши билан туриш ва ботиши билан фаол фаолиятдан тинчланиш кун тартиби.","Потеря энергии от тщеславия, ссор с отцом и мужчинами, с сыном или начальником, неуважительное отношение к любящим вас. Излишняя требовательность, эгоистичность и высокомерие приводят к потери сил. Самолюбование и нарциссизм, уязвимость чувства собственного достоинства, склонность насиловать волю других, используя их в своих целях (нельзя!). Все что излишне и излишество, показуха, жизнь сверх своих возможностей.":"Шуҳратпарастлик, ота ва эркаклар, ўғил ёки бошлиқ билан жанжаллар, сизни севадиганларга ҳурматсиз муносабатдан энергияни йўқотиш. Ортиқча талабчанлик, худбинлик ва кибр кучни йўқотишга олиб келади. Ўзига маҳлиё бўлиш ва нарциссизм, ўз қадр-қиммати ҳиссининг заифлиги, бошқаларнинг иродасини зўрлашга, улардан ўз мақсадларида фойдаланишга мойиллик (мумкин эмас!). Ортиқча ва ортиқчалик бўлган ҳамма нарса, кўз-кўз, имкониятдан ортиқ яшаш.","Вы наполняетесь Луной. Луна – это семья, родственники, материнство, это когда жена, психологичность и подсознание, романтичность, доброта, сердечность, сострадание. Способность чтить традиции предков заряжает вас. Вода, водные процедуры и природа заряжает и придает сил, хорошо жить у воды. Способность сочувствовать и поддерживать, чуткость. Жизнь по лунному календарю. Благотворительность, возможность почитать книги и путешествовать, расслабиться, получить наслаждение, все женское. Стремление к духовному росту, человечности, проявление душевности и доброжелательности, проявление материнских качеств и заботливости, проявление эмоций экологичное. Жизнь на родине. Заряжаетесь от женщин и матери, семьи, дочери.":"Сиз Ой билан тўласиз. Ой — бу оила, қариндошлар, оналик, хотин бўлганда, психологиклик ва онг ости, романтиклик, меҳрибонлик, самимийлик, ҳамдардлик. Аждодлар анъаналарини эъзозлаш қобилияти сизни қувватлантиради. Сув, сув муолажалари ва табиат қувватлантиради ва куч беради, сув ёнида яшаш яхши. Ҳамдард бўлиш ва қўллаб-қувватлаш қобилияти, сезгирлик. Ой тақвими бўйича яшаш. Хайрия, китоб ўқиш ва саёҳат қилиш, бўшашиш, лаззат олиш имконияти, барча аёлларга хос нарсалар. Маънавий ўсишга, инсонийликка интилиш, руҳий илиқлик ва хайрихоҳликни намоён қилиш, оналик фазилатлари ва ғамхўрликни намоён қилиш, ҳис-туйғуларни экологик намоён қилиш. Ватанда яшаш. Аёллар ва онадан, оила, қиздан қувват оласиз.","Потеря энергии при чрезмерной чувствительности, впечатлительности и ранимости. Когда вы проявляете злопамятность, упрямство, подвергаетесь чужому влиянию, непостоянны. нерешительны, когда вы жалуетесь и вечно недовольны, когда вы часто меняете род деятельности нигде не достигая результата, неэкологичное проявление эмоций, робость и застенчивость. Заниженная самооценка и обидчивость ваши расходуют силы не туда. Внутреннее беспокойство и суетливость, страхи, отсутствие дома.":"Ҳаддан ташқари сезгирлик, таъсирчанлик ва озор топувчанликда энергияни йўқотиш. Кекчилик, қайсарлик кўрсатганингизда, бировнинг таъсирига учраганингизда, беқарор, қатъиятсиз бўлганингизда, шикоят қилганингизда ва абадий норози бўлганингизда, фаолият турини тез-тез ўзгартириб, ҳеч қаерда натижага эришмаганингизда, ҳис-туйғуларни ноэкологик намоён қилиш, тортинчоқлик ва уятчанлик. Паст ўзини баҳолаш ва аразчилик кучларингизни нотўғри жойга сарфлайди. Ички безовталик ва ғимирлаш, қўрқувлар, уйнинг йўқлиги.","Вас заряжает Юпитер. Юпитер – ваше стремление найти истину, всегда быть занятым и в поиске чего-то. Искренность, честность, правдивость, благородство, вера и оптимизм. Множество хобби и желаний, принципиальность, умение прощать и быть наставником. Высокие моральные ценности, справедливость и жизнерадостность вас заряжают. Путешествия, религия, церковь, культура, дальние поездки, стремление к духовному росту и сам духовный рост. Стремление получить все самое высшее из всего возможного везде где это возможно. Высшее образование и курсы повышения квалификации, глубокое и системное изучение предметов. Уверенность в себе, авторитетность, авторитетные люди и те кто вас протежируют заряжают. Свободолюбие и независимость, стремление придерживаться одобряемых в обществе вещей. Изучение иностранных языков, любое расширение территории и границ сознания. Любовь ко всему живому и природе, жизнь как приключение и интересное путешествие с большими возможностями. Стремление к глобальному. Передача знание и учительство. Изобилие и стремление к нему.":"Сизни Юпитер қувватлантиради. Юпитер — ҳақиқатни топишга, доим банд бўлишга ва нимадир излашга интилишингиз. Самимийлик, ҳалоллик, ростгўйлик, олижаноблик, эътиқод ва оптимизм. Кўплаб хобби ва истаклар, принципиаллик, кечира олиш ва устоз бўлиш маҳорати. Юксак ахлоқий қадриятлар, адолат ва ҳаётсеварлик сизни қувватлантиради. Саёҳатлар, дин, черков, маданият, узоқ сафарлар, маънавий ўсишга интилиш ва маънавий ўсишнинг ўзи. Иложи бор ҳамма жойда мумкин бўлган ҳамма нарсадан энг олийсини олишга интилиш. Олий таълим ва малака ошириш курслари, фанларни чуқур ва тизимли ўрганиш. Ўзига ишонч, обрўлилик, обрўли одамлар ва сизни ҳимоя қиладиганлар қувватлантиради. Эркинликни севиш ва мустақиллик, жамиятда маъқулланадиган нарсаларга амал қилишга интилиш. Чет тилларини ўрганиш, ҳудуд ва онг чегараларининг ҳар қандай кенгайиши. Барча тирик мавжудотлар ва табиатга муҳаббат, ҳаёт катта имкониятларга эга саргузашт ва қизиқарли саёҳат сифатида. Глобалга интилиш. Билим етказиш ва ўқитувчилик. Тўкинлик ва унга интилиш.","Теряете энергию когда не умеете воспринимать критику, когда преувеличиваете, когда ни к чему не стремитесь и просто кисните сидя дома, не расширяете территории, сознание, не учитесь и не учите, когда ваши ценности моральные оставляют желать лучшего. Не умение выбирать из массы возможностей, жадность, неумение концентрироваться, духовная деградация, фанатизм, поучения вместо наставничества, когда даете непрошенные советы и навязываете свое мировоззрение. Злоупотребление властью, мания величия и желание всего и сразу без понимания последовательного достижения целей. Любые излишества.":"Танқидни қабул қила олмаганингизда, муболаға қилганингизда, ҳеч нарсага интилмай, шунчаки уйда ўтириб ачиганингизда, ҳудудлар, онгни кенгайтирмаганингизда, ўқимаганингиз ва ўргатмаганингизда, ахлоқий қадриятларингиз яхшиликни истаб қолдирганда энергияни йўқотасиз. Кўплаб имкониятлардан танлай олмаслик, очкўзлик, диққатни жамлай олмаслик, маънавий таназзул, фанатизм, устозлик ўрнига насиҳатлар, сўралмаган маслаҳатлар бериб, дунёқарашингизни тиқиштирганингизда. Ҳокимиятни суиистеъмол қилиш, улуғворлик маниясилари ва мақсадларга изчил эришишни тушунмай, ҳаммасини бирданига исташ. Ҳар қандай ортиқчаликлар.","Вас заряжает Раху. Раху – это некая интоксикация, употребление чего-то искусственного, не обязательно таблетки, алкоголь и кофе, это может быть, в т.ч., просмотр сериалов, жизнь в иллюзии. Хорошо черпаете энергию из видеороликов, шоу, фокусов, компьютера и технологий. Практичные, сильные желания, которые истинно ваши. Постоянный, непрекращающийся рост и развитие в тонких мирах тоже. Практичность и планирование, прописанная последовательность действий. Духовность и понимание законов этой вселенной. Тайные знания, магия и эзотерика наполняет. Большая концентрация на чем-либо и способность не останавливаться на достигнутом. Стремление к естественности и натуральному.":"Сизни Раҳу қувватлантиради. Раҳу — бу қандайдир интоксикация, сунъий нарсани истеъмол қилиш, шарт эмас дорилар, алкоголь ва қаҳва, бу жумладан сериаллар кўриш, иллюзияда яшаш ҳам бўлиши мумкин. Видеороликлар, шоу, фокуслар, компьютер ва технологиялардан энергияни яхши оласиз. Амалий, ҳақиқатан сизники бўлган кучли истаклар. Нозик дунёларда ҳам доимий, тўхтовсиз ўсиш ва ривожланиш. Амалийлик ва режалаштириш, ёзиб қўйилган ҳаракатлар кетма-кетлиги. Маънавият ва бу коинот қонунларини тушуниш. Сирли билимлар, сеҳр ва эзотерика тўлдиради. Нимагадир катта диққат ва эришилганда тўхтамаслик қобилияти. Табиийлик ва табиий нарсаларга интилиш.","Силы тратятся на исполнение не истинно ваших желаний (навязанных), от чего исполняя их, вы не кайфуете. Раздрай в жизни и неожиданности забирают много сил. Излишняя оторванность от жизни, интоксикация. Жадность до материального плохо влияет на ресурсное состояние. Отсутствие практичности и четкого плана на каждый день или мероприятие. Отсутствие стремления к духовному развитию и не включенность в эзотерику.":"Кучлар ҳақиқатан сизники бўлмаган (тиқиштирилган) истакларни бажаришга сарфланади, шунинг учун уларни бажариб, завқ олмайсиз. Ҳаётдаги тартибсизлик ва кутилмаган ҳодисалар кўп куч олади. Ҳаётдан ортиқча узилганлик, интоксикация. Моддийга очкўзлик ресурс ҳолатига ёмон таъсир қилади. Амалийликнинг ва ҳар бир кун ёки тадбир учун аниқ режанинг йўқлиги. Маънавий ривожланишга интилишнинг йўқлиги ва эзотерикага кирмаслик.","Меркурий дает вам ресурс. Вы в ресурсе когда легки, любознательны, общительны, контактны, расчетливы, рассудительны, имеете разносторонние связи, все время учитесь или учите, когда занимаетесь несколькими делами одновременно, постепенно завершая каждое. Когда вы рациональны и свободны, много перемещаетесь на короткие расстояния и умеете поддержать беседу. Обмен информацией, торговля, умение переключаться с темы на тему заряжает вас. Автомобиль, телефон, пешие прогулки прибавляют ресурс. Веселье, юмор и развлечения, сильная логика и разум.":"Меркурий сизга ресурс беради. Сиз енгил, қизиқувчан, киришимли, алоқачан, ҳисоб-китобли, мулоҳазали, ҳар томонлама алоқаларга эга, доим ўқиётган ёки ўргатаётганингизда, бир вақтнинг ўзида бир нечта иш билан шуғулланиб, ҳар бирини аста-секин тугатаётганингизда ресурсдасиз. Сиз рационал ва эркин бўлганингизда, қисқа масофаларга кўп ҳаракатланганингизда ва суҳбатни давом эттира олганингизда. Маълумот алмашиш, савдо, мавзудан мавзуга ўтиш маҳорати сизни қувватлантиради. Автомобиль, телефон, пиёда сайрлар ресурс қўшади. Кўнгилхушлик, юмор ва кўнгилочар машғулотлар, кучли мантиқ ва ақл.","Потеря ресурса при поверхностности ваших действий, отсутствии глубины, сплетни, нервозность, импульсивность и раздражительность, пустая болтовня. Когда вы собираете всю информацию и нужную и нет, расфокус на делах и не доведение их до конца, когда учитесь и не применяете свои знания на практике, обман, желание спорить просто так, интриги. Отсутствие свободы перемещения и слова.":"Ҳаракатларингиз юзакилигида, чуқурлик йўқлигида, ғийбатлар, асабийлик, импульсивлик ва жиззакилик, бўш гапда ресурсни йўқотиш. Керакли ва кераксиз барча маълумотни йиғганингизда, ишларда диққатни йўқотиш ва уларни охирига етказмаслик, ўқиб, билимларингизни амалда қўлламаганингизда, алдов, шунчаки баҳслашиш истаги, фитналар. Ҳаракатланиш ва сўз эркинлигининг йўқлиги.","Вы черпаете ресурс от Венеры. Венера – это комфорт, роскошь и всё красивое, приятное, доброе, то, что приносит кайф. Заряжаетесь от общения с девушками, подругами, когда украшаете себя и все вокруг. Все женские дела, спа, парикмахерские, визаж, платья, мода, красота. Ваши хобби, любимые дела заряжают как никогда. Нужно стремиться к миру, бесконфликтности, радости, счастью, финансам. Сладости тоже заряжают. Гармония и мир во всем мире радуют вас и наполняют энергией. Искусство и рукоделие, любовь к природе, любовь к домашним цветам и духам. Практичность, мягкость и нежность, проявление своих талантов, домашний уют и комфорт.":"Сиз Венерадан ресурс оласиз. Венера — бу қулайлик, ҳашамат ва барча чиройли, ёқимли, эзгу, завқ келтирадиган нарсалар. Қизлар, дугоналар билан мулоқотдан, ўзингизни ва атрофдаги ҳамма нарсани безатганингизда қувват оласиз. Барча аёлларга хос ишлар, спа, сартарошхоналар, визаж, кўйлаклар, мода, гўзаллик. Хоббиларингиз, севимли ишларингиз ҳеч қачонгидек қувватлантиради. Тинчлик, низосизлик, қувонч, бахт, молияга интилиш керак. Ширинликлар ҳам қувватлантиради. Бутун дунёда уйғунлик ва тинчлик сизни қувонтиради ва энергия билан тўлдиради. Санъат ва қўл ишлари, табиатга муҳаббат, уй гуллари ва атирларга муҳаббат. Амалийлик, юмшоқлик ва нозиклик, истеъдодларингизни намоён қилиш, уй қулайлиги ва роҳати.","Теряете энергию при конфликтах, в отсутствии гармонии и красоты, даже если не краситесь день будет не таким ресурсным, чем если бы вы смотрели на себя красивую в зеркало в течении дня (для женщин). Продолжительный гнев и неумение прощать, запрет на новое, слишком материалистичное мышление, лень, саботаж результата и процесса, инертность. Отсутствие комфорта и денег.":"Низоларда, уйғунлик ва гўзаллик йўқлигида энергияни йўқотасиз, ҳатто пардоз қилмасангиз ҳам, кун давомида ўзингизни ойнада чиройли кўрганингиздагидек ресурсли бўлмайди (аёллар учун). Узоқ давом этадиган ғазаб ва кечира олмаслик, янгиликка тақиқ, ҳаддан ташқари материалистик фикрлаш, дангасалик, натижа ва жараённи саботаж қилиш, инертлик. Қулайлик ва пулнинг йўқлиги.","Вас питает Кету. Кету – оторванность от жизни, отрешенность и уход в себя ненадолго. Самовольное одиночество и духовность заряжают, все духовные, энергетические практики, успокаивающие ум, медитации. Сидение в гаджетах, программирование. Трансформация всего или чего-либо, жизни, принятие перемен, принятие всего нового и способность отпустить старое. Эзотерика и самопознание. Отращивание головы Кету – это дракон без головы, голова духовная – это и заряжает. Развитие духовных ценностей, глубина и мудрость наполняют. Способность слушать других людей, сочувствовать им, сопереживать им.":"Сизни Кету озиқлантиради. Кету — ҳаётдан узилганлик, узоқлашиш ва қисқа вақтга ўзига кетиш. Ихтиёрий ёлғизлик ва маънавият қувватлантиради, ақлни тинчлантирадиган барча маънавий, энергетик амалиётлар, медитациялар. Гаджетларда ўтириш, дастурлаш. Ҳамма нарса ёки нимадир, ҳаётнинг трансформацияси, ўзгаришларни қабул қилиш, барча янгиликни қабул қилиш ва эскини қўйиб юбориш қобилияти. Эзотерика ва ўзини англаш. Кету бошини ўстириш — бу бошсиз аждаҳо, бош маънавий — бу ва қувватлантиради. Маънавий қадриятларни ривожлантириш, чуқурлик ва донолик тўлдиради. Бошқа одамларни тинглаш, уларга ҳамдард бўлиш, уларнинг дардига шерик бўлиш қобилияти.","Теряете энергию при излишней материалистичности, при пофигизме, когда вы не замечаете чувства людей и не хотите их понимать, при страхе перемен и держании за старое и отжившее, консерватизм. Когда отсутствует смысл того, чем вы занимаетесь. Когда вы не вникаете в суть происходящего.":"Ҳаддан ташқари материалистикликда, бепарволикда, одамларнинг ҳисларини пайқамаганингизда ва уларни тушунишни истамаганингизда, ўзгаришлардан қўрқиб, эски ва эскирганга ёпишганингизда, консерватизмда энергияни йўқотасиз. Шуғулланаётган ишингизнинг маъноси йўқлигида. Бўлаётган нарсанинг моҳиятига кирмаганингизда.","Возможно, будете ощущать одиночество или «выжигать» пространство отношений своим вниманием и эгоизмом, захочется быть в центре внимания, издавать приказы и это не будет нравиться вашим близким. Можете быть излишне требовательными, высокомерными, хвастаться, склонны насиловать волю других людей, используя их в своих целях, можете быть падкими на лесть. Но это все в не лучшем случае. А в хорошем случае вы умеете организовать праздник своим близким, светите им как солнце, радуете, вы благородны, щедры, добры, покровительствуете. С близкими становитесь независимыми, уверенными в себе и получаете удовлетворение собой и жизнью. Ведете себя либо как ребенок, либо с отеческим настроем.":"Эҳтимол, ёлғизликни ҳис қиласиз ёки муносабатлар маконини эътиборингиз ва худбинлигингиз билан «куйдирасиз», диққат марказида бўлишни, буйруқлар беришни истайсиз ва бу яқинларингизга ёқмайди. Ҳаддан ташқари талабчан, кибрли бўлишингиз, мақтанишингиз, бошқа одамларнинг иродасини зўрлашга, улардан ўз мақсадларингизда фойдаланишга мойил бўлишингиз, хушомадга ўч бўлишингиз мумкин. Лекин буларнинг барчаси энг яхши бўлмаган ҳолатда. Яхши ҳолатда эса яқинларингизга байрам ташкил қила оласиз, уларга қуёшдек нур сочасиз, қувонтирасиз, сиз олижаноб, саховатли, меҳрибон, ҳомийлик қиласиз. Яқинлар билан мустақил, ўзингизга ишонган бўласиз ва ўзингиз ва ҳаётдан қониқиш оласиз. Ё бола каби, ё оталарча кайфият билан ўзингизни тутасиз.","Вам требуется особая душевная эмоциональная близость с человеком. Если близости нет, вы становитесь замкнутой и закрытой, можете обманывать, только бы не показать себя настоящую. Друзья со временем могут быть как братья и сестры вам, вы проникаете в душу человека и видите ее суть. Вас сложно обмануть, вы считываете информацию о ваших отношениях интуитивно, на подсознательном уровне. У вас хорошая эмпатия, которая может путать вас в ваших чувствах и вы можете путать свои чувства с чужими. Вам необходимо не воспринимать близко к сердцу выходки ближнего окружения, чтобы так сильно не расстраиваться. Здесь поможет практика сепарации от родителей. Если отношения гармоничные, то вы будете понимающим, добрым, мягким и прощающим человеком. Если нет, то можете бояться этих людей, быть в депрессии и уходить в себя. Вы очень добры к близким и они могут видеть в вас мать. Ваши отношения с близкими могут целиком и полностью зависеть от их поведения и соответственно быть нестабильными и изменчивыми. Ваше настроение тоже скачет и зависит от гормонального состояния. Вы очень дружелюбны и женственны, но если вас обидеть будет очень плохо – мамка накажет «мама не горюй», «по самы помидоры». Вы можете часто сами обижаться часто и если вы не в настроении и захотели на кого-то обидеться, то первый кто зайдет будет виноват и станет вашим обидчиком. Научитесь занимать взрослую позицию в отношениях, где нет обид, и есть ответственность за свою жизнь и поступки.":"Сизга инсон билан алоҳида руҳий ҳиссий яқинлик керак. Агар яқинлик бўлмаса, сиз ёпиқ ва ўзига ўралган бўлиб қоласиз, фақат ҳақиқий ўзингизни кўрсатмаслик учун алдашингиз мумкин. Дўстлар вақт ўтиб сизга ака-ука ва опа-сингилдек бўлиши мумкин, сиз инсон қалбига кириб, унинг моҳиятини кўрасиз. Сизни алдаш қийин, сиз муносабатларингиз ҳақидаги маълумотни интуитив, онг ости даражасида ўқийсиз. Сизда ҳисларингизда чалкаштириши мумкин бўлган яхши эмпатия бор ва ўз ҳисларингизни бировникилари билан чалкаштиришингиз мумкин. Сизга шунчалик кучли хафа бўлмаслик учун яқин атрофнинг қилиқларини яқин олмаслик зарур. Бу ерда ота-оналардан ажралиш амалиёти ёрдам беради. Агар муносабатлар уйғун бўлса, сиз тушунадиган, меҳрибон, юмшоқ ва кечирувчи инсон бўласиз. Агар йўқ бўлса, бу одамлардан қўрқишингиз, депрессияда бўлишингиз ва ўзингизга кетишингиз мумкин. Сиз яқинларга жуда меҳрибонсиз ва улар сизда онани кўриши мумкин. Яқинлар билан муносабатларингиз бутунлай уларнинг хулқига боғлиқ ва мос равишда беқарор ва ўзгарувчан бўлиши мумкин. Кайфиятингиз ҳам сакрайди ва гормонал ҳолатга боғлиқ. Сиз жуда дўстона ва аёлларчасиз, лекин агар сизни хафа қилишса, жуда ёмон бўлади — она жазолайди, ҳам яхшилаб. Сиз ўзингиз тез-тез хафа бўлишингиз мумкин ва агар кайфиятингиз бўлмаса ва кимдандир хафа бўлгингиз келса, биринчи кирган киши айбдор бўлади ва сизни хафа қилган бўлиб қолади. Муносабатларда хафаликлар йўқ, ўз ҳаёти ва қилмишлари учун масъулият бор катталар позициясини эгаллашни ўрганинг.","Вы помогаете и вам помогают. Можете жить вдали от родственников и преодолевать расстояния для встреч с ними. Родственники могут быть путешественниками, учителями, олигархами, богачами, или просто счастливого юпитерианского склада характера. Они побуждают вас стремиться к самому высшему, узнавать другие культуры, учиться и учить самому, путешествовать. Отношения хорошие, вы независимы от близких и вполне удовлетворены общением с ними. С кем не хочется не общаетесь, можете быть излишне принципиальны или эгоистичны. Иногда вы идеализируете их, но стремитесь к честности и искренности с ними. Родственники могут быть верующие или просто занимать должности по Юпитеру – учитель, священник, глава корпорации, судья и тд. Вы оптимистичны с ними, приветливы и вам весело вместе. Вы стремитесь вместе к духовному росту, та или иначе это происходит. С ними вы составляете свою картину мира. Ваши учителя кажутся вам близкими людьми. В плохом случае вы поучаете, не умеете подчиняться, не развиваетесь духовно, злоупотребляете своим положением и излишне перегибаете палку в отношении близких.":"Сиз ёрдам берасиз ва сизга ёрдам беришади. Қариндошлардан узоқда яшашингиз ва улар билан учрашиш учун масофаларни енгишингиз мумкин. Қариндошлар саёҳатчилар, ўқитувчилар, олигархлар, бойлар ёки шунчаки бахтли юпитерча характерли бўлиши мумкин. Улар сизни энг олийга интилишга, бошқа маданиятларни билишга, ўқиш ва ўзингиз ўргатишга, саёҳат қилишга ундайди. Муносабатлар яхши, сиз яқинлардан мустақилсиз ва улар билан мулоқотдан тўлиқ қониқасиз. Кимдир билан гаплашгингиз келмаса, гаплашмайсиз, ҳаддан ташқари принципиал ёки худбин бўлишингиз мумкин. Баъзан уларни идеаллаштирасиз, лекин улар билан ҳалоллик ва самимийликка интиласиз. Қариндошлар диндор бўлиши ёки шунчаки Юпитер бўйича лавозимларни — ўқитувчи, руҳоний, корпорация раҳбари, судья ва ҳ.к. эгаллаши мумкин. Улар билан оптимистик, хушмуомаласиз ва бирга қувноқ. Бирга маънавий ўсишга интиласиз, у ёки бу тарзда бу юз беради. Улар билан ўз дунё манзарангизни тузасиз. Ўқитувчиларингиз сизга яқин одамлардек туюлади. Ёмон ҳолатда насиҳат қиласиз, бўйсунишни билмайсиз, маънавий ривожланмайсиз, мавқеингиздан суиистеъмол қиласиз ва яқинларга нисбатан ҳаддан ошасиз.","Кармические. Раху – это природа обмана, иллюзия, каламбур. Могут быть плохие отношения, если вы не развиваетесь духовно или не занимаетесь эзотерикой. Вам свойственно придумывать то, чего нет в отношениях, ваши близкие вам не дают ясности какой-то, Могут быть предательства, грязь, оскорбления. Лечится это вашим стремлением двигаться только вперед в жизни, только развиваться, стремиться, ставить цели в своей жизни, планировать свои отношения с ближними, упорядочивать их самому. Обретайте баланс духовного и материального без перекосов и тогда у вас будут прекрасные отношения, в которых люди понимают друг друга и могут «читать» отношения между строк. Реакции ближних могут быть не теми, чем кажутся, например, говорит что расстроился из-за этого, а на самом деле из-за того, что произошло раньше и он не мог показать вам, что это расстроило и так заместил и выплеснул свою реакцию на то прошлое событие. Такая некая иллюзия.":"Кармик. Раҳу — бу алдов табиати, иллюзия, сўз ўйини. Агар маънавий ривожланмасангиз ёки эзотерика билан шуғулланмасангиз, ёмон муносабатлар бўлиши мумкин. Сизга муносабатларда йўқ нарсани ўйлаб топиш хос, яқинларингиз сизга қандайдир аниқлик бермайди, хиёнатлар, ифлослик, ҳақоратлар бўлиши мумкин. Бу ҳаётда фақат олдинга ҳаракатланиш, фақат ривожланиш, интилиш, ҳаётингизда мақсадлар қўйиш, яқинлар билан муносабатларингизни режалаштириш, уларни ўзингиз тартибга солиш истагингиз билан даволанади. Оғишларсиз маънавий ва моддий мувозанатини топинг ва шунда сизда одамлар бир-бирини тушунадиган ва муносабатларни сатрлар орасидан «ўқий» оладиган ажойиб муносабатлар бўлади. Яқинларнинг реакциялари кўринганидек бўлмаслиги мумкин, масалан, бундан хафа бўлдим дейди, аслида эса илгари юз берган нарса туфайли ва у сизга бу хафа қилганини кўрсата олмаган ва шу тарзда реакциясини ўша ўтган воқеага алмаштириб, тўкиб солган. Шундай қандайдир иллюзия.","Дружеские, легкие отношения. Много общения, совместное обучение чему – то, вечно играющие и смешливые, веселые и изменчивые отношения. Общие друзья, общение в социальных сетях, мессенджерах, поездки и приколы в отношениях. Долгие беседы, много идей, планов, разносторонние общие интересны, как братья отношения. Важна свобода в отношениях с близкими, практичность. Может быть много переписок, звонков, контактов, встреч, поездок. В плохом случае раздражительность на близких, импульсивность, поверхностность, искажение информации, переменчивые отношения, двуличие, склонность приврать, спорить, вести интриги и изворачиваться, чтобы не получить люлей за свои шалости или сплетни.":"Дўстона, енгил муносабатлар. Кўп мулоқот, нимагадир биргаликда ўқиш, абадий ўйнайдиган ва кулгили, қувноқ ва ўзгарувчан муносабатлар. Умумий дўстлар, ижтимоий тармоқлар, мессенжерларда мулоқот, муносабатларда сафарлар ва ҳазиллар. Узоқ суҳбатлар, кўп ғоялар, режалар, ҳар томонлама умумий қизиқишлар, ака-укалардек муносабатлар. Яқинлар билан муносабатларда эркинлик, амалийлик муҳим. Кўп ёзишмалар, қўнғироқлар, алоқалар, учрашувлар, сафарлар бўлиши мумкин. Ёмон ҳолатда яқинлардан жаҳл чиқиши, импульсивлик, юзакилик, маълумотни бузиш, ўзгарувчан муносабатлар, иккиюзламачилик, ёлғон қўшишга, баҳслашишга, фитна юритишга ва шўхликлари ёки ғийбатлари учун танбеҳ олмаслик учун айёрлик қилишга мойиллик.","Отношения характеризует чувственность, любовь, гармония, привязанность. Близкие, комфортные, добрые отношения, которые всем в кайф и удовольствие. Если девушки, то как близкие подруги могут общаться. Могут наводить красоту или вместе стремиться к богатству. Рассказывать об отношениях, а мужчины делиться рассказами о своих женщинах. Отношения полные поддержки, мира и доставления удовольствий и получения удовольствий вместе. Спокойные, уравновешенные, стабильные отношения. Отдых на природе или в искусстве, мягкие, нежные отношения, в которых можно смело проявлять свои таланты. В плохих случаях можете упрямиться, долго гневаться, не прощать обид, быть недоверчивым, бояться перемен и очень материально зацикленным. Не желание ничего менять, даже если уже плохо.":"Муносабатларни ҳиссиётлилик, муҳаббат, уйғунлик, боғланиш тавсифлайди. Ҳаммага завқ ва роҳат бағишлайдиган яқин, қулай, меҳрибон муносабатлар. Агар қизлар бўлса, яқин дугоналардек мулоқот қилиши мумкин. Гўзаллик яратиши ёки бирга бойликка интилиши мумкин. Муносабатлар ҳақида гапириб бериш, эркаклар эса аёллари ҳақидаги ҳикоялар билан бўлишиш. Қўллаб-қувватлаш, тинчлик ва бирга завқ бериш ва завқ олишга тўла муносабатлар. Хотиржам, мувозанатли, барқарор муносабатлар. Табиатда ёки санъатда дам олиш, истеъдодларингизни дадил намоён қилиш мумкин бўлган юмшоқ, нозик муносабатлар. Ёмон ҳолатларда қайсарлик қилишингиз, узоқ ғазабланишингиз, хафаликларни кечирмаслигингиз, ишонмайдиган бўлишингиз, ўзгаришлардан қўрқишингиз ва жуда моддий қотиб қолишингиз мумкин. Ҳатто аллақачон ёмон бўлса ҳам, ҳеч нарсани ўзгартиришни истамаслик.","Кармические. Можете желать уединения от близких, они могут сподвигнуть вас на духовные поиски, медитации, на программирование, новые технологии и гаджеты, энергетические практики, эзотерику, связь с богом. Аскетичный образ жизни входит в вашу жизнь. Могут быть трудности и проблемы, от того, что люди вас не понимают, вы для них какой-то космический человек. Если духовно развиваетесь и стремитесь к богу отношения со всеми хорошие, хоть и требуют периодического уединения, чтобы побыть внутри себя, как вам так и им.":"Кармик. Яқинлардан ёлғизланишни исташингиз мумкин, улар сизни маънавий излашга, медитацияларга, дастурлашга, янги технологиялар ва гаджетларга, энергетик амалиётларга, эзотерикага, худо билан алоқага ундаши мумкин. Ҳаётингизга зоҳидона ҳаёт тарзи киради. Одамлар сизни тушунмагани учун қийинчиликлар ва муаммолар бўлиши мумкин, сиз улар учун қандайдир космик инсонсиз. Агар маънавий ривожланаётган ва худога интилаётган бўлсангиз, ҳамма билан муносабатлар яхши, гарчи сизга ҳам, уларга ҳам ўзи ичида бўлиш учун вақти-вақти билан ёлғизланиш талаб қилинса ҳам.","Кармические. Суховатые взаимоотношения. Тут через близких работает карма, дает уроки либо через добро, либо через трудности. Отношения требуют больших усилий, нужно над ними много работать, открывать сердце друг другу, учиться заботиться. В отношениях могут быть свои законы и правила, которым нужно строго следовать. Серьезные отношения, без веселья, все везде по делу, по работе. Внутри тепло и есть любовь, но сложно показывать это близким. С возрастом отношения смягчаются и улучшаются. Можете быть жесткими, четкими и организовывать все, когда вы рядом с близкими. Отношения могут быть трудными из- за вашей излишней серьезности и требовательности.":"Кармик. Қуруқроқ ўзаро муносабатлар. Бу ерда яқинлар орқали карма ишлайди, ё яхшилик, ё қийинчиликлар орқали сабоқлар беради. Муносабатлар катта саъй-ҳаракат талаб қилади, улар устида кўп ишлаш, бир-бирига юракни очиш, ғамхўрлик қилишни ўрганиш керак. Муносабатларда қатъий амал қилиш керак бўлган ўз қонун ва қоидалари бўлиши мумкин. Жиддий муносабатлар, кўнгилхушликсиз, ҳамма жойда ҳаммаси иш бўйича, ишга оид. Ичкарида илиқ ва муҳаббат бор, лекин уни яқинларга кўрсатиш қийин. Ёш билан муносабатлар юмшайди ва яхшиланади. Яқинлар ёнида бўлганингизда қаттиққўл, аниқ бўлишингиз ва ҳаммасини ташкил қилишингиз мумкин. Ортиқча жиддийлигингиз ва талабчанлигингиз туфайли муносабатлар оғир бўлиши мумкин.","Конкуренция и воинственные взаимоотношения в плохом случае, либо защита друг друга в хорошем. Может быть много ссор из-за вашего стремления подчинить и вашей вспыльчивости и желания добиваться своего. Спорт, бег, хобби с колюще-режущими предметами нивелируют огонь в отношениях. В хорошем состоянии эти отношения честные, искренние, правда в лицо и совместное достижение целей, возможно только ваших целей. Вы стремитесь быть лидером среди близких, а также независимым и самостоятельным. Можете быть импульсивны, раздражительны и нетерпеливы, а порой очень эгоистичны и провоцировать конфликт, иногда грубы и резки. Вы можете развивать с близкими такие качества как энергичность, храбрость, смелость, решительность, уверенность в себе и бесстрашие.":"Ёмон ҳолатда рақобат ва жангари ўзаро муносабатлар, ёки яхши ҳолатда бир-бирини ҳимоя қилиш. Бўйсундиришга интилишингиз ва жаҳлдорлигингиз ва ўзиникини ўтказиш истагингиз туфайли кўп жанжаллар бўлиши мумкин. Спорт, югуриш, санчувчи-кесувчи буюмлар билан хобби муносабатлардаги оловни текислайди. Яхши ҳолатда бу муносабатлар ҳалол, самимий, юзга ҳақиқат ва мақсадларга, эҳтимол фақат сизнинг мақсадларингизга биргаликда эришиш. Сиз яқинлар орасида етакчи, шунингдек мустақил ва ўзига етарли бўлишга интиласиз. Импульсив, жиззаки ва сабрсиз, баъзан эса жуда худбин бўлишингиз ва низо қўзғатишингиз, баъзан қўпол ва кескин бўлишингиз мумкин. Яқинлар билан ғайратлилик, мардлик, жасорат, қатъият, ўзига ишонч ва қўрқмаслик каби фазилатларни ривожлантиришингиз мумкин.","Вы вкладываете себя в других людей, в эго другого человека, в личность другого человека. Вы склонны отдавать людям, служить миру, служить людям. Это может указывать на то, что у вас по Солнцу могут быть проблемы. Например, с эгоизмом какие-то сложности, с гордыней, с тем чтобы брать на себя ответственность. Вы не живете для себя, не вкладываетесь в себя, в свой бренд, в свое эго и внешний вид, не тратите на свой личностный рост. Учитесь вкладываться в себя и в свое.":"Сиз ўзингизни бошқа одамларга, бошқа инсоннинг эгосига, бошқа инсоннинг шахсиятига киритасиз. Сиз одамларга беришга, дунёга хизмат қилишга, одамларга хизмат қилишга мойилсиз. Бу сизда Қуёш бўйича муаммолар бўлиши мумкинлигини кўрсатиши мумкин. Масалан, худбинлик билан қандайдир қийинчиликлар, кибр билан, масъулиятни олиш билан. Сиз ўзингиз учун яшамайсиз, ўзингизга, брендингизга, эгоингиз ва ташқи кўринишингизга сармоя киритмайсиз, шахсий ўсишингизга сарфламайсиз. Ўзингизга ва ўзингизникига сармоя киритишни ўрганинг.","Если «0» – это могут быть потери, большие расходы, есть проблема в этой области, человеку нужно следить за этими факторами, чтобы свести к минимуму проблемы. Вы либо сознательно ни во что не вкладываете либо имеете большую свободу выбора в этом. У вас нет склонности куда себя вкладывать. Вам нужно самому определить это. Научиться вкладываться в одном выбранном направлении. Тут вы расслаблены и можете сами выбирать куда тратить, а куда нет. Еще ситуация, когда расходы непонятно куда, силы непонятно куда уходят. Может быть склонность проживать жизнь зря, растрачиваясь на все подряд. Вам хорошо найти какое – то дело в которое вы сможете осознанно тратиться, которому можете посвятить себя. Вам нужно найти духовного учителя, жизнь которого вам нравится и вы хотели бы также. И воплощать свои цели и идеи рядом с ним. Также вам хорошо, если вокруг вас есть люди, которым требуется забота, тогда вы можете себя в них вкладывать.":"Агар «0» бўлса — бу йўқотишлар, катта харажатлар бўлиши мумкин, бу соҳада муаммо бор, муаммоларни минималлаштириш учун инсонга бу омилларни кузатиш керак. Сиз ё онгли равишда ҳеч нарсага сармоя киритмайсиз, ё бунда катта танлов эркинлигига эгасиз. Сизда ўзингизни қаергадир киритишга мойиллик йўқ. Сизга буни ўзингиз аниқлаш керак. Битта танланган йўналишга сармоя киритишни ўрганиш. Бу ерда сиз бўшашгансиз ва қаерга сарфлаш, қаерга эмаслигини ўзингиз танлай оласиз. Яна харажатлар нима қаерга кетгани ноаниқ, кучлар нима қаерга кетгани ноаниқ вазият. Ҳар нарсага сарфланиб, ҳаётни беҳуда яшашга мойиллик бўлиши мумкин. Сизга онгли сарфлай оладиган, ўзингизни бағишлай оладиган қандайдир иш топиш яхши. Сизга ҳаёти сизга ёқадиган ва шундай бўлишни истайдиган маънавий устоз топиш керак. Ва унинг ёнида мақсад ва ғояларингизни амалга ошириш. Шунингдек атрофингизда ғамхўрликка муҳтож одамлар бўлса, яхши, шунда ўзингизни уларга киритишингиз мумкин.","Вы живете для себя, вкладываетесь в себя, в свой бренд, в свое эго и внешний вид. Траты на личностный рост, на развитие отечества (государства), на детей и мужа, на всех любимых и любящих вас. Траты на развитие мужественности в муже, на то, чтобы он становился лидером. На свое лидерство и лучшесть. На развлечения и азартные игры, на шоу и представления, на все что делает жизнь яркой, на праздники, на все, что выделит вас или ваш проект из массы и будет вдохновлять других. На творчество и самовыражение, на все, что будет поднимать вам самооценку. В не лучшем случае, траты на излишние земные наслаждения, на самолюбование, эгоизм, показуху, позерство и траты сверх своих возможностей.":"Сиз ўзингиз учун яшайсиз, ўзингизга, брендингизга, эгоингиз ва ташқи кўринишингизга сармоя киритасиз. Шахсий ўсишга, ватан (давлат) ривожига, фарзандлар ва эрга, сизни севадиган ва севимли ҳаммага харажатлар. Эрдаги эркакликни ривожлантиришга, унинг етакчи бўлишига харажатлар. Ўз етакчилигингиз ва энг яхшилигингизга. Кўнгилочар машғулотлар ва қимор ўйинларига, шоу ва томошаларга, ҳаётни ёрқин қиладиган ҳамма нарсага, байрамларга, сизни ёки лойиҳангизни оммадан ажратиб турадиган ва бошқаларни илҳомлантирадиган ҳамма нарсага. Ижод ва ўзини ифода этишга, ўзини баҳолашингизни кўтарадиган ҳамма нарсага. Энг яхши бўлмаган ҳолатда ортиқча дунёвий лаззатларга, ўзига маҳлиё бўлишга, худбинликка, кўз-кўзга, ўзини кўрсатишга ва имкониятдан ортиқ харажатлар.","Траты на материнство, маму, женщину с детьми, грудь, на водные процедуры, спа, комфорт. На заботу о людях, на развитие интуиции и подсознание, на еду и быт. Вклад в семью, жену, детей, родственников, дом и домашнее хозяйство, в родину и народные традиции или семейные традиции. На нянь и психологов. Траты интуитивные, непостоянные, эмоциональные или на эмоциях. Все в дом. На благотворительность и на маленькие душевные радости, домашнюю одежду и кошку.":"Оналикка, онага, болали аёлга, кўкракка, сув муолажаларига, спа, қулайликка харажатлар. Одамларга ғамхўрликка, интуиция ва онг остини ривожлантиришга, овқат ва маишатга. Оилага, хотинга, фарзандларга, қариндошларга, уй ва уй хўжалигига, ватан ва халқ анъаналари ёки оилавий анъаналарга сармоя. Энагалар ва психологларга. Интуитив, беқарор, ҳиссиётли ёки ҳис-туйғулар таъсиридаги харажатлар. Ҳаммаси уйга. Хайрияга ва кичик руҳий қувончларга, уй кийимлари ва мушукка.","Вы вкладываетесь в знания, в культурное просвещение, в духовное развитие, в путештствия, в то, чтобы учить и учиться. Можете вкладываться в мужа и в детей. В высшее образование, расширение мировоззрения и территории. Если нет знания законов, будете нарушать законы – будете платить штрафы (расходы), поэтому знание законов социума и духовные вам сэкономит много ресурса. Вкладываетесь в свою экспертность, в тех людей кому поручили дело. Расходы могут быть огромные, а вы можете щедро тратить заработанное. Изучение иностранных языков и истории расширяет ваше мировоззрение. Расходы приходят тогда когда вы настроены пессимистично, поэтому если оптимизма нет не вкладывайтесь. Излишняя принципиальность тоже приводит к расходам, так же как и слепое следование правилам, без понимания их сути и смысла. Вкладываетесь в свой авторитет или только в авторитетные и крупные проекты. Споры, суды приводят к расходам. Тратите энергию на споры, тут лучше научиться принимать чужую точку зрения, ведь она, возможно, дополняет вашу картину мира. Не тратьте силы на грубости и осуждение других, не поучайте, тогда ресурса будет больше.":"Сиз билимга, маданий маърифатга, маънавий ривожланишга, саёҳатларга, ўргатиш ва ўрганишга сармоя киритасиз. Эр ва фарзандларга сармоя киритишингиз мумкин. Олий таълимга, дунёқараш ва ҳудудни кенгайтиришга. Агар қонунларни билмасангиз, қонунларни бузасиз — жарима тўлайсиз (харажатлар), шунинг учун жамият ва маънавий қонунларни билиш сизга кўп ресурсни тежайди. Ўз экспертлигингизга, иш топширганингиз одамларга сармоя киритасиз. Харажатлар улкан бўлиши мумкин, сиз эса топилганни саховат билан сарфлашингиз мумкин. Чет тиллари ва тарихни ўрганиш дунёқарашингизни кенгайтиради. Харажатлар пессимистик кайфиятда бўлганингизда келади, шунинг учун агар оптимизм бўлмаса, сармоя киритманг. Ортиқча принципиаллик ҳам, моҳияти ва маъносини тушунмай қоидаларга кўр-кўрона эргашиш каби, харажатларга олиб келади. Ўз обрўингизга ёки фақат обрўли ва йирик лойиҳаларга сармоя киритасиз. Баҳслар, судлар харажатларга олиб келади. Энергияни баҳсларга сарфлайсиз, бу ерда бировнинг нуқтаи назарини қабул қилишни ўрганган яхшироқ, ахир у, эҳтимол, дунё манзарангизни тўлдиради. Кучни бошқаларга қўполлик ва қоралашга сарфламанг, насиҳат қилманг, шунда ресурс кўпроқ бўлади.","Вы вкладываете в иллюзии, в фокусы, в шоу, во что-то неестественное, вредное пластиковое, искусственное. Траты на таблетки и алкоголь, на магию и эзотерику, траты тут, вообще, кармически обусловлены и часто бывают неожиданными для вас. На ругань и дрязги, из-за оскорблений могут быть расходы, от всего хаотичного и вами не спланированного. Планируйте траты и расход энергии и все будет супер.":"Сиз иллюзияларга, фокусларга, шоуга, нотабиий, зарарли пластик, сунъий нимагадир сармоя киритасиз. Дорилар ва алкоголга, сеҳр ва эзотерикага харажатлар, бу ердаги харажатлар умуман кармик белгиланган ва кўпинча сиз учун кутилмаган бўлади. Сўкиниш ва жанжалларга, ҳақоратлар туфайли харажатлар бўлиши мумкин, тартибсиз ва сиз режалаштирмаган ҳамма нарсадан. Харажатлар ва энергия сарфини режалаштиринг ва ҳаммаси супер бўлади.","Вклад в перемены в жизни, в братьев и сестер и их проекты, может быть, даже в знакомых и знакомства, в машину, телефон, поездки и перемещения. Тратитесь на любое обучение и свою свободу, на книги журналы, друзей, источники информации и путешествия. Все что связано с общением, контактами и информацией. Тратите легко, ради спора, ради интереса. Рациональные траты, чтобы цена – качество, можно и по акции, чтобы выгодно было все. Зря не потратите ни силы, ни деньги, если есть вариант повыгоднее.":"Ҳаётдаги ўзгаришларга, ака-ука ва опа-сингилларга ва уларнинг лойиҳаларига, эҳтимол, ҳатто танишлар ва танишувларга, машина, телефон, сафарлар ва ҳаракатланишларга сармоя. Ҳар қандай ўқиш ва эркинлигингизга, китоблар, журналлар, дўстлар, маълумот манбалари ва саёҳатларга сарфланасиз. Мулоқот, алоқалар ва маълумот билан боғлиқ ҳамма нарса. Осон, баҳс учун, қизиқиш учун сарфлайсиз. Нарх — сифат бўлиши учун рационал харажатлар, акция бўйича ҳам мумкин, ҳаммаси фойдали бўлиши учун. Агар фойдалироқ вариант бўлса, на кучни, на пулни беҳуда сарфламайсиз.","Вы вкладываете себя во все красивое, дорогое, на то, чтобы покайфовать, в роскошь и комфорт. Вам нужен самый роскошный отель, самое красивое платье, самая вкусная еда, роскошный автомобиль. Траты на женщин и женские вопросы, мужчина тратит на романтические отношения, на женщин, на то, чтобы разбогатеть еще больше. Траты на свидание, на то, чтобы покайфовать и на комфорт. Вы вкладываете свои силы в то, чтобы зарабатывать хорошо, потому что любите тратить и всегда находите средства, чтобы кайфовать. Вам полезно развивать в себе целомудрие и учиться осознанно контролировать свои хотелки. Могут быть чрезмерные траты на развлечения и удовольствия.":"Сиз ўзингизни барча чиройли, қиммат, роҳатланиш учун, ҳашамат ва қулайликка киритасиз. Сизга энг ҳашаматли меҳмонхона, энг чиройли кўйлак, энг мазали овқат, ҳашаматли автомобиль керак. Аёллар ва аёллар масалаларига харажатлар, эркак романтик муносабатларга, аёлларга, янада бойиш учун сарфлайди. Учрашувга, роҳатланиш ва қулайликка харажатлар. Сиз кучингизни яхши пул топишга киритасиз, чунки сарфлашни яхши кўрасиз ва роҳатланиш учун доим маблағ топасиз. Сизга ўзингизда иффатни ривожлантириш ва хоҳишларингизни онгли назорат қилишни ўрганиш фойдали. Кўнгилочар машғулотлар ва завқларга ортиқча харажатлар бўлиши мумкин.","Не понятно куда вам себя вкладывать, тут вам подскажет интуиция, в основном вклад идет в духовное и внутренний мир. Вкладывайте в духовную сферу жизни, в эзотерическую, в ретриты, в йогу, в паломничество и медитации. Вы можете покупать старые вещи, которые уже разваливаются, чтобы дать им вторую жизнь. Вам нужно вкладываться в трансформацию и улучшение своего сознания и мышления, работайте над своими устаревшими установками, над чужими и негативными установками в вашей голове, над неэффективными установками в вашем подсознании, занимайтесь стремлением к Богу. Вкладывать можете в возможности расслабления и уединения, в программирование, в гаджеты, электронику и новейшие технологии, а также в то, что опережает время. Людям часто не понятно куда вы тратите свои силы, деньги и ресурсы. Бывает, что нечего вкладывать либо так со стороны кажется, но дела обстоят гораздо лучше.":"Ўзингизни қаерга киритиш ноаниқ, бу ерда сизга интуиция айтиб беради, асосан сармоя маънавий ва ички дунёга кетади. Ҳаётнинг маънавий соҳасига, эзотерикага, ретритларга, йогага, зиёрат ва медитацияларга сармоя киритинг. Сиз иккинчи ҳаёт бериш учун аллақачон бузилаётган эски нарсаларни сотиб олишингиз мумкин. Сизга онгингиз ва фикрлашингизнинг трансформацияси ва яхшиланишига сармоя киритиш керак, эскирган ўрнатмаларингиз, бошингиздаги бировнинг ва салбий ўрнатмалар, онг остингиздаги самарасиз ўрнатмалар устида ишланг, Худога интилиш билан шуғулланинг. Бўшашиш ва ёлғизланиш имкониятларига, дастурлашга, гаджетлар, электроника ва энг янги технологияларга, шунингдек замондан олдинда бўлган нарсаларга сармоя киритишингиз мумкин. Одамларга кўпинча кучингиз, пулингиз ва ресурсларингизни қаерга сарфлаётганингиз тушунарсиз. Баъзан киритадиган нарса йўқ ёки четдан шундай туюлади, лекин ишлар анча яхши.","Вы можете очень эгоистично относиться к людям, строить отношения где все для себя любимого, хотите чтобы вами восхищались, чтобы вы были в центре внимания, чтобы вы были главным в отношениях. Женщинам необходимо, чтобы умели отдавать первенство мужчине в отношениях. Нужно уметь быть самой женственной, самый лучшей женщиной, самой лучшей во всем, мужчины тоже хотят быть лучшими в отношениях. Вы стремитесь выразить свою индивидуальность, иметь чувство собственного достоинства, быть независимым, самостоятельным, брать ответственность за отношения с людьми, хотите выделиться. Организуете совместные мероприятия и выражаете себя благородным, великодушным, щедрым человеком. Хотите радовать других, чтобы вам доставалось внимание. Можете быть излишне требовательны и высокомерны, заниматься самолюбованием, хвастаться, имеете склонность к показухе, можете насиловать волю людей, используя их в своих личных целях, а иногда в корыстных.":"Сиз одамларга жуда худбинона муносабатда бўлишингиз, ҳаммаси севимли ўзингиз учун бўлган муносабатлар қуришингиз мумкин, сиздан ҳайратланишларини, диққат марказида бўлишингизни, муносабатларда асосий бўлишингизни истайсиз. Аёлларга муносабатларда биринчиликни эркакка бера олиш зарур. Энг аёлларча, энг яхши аёл, ҳамма нарсада энг яхши бўла олиш керак, эркаклар ҳам муносабатларда энг яхши бўлишни истайди. Сиз ўз индивидуаллигингизни ифода этишга, ўз қадр-қиммати ҳиссига эга бўлишга, мустақил, ўзига етарли бўлишга, одамлар билан муносабатлар учун масъулиятни олишга интиласиз, ажралиб туришни истайсиз. Биргаликдаги тадбирлар ташкил қиласиз ва ўзингизни олижаноб, мурувватли, саховатли инсон сифатида ифода этасиз. Сизга эътибор тушиши учун бошқаларни қувонтиришни истайсиз. Ҳаддан ташқари талабчан ва кибрли бўлишингиз, ўзингизга маҳлиё бўлишингиз, мақтанишингиз, кўз-кўзга мойил бўлишингиз, одамларнинг иродасини шахсий, баъзан эса ғаразли мақсадларингизда фойдаланиб зўрлашингиз мумкин.","У вас очень заботливые, теплые, как будто семейные отношения. Вы можете иногда отно- ситься как мама к своему мужу, к родственникам и вообще к людям. Иногда можете быть обидчивы, это говорит о том, что вы не сепарировались от мамы и вам нужно перейти в психологически взрослую позицию из позиции ребенка и брать ответственность за свое поведение и жизнь. Вы всегда приготовите поесть, с вами тепло и уютно, как дома. Отношения могут быть изменчивы и меняться от ваших испытываемых эмоций сейчас и зависеть от вашего настроения. А могут быть эмоциональные. Вам может хотеться быть всегда вместе с партнером, вы чувствуете людей на уровне души и понимаете их, умеете принять как есть и пожалеть, поэтому к вам идут плакаться в жилетку. Если эмоций человек не вызывает, вы не знаете что с ним делать, тк у вас эмоции играют важную роль в отношениях с людьми. На вас сильно влияют установки вашей матери или вашей главной женщины кто вас воспитывал или живет долгое время с вами. Вы альтруистичны и умеете отдавать первенство в отношениях, занимая почетное второе место. Чему учила и учит мама влияет на вас очень сильно, важно уметь различать свои установки от навязанных. Вы можете впитывать как губка состояние и настроение человека и умеете отражать всю сущность и поведение других людей как зеркало воды. Вам нужен человек, которого вы можете отражать, как Луна отражает свет Солнца. Родовые установки и весь род тоже вносит большой вклад в формирование вас как личности в отношениях с социумом. Работайте с родом и родовыми энергетическими практиками, чтобы занять СВОЕ место в роду, а не место мамы или бабушки для вашей мамы, например, ведь тогда рядом с вашим мужем будет «пусто», если вы становитесь ему не женой, а свекровью, например. И отношения в семье испортятся. Вы чтите традиции и умеете сочувствовать, у вас развитая интуиция и чуткость, вы очень заботливы.":"Сизда жуда ғамхўр, илиқ, гўё оилавий муносабатлар. Баъзан эрингизга, қариндошларга ва умуман одамларга онадек муносабатда бўлишингиз мумкин. Баъзан аразчи бўлишингиз мумкин, бу онадан ажралмаганингизни ва сизга бола позициясидан психологик катта позицияга ўтиш ва хулқингиз ва ҳаётингиз учун масъулиятни олиш кераклигини айтади. Сиз доим овқат тайёрлайсиз, сиз билан уйдагидек илиқ ва қулай. Муносабатлар ўзгарувчан бўлиши ва ҳозир бошдан кечираётган ҳис-туйғуларингиздан ўзгариши ва кайфиятингизга боғлиқ бўлиши мумкин. Ёки ҳиссиётли бўлиши мумкин. Сиз доим шерик билан бирга бўлишни исташингиз мумкин, одамларни қалб даражасида ҳис қиласиз ва тушунасиз, қандай бўлса шундай қабул қилиш ва раҳм қилишни биласиз, шунинг учун сизга дардларини айтиш учун келишади. Агар инсон ҳис-туйғу уйғотмаса, у билан нима қилишни билмайсиз, чунки одамлар билан муносабатларда сизда ҳис-туйғулар муҳим роль ўйнайди. Сизга онангиз ёки сизни тарбиялаган ёки сиз билан узоқ вақт яшаган асосий аёлингизнинг ўрнатмалари кучли таъсир қилади. Сиз альтруистсиз ва муносабатларда шарафли иккинчи ўринни эгаллаб, биринчиликни беришни биласиз. Онангиз нимага ўргатган ва ўргатаётгани сизга жуда кучли таъсир қилади, ўз ўрнатмаларингизни тиқиштирилганлардан фарқлай билиш муҳим. Сиз инсоннинг ҳолати ва кайфиятини булутдек шимиб олишингиз ва бошқа одамларнинг бутун моҳияти ва хулқини сув ойнаси каби акс эттира олишингиз мумкин. Сизга Ой Қуёш нурини акс эттиргандек акс эттира оладиган инсон керак. Уруғ ўрнатмалари ва бутун уруғ ҳам жамият билан муносабатларда шахс сифатида шаклланишингизга катта ҳисса қўшади. Уруғда ЎЗ ўрнингизни эгаллаш учун, масалан, онангиз учун она ёки буви ўрнини эмас, уруғ ва уруғ энергетик амалиётлари билан ишланг, ахир агар эрингизга хотин эмас, масалан, қайнона бўлиб қолсангиз, эрингиз ёнида «бўш» бўлади. Ва оиладаги муносабатлар бузилади. Сиз анъаналарни эъзозлайсиз ва ҳамдард бўлишни биласиз, сизда ривожланган интуиция ва сезгирлик бор, сиз жуда ғамхўрсиз.","Отношения искренние, доверительные либо отношения на расстоянии. Часто хочется убежать от партнёра либо давать ему наставления, учить его чему-то, а иногда хочется поучать и давать непрошенные советы. Вы можете быть наставником и мудрым учителем, быть авторитетным в ваших отношениях, по крайней мере вам хочется в глазах партнера и людей видеть свой статус, чтобы вы были великими и величественными, чтобы вами восхищались и вам доверяли. В отношениях можете делать что – либо руками партнера, а также люди сами идут к вам за советами и приносят то, что вам нужно. Вы добропорядочны, чистосердечны и умеете прощать ошибки людей, стремитесь к духовному росту и расширению территорий своей жизни и сознания. Ваше мировоззрение полностью влияет на ваши отношения и положение в социуме. Вы хотите путешествовать с людьми и образовываться. Вы свободолюбивы, имеете высокие жизненные цели и много хобби, в которые увлекаете свое окружение. Богатство через людей. Иногда, вы можете полагаться на авось и фанатично следовать правилам, не зная их сути. Это все в плохом случае. Можете навязывать свои религиозные и нравственные взгляды, злоупотреблять властью и желать все и сразу, без понимания важности постепенности шагов к достижению ваших целей.":"Муносабатлар самимий, ишончли ёки масофадаги муносабатлар. Кўпинча шерикдан қочиб кетгингиз ёки унга йўл-йўриқ бергингиз, унга нимадир ўргатгингиз, баъзан эса насиҳат қилгингиз ва сўралмаган маслаҳатлар бергингиз келади. Сиз устоз ва доно ўқитувчи бўлишингиз, муносабатларингизда обрўли бўлишингиз мумкин, ҳеч бўлмаганда шерик ва одамлар кўзида ўз мавқеингизни, буюк ва улуғвор бўлишингизни, сиздан ҳайратланишларини ва сизга ишонишларини кўргингиз келади. Муносабатларда нимадир шерикнинг қўли билан қилишингиз мумкин, шунингдек одамлар ўзлари сизга маслаҳат сўраб келади ва сизга керакли нарсани олиб келади. Сиз одобли, чин юракли ва одамларнинг хатоларини кечиришни биласиз, маънавий ўсиш ва ҳаётингиз ва онгингиз ҳудудларини кенгайтиришга интиласиз. Дунёқарашингиз муносабатларингиз ва жамиятдаги мавқеингизга бутунлай таъсир қилади. Сиз одамлар билан саёҳат қилишни ва таълим олишни истайсиз. Сиз эркинликни севувчисиз, юксак ҳаётий мақсадларга ва атрофингизни қизиқтирадиган кўплаб хоббиларга эгасиз. Одамлар орқали бойлик. Баъзан «бир гап бўлар»га таянишингиз ва моҳиятини билмай қоидаларга фанатик эргашишингиз мумкин. Буларнинг барчаси ёмон ҳолатда. Диний ва ахлоқий қарашларингизни тиқиштиришингиз, ҳокимиятни суиистеъмол қилишингиз ва мақсадларингизга эришиш қадамларининг аста-секинлиги муҳимлигини тушунмай, ҳаммасини бирданига исташингиз мумкин.","В отношениях могут быть иллюзии и обман, провокации. Часто вы не можете понять партнера, временами в отношениях наступает просвет, когда все становится понятно. Вас может кидать из крайности в крайность, отношения нестабильные, изменчивые и всегда кармические. Может быть много грязи, предательства и оскорблений. Возникать состояние сумасшествия. Щекочущие нервы ситуации, манипуляции, зависимости. Когда у вас возникают сложные ситуации, вы, тем не менее, можете достаточно спокойно внутри их переносить, с какой- то долей оптимизма и с минимальным волнением. Часто партнер только грозится, но реально ничего не делает из того, что говорил.":"Муносабатларда иллюзиялар ва алдов, иғволар бўлиши мумкин. Кўпинча шерикни тушуна олмайсиз, вақти-вақти билан муносабатларда ҳаммаси тушунарли бўладиган ёруғлик келади. Сизни бир ҳаддан бошқасига ташлаши мумкин, муносабатлар беқарор, ўзгарувчан ва доим кармик. Кўп ифлослик, хиёнат ва ҳақоратлар бўлиши мумкин. Телбалик ҳолати пайдо бўлиши мумкин. Асабни қитиқлайдиган вазиятлар, манипуляциялар, қарамликлар. Сизда мураккаб вазиятлар пайдо бўлганда, сиз шунга қарамай уларни ичингизда анча хотиржам, қандайдир оптимизм улуши билан ва минимал ҳаяжон билан кечира оласиз. Кўпинча шерик фақат дўқ қилади, лекин айтганларидан ҳеч нарсани ҳақиқатан қилмайди.","Зависимость от ТВ, порнографии, компьютерных игр может быть в ваших отношениях. Все поведение наше и нашего партнера – это всегда просьба о любви. Вы можете временами видеть сквозь иллюзии и читать между строк, понимая, что то, что показывает вам партнер не настоящее. В душе у него все по другому. Он как будто отыгрывает роль, чтобы проучить вас.":"Муносабатларингизда ТВ, порнография, компьютер ўйинларига қарамлик бўлиши мумкин. Бизнинг ва шеригимизнинг барча хулқи — бу доим муҳаббат илтимоси. Сиз вақти-вақти билан иллюзиялар орқали кўришингиз ва сатрлар орасини ўқишингиз, шерик сизга кўрсатаётган нарса ҳақиқий эмаслигини тушунишингиз мумкин. Унинг қалбида ҳаммаси бошқача. У гўё сизни ўргатиш учун рол ўйнаётгандек.","Вам лучше жить на природе и стремиться ко всему естественному и натуральному, тогда отношения становятся лучше. Чтобы проработать отношения, заглядывайте в глубь себя и ищите ответы там. Занимайтесь духовным ростом своим, а муж как зеркало отразит вам ваше подсознание. Полюбите честность, чистоту мысли и порядок. Избавьтесь от страха перед будущим, тогда отношения станут легче. Избавьтесь от вредных привычек и токсичности. Вы интуитивно понимаете ваши отношения и партнер вам дан для отработки кармических уроков. Не пеняйте на него, все ваши претензии к нему – это глубокие претензии к себе, если бы вы были в его положении. Прорабатывайте темы родителя противоположного с вами пола, делайте практику поклона отцу, матери и роду. Достройте образ отца, матери даже если их нет или не было рядом, продумайте как себя ведет ваш отец, мама, как реагирует на вас и все до мелочей. Ваши проблемы в отношениях, проблемы вас ребенка с вашим родителем, простите себя и их.":"Сизга табиатда яшаш ва барча табиий ва табиийликка интилиш яхшироқ, шунда муносабатлар яхшиланади. Муносабатларни ишлаб чиқиш учун ўзингизнинг чуқурлигингизга назар солинг ва жавобларни у ердан изланг. Ўз маънавий ўсишингиз билан шуғулланинг, эр эса ойнадек сизга онг остингизни акс эттиради. Ҳалоллик, фикр софлиги ва тартибни севинг. Келажакдан қўрқувдан қутулинг, шунда муносабатлар енгиллашади. Зарарли одатлар ва заҳарликдан қутулинг. Сиз муносабатларингизни интуитив тушунасиз ва шерик сизга кармик сабоқларни ишлаб чиқиш учун берилган. Уни айбламанг, унга бўлган барча даъволарингиз — агар унинг ўрнида бўлганингизда, ўзингизга бўлган чуқур даъволар. Сиз билан қарама-қарши жинсдаги ота-она мавзуларини ишлаб чиқинг, отага, онага ва уруғга таъзим амалиётини қилинг. Ота, она образини, ҳатто улар ёнингизда бўлмаса ёки бўлмаган бўлса ҳам, тугалланг, отангиз, онангиз ўзини қандай тутишини, сизга қандай муносабатда бўлишини майда-чуйдасигача ўйлаб чиқинг. Муносабатлардаги муаммоларингиз — бола сиз ва ота-онангиз ўртасидаги муаммолар, ўзингизни ва уларни кечиринг.","Ваши отношения с людьми лёгкие, воздушные, дружеские, могут напоминать чем-то подростковые. Вы чувствуете себя всегда молодым, иногда играете и веселитесь как дети. Вам важно договариваться в отношениях, общаться, быть на связи и при этом иметь свою свободу и давать ее другим. Могут в отношениях быть расчет и выгода, чтобы все практично и рационально, без эмоций. Вы всегда учитесь отношениям и в самих отношениях учитесь жизни. Вы часто знакомитесь с другими людьми, всегда находитесь в каких-то компаниях, стремитесь путешествовать, перемещаться, много общаться, контактировать, с партнером часто созваниваетесь или списываетесь в соцсетях. Вы любите проанализировать свои отношения, в них у вас больше играет разум, нежели чувства. Вы любите умных людей, у вас много интересных идей для отношений, вы все время обучаетесь, вас слушаю взахлеб, потому что вы непревзойденный рассказчик. Вы всегда умеете найти нужную информацию и нужные контакты людей. В случаях не очень хороших, вы можете вести себя двулично. искажать информацию, разносить сплетни, разбрасываться отношениями, тк относитесь к людям поверхностно. Отношениям может не хватать глубины. Вы можете часто менять все в своей жизни внося хаос и суету.":"Одамлар билан муносабатларингиз енгил, ҳаводор, дўстона, нимаси биландир ўсмирларникини эслатиши мумкин. Сиз ўзингизни доим ёш ҳис қиласиз, баъзан болалардек ўйнайсиз ва кўнгил очасиз. Сизга муносабатларда келишиш, мулоқот қилиш, алоқада бўлиш ва бунда ўз эркинлигингизга эга бўлиш ва уни бошқаларга бериш муҳим. Муносабатларда ҳаммаси амалий ва рационал, ҳис-туйғусиз бўлиши учун ҳисоб-китоб ва фойда бўлиши мумкин. Сиз доим муносабатларни ўрганасиз ва муносабатларнинг ўзида ҳаётни ўрганасиз. Сиз кўпинча бошқа одамлар билан танишасиз, доим қандайдир давраларда бўласиз, саёҳат қилишга, ҳаракатланишга, кўп мулоқот қилишга, алоқа қилишга интиласиз, шерик билан тез-тез қўнғироқлашасиз ёки ижтимоий тармоқларда ёзишасиз. Сиз муносабатларингизни таҳлил қилишни яхши кўрасиз, уларда сизда ҳислардан кўра ақл кўпроқ ўйнайди. Сиз ақлли одамларни яхши кўрасиз, сизда муносабатлар учун кўп қизиқарли ғоялар бор, доим ўқийсиз, сизни берилиб тинглашади, чунки сиз беқиёс ҳикоячисиз. Сиз доим керакли маълумот ва одамларнинг керакли алоқаларини топишни биласиз. Унчалик яхши бўлмаган ҳолатларда иккиюзламачилик қилишингиз, маълумотни бузишингиз, ғийбат тарқатишингиз, муносабатларни сочишингиз мумкин, чунки одамларга юзаки муносабатда бўласиз. Муносабатларга чуқурлик етишмаслиги мумкин. Ҳаётингиздаги ҳамма нарсани тез-тез ўзгартириб, хаос ва ғимирлаш киритишингиз мумкин.","У вас добрые, чувственные, хорошие отношения, благодарные, красивые, восхитительные, спокойные, стабильные и гармоничные. Отношения, где тратят деньги на партнёра, кайфуют вместе. Вы всегда можете попросить другого сделать что – то для вас и этот человек будет очень рад вам помочь. Вас объединяют общие хобби, вам нужно получать удовольствие от отношений с людьми. Любовь – самое главное в отношениях. Вы умеете принимать людей какие они есть и люди относятся к вам в ответ так же. Вы чувственны, рассудительны, работаете над отношениями и относитесь с терпением к своему окружению. Ловушка для вас стать удобным для всех, кроме себя. Хорошо отдыхать на природе вместе, облагораживать обстановку и создавать комфорт, ходить на свидания, украшать себя и знать свою истинную ценность по праву рождения. Вы мягкие и нежные, проявляете много элегантности и обаяния в отношениях. Люди подталкивают вас к развитию ваших талантов. Не сопротивляйтесь. Одновременно с этим, вы можете быть упрямы, долго не прощать, быть ленивым или даже долго гневаться. Вы можете быть консервативным и в чем-то инертным. Можете погружаться в чрезмерные земные радости, вплоть до развратных и стать излишне материальным. Даже если в отношениях что-то не так и вы понимаете это, что нужно что-то менять, вы будете продолжать делать тоже самое, ничего не меняя. Умейте сами создавать свои отношения и перестаньте терпеть там, где это уже лишнее.":"Сизда меҳрибон, ҳиссиётли, яхши муносабатлар, миннатдор, чиройли, ажойиб, хотиржам, барқарор ва уйғун. Шерикка пул сарфланадиган, бирга роҳатланадиган муносабатлар. Сиз доим бошқасидан сиз учун нимадир қилишни сўрашингиз мумкин ва бу инсон сизга ёрдам беришдан жуда хурсанд бўлади. Сизни умумий хоббилар бирлаштиради, сизга одамлар билан муносабатлардан завқ олиш керак. Муҳаббат — муносабатларда энг асосийси. Сиз одамларни қандай бўлса шундай қабул қилишни биласиз ва одамлар сизга жавобан худди шундай муносабатда бўлади. Сиз ҳиссиётли, мулоҳазали, муносабатлар устида ишлайсиз ва атрофингизга сабр билан муносабатда бўласиз. Сиз учун тузоқ — ўзингиздан бошқа ҳамма учун қулай бўлиб қолиш. Бирга табиатда дам олиш, муҳитни безатиш ва қулайлик яратиш, учрашувларга бориш, ўзингизни безатиш ва туғилишдан берилган ҳақиқий қадрингизни билиш яхши. Сиз юмшоқ ва нозиксиз, муносабатларда кўп нафислик ва жозиба кўрсатасиз. Одамлар сизни истеъдодларингизни ривожлантиришга ундайди. Қаршилик қилманг. Шу билан бирга, сиз қайсар бўлишингиз, узоқ кечирмаслигингиз, дангаса бўлишингиз ёки ҳатто узоқ ғазабланишингиз мумкин. Консерватив ва нимададир инерт бўлишингиз мумкин. Бузуқликкача ортиқча дунёвий қувончларга шўнғишингиз ва ҳаддан ташқари моддий бўлиб қолишингиз мумкин. Ҳатто муносабатларда нимадир нотўғри бўлса ва сиз буни, нимадир ўзгартириш кераклигини тушунсангиз ҳам, ҳеч нарсани ўзгартирмай, худди шу нарсани қилишда давом этасиз. Муносабатларингизни ўзингиз яратишни билинг ва аллақачон ортиқча бўлган жойда чидашни тўхтатинг.","У вас непонятно какие отношения, но то, что они несут кармическую нагрузку это точно. Возможно также у вас отношения, основанные на духовности и энергетических практиках, на эзотерике. Тем не менее, вам часто нужно бывать в одиночестве, чтобы восстановить силы и разобраться в себе. Ваша задача в отношениях – стремиться к богу. Отношения с людьми строятся интуитивно, без особого понимания, как их строить. В любом случае они очень необычные и могут быть либо слишком консервативными, либо опережать эпоху. Вы можете часто отрекаться от партнёра или от себя. Духовность в ваших отношениях важный момент. У вас какая – то тонкая, незримая связь с людьми, которая не заметна другим. Мистика может быть в отношениях. Отношения хорошие, если вы занимаетесь своей внутренней жизнью и подсознанием. Если нет, то трудностей и непонимания может быть много. Окружайте себя гаджетами и электроникой, новейшими технологиями – это помогает наладить отношения только вам известным образом как. Не бойтесь терять отношения и учитесь принимать перемены с радостью. Хотя ваши отношения приводят вас к трансформации мышления и сознания, а это значит, что и сами отношения могут быть такие же, теми, где часто сходятся и расходятся с одним и тем же человеком или просто меняют как перчатки.":"Сизда тушунарсиз қандай муносабатлар, лекин улар кармик юк олиб юриши аниқ. Эҳтимол, сизда маънавият ва энергетик амалиётлар, эзотерикага асосланган муносабатлар ҳам бор. Шунга қарамай, сизга кучни тиклаш ва ўзингизни тушуниш учун тез-тез ёлғиз бўлиш керак. Муносабатлардаги вазифангиз — худога интилиш. Одамлар билан муносабатлар уларни қандай қуришни алоҳида тушунмай, интуитив қурилади. Ҳар ҳолда улар жуда ғайриоддий ва ё ҳаддан ташқари консерватив, ё даврдан олдинда бўлиши мумкин. Сиз тез-тез шерикдан ёки ўзингиздан воз кечишингиз мумкин. Муносабатларингизда маънавият муҳим жиҳат. Сизда одамлар билан бошқаларга сезилмайдиган қандайдир нозик, кўринмас алоқа бор. Муносабатларда мистика бўлиши мумкин. Агар ички ҳаётингиз ва онг остингиз билан шуғулланаётган бўлсангиз, муносабатлар яхши. Агар йўқ бўлса, қийинчиликлар ва тушунмовчилик кўп бўлиши мумкин. Ўзингизни гаджетлар ва электроника, энг янги технологиялар билан ўранг — бу муносабатларни фақат сизга маълум тарзда созлашга ёрдам беради. Муносабатларни йўқотишдан қўрқманг ва ўзгаришларни қувонч билан қабул қилишни ўрганинг. Гарчи муносабатларингиз сизни фикрлаш ва онг трансформациясига олиб борса ҳам, бу эса муносабатларнинг ўзи ҳам шундай — бир инсон билан тез-тез қўшилиб-ажраладиган ёки шунчаки қўлқопдек алмаштириладиган бўлиши мумкинлигини англатади.","Сухие отношения или по расчёту, отношения, где каждый должен выполнять свою функцию. Вы трудоголик и вам важна работа, так что и отношения могут быть сродни рабочим, все только по делу, без особых проявлений чувств, несмотря на то, что у вас все же есть они глубоко внутри. Вы берете на себя ответственность за отношения и планируете все, что будет происходить, а если и не планируете то, все равно как по режиму, распорядку, по правилам живете в отношениях. Может быть сложно. Вы очень аскетичны и самостоятельны, а это не всем подходит. Вы можете окружать себя людьми с сильной разницей в возрасте, либо вы старше на много, либо люди, партнеры старше вас на много. Вы рассчитываете сразу на долгие и продолжительные отношения, вам не нужны не ваши люди, которые приходят и уходят, потому что вы очень осторожны и закрыты от чужих глаз. В отношениях происходит отдача кармических долгов либо через блага, либо через наказания. Работайте над собой, становитесь теплее к людям, учитесь проявлять любовь и доброту, считайтесь с мнением партнеров и не упрямьтесь. У вас может быть много страхов отношений и людей, примите их в себе и учитесь строить гармоничные отношения. Пессимизм и недоверие делают только хуже отношениям.":"Қуруқ муносабатлар ёки ҳисоб-китоб бўйича, ҳар ким ўз функциясини бажариши керак бўлган муносабатлар. Сиз ишга берилган инсонсиз ва сизга иш муҳим, шунинг учун муносабатлар ҳам ишга ўхшаш бўлиши мумкин, ичингизда чуқур ҳислар бўлишига қарамай, ҳаммаси фақат иш бўйича, ҳисларнинг алоҳида намоён бўлишисиз. Сиз муносабатлар учун масъулиятни оласиз ва бўладиган ҳамма нарсани режалаштирасиз, агар режалаштирмасангиз ҳам, барибир режим, тартиб, қоидалар бўйича муносабатларда яшайсиз. Қийин бўлиши мумкин. Сиз жуда зоҳид ва мустақилсиз, бу эса ҳаммага ҳам мос келмайди. Ёшда кучли фарқ бўлган одамлар билан ўралишингиз мумкин, ё сиз анча катта, ё одамлар, шериклар сиздан анча катта. Сиз дарҳол узоқ ва давомли муносабатларга умид қиласиз, сизга келиб-кетадиган ўзингизники бўлмаган одамлар керак эмас, чунки сиз жуда эҳтиёткор ва бегона кўзлардан ёпиқсиз. Муносабатларда кармик қарзларни ё неъматлар, ё жазолар орқали тўлаш юз беради. Ўз устингизда ишланг, одамларга илиқроқ бўлинг, муҳаббат ва меҳрибонлик кўрсатишни ўрганинг, шерикларнинг фикри билан ҳисоблашинг ва қайсарлик қилманг. Сизда муносабатлар ва одамлардан кўплаб қўрқувлар бўлиши мумкин, уларни ўзингизда қабул қилинг ва уйғун муносабатлар қуришни ўрганинг. Пессимизм ва ишончсизлик муносабатларни фақат ёмонлаштиради.","Могут быть плохие отношения, потому что есть стремление лидировать, подчинять себе, конкуренция, ссоры, размахивание руками, а то и предметами. Вам поможет спорт и тяжелые физические нагрузки, много секса. Вы абсолютно самостоятельный человек и самодостаточный, предприимчивый, а может даже конфликтный и импульсивный. Могут быть испанские страсти, но лучше всего вместе заниматься спортом, хобби с колюще – режущими предметами, экстремально отдыхать, тогда отношения будут не плохие. У женщины муж должен быть спортсмен или любой марсианской профессии, пожарник, стоматолог, хирург и тд, а мужчина":"Ёмон муносабатлар бўлиши мумкин, чунки етакчилик қилиш, ўзига бўйсундириш истаги, рақобат, жанжаллар, қўл силкитиш, ҳатто буюмлар билан ҳам бор. Сизга спорт ва оғир жисмоний юкламалар, кўп яқинлик ёрдам беради. Сиз мутлақо мустақил ва ўзига етарли, ишбилармон, эҳтимол ҳатто низоли ва импульсив инсонсиз. Испанча эҳтирослар бўлиши мумкин, лекин энг яхшиси бирга спорт, санчувчи-кесувчи буюмлар билан хобби билан шуғулланиш, экстремал дам олиш, шунда муносабатлар ёмон бўлмайди. Аёлнинг эри спортчи ёки ҳар қандай марс касбидаги — ўт ўчирувчи, стоматолог, жарроҳ ва ҳ.к. бўлиши керак, эркак эса","сам может работать по такой профессии и тогда тоже отношения будут хорошие, если марсианская энергия в жизни человека все-таки находит выход в профессии или занятии. При этом вы честный человек, который всегда защитит своих. Вы умеете достигать своих целей и от этого к вам тянутся люди. Умеете рисковать и выиграть.":"ўзи шундай касбда ишлаши мумкин ва шунда ҳам муносабатлар яхши бўлади, агар марс энергияси инсон ҳаётида барибир касб ёки машғулотда чиқиш йўлини топса. Бунда сиз доим ўзиникиларни ҳимоя қиладиган ҳалол инсонсиз. Сиз мақсадларингизга эришишни биласиз ва бундан сизга одамлар интилади. Таваккал қилиш ва ютишни биласиз.","У вас способность быть лидером, брать ответственность, взять под крыло большое количество людей, как например градоначальник, либо отец большого семейства, как царь. Талант самопроявления, внешне выглядеть хорошо, талант ставить яркие представления и талант актёрской игры на сцене, ораторские таланты, таланты петь, танцевать, проявлять себя, талант проявлять других, если к вам за этим обращаются, талант создавать личный бренд. Может быть независимость от мнения других либо наоборот тщеславие, гордыня и эгоизм. Вы отвечаете за свои слова. Имеете чувство собственного достоинства и способность руководить. Харизматичны, главное не зарывайте свои таланты, а отдавайте их людям, они не для нас, а для них. Можете четко ставить цель и идти к ней, ясно видите положение вещей. Решительность и яркость, легко можете добиться известности и помогать ее добиваться другим. Сила воли и желание иметь все самое лучшее. Вы как солнышко, светите всем, не разбивая на категории людей. Я самый!":"Сизда етакчи бўлиш, масъулиятни олиш, масалан, шаҳар бошлиғи ёки катта оила отаси, шоҳ каби кўп сонли одамларни қанотингиз остига олиш қобилияти бор. Ўзини намоён қилиш истеъдоди, ташқи томондан яхши кўриниш, ёрқин томошалар қўйиш истеъдоди ва саҳнада актёрлик ўйини истеъдоди, нотиқлик истеъдодлари, қўшиқ айтиш, рақс тушиш, ўзини намоён қилиш истеъдодлари, агар бунинг учун сизга мурожаат қилишса, бошқаларни намоён қилиш истеъдоди, шахсий бренд яратиш истеъдоди. Бошқаларнинг фикридан мустақиллик ёки аксинча шуҳратпарастлик, кибр ва худбинлик бўлиши мумкин. Сиз сўзларингиз учун жавоб берасиз. Ўз қадр-қиммати ҳисси ва раҳбарлик қилиш қобилиятига эгасиз. Харизматиксиз, асосийси истеъдодларингизни кўмманг, уларни одамларга беринг, улар биз учун эмас, улар учун. Аниқ мақсад қўйиб, унга боришингиз, ҳолатни равшан кўришингиз мумкин. Қатъият ва ёрқинлик, шуҳратга осон эришишингиз ва бошқаларга унга эришишда ёрдам беришингиз мумкин. Ирода кучи ва энг яхши ҳамма нарсага эга бўлиш истаги. Сиз қуёшдек, одамларни тоифаларга бўлмай, ҳаммага нур сочасиз. Мен энг...!","Вы умеете эмоционально поддержать человека, видите его душу, умеете быть вовлеченным в его жизнь и чувства. Вы отличный психолог и хорошо если работаете по этой профессии, умеете строить отношения с людьми, заботиться, давать поддержку, у вас талант быть женой и матерью, талант быть женщиной. Талант готовить еду, плавать, общаться с маленькими детьми. Вы романтик и умеете придумать так, чтобы все было для души. У вас развита интуиция, вы добры, сердечны, мягки, милосердны и чтите традиции. Таланты связаны с водой, бытом, детьми, психикой, интуицией и эмоциями.":"Сиз инсонни ҳиссий қўллаб-қувватлашни биласиз, унинг қалбини кўрасиз, унинг ҳаёти ва ҳисларига аралашган бўлишни биласиз. Сиз ажойиб психологсиз ва бу касбда ишласангиз яхши, одамлар билан муносабатлар қуришни, ғамхўрлик қилишни, қўллаб-қувватлаш беришни биласиз, сизда хотин ва она бўлиш истеъдоди, аёл бўлиш истеъдоди бор. Овқат пишириш, сузиш, кичик болалар билан мулоқот қилиш истеъдоди. Сиз романтиксиз ва ҳаммаси қалб учун бўладиган қилиб ўйлаб топишни биласиз. Сизда интуиция ривожланган, сиз меҳрибон, самимий, юмшоқ, раҳмдил ва анъаналарни эъзозлайсиз. Истеъдодлар сув, маишат, болалар, руҳият, интуиция ва ҳис-туйғулар билан боғлиқ.","Вы умеете давать советы, учить людей, быть наставником, учителем, путешественником, талант к изучению истории, иностранных культур и иностранных языков. Вы умеете делать глобальные проекты, ставить высокие цели, умеете зарабатывать авторитет и быть им, под вас могут придумывать профессию. Вы отличный духовный вождь, священник и богач. Вы умеете направлять людей на духовный путь и философски смотрите на мир. Ваше мировоззрение многие люди рады слышать, потому что в ваших талантах мудрость. Вы можете быть хорошим священником или работать в туризме, там где требуется постоянное узнавание нового и расширение восприятия и территорий. Вы оптимистичны, жизнерадостны, приветливы и имеете веселый характер. Вы умеете быть моральным лидером. Свободолюбивым, своенравным, независимым но образцом для подражания. Умеете идти по своему пути, не смотря на других.":"Сиз маслаҳатлар беришни, одамларни ўргатишни, устоз, ўқитувчи, саёҳатчи бўлишни биласиз, тарих, чет маданиятлар ва чет тилларини ўрганиш истеъдоди. Сиз глобал лойиҳалар қилишни, юксак мақсадлар қўйишни биласиз, обрў орттиришни ва обрў бўлишни биласиз, сиз учун касб ўйлаб топишлари мумкин. Сиз ажойиб маънавий раҳнамо, руҳоний ва бойсиз. Сиз одамларни маънавий йўлга йўналтиришни биласиз ва дунёга фалсафий қарайсиз. Дунёқарашингизни кўпчилик одамлар эшитишдан хурсанд, чунки истеъдодларингизда донолик бор. Сиз яхши руҳоний бўлишингиз ёки доим янгиликни билиш ва идрок ва ҳудудларни кенгайтириш талаб қилинадиган туризмда ишлашингиз мумкин. Сиз оптимистик, ҳаётсевар, хушмуомала ва қувноқ характерга эгасиз. Сиз ахлоқий етакчи бўлишни биласиз. Эркинликни севувчи, ўзбошимча, мустақил, лекин тақлид учун намуна. Бошқаларга қарамай, ўз йўлингиздан боришни биласиз.","У вас талант иллюзиониста, эзотерика, химика, шоу-бизнесмена, способность управлять толпами людей. Люди всегда под впечатлением от того, что вы говорите. Вы видите людей и ситуации насквозь и умеете направлять людей в верном направлении. Вы умеете создавать что-то искусственное, талант фармацевта, ученого, таланты связанные с каким-то токсичным веществами, талант видеть суть вещей в общем и целом. А также у вас предрасположенность находиться в обмане и обманывать самому, создавать так называемую иллюзию чего-либо. Умеете мечтать и много желать. Талант вносить либо полный хаос, либо порядок (зависит от вашего развития). Талант к криминалу, и любые негативные таланты. Способности магического, мистического характера.":"Сизда иллюзионист, эзотерик, кимёгар, шоу-бизнесмен истеъдоди, одамлар оломонини бошқариш қобилияти бор. Одамлар доим айтаётганингиздан таассурот остида. Сиз одамлар ва вазиятларни кўриб турасиз ва одамларни тўғри йўналишга йўналтиришни биласиз. Сиз нимадир сунъий яратишни биласиз, фармацевт, олим истеъдоди, қандайдир заҳарли моддалар билан боғлиқ истеъдодлар, нарсаларнинг моҳиятини умуман ва бутунлигича кўриш истеъдоди. Шунингдек сизда алдовда бўлиш ва ўзингиз алдаш, нимадирнинг иллюзиясини яратишга мойиллик бор. Орзу қилишни ва кўп исташни биласиз. Ё тўлиқ хаос, ё тартиб киритиш истеъдоди (ривожланишингизга боғлиқ). Жиноятга истеъдод ва ҳар қандай салбий истеъдодлар. Сеҳрли, мистик хусусиятдаги қобилиятлар.","Таланты в общении, к способности найти нужный контакт, в знакомствах, в торговле, в изучении чего-либо. Талант водить машину, работать с телефонами, авто, логистика и организация чего угодно. Талант анализировать большие объемы информации, создание карт, визиток, писательский талант, копирайтинг, писать статьи в журнал. Вы умеете договариваться с людьми, умеете быть легким на подъем и постоянно находиться в динамичном движении. Талант работника сетевого маркетинга, вы крутые с сетевики. Вы очень умны и сообразительны, остроумны, любознательны, находчивы, обладаете ловкостью рук и умеете заниматься несколькими делами одновременно. Свободны в своих высказываниях. Умеете склонить собеседника к своей точке зрения, убедить и переубедить его, вы превосходный собеседник. Умеете поддерживать беседу и рассказываете что-либо непревзойденно.":"Мулоқотда, керакли алоқани топиш қобилиятида, танишувларда, савдода, нимадир ўрганишда истеъдодлар. Машина ҳайдаш, телефонлар, авто билан ишлаш, логистика ва ҳар қандай нарсани ташкил этиш истеъдоди. Катта ҳажмдаги маълумотни таҳлил қилиш, карталар, визиткалар яратиш истеъдоди, ёзувчилик истеъдоди, копирайтинг, журналга мақолалар ёзиш. Сиз одамлар билан келишишни, енгил кўтариладиган бўлишни ва доим динамик ҳаракатда бўлишни биласиз. Тармоқли маркетинг ходими истеъдоди, сиз зўр тармоқчилардансиз. Сиз жуда ақлли ва зийрак, ўткир сўзли, қизиқувчан, топқир, қўл чаққонлигига эгасиз ва бир вақтнинг ўзида бир нечта иш билан шуғулланишни биласиз. Фикрларингизда эркинсиз. Суҳбатдошни ўз нуқтаи назарингизга оғдиришни, ишонтириш ва қайта ишонтиришни биласиз, сиз аъло суҳбатдошсиз. Суҳбатни давом эттиришни биласиз ва нимадир беқиёс ҳикоя қиласиз.","У вас творческие таланты, таланты связанные с чувством красоты и удовольствиями, с комфортом и праздником, с радостью. Художник, музыка, вокал, актерство, дизайн, визуал и тд. все что по Венере. Талант строить любовные отношения и заводить подруг. Талант гармонизировать пространство и вносить мир и справедливость в ситуации, вы очень добры и скорее всего от природы красивы. Вы спокойны, уравновешенны, настойчивы, упорны, терпеливы, стабильны, имеете выдержку, щедры, честолюбивы, хозяйственны и чувственны. Все это очень привлекает к вам людей и в особенности противоположный пол. Вы отлично разбираетесь в искусстве, рукоделии и умеете делать своими руками: лепка, шитье, вязание и тд. Любовь – ваш талант. Вы знаете цену себе и умеете ценить других.":"Сизда ижодий истеъдодлар, гўзаллик ҳисси ва лаззатлар, қулайлик ва байрам, қувонч билан боғлиқ истеъдодлар бор. Рассом, мусиқа, вокал, актёрлик, дизайн, визуал ва ҳ.к. Венера бўйича ҳамма нарса. Ишқий муносабатлар қуриш ва дугоналар орттириш истеъдоди. Маконни уйғунлаштириш ва вазиятларга тинчлик ва адолат киритиш истеъдоди, сиз жуда меҳрибонсиз ва эҳтимол табиатан чиройлисиз. Сиз хотиржам, мувозанатли, қатъиятли, тиришқоқ, сабрли, барқарор, бардошли, саховатли, шуҳратпараст, хўжаликчи ва ҳиссиётлисиз. Буларнинг барчаси сизга одамларни ва айниқса қарама-қарши жинсни жуда жалб қилади. Сиз санъат, қўл ишларини аъло тушунасиз ва ўз қўлингиз билан қилишни биласиз: ҳайкалтарошлик, тикиш, тўқиш ва ҳ.к. Муҳаббат — сизнинг истеъдодингиз. Сиз ўз қадрингизни биласиз ва бошқаларни қадрлашни биласиз.","У вас талант в духовности, сильный дух, сильная интуиция, таланты к эзотерике, астрологии, нумерологии, йоге, мистике и тд. Талант разбираться в гаджетах, компьютерах и программировании. Талант в отсечении частей тела (в медицине), в аскезе и отшельническом образе жизни. Талант шпиона и серого кардинала, хакер. Непонятные таланты для людей.":"Сизда маънавиятда истеъдод, кучли руҳ, кучли интуиция, эзотерика, астрология, нумерология, йога, мистика ва ҳ.к.га истеъдодлар бор. Гаджетлар, компьютерлар ва дастурлашни тушуниш истеъдоди. Тана қисмларини кесишда (тиббиётда), зоҳидлик ва зоҳидона ҳаёт тарзида истеъдод. Жосус ва кулранг кардинал, хакер истеъдоди. Одамлар учун тушунарсиз истеъдодлар.","У вас способность преодолевать любые сложности и любые испытания, вы способны упорно трудиться и быть очень выносливым. Вы способны выдержать любой удар судьбы, чтобы с вами не делали, у вас стальной внутренний стержень. Вы умеете руководить и устанавливать закон, соблюдать их и соблюдать режим дня и аскетичный образ жизни. Вы умеете ставить верные задачи и далекие цели, и их планомерно выполнять, либо направлять людей, как достичь поставленных высоких материальных целей. Вы пунктуальны, умеете планировать, рассчитывать, вы – хороший менеджер и у вас очень много терпения. вы умеете довести дело до конца и вести дела в долгую. Вы основательны, надежны, способна чётко следовать правилам, способны пахать без остановки, трудоголизм. Трудоспособность тут ключевое слово.":"Сизда ҳар қандай қийинчиликлар ва ҳар қандай синовларни енгиш қобилияти бор, сиз қатъият билан меҳнат қилишга ва жуда чидамли бўлишга қодирсиз. Сиз билан нима қилишмасин, тақдирнинг ҳар қандай зарбасига бардош беришга қодирсиз, сизда пўлат ички ўзак бор. Сиз раҳбарлик қилишни ва қонун ўрнатишни, уларга риоя қилишни ва кун тартиби ва зоҳидона ҳаёт тарзига амал қилишни биласиз. Сиз тўғри вазифалар ва узоқ мақсадлар қўйишни ва уларни режали бажаришни, ёки одамларни қўйилган юксак моддий мақсадларга қандай эришишга йўналтиришни биласиз. Сиз аниқсиз, режалаштириш, ҳисоблашни биласиз, сиз — яхши менежерсиз ва сизда жуда кўп сабр бор. Ишни охирига етказишни ва ишларни узоқ муддатга юритишни биласиз. Сиз пухта, ишончлисиз, қоидаларга аниқ амал қилишга, тўхтовсиз ишлашга қодирсиз, ишга берилиш. Иш қобилияти бу ерда калит сўз.","Спорт, умение защитить себя и слабых, физическая сила. Вы вкусно готовите мясо и все, что жарится, все что связано с огнём. У вас талант достигать целей во, что бы то ни стало. Вы энергичны, активны, лидируете, у вас очень много жизненной энергии. Вы способны везде, где опасно, рискованно, экстремально, а также в обращении с колюще-режущими предметами. Вы можете работать по Марсу, а это – хирурги, стоматологи, военные, полиция, пожарные, спортсмены, мотиваторы, антикризисные менеджеры и тд. У вас большой энтузиазм и сила. Вы благородны, честны, искренни, просты и уверены в себе. Обладаете храбростью, отвагой, мужеством, решительностью и бесстрашием. Вы инициативны и умеете пойти на риск и выиграть. Талант делать руками, энтузиазм, практичность, сексуальная энергия, хорошая логика и четкое видение ситуации, смелость, умение отвечать любовью на агрессию, умение конкурировать экологично, благородный воин":"Спорт, ўзини ва заифларни ҳимоя қила олиш, жисмоний куч. Сиз гўштни ва қовуриладиган, олов билан боғлиқ ҳамма нарсани мазали пиширасиз. Сизда ҳар қандай нархда мақсадларга эришиш истеъдоди бор. Сиз ғайратли, фаол, етакчилик қиласиз, сизда жуда кўп ҳаётий энергия бор. Сиз хавфли, таваккалли, экстремал бўлган ҳамма жойда, шунингдек санчувчи-кесувчи буюмлар билан муомалада қобилиятлисиз. Марс бўйича ишлашингиз мумкин, бу эса — жарроҳлар, стоматологлар, ҳарбийлар, полиция, ўт ўчирувчилар, спортчилар, мотиваторлар, инқирозга қарши менежерлар ва ҳ.к. Сизда катта иштиёқ ва куч бор. Сиз олижаноб, ҳалол, самимий, содда ва ўзингизга ишонгансиз. Мардлик, жасорат, ботирлик, қатъият ва қўрқмасликка эгасиз. Сиз ташаббускор ва таваккал қилиб, ютишни биласиз. Қўл билан қилиш истеъдоди, иштиёқ, амалийлик, жинсий энергия, яхши мантиқ ва вазиятни аниқ кўриш, жасорат, тажовузга муҳаббат билан жавоб бериш маҳорати, экологик рақобатлашиш маҳорати, олижаноб жангчи","Ваша способность быть проявленным, ярким, заметным, когда вы делаете то, что хотите искренне душой. Ваш сын, отец и муж приносят вам и радость и удачу. Лидирующее положение, когда вы в центре внимания или руководите чем-то, ваш личный бренд обречен на удачу. Вы сами удачливы, сами себя радуете. Удача приходит, когда вы смелы, имеете сильную волю и берете ответственность за свою жизнь и жизнь ваших подчиненных или тех, кто под вашим крылом, детей или всю семью. Ваша харизма приносит удачу, благородство, великодушие, щедрость, умение воодушевлять людей на подвиги. Золото приносит удачу, начальники и любые яркие личности. Работа по солнечным профессиям вас радует. Вера в Бога приносит удачу и радость, животные Львы или люди Львы по знаку зодиака.":"Чин қалбдан истаган нарсангизни қилганингизда намоён, ёрқин, кўзга ташланадиган бўлиш қобилиятингиз. Ўғлингиз, отангиз ва эрингиз сизга ҳам қувонч, ҳам омад келтиради. Етакчи мавқе, диққат марказида бўлганингизда ёки нимагадир раҳбарлик қилганингизда, шахсий брендингиз омадга маҳкум. Сиз ўзингиз омадлисиз, ўзингизни ўзингиз қувонтирасиз. Омад жасур бўлганингизда, кучли иродага эга бўлганингизда ва ҳаётингиз ва қўл остидагилар ёки қанотингиз остидагилар, фарзандлар ёки бутун оиланинг ҳаёти учун масъулиятни олганингизда келади. Харизмангиз омад, олижаноблик, мурувват, саховат, одамларни жасоратларга руҳлантириш маҳоратини келтиради. Олтин омад келтиради, бошлиқлар ва ҳар қандай ёрқин шахслар. Қуёш касблари бўйича иш сизни қувонтиради. Худога ишонч омад ва қувонч келтиради, Арслон ҳайвонлари ёки зодиак белгиси бўйича Арслон одамлар.","Ваша способность разбираться в людях, интуиция и чувствительность приносит удачу. Домашние кошки, готовка, бытовые дела, материнство и детство радуют. Лялечки, родственники, семья, статус жены, жена, мама, теща, любые женщины могут как радовать, так и приносить удачу или все вместе. Занятия на воде, семейная жизнь, бутылочка воды с собой, символика воды – приносит удачу. Познавание глубин души и подсознания, как своих, так и чужих приносит радость, возможность заботиться и ухаживать за кем-то, быть нужной – все это приносит радость и удачу. Символ Луны приносит удачу и жизнь по Лунному календарю. Раки по гороскопу – приносят радость и удачу.":"Одамларни тушуниш қобилиятингиз, интуиция ва сезгирлик омад келтиради. Уй мушуклари, овқат пишириш, маиший ишлар, оналик ва болалик қувонтиради. Чақалоқлар, қариндошлар, оила, хотин мақоми, хотин, она, қайнона, ҳар қандай аёллар ҳам қувонтириши, ҳам омад келтириши ёки ҳаммаси бирга бўлиши мумкин. Сувдаги машғулотлар, оилавий ҳаёт, ёнингиздаги сув шишаси, сув рамзлари — омад келтиради. Ўзингиз ва бошқаларнинг қалб ва онг ости чуқурликларини англаш қувонч келтиради, кимгадир ғамхўрлик қилиш ва қараш, керакли бўлиш имконияти — буларнинг барчаси қувонч ва омад келтиради. Ой рамзи омад келтиради ва Ой тақвими бўйича ҳаёт. Гороскоп бўйича Қисқичбақалар — қувонч ва омад келтиради.","Радости от исполнения желаний, от получения знания, от наставничества и обучения, от передачи знаний и от учительства. От экспертности и авторитета. Муж и дети приносят радость. Путешествия, высшее образование и сертификаты, дипломы. Возможность развиваться духовно и с кем-нибудь пофилософствовать. Удача приходит когда вы щедры, независимы и стремитесь вперед как стрела, обладаете честностью, уважением и преданностью. В спорах и судах, в юридических вопросах удача. Вера во что-то высокое радует вас и приносит удачу. Высшие силы вас любят и авторитеты тоже. Высокое социальное положение радует и приносит удачу. Ваши советы лучше слушать, часто они правдивы. Символ Юпитера или символика учительства и наставничества приносит удачу, символика путешествий тоже. Радует работа по Юпитерианским профессиям – туризм, языковед, путешественник, учитель, священник, духовный гуру и тд. Люди приносящие удачу и радость – Стрельцы и Рыбы со солнцу.":"Истакларни бажаришдан, билим олишдан, устозлик ва ўқитишдан, билим етказишдан ва ўқитувчиликдан қувончлар. Экспертлик ва обрўдан. Эр ва фарзандлар қувонч келтиради. Саёҳатлар, олий таълим ва сертификатлар, дипломлар. Маънавий ривожланиш ва кимдир билан фалсафа сўқиш имконияти. Омад саховатли, мустақил бўлганингизда ва ўқдек олдинга интилганингизда, ҳалоллик, ҳурмат ва садоқатга эга бўлганингизда келади. Баҳслар ва судларда, юридик масалаларда омад. Нимадир юксакка ишонч сизни қувонтиради ва омад келтиради. Олий кучлар сизни севади, обрўлар ҳам. Юқори ижтимоий мавқе қувонтиради ва омад келтиради. Маслаҳатларингизни тинглаган яхшироқ, улар кўпинча ҳақиқий. Юпитер рамзи ёки ўқитувчилик ва устозлик рамзлари омад келтиради, саёҳатлар рамзлари ҳам. Юпитер касблари бўйича иш қувонтиради — туризм, тилшунос, саёҳатчи, ўқитувчи, руҳоний, маънавий гуру ва ҳ.к. Омад ва қувонч келтирадиган одамлар — Қуёш бўйича Ўқотар ва Балиқлар.","Вы черпаете радость от чего-то иллюзорного, искусственного либо от возможности влиять на большое количество людей, от мечтаний, фокусов, шоу бизнеса, таблеток или токсичных веществ, в т.ч. алкоголя (это зависит от уровня сознания человека). Радость приносит эзотерика и магия, удачу приносит все хорошо распланированное и без хаотичное. Компьютеры и новые технологии. Чтобы была удача важно отказаться от жадности и ненасытности, и уметь определять свои истинные желания от навязанных. Удачу и радость приносит баланс духовного и материального. Хаос тоже может приносить и радость и удачу. Символика удачи эзотерическая.":"Сиз қувончни нимадир иллюзор, сунъий нарсадан ёки кўп сонли одамларга таъсир кўрсатиш имкониятидан, орзулардан, фокуслардан, шоу-бизнесдан, дорилар ёки заҳарли моддалардан, жумладан алкоголдан оласиз (бу инсоннинг онг даражасига боғлиқ). Қувонч эзотерика ва сеҳр келтиради, омадни яхши режалаштирилган ва тартибсизликсиз ҳамма нарса келтиради. Компьютерлар ва янги технологиялар. Омад бўлиши учун очкўзлик ва тўймасликдан воз кечиш ва ҳақиқий истакларингизни тиқиштирилганлардан ажрата билиш муҳим. Омад ва қувончни маънавий ва моддий мувозанати келтиради. Хаос ҳам қувонч ва омад келтириши мумкин. Омад рамзлари — эзотерик.","Через общение, свободу, поездки, знакомых, братьев и сестер, соседей, телефон, авто- мобили, дороги. Ваша легкость и контактность приносит вам удачу. Умные люди и умение заниматься одновременно многими делами сразу радуют. Удача приходит при отсутствии предрассудков, умение поддержать беседу и познакомиться, найти любой контакт и любую информацию. Радует обучение, чтение книг и журналов, общение в соц. сетях и переписки по телефону или письма. Удача в продажах, торговле, маркетинге и всех остальных занятиях Меркурия. Символика удачи – книги, куб, авто, дороги, общение, телефон символика Меркурия, Люди под знаком Близнецы и Дева.":"Мулоқот, эркинлик, сафарлар, танишлар, ака-ука ва опа-сингиллар, қўшнилар, телефон, автомобиллар, йўллар орқали. Енгиллигингиз ва киришимлилигингиз сизга омад келтиради. Ақлли одамлар ва бир вақтнинг ўзида кўплаб ишлар билан шуғуллана олиш қувонтиради. Омад хурофотлар йўқлигида, суҳбатни давом эттира олиш ва танишиш, ҳар қандай алоқа ва ҳар қандай маълумотни топа олишда келади. Ўқиш, китоблар ва журналлар ўқиш, ижтимоий тармоқларда мулоқот ва телефондаги ёзишмалар ёки хатлар қувонтиради. Сотувлар, савдо, маркетинг ва Меркурийнинг барча бошқа машғулотларида омад. Омад рамзлари — китоблар, куб, авто, йўллар, мулоқот, телефон, Меркурий рамзлари, Эгизаклар ва Парижатли белгиси остидаги одамлар.","Удачу приносит спокойствие, деньги, комфорт, все красивое, девушки, подруги и любовь. Влюбляйтесь и будете удачливы. Практичность и постоянство радуют, творчество и все творческие профессии и таланты приносят радость и удачу. Сладости радуют. Все радостное вам приносит удачу, все, что вам приносит удовольствие, а значит само состояние радости и наслаждения приносит удачу. Мир, гармония, добро и хорошие отношения со всеми людьми, драгоценности и украшения. Символика удачи – символ Венеры, зеркало, косметика, девушка, сердечко, символы денег. Люди приносящие радость и удачу – Телец и Весы по гороскопу.":"Омадни хотиржамлик, пул, қулайлик, барча чиройли нарсалар, қизлар, дугоналар ва муҳаббат келтиради. Севиб қолинг ва омадли бўласиз. Амалийлик ва доимийлик қувонтиради, ижод ва барча ижодий касблар ва истеъдодлар қувонч ва омад келтиради. Ширинликлар қувонтиради. Барча қувончли нарсалар сизга омад келтиради, сизга завқ келтирадиган ҳамма нарса, демак қувонч ва лаззат ҳолатининг ўзи омад келтиради. Тинчлик, уйғунлик, эзгулик ва барча одамлар билан яхши муносабатлар, қимматбаҳо тошлар ва безаклар. Омад рамзлари — Венера рамзи, ойна, косметика, қиз, юракча, пул рамзлари. Қувонч ва омад келтирадиган одамлар — гороскоп бўйича Бузоқ ва Тарози.","Гаджеты, программирование, новые технологии, эзотерика, как путь духовного развития, уединение и аскеза радуют и приносят удачу. Духовные практики, мистика, астрология и люди этих профессий приносят удачу. Вас эти занятия тоже радуют. Может быть людям непонятно, что вас радует. Мистические радости и удача. Перемены приносят удачу, когда вы осознанно уходите от консерватизма. Радует давать вещам вторую жизнь. Символика удачи – духовная.":"Гаджетлар, дастурлаш, янги технологиялар, маънавий ривожланиш йўли сифатида эзотерика, ёлғизлик ва зоҳидлик қувонтиради ва омад келтиради. Маънавий амалиётлар, мистика, астрология ва бу касблар одамлари омад келтиради. Бу машғулотлар сизни ҳам қувонтиради. Балки одамларга сизни нима қувонтириши тушунарсиз. Мистик қувончлар ва омад. Консерватизмдан онгли узоқлашганингизда ўзгаришлар омад келтиради. Нарсаларга иккинчи ҳаёт бериш қувонтиради. Омад рамзлари — маънавий.","Труд и планирование, режим дня и умение следовать законам, ответственность и начальники, тяжелая работа, хоть и тяжелая, но радует. Высшее образование, высокий социальный статус и самостоятельность, а также люди с такими качествами, старики и пенсионеры, высокопоставленные и государственные деятели приносят радость и удачу. Дедушки и бабушки, представители власти, закон и порядок. Осторожность, практичность, расчетливость, выдержка и самодисциплина – те самые нужные для удачи качества. Целеустремленность и упорство в достижении целей. Символика – коса, черный цвет, черный плащ, дедушки и бабушки, символы власти и вашей фирмы или работы. Профессии по Сатурну радуют, а люди Козероги и Водолеи приносят удачу.":"Меҳнат ва режалаштириш, кун тартиби ва қонунларга амал қила олиш, масъулият ва бошлиқлар, оғир иш, оғир бўлса ҳам, қувонтиради. Олий таълим, юқори ижтимоий мавқе ва мустақиллик, шунингдек шундай фазилатларга эга одамлар, қариялар ва пенсионерлар, юқори мансабдор ва давлат арбоблари қувонч ва омад келтиради. Бобо ва бувилар, ҳокимият вакиллари, қонун ва тартиб. Эҳтиёткорлик, амалийлик, ҳисоб-китоблилик, бардош ва ўзини интизомга солиш — омад учун керакли ўша фазилатлар. Мақсадга интилувчанлик ва мақсадларга эришишда қатъият. Рамзлар — ўроқ, қора ранг, қора плащ, бобо ва бувилар, ҳокимият ва фирмангиз ёки ишингиз рамзлари. Сатурн касблари қувонтиради, Тоғ эчкиси ва Қовға одамлари эса омад келтиради.","Получаете радость и удачу через спорт и достижение цели, через физическую активность и через инициативность, через стремление к цели, при мотивации и энтузиазме. Экстрим, опасности, огонь, колюще – режущие предметы тоже приносят радость и удачу. Военное дело, пожарники, мясники, готовка мяса, хирург – то, что приносит радость, а эти люди в вашей жизни еще могут принести и удачу. Хорошо работать по профессиям Марса, в т.ч перечисленным. Храбрость, смелость, отвага, способность быстро предпринимать решительные действия, лидерские качества и самостоятельность, самодостаточность. Символика удачи – мечи, огонь, спорт, скорость, опасность. Люди Овен и Скорпион по гороскопу радуют и приносят удачу.":"Спорт ва мақсадга эришиш, жисмоний фаоллик ва ташаббускорлик, мақсадга интилиш орқали, мотивация ва иштиёқда қувонч ва омад оласиз. Экстрим, хавфлар, олов, санчувчи-кесувчи буюмлар ҳам қувонч ва омад келтиради. Ҳарбий иш, ўт ўчирувчилар, қассоблар, гўшт пишириш, жарроҳ — қувонч келтирадиган нарсалар, бу одамлар эса ҳаётингизда яна омад ҳам келтириши мумкин. Марс касблари, жумладан санаб ўтилганлар бўйича ишлаш яхши. Мардлик, жасорат, ботирлик, тез қатъий ҳаракатларни амалга ошириш қобилияти, етакчилик фазилатлари ва мустақиллик, ўзига етарлилик. Омад рамзлари — қиличлар, олов, спорт, тезлик, хавф. Гороскоп бўйича Ҳамал ва Чаён одамлари қувонтиради ва омад келтиради.","Если ноль, то можно было бы сказать, что нет никаких задач, но это не так. Вам, наоборот, нужно нарабатывать, самому выбирать какие-то задачи, причем желательно делать позитивное, чтобы получать потом позитивную карму. Также возможна задача преодолевать трудности, не прожить жизнь зря. Ноль – это взращивать в себе все чего не хватает, развивать себя, развивать все направления в себе. Изначально вам не понятно, что нужно делать. Нужно осознанно искать себя, развивать себя во всех направлениях, нужен учитель, который уже добился, того результата который хотите вы.":"Агар ноль бўлса, ҳеч қандай вазифа йўқ дейиш мумкин эди, лекин бундай эмас. Сизга, аксинча, ишлаб чиқиш, қандайдир вазифаларни ўзингиз танлаш керак, бунда кейин ижобий карма олиш учун ижобий нарса қилган маъқул. Шунингдек қийинчиликларни енгиш, ҳаётни беҳуда яшамаслик вазифаси бўлиши мумкин. Ноль — бу ўзингизда етишмаётган ҳамма нарсани ўстириш, ўзингизни ривожлантириш, ўзингиздаги барча йўналишларни ривожлантириш. Дастлаб сизга нима қилиш кераклиги тушунарсиз. Онгли равишда ўзингизни излаш, ўзингизни барча йўналишларда ривожлантириш керак, сиз истаган натижага аллақачон эришган устоз керак.","Нужно работать над собой, быть ответственным, работать над своим эгоизмом, гордыней, учиться быть смелым и решительным, работать над личностным ростом и стать яркой личностью, создать свой личный бренд, быть ярким, уметь проявиться, стать лидером своей жизни, стать лидером везде, где вы находитесь. Могут быть кармические уроки, связанные с отцом, с начальством, с ребенком мальчиком.":"Ўз устингизда ишлаш, масъулиятли бўлиш, худбинлигингиз, кибрингиз устида ишлаш, жасур ва қатъиятли бўлишни ўрганиш, шахсий ўсиш устида ишлаш ва ёрқин шахс бўлиш, шахсий брендингизни яратиш, ёрқин бўлиш, намоён бўла олиш, ҳаётингиз етакчиси бўлиш, қаерда бўлсангиз ҳам етакчи бўлиш керак. Ота, бошлиқлар, ўғил бола билан боғлиқ кармик сабоқлар бўлиши мумкин.","Умейте держать слово, справляться с гневом, не унывайте, не ленитесь, перестаньте наслаждаться от страданий других людей, уберите враждебность к миру, высокомерие и неуверенность. Уважайте мужчин, отца, мужа, начальника. Проявляйте большую активность в достижении целей, обретите любовь к себе и чувство собственного достоинства внутри, а не напоказ. Работайте над искренностью, уверенностью, жизнерадостностью, харизмой и учитесь быть благодарным за все, что имеете и хотите получить. Проработайте эгоизм, либо он нездоровый, либо его нет. Ваша главная задача – вы сами.":"Сўзда туришни, ғазаб билан уддалашни билинг, тушкунликка тушманг, дангасалик қилманг, бошқа одамларнинг азобларидан лаззатланишни тўхтатинг, дунёга душманлик, кибр ва ишончсизликни олиб ташланг. Эркаклар, ота, эр, бошлиқни ҳурмат қилинг. Мақсадларга эришишда катта фаоллик кўрсатинг, ўзингизга муҳаббат ва ўз қадр-қиммати ҳиссини кўз-кўз учун эмас, ичкарида топинг. Самимийлик, ишонч, ҳаётсеварлик, харизма устида ишланг ва бор ва олишни истаган ҳамма нарсангиз учун миннатдор бўлишни ўрганинг. Худбинликни ишлаб чиқинг, ё у носоғлом, ё у йўқ. Сизнинг асосий вазифангиз — ўзингиз.","Взять под контроль свое эго, избавиться от уязвимости эго и научиться жить так, чтобы вас не задевали, научиться жить так, чтобы ваше эго не задевали вообще, быть прозрачным, чтобы оно не причиняло вам страданий. Умейте спокойно слушать критику в свой адрес и делать выводы. В жизни не всегда бывает «как хочется», но при должном взятии ответственности на себя, большая часть желаемого будет получена вами. Найдите себя и все свои таланты, выражайте их. Отдавайте другим то, что у вас в избытке без ожидания награды. На этом пути помогут духовные практики и узнавание себя через все возможные методики самопознания. Отделитесь от сознания массы и станьте личностью, для этого создавайте все свое, а не копируйте. Будьте индивидуалистом. Станьте самодостаточным, не ожидайте одобрения ваших поступков и действий. Будьте единственным, кто может определить насколько вы супер или нет. Идите по пути самопознания и саморазвития. Раскройте таланты и поймите для себя зачем же вы родились на свет. Все ответы внутри вас. Ваша сильная сторона – умение находиться в одиночестве и исследовать себя.":"Эгонгизни назоратга олиш, эгонинг заифлигидан қутулиш ва сизга тегмайдиган қилиб яшашни ўрганиш, эгонгизга умуман тегмайдиган қилиб яшашни ўрганиш, у сизга азоб бермаслиги учун шаффоф бўлиш. Ўз манзилингизга танқидни хотиржам тинглашни ва хулоса чиқаришни билинг. Ҳаётда доим ҳам «истагандек» бўлмайди, лекин масъулиятни лозим даражада ўз зиммангизга олганда, истаганингизнинг катта қисмини оласиз. Ўзингизни ва барча истеъдодларингизни топинг, уларни ифода этинг. Бошқаларга ортиқча бўлган нарсангизни мукофот кутмай беринг. Бу йўлда маънавий амалиётлар ва ўзини англашнинг барча мумкин бўлган усуллари орқали ўзини билиш ёрдам беради. Омма онгидан ажралинг ва шахс бўлинг, бунинг учун нусха кўчирмай, ҳаммасини ўзингизникини яратинг. Индивидуалист бўлинг. Ўзига етарли бўлинг, қилмишлар ва ҳаракатларингизнинг маъқулланишини кутманг. Сиз қанчалик супер эканингизни ёки йўқлигини аниқлай оладиган ягона инсон бўлинг. Ўзини англаш ва ўз-ўзини ривожлантириш йўлидан боринг. Истеъдодларни очинг ва ўзингиз учун дунёга нима учун туғилганингизни тушунинг. Барча жавоблар ичингизда. Сизнинг кучли томонингиз — ёлғизликда бўла олиш ва ўзингизни тадқиқ қилиш.","У вас задача заботиться, учиться заботиться, быть семьянином, учиться материнству, изучать психологию, понимать психику людей, понимать женщин, понимать себя и понимать всех и вся, каждое живое и неживое существо, понять что вы хотите, быть «матерью» всему, уметь делать правильный выбор, побороть нерешительность и прислушиваться к интуиции, когда делаешь выбор. Слушать сердце. чувствовать, вместо того, чтобы думать. Учиться взаимодействовать с людьми, принимать эмоции и проявлять эмоции, учиться партнерству, вступать в отношения, быть женой, учиться быть семьёй. Прекратите быть истеричным. Не теряйте индивидуальности, подстраиваясь под людей, учитесь говорить «нет». Понять с кем вы хотите быть, для того, чтобы не запутаться в жизни еще сильнее. Научитесь быть самодостаточным и не зависеть от других. Перестаньте сомневаться и начните действовать. Здесь тоже важно не запутаться в вариантах. Принимайте решения и реализовывайте их. Научитесь находиться наедине с самим собой, хоть вам и нужно внимание с самим собой тоже надо находиться, чтобы разобраться в себе и успокоиться. Не изменяйте партнеру, даже в мыслях. В отношениях вы часто делаете то, что сами хотели бы скрыть от партнера, поэтому ваши мысли вылезут наружу очень быстро.":"Сизда вазифа — ғамхўрлик қилиш, ғамхўрлик қилишни ўрганиш, оилапарвар бўлиш, оналикни ўрганиш, психологияни ўрганиш, одамлар руҳиятини тушуниш, аёлларни тушуниш, ўзини тушуниш ва ҳамма ва ҳамма нарсани, ҳар бир тирик ва жонсиз мавжудотни тушуниш, нимани истаётганингизни тушуниш, ҳамма нарсага «она» бўлиш, тўғри танлов қила олиш, қатъиятсизликни енгиш ва танлов қилганда интуицияга қулоқ солиш. Юракни тинглаш. Ўйлаш ўрнига ҳис қилиш. Одамлар билан ўзаро таъсирни ўрганиш, ҳис-туйғуларни қабул қилиш ва ҳис-туйғуларни намоён қилиш, шерикликни ўрганиш, муносабатларга кириш, хотин бўлиш, оила бўлишни ўрганиш. Жазавали бўлишни тўхтатинг. Одамларга мослашиб, индивидуалликни йўқотманг, «йўқ» дейишни ўрганинг. Ҳаётда янада кўпроқ чалкашиб кетмаслик учун ким билан бўлишни истаётганингизни тушуниш. Ўзига етарли бўлишни ва бошқаларга боғлиқ бўлмасликни ўрганинг. Шубҳаланишни тўхтатинг ва ҳаракат қила бошланг. Бу ерда ҳам вариантларда чалкашиб кетмаслик муҳим. Қарорлар қабул қилинг ва уларни амалга оширинг. Ўзингиз билан ёлғиз бўлишни ўрганинг, гарчи сизга эътибор керак бўлса ҳам, ўзингизни тушуниш ва тинчланиш учун ўзингиз билан ҳам бўлиш керак. Шерикка, ҳатто фикрларда ҳам хиёнат қилманг. Муносабатларда сиз кўпинча шерикдан ўзингиз яширгингиз келадиган нарсани қиласиз, шунинг учун фикрларингиз жуда тез ташқарига чиқади.","Обучиться быть удовлетворенным вне зависимости от внешних условий. Неуправляемые эмоции научитесь контролировать. Успокойте свой ум, чтобы беспокойство не мешало вам понимать свои задачи в жизни, действовать. Побороть ненависть к матерям и детям, выработать уважительное отношение. Избавьтесь от мнительности, страхов, фобий и избегайте затяжных депрессий. Научитесь жить без вредных привычек.":"Ташқи шароитлардан қатъи назар қаноатли бўлишни ўрганиш. Бошқарилмайдиган ҳис-туйғуларни назорат қилишни ўрганинг. Хавотир ҳаётдаги вазифаларингизни тушуниш, ҳаракат қилишга халақит бермаслиги учун ақлингизни тинчлантиринг. Оналар ва болаларга нафратни енгиш, ҳурматли муносабатни ишлаб чиқиш. Шубҳаланувчанлик, қўрқувлар, фобиялардан қутулинг ва узоқ депрессиялардан сақланинг. Зарарли одатларсиз яшашни ўрганинг.","Вам нужно развивать мудрость, щедрость, стать наставником для других, учиться зарабатывать деньги и сохранять их. Нужно растить в себе мудреца и научиться давать правильные советы. Быть щедрым на знание и на благотворительность. Путешествуйте и расширяйте границы сознания и территории. Изучайте историю и культуру. Станьте покровителем или спонсором. Изучайте иностранные языки и научитесь принимать чужие точки зрения. Вырабатывайте собственную картину мира и мировоззрение. Ваши задачи так или иначе связаны с авторитетностью, высоким социальным статусом и образованностью. Занимайтесь исследованиями, формируйте философский взгляд на мир, передавайте знания. Избавьтесь от разрушительных и насильственных идеологий, перестаньте осуждать людей, не следуйте правилам фанатично, уберите излишнюю принципиальность. Вырабатывайте честность и искренность. Обретите более 16 любимых занятий, можно их периодически делать делами жизни. Научиться меньше говорить и больше действовать. Вы философы, склонные рассуждать, что было бы если… Тратьте силы на реальные дела, можно параллельно с размышлениями. Работайте над собственным эго. Вас могут называть эгоистичным и самоуверенным, для вас это неплохо, но не всегда хорошо другим. Вы сами эксперт в своем деле, но когда вы приходите за знаниями к другому учителю, вам стоит уметь принять тот факт, что этот человек знает что-то больше вас. Учитесь быть терпеливым, тк все приходит со временем и во все нужно вкладывать энергию. Юпитер помогает тем, кто идет по истинному пути и если вы занимаетесь противозаконными или неправильными со стороны вселенских законов делами, за это приходит немедленное наказание на верный путь. Занимайтесь духовным развитием и развивайте веру в высшее, тк у троек бывает такое, что обладая многими знаниями вы начинаете замечать противоречия в системах и перестаете верить во что бы то ни было. Если веры нет вам придется на себе испытать те события, которые покажут что Высшее существует. Лучше до этого не доводить. Передавайте свои знания, ведь вы так много учитесь всю жизнь, используйте свой педагогический дар на благо себе и других.":"Сизга донолик, саховатни ривожлантириш, бошқалар учун устоз бўлиш, пул топиш ва уни сақлашни ўрганиш керак. Ўзингизда донишмандни ўстириш ва тўғри маслаҳатлар беришни ўрганиш керак. Билим ва хайрияга саховатли бўлиш. Саёҳат қилинг ва онг ва ҳудуд чегараларини кенгайтиринг. Тарих ва маданиятни ўрганинг. Ҳомий ёки спонсор бўлинг. Чет тилларини ўрганинг ва бировнинг нуқтаи назарини қабул қилишни ўрганинг. Ўз дунё манзарангиз ва дунёқарашингизни ишлаб чиқинг. Вазифаларингиз у ёки бу тарзда обрўлилик, юқори ижтимоий мавқе ва билимдонлик билан боғлиқ. Тадқиқотлар билан шуғулланинг, дунёга фалсафий қарашни шакллантиринг, билим етказинг. Вайронкор ва зўравон мафкуралардан қутулинг, одамларни қоралашни тўхтатинг, қоидаларга фанатик эргашманг, ортиқча принципиалликни олиб ташланг. Ҳалоллик ва самимийликни ишлаб чиқинг. 16 дан ортиқ севимли машғулот топинг, уларни вақти-вақти билан ҳаёт ишига айлантириш мумкин. Камроқ гапириш ва кўпроқ ҳаракат қилишни ўрганиш. Сиз агар... нима бўлар эди деб мулоҳаза юритишга мойил файласуфлар. Кучни ҳақиқий ишларга сарфланг, мулоҳазалар билан параллел ҳам мумкин. Ўз эгонгиз устида ишланг. Сизни худбин ва ўзига ишонган деб аташлари мумкин, сиз учун бу ёмон эмас, лекин бошқаларга доим ҳам яхши эмас. Сиз ўзингиз ишингизда экспертсиз, лекин бошқа ўқитувчига билим учун келганингизда, бу инсон сиздан кўпроқ нимадир билиш фактини қабул қила билишингиз керак. Сабрли бўлишни ўрганинг, чунки ҳамма нарса вақт билан келади ва ҳамма нарсага энергия киритиш керак. Юпитер ҳақиқий йўлдан борганларга ёрдам беради ва агар сиз коинот қонунлари нуқтаи назаридан ноқонуний ёки нотўғри ишлар билан шуғулланаётган бўлсангиз, бунинг учун тўғри йўлга дарҳол жазо келади. Маънавий ривожланиш билан шуғулланинг ва олийга ишончни ривожлантиринг, чунки учликларда шундай бўладики, кўп билимга эга бўлиб, тизимлардаги зиддиятларни пайқай бошлайсиз ва ҳеч нарсага ишонмай қўясиз. Агар ишонч бўлмаса, Олий мавжуд эканини кўрсатадиган воқеаларни ўзингизда синаб кўришингизга тўғри келади. Бунга олиб келмаган яхшироқ. Билимларингизни етказинг, ахир бутун ҳаёт шунча кўп ўқийсиз, педагогик иқтидорингиздан ўзингиз ва бошқалар фойдасига фойдаланинг.","Ваша задача избавляться от иллюзий, контролировать время, перестать обманывать, перестать тратить время зря, научиться различать свои истинные желания от навязанных, научиться управлять толпой и перестать употреблять токсичные препараты. Развивать осознанность, отказаться от постоянного просмотра сериалов и всего бесполезного, от того, что нельзя применить в жизни на практике. Развивать осознанность с помощью духовных практик. Научиться держать вещи и дом в порядке. Откажитесь от бардака, хаоса, грязи. Избавляйтесь от зависимостей, вредных привычек. Занимайтесь регулярными медитациями, идите в страхи и растите над собой. Перестаньте манипулировать людьми и портить им психику, и себе в том числе. Научитесь читать между строк, стремитесь видеть суть всего сквозь обман и иллюзии. Приложите все усилия, чтобы жить на природе, жить естественно, питаться натурально. Откажитесь от искусственного, токсичного. Наводите порядок и чистоту, соблюдайте, ложитесь спать до 22:00. Перестаньте оскорблять, грубить и наслаждаться дестроем насилием. Ваша задача духовно развиваться, т.к среди 4-ок часто бывают прагматики, которые верят в фарму, но не верят в Высшее. Задумайтесь и изучите законы кармы. Научитесь понимать себя и не усложнять себе жизнь там, где у вас есть контроль над ситуацией. Умейте управлять своими мыслями, тогда вы увидите реальность такой какая она есть, без иллюзий. У вас в голове слишком много мыслей, прислушивайтесь к интуиции и делайте медитации для успокоения ума. Страхи у вас в большинстве своем надуманные и вам нужно научиться от них избавляться. Несмотря на то, что страхи нас защищают от чего-то, большинство из них уже в прошлом и мешают двигаться вперед. От страхов вы можете уходить в иллюзии и употребление токсичных веществ. Выбирайте всегда верный путь на благо себе и другим и отказывайтесь от того пути, где вред будет хотя бы кому – то. Ваш урок – во благо использовать свои навыки, таланты и умения. Другая ваша задача – быть благополучным, если вы в иллюзиях или в страхах, то материальное благополучие становится вашей кармической задачей.":"Сизнинг вазифангиз иллюзиялардан қутулиш, вақтни назорат қилиш, алдашни тўхтатиш, вақтни беҳуда сарфлашни тўхтатиш, ҳақиқий истакларингизни тиқиштирилганлардан фарқлашни ўрганиш, оломонни бошқаришни ўрганиш ва заҳарли препаратлар истеъмол қилишни тўхтатиш. Онглиликни ривожлантириш, сериалларни ва барча фойдасиз, ҳаётда амалда қўллаб бўлмайдиган нарсаларни доимий кўришдан воз кечиш. Маънавий амалиётлар ёрдамида онглиликни ривожлантириш. Нарсалар ва уйни тартибда сақлашни ўрганиш. Тартибсизлик, хаос, ифлосликдан воз кечинг. Қарамликлар, зарарли одатлардан қутулинг. Мунтазам медитациялар билан шуғулланинг, қўрқувларга боринг ва ўзингиздан юқорига ўсинг. Одамларни манипуляция қилиш ва уларнинг, шу жумладан ўзингизнинг ҳам руҳиятини бузишни тўхтатинг. Сатрлар орасини ўқишни ўрганинг, алдов ва иллюзиялар орқали ҳамма нарсанинг моҳиятини кўришга интилинг. Табиатда яшаш, табиий яшаш, табиий овқатланиш учун барча саъй-ҳаракатларни қилинг. Сунъий, заҳарлидан воз кечинг. Тартиб ва тозаликни ўрнатинг, риоя қилинг, 22:00 гача ухланг. Ҳақорат қилиш, қўполлик қилиш ва вайронагарчилик, зўравонликдан лаззатланишни тўхтатинг. Сизнинг вазифангиз маънавий ривожланиш, чунки 4 лар орасида кўпинча фармага ишонадиган, лекин Олийга ишонмайдиган прагматиклар бўлади. Ўйланг ва карма қонунларини ўрганинг. Ўзингизни тушунишни ва вазият устидан назоратингиз бўлган жойда ҳаётингизни мураккаблаштирмасликни ўрганинг. Фикрларингизни бошқаришни билинг, шунда ҳақиқатни иллюзияларсиз, қандай бўлса шундайлигича кўрасиз. Бошингизда жуда кўп фикрлар бор, интуицияга қулоқ солинг ва ақлни тинчлантириш учун медитациялар қилинг. Қўрқувларингиз кўпчилиги ўйлаб топилган ва сизга улардан қутулишни ўрганиш керак. Қўрқувлар бизни нимадандир ҳимоя қилишига қарамай, уларнинг кўпчилиги аллақачон ўтмишда ва олдинга ҳаракатланишга халақит беради. Қўрқувлардан иллюзияларга ва заҳарли моддалар истеъмолига кетишингиз мумкин. Доим ўзингиз ва бошқалар фойдасига тўғри йўлни танланг ва ҳеч бўлмаганда кимгадир зарар бўладиган йўлдан воз кечинг. Сизнинг сабоғингиз — кўникмалар, истеъдодлар ва маҳоратларингиздан яхшилик учун фойдаланиш. Бошқа вазифангиз — фаровон бўлиш, агар иллюзияларда ёки қўрқувларда бўлсангиз, моддий фаровонлик сизнинг кармик вазифангизга айланади.","Ваша задача изучать языки, путешествовать, учиться договариваться, контактировать, общаться, знакомиться, писать, сочинять, логически разбирать, придумывать и анализировать. Нужно развивать интеллект, учиться рациональности. Быть легким на подъем, давать свободу людям и самому быть свободным, заводите больше знакомств. Перемещайтесь, переключайтесь, увлекайтесь многим, находитесь в движении, в динамике. Откажитесь от хаоса, бестолковой активности ума и тела, или же от вялости и апатичности. Поставьте себе цель жизни, увидьте картину жизни целиком и определите способы достижения этой цели. Изучайте знания глубоко и применяйте их на практике. Учитесь на чужих ошибках, умейте выслушать и слушать собеседника. Развивайте чувство юмора. Принимайте других такими какие они есть, воспитайте в себе добрый нрав. Учитесь концентрации внимания, чтобы в делах не было расфокуса, чтобы вы не распылялись и умели заканчивать свои дела. Если результата нет, то значит есть расфокус и нужно сконцентрироваться на 1,2,3 делах и заканчивать их. Вы так разбрасываетесь, потому что не хотите углубляться, но иногда для результата это необходимо. Если вы не углубляетесь, то проблемы становятся еще глубже хоть в делах, хоть в отношениях. Разберитесь в себе и в том, что происходит и внесите ясность во все процессы и всем участникам. Приобретайте высшие знания, когда-то они вас вытянут из запутанной вами же жизни. Развивайте свои таланты, у вас их множество, но вы их не цените. С ними вы достигнете больших высот, чем без них, это вам покажет время, но может быть уже поздно.":"Сизнинг вазифангиз тилларни ўрганиш, саёҳат қилиш, келишишни, алоқа қилишни, мулоқот қилишни, танишишни, ёзишни, ижод қилишни, мантиқий таҳлил қилишни, ўйлаб топишни ва таҳлил қилишни ўрганиш. Интеллектни ривожлантириш, рационалликни ўрганиш керак. Енгил кўтариладиган бўлиш, одамларга эркинлик бериш ва ўзингиз эркин бўлиш, кўпроқ танишувлар орттиринг. Ҳаракатланинг, алмашинг, кўп нарсага берилинг, ҳаракатда, динамикада бўлинг. Хаос, ақл ва тананинг маъносиз фаоллигидан, ёки лоқайдлик ва бефарқликдан воз кечинг. Ўзингизга ҳаёт мақсадини қўйинг, ҳаёт манзарасини бутунлигича кўринг ва бу мақсадга эришиш усулларини аниқланг. Билимларни чуқур ўрганинг ва амалда қўлланг. Бировнинг хатоларидан ўрганинг, суҳбатдошни охиригача тинглаш ва тинглашни билинг. Юмор ҳиссини ривожлантиринг. Бошқаларни қандай бўлса шундайлигича қабул қилинг, ўзингизда меҳрибон феълни тарбияланг. Ишларда диққатни йўқотмаслик, тарқалмаслик ва ишларингизни тугата олиш учун эътиборни жамлашни ўрганинг. Агар натижа бўлмаса, демак диққат тарқоқ ва 1, 2, 3 ишга эътибор қаратиш ва уларни тугатиш керак. Сиз чуқурлашишни истамаганингиз учун шундай сочиласиз, лекин баъзан натижа учун бу зарур. Агар чуқурлашмасангиз, муаммолар ишларда ҳам, муносабатларда ҳам янада чуқурлашади. Ўзингизни ва нима бўлаётганини тушуниб олинг ва барча жараёнларга ва барча иштирокчиларга аниқлик киритинг. Олий билимларни орттиринг, қачондир улар сизни ўзингиз чалкаштирган ҳаётдан тортиб чиқаради. Истеъдодларингизни ривожлантиринг, сизда улар кўп, лекин сиз уларни қадрламайсиз. Улар билан улардан кўра катта чўққиларга эришасиз, буни вақт кўрсатади, лекин эҳтимол кеч бўлади.","Ваша задача развить свои творческие навыки, развивать свои таланты. Научитесь приме- нять свои таланты на практике, создавать что-то красивое, создавать что-то восхитительное, уметь благодарить и научиться благодарности. Быть щедрым, без того чтобы быть жадным. Научитесь быть гармоничным, стремится гармонии, гармонизировать пространство вокруг, украшать всё вокруг и себя. Общайтесь с девушками, с подругами, обзаведитесь подругами, раскрывайте женственность (для девушек). Стройте гармоничные отношения с противоположным полом. Развивайте чувственный аспект своей жизни, следите за своей внешностью и заботьтесь о своей женственности (для девушек), заботьтесь о девушках (для мужчин). Сохраняйте целомудрие и умейте контролировать свои чувства. Занимайтесь финансовой сферой, деньгами, научитесь зарабатывать. Научитесь обустраивать свою жизнь в комфорте и удовлетворяйте свои желания, доставляйте удовольствие себе и другим. Справляйтесь с искушениями, вас так часто испытывают на это, но здесь кроется важный урок – соблюдайте вселенские законы, духовно развивайтесь. Проявляйте творчество на которое вы способны, проявляйте себя, если не будете, то это приводит к тому, что вы становитесь удобны всем кроме себя и можете впадать в разного рода зависимости. Избавляйтесь от них тем, что вы сделаете то, о чем много лет мечтали. и возможно это будет нужно миллионам людей. Научитесь себя содержать и быть независимым, даже если вы привыкли, что вас обеспечивают всем. Практичность в жизни поможет вам подстелить соломки на трудные времена. Занимайтесь самопознанием и духовным развитием, если хотите найти себя в жизни. Ни словом, ни мыслью, ни делом не вредите никому, в том числе и себе, помогайте тем с кем живете и кому нужна ваша помощь, относитесь с уважением к людям. Найдите и проявите свой креативный талант и однажды он будет приносить вам неплохой доход.":"Сизнинг вазифангиз ижодий кўникмаларингизни ривожлантириш, истеъдодларингизни ривожлантириш. Истеъдодларингизни амалда қўллашни, чиройли нарса яратишни, ажойиб нарса яратишни, миннатдорлик билдиришни ва миннатдорликни ўрганинг. Очкўз бўлмай, саховатли бўлиш. Уйғун бўлишни, уйғунликка интилишни, атрофдаги маконни уйғунлаштиришни, атрофдаги ҳамма нарсани ва ўзингизни безатишни ўрганинг. Қизлар, дугоналар билан мулоқот қилинг, дугоналар орттиринг, аёлликни очинг (қизлар учун). Қарама-қарши жинс билан уйғун муносабатлар қуринг. Ҳаётингизнинг ҳиссий жиҳатини ривожлантиринг, ташқи кўринишингизни кузатинг ва аёллигингизга ғамхўрлик қилинг (қизлар учун), қизларга ғамхўрлик қилинг (эркаклар учун). Иффатни сақланг ва ҳисларингизни назорат қилишни билинг. Молиявий соҳа, пул билан шуғулланинг, пул топишни ўрганинг. Ҳаётингизни қулайликда жиҳозлашни ўрганинг ва истакларингизни қондиринг, ўзингиз ва бошқаларга завқ беринг. Васвасалар билан уддаланг, сизни бунга жуда тез-тез синашади, лекин бу ерда муҳим сабоқ яширинган — коинот қонунларига риоя қилинг, маънавий ривожланинг. Қобилиятли бўлган ижодингизни намоён қилинг, ўзингизни намоён қилинг, агар қилмасангиз, бу ўзингиздан бошқа ҳамма учун қулай бўлиб қолишингизга олиб келади ва турли қарамликларга тушишингиз мумкин. Улардан йиллар давомида орзу қилган нарсангизни қилиш орқали қутулинг, эҳтимол бу миллионлаб одамларга керак бўлади. Сизни ҳамма нарса билан таъминлашларига одатланган бўлсангиз ҳам, ўзингизни таъминлашни ва мустақил бўлишни ўрганинг. Ҳаётдаги амалийлик оғир кунлар учун ғамлаб қўйишга ёрдам беради. Ҳаётда ўзингизни топишни истасангиз, ўзини англаш ва маънавий ривожланиш билан шуғулланинг. На сўз, на фикр, на иш билан ҳеч кимга, жумладан ўзингизга зарар етказманг, бирга яшаётганларингиз ва ёрдамингизга муҳтожларга ёрдам беринг, одамларга ҳурмат билан муносабатда бўлинг. Креатив истеъдодингизни топинг ва намоён қилинг ва бир кун у сизга ёмон бўлмаган даромад келтиради.","Основная задача – это духовность, связь с богом, развитие интуиции. Следование религии не всегда приводит к духовности, требуется знать вселенские и кармические законы. Учитесь пользоваться новыми технологиями и гаджетами. Обретите современные технические навыки и занимайтесь оккультными науками. Познавайте законы вселенной через оккультные науки, медитации, паломничества, практики. Успокаивайте свою голову духовную практиками, умейте уединиться, если это требуется и умейте принять изменения, перемены если они необходимы и совершить их. Определитесь с самоидентификацией, с тем кто вы. Умейте побороть свои большие страхи, как правило в основе всех страхов – страх конца. Избавьтесь от консервативных взглядов на жизнь, не держитесь за старые идеи и устаревшие, неактуальные ценности. Развивайте свои мистические способности, обретите глубокое понимание мира и духовных истин. Внедряйте аскетичный образ жизни в свою жизнь или периодические аскезы. Развивайте интуицию, проницательность и силу провидения. Отбрасывайте старое и внедряйте в новое. Живите в балансе духовного и материального, мы имеем тело и его нужно кормить и укреплять, так же мы имеем душу, которой требуется тоже самое. Не бросайтесь в крайности, т.к любое действие имеет противодействие, которое рано или поздно к вам придет. Некоторые из вас живут либо оторвано от жизни и только в потоке, другие приходят в ярость от того, что держат все под жесточайшим контролем и у них срываются планы. Тут нужен баланс – что-то пускать на самотек, а что-то брать в свои руки. Пользуйтесь интуицией в этом вопросе. Не впадайте в жертву, а умейте принять свой выбор и нести за него ответственность. Все в вашей жизни есть ваш собственный выбор, пусть это не всегда очевидно, но вы справитесь если поразмыслите на эту тему. Не будьте доверчивы, не попадайте под чужое влияние, так как в вас есть огромная сила, способная решить все ваши вопросы. Находитесь в здесь и сейчас, не отлетайте от реальности. Быть в моменте ваша основная задача. Ставьте себя в вашей жизни на первое место, никто не выше и не ниже вас. Каждый проживает свою жизнь и каждый в ней главный, вам незачем отдавать свое время жизни и приносить себя в жертву. Достаточно не вредить и любить себя, быть в центре своей жизни. Ваша фантазия очень тонко граничит с безумием, возможно, вы видите образы будущего или прошлого, но людям это сложно принять так сразу как вам. Старайтесь найти разумное объяснение этим историям, например, что это был сон, для того, чтобы вас не обвиняли в том, что у вас «поехала крыша».":"Асосий вазифа — маънавият, худо билан алоқа, интуицияни ривожлантириш. Динга эргашиш доим ҳам маънавиятга олиб келмайди, коинот ва кармик қонунларни билиш талаб қилинади. Янги технологиялар ва гаджетлардан фойдаланишни ўрганинг. Замонавий техник кўникмаларни эгалланг ва оккульт фанлар билан шуғулланинг. Коинот қонунларини оккульт фанлар, медитациялар, зиёратлар, амалиётлар орқали англанг. Бошингизни маънавий амалиётлар билан тинчлантиринг, агар бу талаб қилинса ёлғизланишни ва агар зарур бўлса ўзгаришлар, янгиланишларни қабул қилишни ва уларни амалга оширишни билинг. Ўзини аниқлаш, кимлигингиз билан аниқлик киритинг. Катта қўрқувларингизни енгишни билинг, одатда барча қўрқувлар асосида — охир қўрқуви. Ҳаётга консерватив қарашлардан қутулинг, эски ғоялар ва эскирган, долзарб бўлмаган қадриятларга ёпишманг. Мистик қобилиятларингизни ривожлантиринг, дунё ва маънавий ҳақиқатларни чуқур тушунишга эришинг. Ҳаётингизга зоҳидона ҳаёт тарзини ёки вақти-вақти билан зоҳидликни жорий этинг. Интуиция, зийраклик ва олдиндан кўриш кучини ривожлантиринг. Эскини ташланг ва янгисига жорий этинг. Маънавий ва моддий мувозанатида яшанг, бизнинг танамиз бор ва уни боқиш ва мустаҳкамлаш керак, шунингдек худди шуни талаб қиладиган қалбимиз бор. Ҳаддан ошишларга ташланманг, чунки ҳар қандай ҳаракатнинг акс ҳаракати бор, у эртами-кечми сизга келади. Баъзиларингиз ё ҳаётдан узилган ва фақат оқимда яшайди, бошқалари эса ҳаммасини энг қаттиқ назоратда ушлаб, режалари бузилганидан ғазабга келади. Бу ерда мувозанат керак — нимадир ўз ҳолига қўйиш, нимадир эса ўз қўлингизга олиш. Бу масалада интуициядан фойдаланинг. Қурбон бўлманг, танловингизни қабул қилишни ва у учун масъулиятни кўтаришни билинг. Ҳаётингиздаги ҳамма нарса ўз танловингиз, бу доим ҳам аниқ бўлмаса ҳам, лекин бу мавзуда ўйлаб кўрсангиз уддалайсиз. Ишонувчан бўлманг, бировнинг таъсирига тушманг, чунки сизда барча масалаларингизни ҳал қила оладиган улкан куч бор. Шу ерда ва ҳозир бўлинг, ҳақиқатдан учиб кетманг. Лаҳзада бўлиш — асосий вазифангиз. Ҳаётингизда ўзингизни биринчи ўринга қўйинг, ҳеч ким сиздан юқори ҳам, паст ҳам эмас. Ҳар ким ўз ҳаётини яшайди ва ҳар ким унда асосий, сизга ҳаёт вақтингизни бериш ва ўзингизни қурбон қилишнинг ҳожати йўқ. Зарар етказмаслик ва ўзингизни севиш, ҳаётингиз марказида бўлиш етарли. Хаёлотингиз телбалик билан жуда нозик чегарадош, эҳтимол, сиз келажак ёки ўтмиш образларини кўрасиз, лекин одамларга буни сиз каби дарҳол қабул қилиш қийин. «Томингиз кетиб қолди» деб айбламасликлари учун бу ҳикояларга оқилона изоҳ топишга, масалан, бу туш эди деб ҳаракат қилинг.","Задача вырабатывать терпение и выносливость, прикладывать усилия к достижению целей, преодолевать препятствия, держать удар судьбы, быть последовательным, следовать законам, учитесь разряжать себя от напряжения. Работайте. Научитесь скромности, трудо- любию, постоянному и четкому выполнению своих обязанностей, внутренней не привязанности к миру. Научитесь верности, осторожности, надежности и серьезному ответственному отношению к жизни. Не впадайте в уныние, в депрессии, не ленитесь и избавьтесь от презрения к другим и желания причинить им боль. Учитесь концентрации и целеустремленно- сти, планируйте все, что можете распланировать и следуйте режиму дня, аскезам. Стремитесь к карьере и руководящим должностям. Вырастите свой стальной внутренний стержень. Принимайте свою карму, по большей мере, вы здесь для того, чтобы негативную карму отработать за одно воплощение и превратить ее в свои достоинства и в финансовое благополучие. У других чисел карма растягивается на 10—100 жизней, не так концентрированно как у вас. Научитесь управлять материальным миром. Среди 8-ок очень много богачей, а кто-то из вас живет от зарплаты до зарплаты. У вас в деньгах всегда крайности. Если вы не будете привязываться к деньгам, то и крайностей будет меньше. Даже самые богатые 8ки теряют все в своей жизни хоть раз, чтобы начать все с нуля. Карма вас проверяет деньгами – останетесь ли вы человечным, начнете ли вредить себе и людям, будете ли манипулировать людьми и использовать их в своих целях. Развивайтесь духовно параллельно развитию в материальном мире, знания вас защищают от грубых ошибок и нарушений. Развивайте личную силу и авторитет, тк в жизни и в любой профессии вы хотите быть авторитетом. К 40 годам вам уже нужно ощутить, что вы управляете своей жизнью и никто и ничто другое. Ставьте себя на первое место и не опекайте излишне других, а особенно тех, кто этого не просит. Вы слишком хорошие и это проблема, любое излишество вредит и нарушает гармонию. Вы хотите всем помочь и от этого не даете получить им свой опыт, а это уже плохо. Вас за это могут лишить личной жизни, чтобы вы и партнера не испортили. Вы умеете влиять на людей и вам нужно использовать свою силу только во благо. Будьте аскетом хоть в какой-то области, сознательно ограничьте себя в излишествах. Это компенсирует энергию Сатурна и не даст трудностям наваливаться горой на вас. Найдите свою радость и будьте позитивным. Вам хоть и тяжелее, чем многим другим, но будет еще хуже если вы будете пессимистичны или опустите руки.":"Вазифа — сабр ва чидамлиликни ишлаб чиқиш, мақсадларга эришишга саъй-ҳаракат қилиш, тўсиқларни енгиш, тақдир зарбасига бардош бериш, изчил бўлиш, қонунларга амал қилиш, ўзингизни тарангликдан бўшатишни ўрганинг. Ишланг. Камтарлик, меҳнатсеварлик, мажбуриятларингизни доимий ва аниқ бажариш, дунёга ички боғланмасликни ўрганинг. Садоқат, эҳтиёткорлик, ишончлилик ва ҳаётга жиддий масъулиятли муносабатни ўрганинг. Тушкунликка, депрессияга тушманг, дангасалик қилманг ва бошқаларга нафрат ва уларга оғриқ етказиш истагидан қутулинг. Диққатни жамлаш ва мақсадга интилувчанликни ўрганинг, режалаштира оладиган ҳамма нарсани режалаштиринг ва кун тартиби, зоҳидликларга амал қилинг. Карьера ва раҳбарлик лавозимларига интилинг. Пўлат ички ўзагингизни ўстиринг. Кармангизни қабул қилинг, кўп жиҳатдан сиз бу ерда салбий кармани бир мужассамлашда ишлаб чиқиш ва уни фазилатларингиз ва молиявий фаровонликка айлантириш учун келгансиз. Бошқа сонларда карма 10—100 ҳаётга чўзилади, сиздагидек жамланган эмас. Моддий дунёни бошқаришни ўрганинг. 8 лар орасида бойлар жуда кўп, кимлардир эса маошдан маошгача яшайди. Сизда пулда доим ҳаддан ошишлар. Агар пулга боғланмасангиз, ҳаддан ошишлар ҳам камроқ бўлади. Ҳатто энг бой 8 лар ҳам ҳаётида ҳеч бўлмаганда бир марта нолдан ҳаммасини бошлаш учун ҳаммасини йўқотади. Карма сизни пул билан синайди — инсоний қоласизми, ўзингиз ва одамларга зарар етказа бошлайсизми, одамларни манипуляция қилиб, улардан ўз мақсадларингизда фойдаланасизми. Моддий дунёда ривожланиш билан параллел маънавий ривожланинг, билимлар сизни қўпол хатолар ва бузилишлардан ҳимоя қилади. Шахсий куч ва обрўни ривожлантиринг, чунки ҳаётда ва ҳар қандай касбда обрў бўлишни истайсиз. 40 ёшга келиб сизга ҳаётингизни бошқа ҳеч ким ва ҳеч нарса эмас, сиз бошқараётганингизни ҳис қилиш керак. Ўзингизни биринчи ўринга қўйинг ва бошқаларга, айниқса буни сўрамаганларга ортиқча васийлик қилманг. Сиз жуда яхшисиз ва бу муаммо, ҳар қандай ортиқчалик зарар қилади ва уйғунликни бузади. Сиз ҳаммага ёрдам беришни истайсиз ва бундан уларга ўз тажрибасини олишга имкон бермайсиз, бу эса энди ёмон. Бунинг учун сизни шерикни ҳам бузмаслигингиз учун шахсий ҳаётдан маҳрум қилишлари мумкин. Сиз одамларга таъсир кўрсатишни биласиз ва кучингиздан фақат яхшилик учун фойдаланишингиз керак. Ҳеч бўлмаганда қандайдир соҳада зоҳид бўлинг, ортиқчаликларда ўзингизни онгли чекланг. Бу Сатурн энергиясини қоплайди ва қийинчиликларнинг устингизга тоғдек тўпланишига йўл қўймайди. Ўз қувончингизни топинг ва ижобий бўлинг. Сизга кўплаб бошқаларга қараганда оғирроқ бўлса ҳам, агар пессимистик бўлсангиз ёки қўлни туширсангиз, янада ёмонроқ бўлади.","Это могут быть потери, большие расходы, есть проблема в этой области, человеку нужно следить за этой сферой, чтобы свести к минимуму проблемы. Может быть ощущение, что ничего не приносит, только сложности и испытания. Вам нужно самому для себя понять, что вам приносит любовь, у вас просто нет этого понимания или даже умения ощущать любовь. Выберите для себя, что вам дает любовь и хорошенько разберитесь в этом вопросе, желательно с учителем, у которого в этой сфере все отлично, как вам и хотелось. Любовь может приходить когда вы на нуле в чем-то или где-то или ваш возлюбленный/ая на нуле и вы влюбились при этом зная или не зная этого. Приходит любовь когда трудно и когда проблемы у вас или у будущего возлюбленного.":"Бу йўқотишлар, катта харажатлар бўлиши мумкин, бу соҳада муаммо бор, муаммоларни минимумга тушириш учун инсон бу соҳани кузатиб бориши керак. Ҳеч нарса келтирмаётгандек, фақат қийинчиликлар ва синовлар келтираётгандек ҳис бўлиши мумкин. Сизга севги нима келтиришини ўзингиз учун тушуниб олишингиз керак, сизда шунчаки бу тушунча ёки ҳатто севгини ҳис қилиш кўникмаси йўқ. Севги сизга нима беришини ўзингиз учун танланг ва бу масалани яхшилаб ўрганинг, яхшиси бу соҳада ҳаммаси сиз истагандек аъло бўлган устоз билан. Севги сиз нимададир ёки қаердадир нолда бўлганингизда ёки севгилингиз нолда бўлганида келиши ва сиз буни билган ёки билмаган ҳолда севиб қолишингиз мумкин. Севги қийин бўлганда ва муаммолар сизда ёки бўлажак севгилингизда бўлганда келади.","Вам любовь приносит любовь к себе и окружения к вам, ощущение главенства вас в жизни своей и может даже других людей, процветание во всех сферах, улучшение внешнего вида, формирование имиджа и личного бренда. Вы становитесь лидером и предпочитаете делать то, что хочется, наслаждаться жизнью. Иногда это доходит до того, что вы не считаетесь с другими. Ваша любовь если есть, то очень сильная, вам важно чтобы любили вас. Когда вы любите и вас любят вы растете личностно, обретаете силу духа. Любовь приносит вам детей, мужа, или вы сами становитесь отцом, мужем. Приносит много внимания, чувство собственного достоинства, радости от жизни и восхищение вами. Может приносить гордыню от которой нужно избавляться, может приносить взросление в ответственного человека. Вы становитесь яркой личностью, имеете смелость проявляться и самореализоваться. Любовь – один из основных моментов в вашей жизни. Вы стремитесь к самовыражению и желаете быть в центре внимания, становитесь независимым и самостоятельным в жизни. В вас появляется доброта, благородство, великодушие, щедрость, доброжелательность, сердечность и снисходительность к промахам других людей и своим. Работа или занятия по солнечным профессиям – менеджер, управленец, артист, начальник, звезда и собственный бизнес, администратор, банкир, биржа, спекуляции, инвестор, директор, юриспруденция, финансы, налоги, чиновник, политик, страхование, врач, медицина, режиссер, шоу-бизнес, заработок от хобби, актер, креатив, дизайн, оратор, писатель, мода, ювелир, антиквариат, учитель творческих, управляющих сфер и учитель личностного роста, работа с детьми, управляющие должности, творческие профессии приносит любовь, или можете влюбиться в человека с такими качествами или профессией.":"Севги сизга ўзингизга бўлган севгини ва атрофдагиларнинг сизга бўлган севгисини, ўз ҳаётингизда ва ҳатто бошқа одамлар ҳаётида етакчилик ҳиссини, барча соҳаларда гуллаб-яшнашни, ташқи кўринишнинг яхшиланишини, имиж ва шахсий брендни шакллантиришни келтиради. Сиз етакчига айланасиз ва истаган нарсангизни қилишни, ҳаётдан завқланишни афзал кўрасиз. Баъзан бу бошқалар билан ҳисоблашмаслик даражасига боради. Севгингиз агар бўлса, жуда кучли, сизни севишлари сиз учун муҳим. Сиз севганингизда ва сизни севишганда шахсан ўсасиз, руҳ кучини топасиз. Севги сизга болалар, эр келтиради ёки ўзингиз ота, эр бўласиз. Кўп эътибор, ўз қадр-қиммат ҳисси, ҳаётдан қувонч ва сиздан ҳайратланиш келтиради. Ундан қутулиш керак бўлган кибр келтириши, масъулиятли инсонга етилиш келтириши мумкин. Сиз ёрқин шахсга айланасиз, ўзингизни намоён қилиш ва ўзингизни рўёбга чиқариш жасоратига эга бўласиз. Севги — ҳаётингиздаги асосий лаҳзалардан бири. Сиз ўзингизни ифода этишга интиласиз ва диққат марказида бўлишни истайсиз, ҳаётда мустақил ва ўзига ишонган бўласиз. Сизда меҳрибонлик, олижаноблик, бағрикенглик, саховат, хайрихоҳлик, самимийлик ва бошқа одамлар ва ўз хатоларингизга кечиримлилик пайдо бўлади. Қуёш касблари бўйича иш ёки машғулотлар — менежер, бошқарувчи, артист, бошлиқ, юлдуз ва шахсий бизнес, администратор, банкир, биржа, спекуляциялар, инвестор, директор, юриспруденция, молия, солиқлар, амалдор, сиёсатчи, суғурта, шифокор, тиббиёт, режиссёр, шоу-бизнес, хоббидан даромад, актёр, креатив, дизайн, нотиқ, ёзувчи, мода, заргар, антиквариат, ижодий, бошқарув соҳалари ўқитувчиси ва шахсий ўсиш ўқитувчиси, болалар билан ишлаш, бошқарув лавозимлари, ижодий касблар севги келтиради, ёки шундай фазилатлар ёки касбга эга инсонни севиб қолишингиз мумкин.","Любовь приносит вам чувство безопасности либо наоборот тревожности от того, что вы можете потерять обретенное, т.к ваша жизнь изменчива. Любовь приносит семью, материнство, маленьких детей, чувство заботы, вашу заботливость, большую эмоциональность. Вы глубоко вовлекаетесь в любовь и становитесь женственней. Вы становитесь изменчивой как вода. Лучше начинаете понимать свою психику и психику других людей, начинаете видеть суть души человека, делаете все в любви. Вам в любви важно быть вместе с партнером. Иногда любовь приносит сомнения и нерешительность и вы дрожите как осенний листок. Вы интуитивно знаете потребности, а иногда и мысли по лицу или голосу человека, без слов умеете понимать его. Вы становитесь лучшей женой, мамой детей, хозяйкой, женщиной и родным человеком. Тесная связь любви и семьи. Любимый человек может заниматься профессиями или занятиями по Луне – повар, няня, домохозяин или домохозяйка, мебель, все что связано с домом и уютом, педагог, еда и напитки, сельское хозяйство, дипломат, повар, недвижимость, отели, рестораны, дома отдыха, моряк, няня, массажист, пекарня, кондитерская, туризм, сфера массового обслуживания, медицина, писатель, психолог, домохозяйка, химик, врач, целитель, продукты, импорт/экспорт, реклама, журналистика, искусство, биолог, одежда, продавец, консультант, семейный бизнес, окружающая среда, народная музыка, снабжение, все что связано с партнерством, материнством, домом, забота о людях и творчество от души, а также ваша работа или занятия по Луне принесет вам любовь.":"Севги сизга хавфсизлик ҳиссини ёки аксинча ҳаётингиз ўзгарувчан бўлгани учун топганингизни йўқотишингиз мумкинлигидан хавотир ҳиссини келтиради. Севги оила, оналик, кичик болалар, ғамхўрлик ҳисси, ғамхўрлигингиз, катта ҳиссиётлилик келтиради. Сиз севгига чуқур берилиб кетасиз ва аёлроқ бўласиз. Сув каби ўзгарувчан бўласиз. Ўз руҳиятингиз ва бошқа одамлар руҳиятини яхшироқ тушуна бошлайсиз, инсон қалбининг моҳиятини кўра бошлайсиз, ҳамма нарсани севги билан қиласиз. Севгида сиз учун шерик билан бирга бўлиш муҳим. Баъзан севги шубҳалар ва қатъиятсизлик келтиради ва сиз куз барги каби титрайсиз. Сиз инсоннинг эҳтиёжларини, баъзан эса фикрларини юзидан ёки овозидан интуитив биласиз, уни сўзсиз тушуна оласиз. Сиз энг яхши хотин, болаларнинг онаси, бека, аёл ва яқин инсонга айланасиз. Севги ва оиланинг яқин алоқаси. Севимли инсон Ой бўйича касблар ёки машғулотлар билан шуғулланиши мумкин — ошпаз, энага, уй бекаси ёки уй хўжайини, мебель, уй ва қулайлик билан боғлиқ ҳамма нарса, педагог, овқат ва ичимликлар, қишлоқ хўжалиги, дипломат, ошпаз, кўчмас мулк, меҳмонхоналар, ресторанлар, дам олиш уйлари, денгизчи, энага, массажчи, нонвойхона, қандолатхона, туризм, оммавий хизмат кўрсатиш соҳаси, тиббиёт, ёзувчи, психолог, уй бекаси, кимёгар, шифокор, табиб, озиқ-овқат, импорт/экспорт, реклама, журналистика, санъат, биолог, кийим, сотувчи, маслаҳатчи, оилавий бизнес, атроф-муҳит, халқ мусиқаси, таъминот, шериклик, оналик, уй билан боғлиқ ҳамма нарса, одамларга ғамхўрлик ва қалбдан ижод, шунингдек Ой бўйича ишингиз ёки машғулотларингиз сизга севги келтиради.","Вам любовь приносит расширение сознания, богатство, расширение границ территории, путешествия в различные страны, приносит высокий социальный статус,, новую должность и высокий авторитет. К вам приходит изобилие, чувство собственного важности в социуме и некое превосходство, начинает формироваться мировоззрение и философский взгляд на мир, ваша картина мира становится яснее и четче. Могут быть отношения на расстоянии или в отношениях с иностранцем, можете быть наставником в любовных отношениях. Любовь приходит если вы работаете или занимаетесь чем-то связанным с преподаванием или в любой из перечисленных сфер ниже, также вариант влюбить или влюбиться в вашего учителя, наставника, гида, священника, в человека по профессии в сферах: собственный бизнес, сфера финансов, юрист, бухгалтер, туризм, дипломат, ювелир, преподавание, гид, историк, культурист, священник, педагог, врач, архитектор, ученый, инженер, политик, философ, издательское дело, писатель, переводчик, дизайнер, топ менеджер, наставничество, PR, СМИ, издательство. Ваша любовь идеалистична, честна и вы становитесь независимы, добропорядочны, благородны, оптимистичны, жизнерадостны, с вами очень весело и задорно, вы стремитесь к духовному росту и достижению самого высокого во всех сферах жизни.":"Севги сизга онгнинг кенгайишини, бойлик, ҳудуд чегараларининг кенгайишини, турли мамлакатларга саёҳатлар келтиради, юқори ижтимоий мақом, янги лавозим ва юқори обрў келтиради. Сизга мўл-кўллик, жамиятда ўз аҳамиятингиз ҳисси ва қандайдир устунлик келади, дунёқараш ва дунёга фалсафий қараш шакллана бошлайди, дунё манзарангиз аниқроқ ва равшанроқ бўлади. Масофадаги муносабатлар ёки чет эллик билан муносабатлар бўлиши мумкин, севги муносабатларида устоз бўлишингиз мумкин. Агар ўқитиш билан ёки қуйида санаб ўтилган соҳалардан бирида ишласангиз ёки шуғуллансангиз севги келади, шунингдек ўқитувчингиз, устозингиз, гид, руҳоний, касби бўйича қуйидаги соҳалардаги инсонни севдириш ёки севиб қолиш варианти бор: шахсий бизнес, молия соҳаси, юрист, бухгалтер, туризм, дипломат, заргар, ўқитиш, гид, тарихчи, культурист, руҳоний, педагог, шифокор, меъмор, олим, муҳандис, сиёсатчи, файласуф, ноширлик иши, ёзувчи, таржимон, дизайнер, топ-менеджер, устозлик, PR, ОАВ, нашриёт. Севгингиз идеалистик, ҳалол ва сиз мустақил, ҳалол, олижаноб, оптимистик, ҳаётсевар бўласиз, сиз билан жуда қувноқ ва завқли, сиз маънавий ўсишга ва ҳаётнинг барча соҳаларида энг юксак нарсага эришишга интиласиз.","Число 4 здесь приносит иллюзии в любовь, карму, обман, может приносить предательство, что-то не очень хорошее. Может приносить что-то безумное, сумасшедшее, сумасбродное и море желаний, которых все больше и больше, ненасытность. Может приносить проблемы с токсичными вещами, а может приносить ясность видения ситуации, когда вы находитесь на над ситуацией, стабильность, духовное пробуждение, проработку кармических уроков. Много неожиданностей, крайностей, крышесносных событий, вы можете открыть в себе способность управлять толпой. Можете открывать в себе магические способности, силу мысли. Любовь приносит стремление быть настоящей, натуральной и иногда даже ЗОЖ. Карма – тут ключевое, никогда не знаешь, что вы натворили в прошлых жизнях. Тут все карма. Стремитесь к духовности, развивайтесь, откажитесь от предательства себя во имя любви. Не впадайте в крайности и зависимости, вредные привычки нужно исключать. Ваша задача развиваться в любви. Вы можете обрести любовь работая по этим профессиям или влюбиться в того, кто работает по этой профессии – экономист, программист, юрист, исследования, интернет, электрика, компьютерщик, новые технологии, космическая техника, психология, психиатрия, анестезиолог, радио, телевидение, СМИ, наука, политика, детектив, фокусник, иллюзионист, экс- трасенс, эзотерик, окружающая среда, метафизика, казино, алкоголь, яды, химия, наркотики, криминал, врач, секретные службы, порнография, киноиндустрия, писатели-фантасты. Если не профессия то просто занятия из подобных сфер.":"Бу ерда 4 сони севгига иллюзиялар, карма, алдов келтиради, хиёнат, унча яхши бўлмаган нимадир келтириши мумкин. Қандайдир телбаларча, ақлдан озган, тентаклик ва тобора кўпайиб борадиган истаклар денгизи, тўймаслик келтириши мумкин. Заҳарли нарсалар билан муаммолар келтириши мумкин, ёки вазиятдан юқорида турганингизда вазиятни аниқ кўриш, барқарорлик, маънавий уйғониш, кармик сабоқларни ишлаб чиқиш келтириши мумкин. Кўплаб кутилмаган ҳодисалар, ҳаддан ошишлар, ақлни шоширадиган воқеалар, сиз ўзингизда оломонни бошқариш қобилиятини очишингиз мумкин. Ўзингизда сеҳрли қобилиятларни, фикр кучини очишингиз мумкин. Севги ҳақиқий, табиий бўлишга интилиш ва баъзан ҳатто СТТ (соғлом турмуш тарзи) келтиради. Карма — бу ерда асосий, ўтган ҳаётларда нима қилганингизни ҳеч қачон билмайсиз. Бу ерда ҳаммаси карма. Маънавиятга интилинг, ривожланинг, севги номи билан ўзингизга хиёнат қилишдан воз кечинг. Ҳаддан ошишлар ва қарамликларга тушманг, зарарли одатларни истисно қилиш керак. Сизнинг вазифангиз севгида ривожланиш. Сиз бу касблар бўйича ишлаб севги топишингиз ёки бу касб бўйича ишлайдиганни севиб қолишингиз мумкин — иқтисодчи, дастурчи, юрист, тадқиқотлар, интернет, электрика, компьютерчи, янги технологиялар, космик техника, психология, психиатрия, анестезиолог, радио, телевидение, ОАВ, фан, сиёсат, детектив, фокусчи, иллюзионист, экстрасенс, эзотерик, атроф-муҳит, метафизика, казино, алкоголь, заҳарлар, кимё, гиёҳвандлик воситалари, жиноят, шифокор, махфий хизматлар, порнография, кино индустрияси, фантаст ёзувчилар. Агар касб бўлмаса, шунчаки шунга ўхшаш соҳалардаги машғулотлар.","Любовь приносит легкость, знания, много знакомств, много перемещений, много общения в т.ч. в телефоне, рациональность. Приносит, как ни странно, может быть переменчивость в любви, расфокус в жизни или в делах, у вас может быть несколько любящих или тех кого вы любите, вам свойственно непостоянство, вы легки на подъем и у вас много знакомых, много контактов. Любимый может быть как то связан с вашими друзьями, или же он станет вам другом в плюс к любви, или же станете ему другом. Приходит любовь если вы или ваш будущий возлюбленный работаете или занимаетесь по этим сферам: импорт-экспорт, новые технологии, библиотека, бизнесмен, бухгалтер, финансист, аудитор, аналитик, менеджер, математик, брокер, посредник, дилер, писатель, редактор, программист, ученый, учитель, лингвист, переводчик, пиарщик, астролог, нумеролог, секретарь, продавец, кассир, посредник, экскурсовод, курьер, ремесленник, фокусник, политик, пародист, водитель, средства связи, реклама, издательство, страхование, работа в СМИ, журналистика, логистика, работа-хобби, мошенничество, теневой бизнес, репортер, инженер, оценщик, актер. И наоборот любовь приносит занятия или работу по этим сферам.":"Севги енгиллик, билимлар, кўп танишувлар, кўп ҳаракатланишлар, кўп мулоқот, жумладан телефонда, рационаллик келтиради. Ғалати туюлса ҳам, севгида ўзгарувчанлик, ҳаётда ёки ишларда диққатнинг тарқоқлиги келтириши мумкин, сизда бир нечта севувчи ёки сиз севадиганлар бўлиши мумкин, сизга беқарорлик хос, сиз енгил кўтариласиз ва сизда кўп танишлар, кўп алоқалар бор. Севимли инсон дўстларингиз билан қандайдир боғлиқ бўлиши мумкин, ёки у сизга севгига қўшимча дўст бўлади, ёки сиз унга дўст бўласиз. Агар сиз ёки бўлажак севгилингиз бу соҳаларда ишласангиз ёки шуғуллансангиз севги келади: импорт-экспорт, янги технологиялар, кутубхона, бизнесмен, бухгалтер, молиячи, аудитор, таҳлилчи, менежер, математик, брокер, воситачи, дилер, ёзувчи, муҳаррир, дастурчи, олим, ўқитувчи, тилшунос, таржимон, пиарчи, астролог, нумеролог, котиба, сотувчи, кассир, воситачи, экскурсовод, курьер, ҳунарманд, фокусчи, сиёсатчи, пародист, ҳайдовчи, алоқа воситалари, реклама, нашриёт, суғурта, ОАВда ишлаш, журналистика, логистика, иш-хобби, фирибгарлик, яширин бизнес, репортёр, муҳандис, баҳоловчи, актёр. Ва аксинча севги бу соҳалардаги машғулотлар ёки иш келтиради.","Вам любовь приносит чувственное удовлетворение, удовольствие, наслаждение, добро. У вас может быть увлечение большим количеством партнёров, а не одним и качественным со стремлением к долгой совместной жизни. Вам нужно учиться жить долгой совместной жизнью с одним партнером качественно, доставлять ему удовольствие, радовать и радоваться жизни, быть благодарным партнёру, украшать себя, быть красивой. Любовь делает вас красивым, вы светитесь изнутри и становитесь сексуальной. Любовь приходит к вам если вы или ваш будущий возлюбленный занимаетесь в сферах: мода, искусство, музыка, танцы, кондитер, сфера развлечений, сфера красоты, массажист, косметолог, парикмахер, дизайнер, художник, гравер, ремесленник, иллюстратор, артист, портной, кондитер, антиквариат, горничная, казино, эксклюзивные товары, ювелирный бизнес, гостиничный бизнес, организация праздников, фотограф, цветовод, проституция, секретарь, декоратор, сфера отдыха. Так же влюбившись вы можете переходить к этим занятиям сами или ваш возлюбленный. Вы становитесь обаятельным, справедливым, вежливым, уравновешенным, спокойным, стремитесь удовлетворить любимого и находиться в комфорте. Любовь приносит деньги, а деньги принесут любовь.":"Севги сизга ҳиссий қониқиш, лаззат, завқ, эзгулик келтиради. Сизда бир ва сифатли, узоқ биргаликдаги ҳаётга интилиш билан эмас, балки кўп шериклар билан овуниш бўлиши мумкин. Сизга бир шерик билан узоқ биргаликдаги ҳаётни сифатли яшашни, унга лаззат бағишлашни, хурсанд қилиш ва ҳаётдан қувонишни, шерикка миннатдор бўлишни, ўзингизни безатишни, чиройли бўлишни ўрганиш керак. Севги сизни чиройли қилади, сиз ичингиздан нур сочасиз ва жозибали бўласиз. Агар сиз ёки бўлажак севгилингиз бу соҳаларда шуғуллансангиз севги сизга келади: мода, санъат, мусиқа, рақслар, қандолатчи, кўнгилочар соҳа, гўзаллик соҳаси, массажчи, косметолог, сартарош, дизайнер, рассом, ўймакор, ҳунарманд, иллюстратор, артист, тикувчи, қандолатчи, антиквариат, хизматкор, казино, эксклюзив товарлар, заргарлик бизнеси, меҳмонхона бизнеси, байрамлар ташкил этиш, фотограф, гулчи, фоҳишабозлик, котиба, декоратор, дам олиш соҳаси. Шунингдек севиб қолиб, сиз ўзингиз ёки севгилингиз бу машғулотларга ўтишингиз мумкин. Сиз жозибали, адолатли, хушмуомала, вазмин, хотиржам бўласиз, севимли инсонни қониқтиришга ва қулайликда бўлишга интиласиз. Севги пул келтиради, пул эса севги келтиради.","Кармические уроки. Любовь приносит вам духовное развитие, стремление к Богу, некоторое отречение от материального мира, способность трансформировать свое сознание в новое, поиск духовного пути, непредсказуемость, необычность, космичность и возможно некую скрытность. Любовь ожидает на работе или занятии в этих сферах: медицина, психология, яды, химия, наука, дизайнер, биолог, зоолог, электрик, целительство, Аюрведа, эзотерика, оккультизм, теология, религия, священник, шитье, духовные практики, учитель йоги, астролог, таролог, нумеролог, программист, метеорология, интернет, компьютерщик, секретные службы, космос, новейшие технологии, философия. Вы сами или ваш будущий возлюбленный имеете эти занятия. Также если вы влюбляетесь, то сами можете перейти в эти занятия или ваш возлюбленный как-то будет связан с этим. В любви хочется уединения. В уединении хочется любви.":"Кармик сабоқлар. Севги сизга маънавий ривожланиш, Худога интилиш, моддий дунёдан маълум даражада воз кечиш, онгингизни янгисига трансформация қилиш қобилияти, маънавий йўлни излаш, олдиндан айтиб бўлмаслик, ғайриоддийлик, космиклик ва эҳтимол қандайдир сирлилик келтиради. Севги бу соҳалардаги иш ёки машғулотда кутади: тиббиёт, психология, заҳарлар, кимё, фан, дизайнер, биолог, зоолог, электрик, табиблик, Аюрведа, эзотерика, оккультизм, теология, дин, руҳоний, тикиш, маънавий амалиётлар, йога ўқитувчиси, астролог, таролог, нумеролог, дастурчи, метеорология, интернет, компьютерчи, махфий хизматлар, космос, энг янги технологиялар, фалсафа. Сиз ўзингиз ёки бўлажак севгилингиз шу машғулотларга эгасиз. Шунингдек агар севиб қолсангиз, ўзингиз бу машғулотларга ўтишингиз мумкин ёки севгилингиз бу билан қандайдир боғлиқ бўлади. Севгида ёлғизликни истайсиз. Ёлғизликда севгини истайсиз.","Вам любовь приносит много трудностей, это кармические уроки через любовь, вам необходимо видеть истинность всего, что в вашей жизни, иначе оно уйдет, когда придет любовь. Нельзя врать себе и обманывать ни себя никого. Приносит много работы, жизнь с постоянными режимными задачами, взросление души, старение тела может происходить, если ваш возлюбленный не старше вас на много. Приходит основательность, вы строите эту любовь самостоятельно, по кирпичикам, долго и упорно, выносливо. У вас должна быть цель в жизни, чтобы пришла любовь, а любовь приносит цели в жизни. Вам приходится преодолевать много препятствий, это вас закаляет. Бывает любовь приносит карьеру и социальный статус, полученные своим трудом. Хорошо если в любви есть большая разница в возрасте, прям можно огромная. Любовь среди тех с кем вы давным-давно знакомы, с детства возможно. Любовь учит вас брать ответственность на себя, быть выносливым и местами холодным. Через любовь к вам приходит ваша карма, как благостная так через какие-то наказания. Профессии и занятия где встретите любовь: политик, бизнесмен, чиновник, ученый, директор, финансист, администратор, юрист, судья, руководитель, промышленность, преподаватель, духовный учитель, врач, философ, психолог, астролог, аналитик, исследователь, строитель, часовщик, шахтер, уборщик, сторож, техник, недвижимость, социальная служба, ритуальные услуги, секретные службы, металлообработка, полезные ископаемые, антиквариат, ночная работа, подземная работа, умственно тяжелая работа, физически тяжелая работа. Так же может быть ваш партнер из этих занятий или влюбившись вы станете ими заниматься.":"Севги сизга кўп қийинчиликлар келтиради, бу севги орқали кармик сабоқлар, сизга ҳаётингиздаги ҳамма нарсанинг ҳақиқийлигини кўриш зарур, акс ҳолда севги келганда у кетади. Ўзингизга ёлғон гапириш ва на ўзингизни, на ҳеч кимни алдаш мумкин эмас. Кўп иш, доимий тартибли вазифалар билан ҳаёт, қалбнинг улғайиши келтиради, агар севгилингиз сиздан анча катта бўлмаса, тананинг қариши содир бўлиши мумкин. Пухталик келади, сиз бу севгини мустақил, ғиштма-ғишт, узоқ ва тиришқоқлик билан, чидамлилик билан қурасиз. Севги келиши учун ҳаётда мақсадингиз бўлиши керак, севги эса ҳаётда мақсадлар келтиради. Сизга кўп тўсиқларни енгишга тўғри келади, бу сизни чиниқтиради. Баъзан севги ўз меҳнатингиз билан олинган карьера ва ижтимоий мақом келтиради. Агар севгида ёшда катта фарқ бўлса яхши, ҳатто жуда катта бўлиши мумкин. Севги азалдан, эҳтимол болаликдан таниш бўлганларингиз орасида. Севги сизни масъулиятни ўз зиммангизга олишга, чидамли ва баъзи жойларда совуқ бўлишга ўргатади. Севги орқали сизга кармангиз келади, ҳам эзгу, ҳам қандайдир жазолар орқали. Севгини учратадиган касблар ва машғулотлар: сиёсатчи, бизнесмен, амалдор, олим, директор, молиячи, администратор, юрист, судья, раҳбар, саноат, ўқитувчи, маънавий устоз, шифокор, файласуф, психолог, астролог, таҳлилчи, тадқиқотчи, қурувчи, соатсоз, кончи, фаррош, қоровул, техник, кўчмас мулк, ижтимоий хизмат, дафн маросими хизматлари, махфий хизматлар, металлга ишлов бериш, фойдали қазилмалар, антиквариат, тунги иш, ер ости иши, ақлан оғир иш, жисмонан оғир иш. Шунингдек шеригингиз шу машғулотлардан бўлиши ёки севиб қолиб, сиз улар билан шуғуллана бошлашингиз мумкин.","Профессии и сферы деятельности:":"Касблар ва фаолият соҳалари:","Собственный бизнес, менеджер, администратор, банкир, биржа, спекуляции, инвестор, директор, юриспруденция, финансы, налоги, чиновник, политик, страхование, врач, медицина, режиссер, шоу-бизнес, заработок от хобби, актер, креатив, дизайн, оратор, писатель, мода, ювелир, антиквариат, учитель творческих, управляющих сфер и учитель личностного роста, работа с детьми, управляющие должности, творческие профессии.":"Шахсий бизнес, менежер, администратор, банкир, биржа, спекуляциялар, инвестор, директор, юриспруденция, молия, солиқлар, амалдор, сиёсатчи, суғурта, шифокор, тиббиёт, режиссёр, шоу-бизнес, хоббидан даромад, актёр, креатив, дизайн, нотиқ, ёзувчи, мода, заргар, антиквариат, ижодий, бошқарув соҳалари ўқитувчиси ва шахсий ўсиш ўқитувчиси, болалар билан ишлаш, бошқарув лавозимлари, ижодий касблар.","Деньги от своих усилий, от своей внешности, своего имиджа и личного бренда. Производите неизгладимое впечатление на людей, выходите в социум с сигналом «Я на коне, я – царь!». Центральное место в финансах занимает личная активность, личная власть и «Я» человека. Приобретайте статусные атрибуты. Все зависит от вас самих, харизмы и силы духа.":"Пул ўз саъй-ҳаракатларингиздан, ташқи кўринишингиздан, имижингиз ва шахсий брендингиздан. Одамларда унутилмас таассурот қолдирасиз, жамиятга «Мен отдаман, мен — подшоҳман!» сигнали билан чиқасиз. Молияда марказий ўринни шахсий фаоллик, шахсий ҳокимият ва инсоннинг «Мен»и эгаллайди. Мақом атрибутларини сотиб олинг. Ҳаммаси ўзингизга, харизма ва руҳ кучига боғлиқ.","Что мешает зарабатывать:":"Пул топишга нима халақит беради:","Лень, тщеславие, эгоизм, вялый ум и отсутствие ясности будущего и целей, безответственность, зависимость от мнений окружающих, когда вы не держите свое слово, враждебны к миру, унываете и не улыбаетесь, проявляете жадность и претензии к окружающим, высокомерие и неуверенность в себе, неуважение, в т.ч. и к отцу и мужскому полу, длительный гнев, когда вы властью причиняете страдания другим и кайфуете от этого, слабый голос, мямленье. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Дангасалик, шуҳратпарастлик, худбинлик, суст ақл ва келажак ва мақсадлар аниқлигининг йўқлиги, масъулиятсизлик, атрофдагилар фикрига қарамлик, сўзингизда турмаганингизда, дунёга душманлик қилганингизда, тушкунликка тушиб, жилмаймаганингизда, очкўзлик ва атрофдагиларга даъволар билдирганингизда, кибр ва ўзингизга ишончсизлик, ҳурматсизлик, жумладан отага ва эркак жинсига, узоқ давом этадиган ғазаб, ҳокимият билан бошқаларга азоб берганингизда ва бундан роҳатланганингизда, заиф овоз, ғўлдираш. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Педагог, еда и напитки, сельское хозяйство, дипломат, повар, недвижимость, отели, рестораны, дома отдыха, моряк, няня, массажист, пекарня, кондитерская, туризм, сфера массового обслуживания, медицина, писатель, психолог, домохозяйка, химик, врач, целитель, продукты, импорт/экспорт, реклама, журналистика, искусство, биолог, одежда, продавец, консультант, семейный бизнес, окружающая среда, народная музыка, снабжение, мебель и уют, все что связано с партнерством, материнством, домом, забота о людях и творчество от души.":"Педагог, овқат ва ичимликлар, қишлоқ хўжалиги, дипломат, ошпаз, кўчмас мулк, меҳмонхоналар, ресторанлар, дам олиш уйлари, денгизчи, энага, массажчи, нонвойхона, қандолатхона, туризм, оммавий хизмат кўрсатиш соҳаси, тиббиёт, ёзувчи, психолог, уй бекаси, кимёгар, шифокор, табиб, озиқ-овқат, импорт/экспорт, реклама, журналистика, санъат, биолог, кийим, сотувчи, маслаҳатчи, оилавий бизнес, атроф-муҳит, халқ мусиқаси, таъминот, мебель ва қулайлик, шериклик, оналик, уй билан боғлиқ ҳамма нарса, одамларга ғамхўрлик ва қалбдан ижод.","Деньги от сотрудничества с кем-либо, от привлечения женщин в работу, стараться не заниматься заработками в одиночку, привлекайте родственников. Доверяйте своей интуиции, финансовые решения принимайте по сердцу, а не по уму. Развивайте чувствительность, умение сканировать обстановку и зарабатывать на том, что вы приспосабливаетесь быстрее всех. Приветствуйте собственную зависимость, притворяйтесь слабым, просите деньги у более сильных, стремитесь быть нужным. Также приветствуйте свои эмоциональные перекосы в виде боязни бедности, нестабильности и незащищенности, это помогает вам зарабатывать.":"Пул кимдир билан ҳамкорликдан, ишга аёлларни жалб қилишдан, ёлғиз пул топиш билан шуғулланмасликка ҳаракат қилинг, қариндошларни жалб қилинг. Интуициянгизга ишонинг, молиявий қарорларни ақл билан эмас, юрак билан қабул қилинг. Сезгирликни, вазиятни сканерлаш ва ҳаммадан тезроқ мослашишингиз ҳисобига пул топиш кўникмасини ривожлантиринг. Ўз қарамлигингизни олқишланг, ўзингизни заиф қилиб кўрсатинг, кучлироқлардан пул сўранг, керакли бўлишга интилинг. Шунингдек камбағаллик, беқарорлик ва ҳимоясизликдан қўрқиш кўринишидаги ҳиссий оғишларингизни олқишланг, бу сизга пул топишга ёрдам беради.","Фобии, страхи, безумие, уныние, депрессии и депрессии независимо от обстоятельств, ненависть к матерям, ненависть к детям, претензии к жизни, большая мнительность, большое количество кофе и алкоголя, подавление эмоций, когда сложно понять, что делать из- за постоянных беспокойств, сильные неуправляемые эмоции, потребительское отношение к людям, неспокойный ум. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Фобиялар, қўрқувлар, телбалик, тушкунлик, депрессиялар ва шароитлардан қатъи назар депрессиялар, оналарга нафрат, болаларга нафрат, ҳаётга даъволар, катта шубҳаланувчанлик, кўп миқдорда қаҳва ва алкоголь, ҳисларни бостириш, доимий хавотирлар туфайли нима қилишни тушуниш қийин бўлганда, кучли бошқарилмайдиган ҳислар, одамларга истеъмолчи муносабат, нотинч ақл. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","собственный бизнес, сфера финансов, юрист, бухгалтер, туризм, дипломат, ювелир, преподавание, гид, историк, культурист, священник, педагог, врач, архитектор, ученый, инженер, политик, философ, издательское дело, писатель, переводчик, дизайнер, топ менеджер, наставничество, PR, СМИ, издательство,":"шахсий бизнес, молия соҳаси, юрист, бухгалтер, туризм, дипломат, заргар, ўқитиш, гид, тарихчи, культурист, руҳоний, педагог, шифокор, меъмор, олим, муҳандис, сиёсатчи, файласуф, ноширлик иши, ёзувчи, таржимон, дизайнер, топ-менеджер, устозлик, PR, ОАВ, нашриёт,","Деньги от мужа, от высокого социального статуса, от высшего образования (нужно получить его или преподавать в вузах). В деньгах огромный потенциал на миллионерство. Деньги от крупных, мировых или глобальных проектов. Авторитетность и имя дают большие материальные возможности. Под вас могут даже создавать должность, которых до этого не существовало.":"Пул эрдан, юқори ижтимоий мақомдан, олий маълумотдан (уни олиш ёки олий ўқув юртларида дарс бериш керак). Пулда миллионерликка улкан салоҳият бор. Пул йирик, жаҳон ёки глобал лойиҳалардан. Обрў ва ном катта моддий имкониятлар беради. Сиз учун ҳатто илгари мавжуд бўлмаган лавозим яратишлари мумкин.","Деньги приходят, когда вы оптимистичны и стремитесь двигаться вперед, расширяться, развиваться в любых сферах и духовно. Один из самых богатых чисел, потенциал на огромное богатство. Учитесь зарабатывать на масштабе, тянитесь к элитарным сферам, где можно блеснуть знаниями, быть идеологом и вдохновителем, проявлять неформальную моральную власть (церковь, советник руководителя крупной структуры), быть законодателем, духовным владыкой. Будьте щедрым и беззаботным в деньгах. Занимайтесь крупными коммерческими проектами, сложными, непонятными, не тратьте время на мелочи. Используйте уникальные методы работы и иностранные языки. Общайтесь с людьми высокого статуса с целью вашей протекции в будущем.":"Пул сиз оптимистик бўлганингизда ва олдинга ҳаракатланишга, кенгайишга, ҳар қандай соҳаларда ва маънавий ривожланишга интилганингизда келади. Энг бой сонлардан бири, улкан бойликка салоҳият. Миқёсда пул топишни ўрганинг, билимлар билан порлаш, мафкурачи ва илҳомлантирувчи бўлиш, норасмий маънавий ҳокимиятни намоён қилиш мумкин бўлган элитар соҳаларга интилинг (черков, йирик тузилма раҳбари маслаҳатчиси), қонун чиқарувчи, маънавий ҳукмдор бўлинг. Пулда саховатли ва бепарво бўлинг. Йирик тижорий лойиҳалар, мураккаб, тушунарсиз лойиҳалар билан шуғулланинг, майда-чуйдаларга вақт сарфламанг. Ноёб иш усуллари ва чет тилларидан фойдаланинг. Келажакда сизга ҳомийлик қилиш мақсадида юқори мақомли одамлар билан мулоқот қилинг.","Ставьте четкую цель и намеренно идите в эту сторону, снося любые препятствия на своем пути. Расширяйтесь, путешествуйте.":"Аниқ мақсад қўйинг ва йўлингиздаги ҳар қандай тўсиқларни бузиб, атайлаб шу томонга боринг. Кенгайинг, саёҳат қилинг.","«Черный пессимизм» и мрачный взгляд на жизнь, разрушительные, деструктивные идеи и насильственное мировоззрение и идеология, ненависть к старшим, к авторитетам, к учителям, грубая непочтительная речь и такое же поведение, постоянное осуждение других, полное отсутствие морали и нравственности, осуждение инако мыслящих, следование только тем моральным нормам, которые приводят к материальному прогрессу. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"«Қора пессимизм» ва ҳаётга хира қараш, бузғунчи, деструктив ғоялар ва зўравон дунёқараш ва мафкура, катталарга, обрўли кишиларга, устозларга нафрат, қўпол ҳурматсиз нутқ ва худди шундай хулқ, бошқаларни доимий қоралаш, ахлоқ ва одобнинг бутунлай йўқлиги, бошқача фикрлайдиганларни қоралаш, фақат моддий тараққиётга олиб келадиган ахлоқий меъёрларга амал қилиш. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Экономист, программист, юрист, исследования, интернет, электрика, компьютерщик, новые технологии, космическая техника, психология, психиатрия, анестезиолог, радио, телевидение, СМИ, наука, политика, детектив, фокусник, иллюзионист, экстрасенс, эзотерик, окружающая среда, метафизика, казино, алкоголь, яды, химия, наркотики, криминал, врач, секретные службы, порнография, киноиндустрия, писатели-фантасты.":"Иқтисодчи, дастурчи, юрист, тадқиқотлар, интернет, электрика, компьютерчи, янги технологиялар, космик техника, психология, психиатрия, анестезиолог, радио, телевидение, ОАВ, фан, сиёсат, детектив, фокусчи, иллюзионист, экстрасенс, эзотерик, атроф-муҳит, метафизика, казино, алкоголь, заҳарлар, кимё, гиёҳвандлик воситалари, жиноят, шифокор, махфий хизматлар, порнография, кино индустрияси, фантаст ёзувчилар.","Деньги от вашего духовного уровня развития, от стремления к расширению территории и расширению сознания, выход за пределы и преодоление препятствий, от щекочущих нервы ситуаций, от магии и эзотерики, от интуиции, при стремлении к натуральности и естественности, приверженности к реализму и реальности своих мечт, без иллюзий, при непривязанности к чему-либо и способностей видеть суть событий и людей, от интуиции, от способности зажигать толпу и вести ее за собой.":"Пул маънавий ривожланиш даражангиздан, ҳудудни кенгайтириш ва онгни кенгайтиришга интилишдан, чегаралардан чиқиш ва тўсиқларни енгишдан, асабни қитиқлайдиган вазиятлардан, сеҳр ва эзотерикадан, интуициядан, табиийлик ва ўзига хосликка интилганда, реализмга ва орзуларингизнинг реаллигига содиқликда, иллюзияларсиз, ҳеч нарсага боғланмаганда ва воқеалар ва одамларнинг моҳиятини кўриш қобилиятида, интуициядан, оломонни ёқиш ва уни ортидан эргаштириш қобилиятидан.","Сильные погружения в иллюзии, обманы, впадание в зависимости и в зависимости от химических веществ, алкоголь, пристрастия к издевательствам, жестокости, зависимость от виртуального мира, психические помутнения, бардак, хаос, оскорбления, грязь, пристрастие к искусственному и не естественному, фанатизм и стремление манипулировать, газлайтить. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Иллюзияларга кучли чўмиш, алдовлар, қарамликка ва кимёвий моддаларга қарамликка тушиш, алкоголь, мазах қилиш, шафқатсизликка мойиллик, виртуал дунёга қарамлик, руҳий хиралашишлар, тартибсизлик, хаос, ҳақоратлар, ифлослик, сунъий ва табиий бўлмаган нарсага мойиллик, фанатизм ва манипуляция қилиш, газлайтинг қилишга интилиш. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Импорт-экспорт, новые технологии, IT, библиотека, бизнесмен, бухгалтер, финансист, аудитор, аналитик, менеджер, математик, брокер, посредник, дилер, писатель, редактор, программист, ученый, учитель, лингвист, переводчик, маркетолог, пиарщик, астролог, нумеролог, секретарь, продавец, кассир, посредник, экскурсовод, курьер, ремесленник, фокусник, политик, пародист, водитель, средства связи, реклама, издательство, страхование, работа в СМИ, журналистика, логистика, работа-хобби, мошенничество, теневой бизнес, репортер, инженер, оценщик, актер.":"Импорт-экспорт, янги технологиялар, IT, кутубхона, бизнесмен, бухгалтер, молиячи, аудитор, таҳлилчи, менежер, математик, брокер, воситачи, дилер, ёзувчи, муҳаррир, дастурчи, олим, ўқитувчи, тилшунос, таржимон, маркетолог, пиарчи, астролог, нумеролог, котиба, сотувчи, кассир, воситачи, экскурсовод, курьер, ҳунарманд, фокусчи, сиёсатчи, пародист, ҳайдовчи, алоқа воситалари, реклама, нашриёт, суғурта, ОАВда ишлаш, журналистика, логистика, иш-хобби, фирибгарлик, яширин бизнес, репортёр, муҳандис, баҳоловчи, актёр.","Деньги от интеллекта, любопытства и коммуникативных качеств, идеальна торговля и любая сфера, предполагающая продажу/передачу информации, простые, быстрые операции в деньгах небольшого масштаба. Контакты и знакомства влияют на самореализацию и финансы, умение делать и доделывать дела последовательно, не все сразу, хорошо иметь несколько сразу источников заработка. Допускайте некий хаос и «ветер» в этих сферах, чтобы была динамика, обновление. Копите информацию, связи, телефоны, адреса. Раздавайте свои визитки, пишите о себе в соц. сетях, пишите о себе везде, где имеете возможность. Будьте легки на подъем. Имейте ясность в мышлении, имейте способность видеть картину целиком, способность к планированию. Четко определите цель жизни и знайте как к ней идти. Учитесь на чужих ошибках, учитесь и развивайте интеллект. Чувство юмора помогает зарабатывать, над собой в т. ч. Крепкие нервы и отличная память способствуют самореализации.":"Пул интеллектдан, қизиқувчанлик ва коммуникатив фазилатлардан, савдо ва маълумотни сотиш/узатишни назарда тутувчи ҳар қандай соҳа идеал, кичик миқёсдаги пулдаги оддий, тез операциялар. Алоқалар ва танишувлар ўзини рўёбга чиқариш ва молияга таъсир қилади, ишларни изчил, ҳаммасини бирданига эмас, қилиш ва охирига етказиш кўникмаси, бирданига бир нечта даромад манбаига эга бўлиш яхши. Динамика, янгиланиш бўлиши учун бу соҳаларда қандайдир хаос ва «шамол»га йўл қўйинг. Маълумот, алоқалар, телефонлар, манзилларни тўпланг. Визиткаларингизни тарқатинг, ижтимоий тармоқларда ўзингиз ҳақингизда ёзинг, имконингиз бор ҳамма жойда ўзингиз ҳақингизда ёзинг. Енгил кўтариладиган бўлинг. Фикрлашда аниқликка эга бўлинг, манзарани бутунлигича кўриш қобилиятига, режалаштириш қобилиятига эга бўлинг. Ҳаёт мақсадини аниқ белгиланг ва унга қандай боришни билинг. Бировнинг хатоларидан ўрганинг, ўрганинг ва интеллектни ривожлантиринг. Юмор ҳисси пул топишга ёрдам беради, жумладан ўзингиз устидан. Мустаҳкам асаблар ва аъло хотира ўзини рўёбга чиқаришга ёрдам беради.","Расфокус, закрытость, необщительность, хаотичная и бестолковая активность, или вялость и апатичность, бессмысленная болтовня, сплетни, интриги, осуждение и критика других, оскорбления. Отсутствие цели в жизни, нежелание учиться, поверхностность, поведение, когда «жизнь ничему не учит», уроки даются, а в ответ агрессия. Отсутствие чувства юмора, импульсивность и беспокойства. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Диққатнинг тарқоқлиги, ёпиқлик, камгаплик, хаотик ва маъносиз фаоллик, ёки лоқайдлик ва бефарқлик, маъносиз вайсаш, ғийбатлар, фитналар, бошқаларни қоралаш ва танқид қилиш, ҳақоратлар. Ҳаётда мақсаднинг йўқлиги, ўқишни истамаслик, юзакилик, «ҳаёт ҳеч нарсага ўргатмайдиган» хулқ, сабоқлар берилади, жавобан эса тажовуз. Юмор ҳиссининг йўқлиги, импульсивлик ва хавотирлар. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Мода, искусство, музыка, танцы, сфера развлечений, сфера красоты, массажист, косметолог, парикмахер, дизайнер, художник, гравер, ремесленник, иллюстратор, артист, портной, кондитер, антиквариат, горничная, казино, эксклюзивные товары, ювелирный бизнес, гостиничный бизнес, организация праздников, фотограф, цветовод, проституция, секретарь, декоратор, сфера отдыха, деньги от хобби и любимых занятий, кондитеры, цветы.":"Мода, санъат, мусиқа, рақслар, кўнгилочар соҳа, гўзаллик соҳаси, массажчи, косметолог, сартарош, дизайнер, рассом, ўймакор, ҳунарманд, иллюстратор, артист, тикувчи, қандолатчи, антиквариат, хизматкор, казино, эксклюзив товарлар, заргарлик бизнеси, меҳмонхона бизнеси, байрамлар ташкил этиш, фотограф, гулчи, фоҳишабозлик, котиба, декоратор, дам олиш соҳаси, хобби ва севимли машғулотлардан пул, қандолатчилар, гуллар.","Деньги от умения контролировать свои желания и управлять ими, от женственности, красоты, гармонии с миром, от умения строить отношения, от женского пола. Проявление доброжелательности помогает в самореализации. Любовь и любовные отношения влияют на финансовую сферу. Умение нравиться людям приносит богатство. Радость жизни и удовольствия от нее прямо влияют на финансы. Деньги на комфорт и семью.":"Пул истакларингизни назорат қилиш ва уларни бошқариш кўникмасидан, аёлликдан, гўзалликдан, дунё билан уйғунликдан, муносабатлар қуриш кўникмасидан, аёл жинсидан. Хайрихоҳликни намоён қилиш ўзини рўёбга чиқаришда ёрдам беради. Севги ва севги муносабатлари молиявий соҳага таъсир қилади. Одамларга ёқиш кўникмаси бойлик келтиради. Ҳаёт қувончи ва ундан лаззатланиш молияга бевосита таъсир қилади. Пул қулайлик ва оила учун.","Неспособность контролировать свои желания и поступки, сексуальные в том числе. Ненасытное вожделение, распутство, агрессия, грубость и привязанность к невежественному искусству. Отсутствие уважения к женщинам. Желание насмехаться над людьми, публично высмеивать, грязь и беспорядок. Не украшение себя и не одевание себя в красивые одежды, неопрятность, нельзя конфликтовать, излишне привязываться к материальному, не учитывая мораль, душу и человечность. Не грубите и относитесь почтительно к людям. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Истаклар ва хатти-ҳаракатларингизни, жумладан жинсийларини назорат қила олмаслик. Тўймас шаҳват, бузуқлик, тажовуз, қўполлик ва жоҳил санъатга боғланиш. Аёлларга ҳурматнинг йўқлиги. Одамларни масхара қилиш, омма олдида кулги қилиш истаги, ифлослик ва тартибсизлик. Ўзингизни безатмаслик ва чиройли кийимлар киймаслик, саришталикнинг йўқлиги, низолашиш, ахлоқ, қалб ва инсонийликни ҳисобга олмай моддий нарсага ҳаддан ташқари боғланиш мумкин эмас. Қўполлик қилманг ва одамларга ҳурмат билан муносабатда бўлинг. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","медицина, психология, яды, химия, наука, дизайнер, биолог, зоолог, электрик, целительство, Аюрведа, эзотерика, оккультизм, теология, религия, священник, шитье, духовные практики, учитель йоги, астролог, таролог, нумеролог, программист, метеорология, интернет, компьютерщик, секретные службы, шпион, философия.":"тиббиёт, психология, заҳарлар, кимё, фан, дизайнер, биолог, зоолог, электрик, табиблик, Аюрведа, эзотерика, оккультизм, теология, дин, руҳоний, тикиш, маънавий амалиётлар, йога ўқитувчиси, астролог, таролог, нумеролог, дастурчи, метеорология, интернет, компьютерчи, махфий хизматлар, жосус, фалсафа.","Деньги от использования интуиции и проницательности, от новых технологий и гаджетов, от непредсказуемого и непонятного поведения и такой же стратегии, от способности не привязываться, от глубокого понимания духовности и мистических способностей. Умение отстраняться от всех. Аскетичный образ жизни влияет на финансы в лучшую сторону.":"Пул интуиция ва зийракликдан фойдаланишдан, янги технологиялар ва гаджетлардан, олдиндан айтиб бўлмайдиган ва тушунарсиз хулқ ва худди шундай стратегиядан, боғланмаслик қобилиятидан, маънавиятни чуқур тушуниш ва мистик қобилиятлардан. Ҳаммадан узоқлаша олиш кўникмаси. Зоҳидона ҳаёт тарзи молияга яхши томонга таъсир қилади.","Проблемы с самоидентификацией, большие страхи, необоснованный гнев, крайне импульсивное поведение, консерватизм и нежелание принимать перемены в жизни. Тенденции к саморазрушению, огромная неуверенность в себе, желание отдалиться от мира, отсутствие концентрации, противоречие ваших действий логике и здравому смыслу. Отсутствие духовности и активной внутренней жизни. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Ўзини аниқлаш билан муаммолар, катта қўрқувлар, асоссиз ғазаб, ўта импульсив хулқ, консерватизм ва ҳаётдаги ўзгаришларни қабул қилишни истамаслик. Ўзини емиришга мойиллик, ўзига улкан ишончсизлик, дунёдан узоқлашиш истаги, диққатнинг йўқлиги, хатти-ҳаракатларингизнинг мантиқ ва соғлом фикрга зидлиги. Маънавият ва фаол ички ҳаётнинг йўқлиги. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Политик, бизнесмен, чиновник, ученый, директор, финансист, администратор, юрист, судья, руководитель, гос. служба, промышленность, преподаватель, духовный учитель, врач, философ, психолог, астролог, нумеролог, аналитик, исследователь, строитель, часовщик, шахтер, уборщик, сторож, техник, недвижимость, архитектура, социальная служба, ритуальные услуги, секретные службы, металлообработка, полезные ископаемые, антиквариат, часы, ночная работа, подземная работа, умственно тяжелая работа, физически тяжелая работа.":"Сиёсатчи, бизнесмен, амалдор, олим, директор, молиячи, администратор, юрист, судья, раҳбар, давлат хизмати, саноат, ўқитувчи, маънавий устоз, шифокор, файласуф, психолог, астролог, нумеролог, таҳлилчи, тадқиқотчи, қурувчи, соатсоз, кончи, фаррош, қоровул, техник, кўчмас мулк, меъморчилик, ижтимоий хизмат, дафн маросими хизматлари, махфий хизматлар, металлга ишлов бериш, фойдали қазилмалар, антиквариат, соатлар, тунги иш, ер ости иши, ақлан оғир иш, жисмонан оғир иш.","Деньги приходят от своего труда, от постоянного труда. Необходимо получить высшее профессиональное образование, чтобы не работать физически трудно потом. Создавайте свое дело, свою систему, руководите строго и скрупулезно. Будьте пунктуальны, внедряйте расписание и режим в свою жизнь и в каждый день, распланируйте все, что может быть запланированным, определитесь с целями везде, где можно их поставить, в финансах тоже. Рассчитайте и просчитайте все свои действия, в финансовой сфере особенно. Везёт тому, кто везёт. Берите ответственность и свою жизнь в свои руки. Взрослейте. Будьте терпеливы и выносливы, преодолевайте все препятствия, опираясь на свой стальной внутренний стержень. Сосредоточьтесь и сконцентрируйтесь, относитесь ко всему серьезно. Следуйте законам и исполняйте все законы, какими бы они не были. Деньги приходят за счет власти и управления, когда вы наверху иерархии внутри частной или государственной организации, и забираете все больше и больше призов на каждой ступени. Важна жесткая дисциплина в деньгах, контроль и терпение. Можно адекватно жадничать и быть аскетом, рост за счет связей с людьми высокого статуса.":"Пул ўз меҳнатингиздан, доимий меҳнатдан келади. Кейин жисмонан оғир ишламаслик учун олий касбий маълумот олиш зарур. Ўз ишингизни, ўз тизимингизни яратинг, қатъий ва синчковлик билан раҳбарлик қилинг. Вақтга риояли бўлинг, ҳаётингизга ва ҳар бир кунга жадвал ва тартиб жорий этинг, режалаштирилиши мумкин бўлган ҳамма нарсани режалаштиринг, қўйиш мумкин бўлган ҳамма жойда, молияда ҳам мақсадларни аниқланг. Барча хатти-ҳаракатларингизни, айниқса молиявий соҳада ҳисоблаб чиқинг. Омад меҳнат қилганга кулиб боқади. Масъулиятни ва ҳаётингизни ўз қўлингизга олинг. Улғайинг. Пўлат ички ўзагингизга таяниб, сабрли ва чидамли бўлинг, барча тўсиқларни енгинг. Диққатингизни жамланг ва тўпланг, ҳамма нарсага жиддий муносабатда бўлинг. Қонунларга амал қилинг ва улар қандай бўлмасин барча қонунларни бажаринг. Пул ҳокимият ва бошқарув ҳисобига, сиз хусусий ёки давлат ташкилоти ичидаги иерархиянинг юқорисида бўлганингизда ва ҳар бир поғонада тобора кўпроқ мукофотларни олганингизда келади. Пулда қаттиқ интизом, назорат ва сабр муҳим. Адекват даражада хасислик қилиш ва зоҳид бўлиш мумкин, юқори мақомли одамлар билан алоқалар ҳисобига ўсиш.","Неспособность терпеть, глубочайшее уныние и угрюмость, депрессия, огромный страх и пустота в душе, претензии к другим, желание причинять боль и наказывать, лень и отсутствие дисциплины, неспособность выполнять свои обязанности, гордыня и способность предать, отсутствие концентрации. Неприятие критики, внутреннее напряжение и неспособность расслабляться. Отсутствие последовательности в действиях, и быстрое опускание рук и отступление назад. Избавьтесь от этих качеств для возможности полной самореализации и финансовой независимости.":"Сабр қила олмаслик, чуқур тушкунлик ва қовоғи солиқлик, депрессия, қалбдаги улкан қўрқув ва бўшлиқ, бошқаларга даъволар, оғриқ етказиш ва жазолаш истаги, дангасалик ва интизомнинг йўқлиги, мажбуриятларингизни бажара олмаслик, кибр ва хиёнат қилиш қобилияти, диққатнинг йўқлиги. Танқидни қабул қилмаслик, ички таранглик ва бўшаша олмаслик. Ҳаракатларда изчилликнинг йўқлиги ва тезда қўлни тушириб, орқага чекиниш. Тўлиқ ўзини рўёбга чиқариш ва молиявий мустақиллик имконияти учун бу фазилатлардан қутулинг.","Спорт, бизнесмен, полиция, таможенник, налоговый инспектор, автогонщик, командир, летчик, военный, солдат, снайпер, пожарный, медицина, хирург, металлург, механик, машинист, водитель, мясник, зубной врач, охранник, слесарь, лесоруб, мясник, боевые искусства, охотник, оружие, судебная система, криминал, индивидуальное предпринимательство, темы секса, ремонт.":"Спорт, бизнесмен, полиция, божхоначи, солиқ инспектори, автопойгачи, қўмондон, учувчи, ҳарбий, аскар, снайпер, ўт ўчирувчи, тиббиёт, жарроҳ, металлург, механик, машинист, ҳайдовчи, қассоб, тиш шифокори, қўриқчи, чилангар, ўтинчи, қассоб, жанговар санъатлар, овчи, қурол, суд тизими, жиноят, якка тартибдаги тадбиркорлик, жинсий мавзулар, таъмирлаш.","Деньги от своих усилий, как потопаешь – так и полопаешь, можно быть агрессором и брать напором, воспринимать заработки как поле боя, кто смел, тот и съел, делать деньги на простых, элементарных быстрых задачах, можно быть немного безалаберным, легко пришло – легко ушло. Соревноваться и конкурировать с собой из прошлого или с кем-то. Ресурсы берутся напором и важна сила воли.":"Пул ўз саъй-ҳаракатларингиздан, нима эксанг шуни ўрасан, тажовузкор бўлиш ва шижоат билан олиш, даромадларни жанг майдони сифатида қабул қилиш мумкин, ким жасур бўлса, ўша ютади, оддий, элементар тез вазифаларда пул қилиш, бироз бепарво бўлиш мумкин, осон келди — осон кетди. Ўтмишдаги ўзингиз ёки кимдир билан мусобақалашиш ва рақобатлашиш. Ресурслар шижоат билан олинади ва ирода кучи муҳим.","Мешают зарабатывать деньги договоренности, партнерство, болтовня вместо действий. Лень и трусость, агрессия ко всем, даже к тем, кто когда – то пытался помочь, жестокость, гнев, грубость и нецензурная брань.":"Пул топишга келишувлар, шериклик, ҳаракат ўрнига вайсаш халақит беради. Дангасалик ва қўрқоқлик, ҳаммага, ҳатто қачондир ёрдам беришга уринганларга ҳам тажовуз, шафқатсизлик, ғазаб, қўполлик ва сўкиниш.","Вы проявляете заботу сухо, не эмоционально, если двойка – это поддержка, то -2 – это как бесчувственность в этом плане. Вы можете просто сказать «не переживай, не плачь» и все. Могут быть нездоровые отношения. Или вообще закрываетесь, когда о ком-то нужно позаботиться. Вы можете быть чрезмерно чувствительны и впечатлительны, обидчивы на то, как о вас заботятся, истеричны при заботе о других или боитесь заботиться о людях. Сами склонны жаловаться на жизнь и выражать недовольство. Можете считать, что вы не достойны заботы.":"Сиз ғамхўрликни қуруқ, ҳиссиз намоён қиласиз, агар иккилик — бу қўллаб-қувватлаш бўлса, -2 — бу жиҳатдан бефарқлик кабидир. Сиз шунчаки «хавотирланма, йиғлама» дейишингиз мумкин, тамом. Носоғлом муносабатлар бўлиши мумкин. Ёки кимгадир ғамхўрлик қилиш керак бўлганда умуман ёпилиб оласиз. Сиз ҳаддан ташқари сезгир ва таъсирчан, сизга қандай ғамхўрлик қилишларидан хафа бўлувчи, бошқаларга ғамхўрлик қилганда асабий бўлишингиз ёки одамларга ғамхўрлик қилишдан қўрқишингиз мумкин. Ўзингиз ҳаётдан шикоят қилишга ва норозилик билдиришга мойилсиз. Ўзингизни ғамхўрликка лойиқ эмас деб ҳисоблашингиз мумкин.","У вас может быть излишняя требовательность к себе при заботе о других, так же и к другим, которые заботятся о вас. Вы можете вести себя эгоистично и высокомерно в ситуация заботы. Можете заниматься самолюбованием, получая или отдавая заботу, хвастаетесь, если о ком-то позаботились или о вас кто-то. Склонны при заботе насиловать волю других людей, использовать их в своих, иногда, корыстных целях. Заботитесь, увлекая в чрезмерные земные наслаждения и удовольствия, которые в избытке даже не идут на пользу. Показушная забота. Заботитесь ради внимания и падки на лесть и похвалу.":"Бошқаларга ғамхўрлик қилганда ўзингизга, шунингдек сизга ғамхўрлик қиладиган бошқаларга ҳам ортиқча талабчанлигингиз бўлиши мумкин. Ғамхўрлик вазиятида худбин ва мағрур тутишингиз мумкин. Ғамхўрлик олиб ёки бериб, ўзингизга маҳлиё бўлишингиз, кимгадир ғамхўрлик қилсангиз ёки сизга кимдир ғамхўрлик қилса, мақтанишингиз мумкин. Ғамхўрлик қилганда бошқа одамлар иродасини зўрлашга, улардан ўз, баъзан, ғаразли мақсадларингизда фойдаланишга мойилсиз. Ортиқча бўлганда ҳатто фойдали бўлмайдиган ҳаддан ташқари дунёвий лаззатлар ва роҳатларга жалб қилиб ғамхўрлик қиласиз. Кўз-кўз қилиш учун ғамхўрлик. Эътибор учун ғамхўрлик қиласиз ва хушомад ва мақтовга ўчсиз.","Вы не умеете заботиться. Вам нужно в этой жизни учиться проявлять заботу вообще ко всему в мире, к себе в т. ч. Возможно, когда требуется забота вас нет рядом, либо вы чреземерно заботитесь и не даете продохнуть человеку от своей заботы, и вам всегда нужен тот, кому нужна ваша помощь. Найдите человека, у которого отдача в мир гармоничная, забота такая, какую вам хочется и учитесь у него. У вас либо недозабота либо переизбыток заботы, и к вам люди тоже так же. И еще вас могут окружать люди, которые без заботы не смогут обходиться и вы так научитесь заботиться.":"Сиз ғамхўрлик қилишни билмайсиз. Бу ҳаётда сизга умуман дунёдаги ҳамма нарсага, жумладан ўзингизга ғамхўрлик кўрсатишни ўрганиш керак. Эҳтимол, ғамхўрлик талаб қилинганда сиз ёнида бўлмайсиз, ёки ҳаддан ташқари ғамхўрлик қилиб, инсонга ғамхўрлигингиздан нафас олишга имкон бермайсиз ва сизга доим ёрдамингизга муҳтож бўлган кимдир керак. Дунёга бериши уйғун, ғамхўрлиги сиз истагандек бўлган инсонни топинг ва ундан ўрганинг. Сизда ё ғамхўрлик етишмайди, ё ғамхўрлик ортиқча, одамлар ҳам сизга худди шундай. Яна сизни ғамхўрликсиз яшай олмайдиган одамлар ўраб олиши мумкин ва сиз шундай қилиб ғамхўрлик қилишни ўрганасиз.","Вы заботитесь так, чтобы себя не обделить ни в чем при этом, также заботитесь тогда, когда хотите, независимо от чувств того, кому нужна ваша забота. Проявляетесь ярко и при этом хотите признания за свою заботу, чтобы вы были лучшим человеком в этот момент для того, кому даете заботу. Если вам не сильно выгодно заботиться, то желания этого делать у вас может не быть. О детях, муже и отце вы стараетесь заботиться всегда, можете заботиться только о тех, кого любите или кто больше любит вас. Ваша задача не обделять вниманием никого и научиться отдавать свою заботу и внимание всем, не разделяя их на какие-либо категории и выгодность вам, моральную или материальную. Вы очень радуетесь когда кому-либо нужно ваше внимание, это прибавляет вам жизненных сил. Иногда можете заботиться показушно, демонстративно. Можете устроить игру или театр для близкого, заботясь о нем.":"Сиз шундай ғамхўрлик қиласизки, бунда ўзингизни ҳеч нарсада камситмайсиз, шунингдек ғамхўрлигингиз керак бўлган инсоннинг ҳисларидан қатъи назар, истаганингизда ғамхўрлик қиласиз. Ёрқин намоён бўласиз ва бунда ғамхўрлигингиз учун тан олинишни, ғамхўрлик бераётган инсон учун шу лаҳзада энг яхши инсон бўлишни истайсиз. Агар ғамхўрлик қилиш сизга унча фойдали бўлмаса, буни қилиш истагингиз бўлмаслиги мумкин. Болалар, эр ва отага доим ғамхўрлик қилишга ҳаракат қиласиз, фақат севганларингиз ёки сизни кўпроқ севадиганларга ғамхўрлик қилишингиз мумкин. Сизнинг вазифангиз ҳеч кимни эътибордан четда қолдирмаслик ва ғамхўрлик ва эътиборингизни уларни қандайдир тоифаларга ва сизга маънавий ёки моддий фойдасига ажратмасдан, ҳаммага беришни ўрганиш. Кимгадир эътиборингиз керак бўлганда жуда қувонасиз, бу сизга ҳаётий куч қўшади. Баъзан кўз-кўз қилиб, намойишкорона ғамхўрлик қилишингиз мумкин. Яқин инсонга ғамхўрлик қилиб, унга ўйин ёки театр уюштиришингиз мумкин.","Вы очень заботливы, всегда поддержите, поймете. К вам приходят плакаться в жилетку. Вы добрым словом всегда поднимаете настроение. Может быть такое, что вы настолько проникаетесь, что вам самим становится плохо, если у человека что-то произошло. Не воспринимайте все близко к сердцу. Вы очень чувствительная натура. Вы всегда знаете, что нужно человеку сейчас и знаете как это реализовать от души. Вы вызываете доверие своей чуткостью и умением выслушать, и сказать нужное слово в нужное время. Вы помогаете побороть людям страхи, при этом сами не знаете как это происходит. Вы очень интуитивны. Вы очень быстро адаптируетесь под настроение человека, чтобы ему было комфортно, иногда даже забывая о себе. Можете привлекать детей к заботе над другим человеком, а также присоединяться к тем, кто уже проявляет внимание к кому-то из ваших близких. В любом случае вам всегда нужен сигнал, о том, что вы сейчас нужны и требуется ваша поддержка.":"Сиз жуда ғамхўрсиз, доим қўллаб-қувватлайсиз, тушунасиз. Сизга дардини тўкиб солгани келишади. Сиз доим яхши сўз билан кайфиятни кўтарасиз. Шундай бўлиши мумкинки, инсонда нимадир юз берса, шунчалик берилиб кетасизки, ўзингиз ёмон бўлиб қоласиз. Ҳамма нарсани юракка яқин олманг. Сиз жуда сезгир табиатсиз. Сиз доим инсонга ҳозир нима кераклигини биласиз ва буни қалбдан қандай амалга оширишни биласиз. Сиз ўз сезгирлигингиз ва тинглай олиш, керакли сўзни керакли вақтда айта олиш кўникмаси билан ишонч уйғотасиз. Сиз одамларга қўрқувларни енгишга ёрдам берасиз, бунда ўзингиз бу қандай содир бўлишини билмайсиз. Сиз жуда интуитивсиз. Инсонга қулай бўлиши учун унинг кайфиятига жуда тез мослашасиз, баъзан ҳатто ўзингизни унутиб. Болаларни бошқа инсонга ғамхўрлик қилишга жалб қилишингиз, шунингдек яқинларингиздан бирига аллақачон эътибор кўрсатаётганларга қўшилишингиз мумкин. Ҳар ҳолда сизга доим ҳозир кераклигингиз ва қўллаб-қувватлашингиз талаб қилинаётгани ҳақида сигнал керак.","В заботе вы авторитет, вы суперски умеете заботиться, если захотите, но захотите вы редко, т.к дел много. Оптимистичны, радостны, позитивны, весело и на высшем уровне заботитесь о людях и о себе. Вы богаты своей заботой. К вам люди относятся так же. Вы опираетесь на духовность и веру в Бога при заботе, учитываете божественные законы. Можете стремиться использовать все импортное или очень дорогое. Опираетесь на писания авторитетных источников, если это требуется и можете любого научить заботиться максимально эффективно. Возможно, вам после или вместо заботы хочется отдалиться и освободиться, и поменять обстановку. Можете просить кого-то заботиться вместо вас, а также люди сами предлагают сделать что-то вместо вас. Или заботитесь на расстоянии. Впрочем, скорее всего вы сильно заняты всегда.":"Ғамхўрликда сиз обрўсиз, истасангиз, жуда зўр ғамхўрлик қила оласиз, лекин камдан-кам истайсиз, чунки ишлар кўп. Оптимистик, қувноқ, ижобий, хурсандчилик билан ва энг юқори даражада одамларга ва ўзингизга ғамхўрлик қиласиз. Сиз ғамхўрлигингиз билан бойсиз. Одамлар сизга ҳам худди шундай муносабатда бўлади. Ғамхўрлик қилганда маънавият ва Худога ишончга таянасиз, илоҳий қонунларни ҳисобга оласиз. Ҳамма импорт ёки жуда қиммат нарсадан фойдаланишга интилишингиз мумкин. Агар бу талаб қилинса, обрўли манбалар битикларига таянасиз ва ҳар кимни энг самарали ғамхўрлик қилишга ўргата оласиз. Эҳтимол, ғамхўрликдан кейин ёки унинг ўрнига узоқлашиш ва озод бўлиш, вазиятни ўзгартиришни истайсиз. Кимдандир сизнинг ўрнингизга ғамхўрлик қилишни сўрашингиз мумкин, шунингдек одамлар ўзлари сизнинг ўрнингизга нимадир қилишни таклиф қилади. Ёки масофадан ғамхўрлик қиласиз. Дарвоқе, эҳтимол сиз доим жуда бандсиз.","Вы можете создавать иллюзию заботы, но толком этого не делать. Вы можете заботиться обманывая, якобы «ложь во благо». Забота может быть конфликтная, вы можете заботиться хаотично, что становится только хуже или просто делать вид, что заботитесь. Можете считать фарму и алкоголь (или токсичные вещества, меняющие сознание) заботой. В лучших случаях забота может быть чрезмерной, и если не давать возможность заботиться, то вы будете истерить “ почему не даете мне заботиться?».":"Сиз ғамхўрлик иллюзиясини яратишингиз, лекин буни тузукроқ қилмаслигингиз мумкин. Сиз алдаб, гўёки «яхшилик учун ёлғон» билан ғамхўрлик қилишингиз мумкин. Ғамхўрлик низоли бўлиши мумкин, сиз хаотик ғамхўрлик қилишингиз мумкин, бу фақат ёмонлаштиради, ёки шунчаки ғамхўрлик қилаётгандек кўрсатишингиз мумкин. Дори-дармон ва алкоголни (ёки онгни ўзгартирувчи заҳарли моддаларни) ғамхўрлик деб ҳисоблашингиз мумкин. Энг яхши ҳолларда ғамхўрлик ҳаддан ташқари бўлиши мумкин ва агар ғамхўрлик қилишга имкон берилмаса, сиз «нега менга ғамхўрлик қилишга йўл қўймаяпсизлар?» деб асабийлашасиз.","Вас кидает из крайности в крайность, можете душить своей заботой или вас нет, когда надо. Вы умеете очень хорошо заботиться, если все по полочкам и по плану у вас. У вас переменчивая природа и заботливость может проявляться из страха.":"Сизни бир ҳаддан бошқасига ташлайди, ғамхўрлигингиз билан бўғишингиз ёки керак бўлганда йўқ бўлишингиз мумкин. Агар ҳаммаси жой-жойида ва режа бўйича бўлса, сиз жуда яхши ғамхўрлик қила оласиз. Сизда ўзгарувчан табиат бор ва ғамхўрлик қўрқувдан намоён бўлиши мумкин.","Вы заботитесь с умом, сообразительностью и рациональностью. Общение и есть ваша забота, вы всегда поговорите с человеком. Забота может напоминать дружбу или отношения как к брату, сестре. Вы заботитесь, окутывая человека легкостью, весельем, дружелюбием, приколами и интересными историями. Можете увезти, сменить обстановку или пригласить в гости, или в театр, или в кино, туда где есть люди и где можно общаться или знакомиться. Катаете на машине или просто отправляетесь гулять. От вашей заботы легко на душе, у вас очень развита смекалка и это всегда то, что нужно человеку, даже если он сам еще этого не понял.":"Сиз ақл, зийраклик ва рационаллик билан ғамхўрлик қиласиз. Мулоқот — сизнинг ғамхўрлигингиз, сиз доим инсон билан гаплашасиз. Ғамхўрлик дўстликни ёки ака-ука, опа-сингилга бўлган муносабатни эслатиши мумкин. Сиз инсонни енгиллик, қувноқлик, дўстона муносабат, ҳазиллар ва қизиқарли ҳикоялар билан ўраб ғамхўрлик қиласиз. Олиб кетишингиз, вазиятни ўзгартиришингиз ёки меҳмонга, ёки театрга, ёки кинога, одамлар бор ва мулоқот қилиш ёки танишиш мумкин бўлган жойга таклиф қилишингиз мумкин. Машинада сайр қилдирасиз ёки шунчаки сайрга чиқасиз. Ғамхўрлигингиздан қалб енгил тортади, сизда зийраклик жуда ривожланган ва бу доим инсонга керак бўлган нарса, ҳатто у ўзи буни ҳали тушунмаган бўлса ҳам.","Вы заботитесь так, чтобы человеку было комфортно, приятно, красиво, удобно и с большим добром. От вашей заботы в вас влюбляются люди, вы заботитесь прекрасно, с любовью и уже своей сильной энергетикой поправляете состояние людям. От вас веет радостью, истиной, ресурсом и искренним желанием привести человека к хорошему. Вы очень бережно относитесь к людям, требующим заботы. Вы все помните, что и когда нужно делать. В заботе вы аккуратны, ответственны и делаете то, в чем именно сейчас нуждается человек, даже если он не сказал вам еще этого. Вы чувствуете. Заботитесь, доставляя удовольствие. Исцеляете людей своим присутствием. А так же можете тратить деньги и дарить подарки в виде заботы.":"Сиз инсонга қулай, ёқимли, чиройли, шинам ва катта эзгулик билан бўлиши учун ғамхўрлик қиласиз. Ғамхўрлигингиздан одамлар сизни севиб қолади, сиз ажойиб, севги билан ғамхўрлик қиласиз ва кучли энергетикангизнинг ўзи билан одамлар ҳолатини тузатасиз. Сиздан қувонч, ҳақиқат, ресурс ва инсонни яхшиликка олиб бориш учун самимий истак эсади. Сиз ғамхўрлик талаб қиладиган одамларга жуда эҳтиёткорлик билан муносабатда бўласиз. Нимани ва қачон қилиш кераклигини ҳаммасини эслайсиз. Ғамхўрликда сиз аниқ, масъулиятли ва инсон айнан ҳозир муҳтож бўлган нарсани, ҳатто у сизга буни ҳали айтмаган бўлса ҳам қиласиз. Сиз ҳис қиласиз. Лаззат бағишлаб ғамхўрлик қиласиз. Одамларни ўз борлигингиз билан даволайсиз. Шунингдек ғамхўрлик сифатида пул сарфлашингиз ва совғалар беришингиз мумкин.","Вы сами в своей жизни определяете то, как будут развиваться события, вы сами режиссер своей жизни. Вам также могут помогать начальники и отец, отчим, государство. Вам помогает ваше ответственное отношение ко всему, возможность управлять и руководить, ваши лидерские качества. Ваш внешний вид и открытость к миру открывают для вас большие перспективы. Не бойтесь проявлять себя миру, показывать кто вы есть, рассказывайте о себе на каж- дом углу. Создайте визитки о себе и своей деятельности и каждому отдавайте и оставляйте везде, где можно. Напечатайте на своей машине о ваших проектах, делайте баннеры по городу и рекламу в интернете и телевидении.":"Ҳаётингизда воқеалар қандай ривожланишини ўзингиз белгилайсиз, сиз ҳаётингизнинг ўзингиз режиссёрисиз. Сизга шунингдек бошлиқлар ва ота, ўгай ота, давлат ёрдам бериши мумкин. Сизга ҳамма нарсага масъулиятли муносабатингиз, бошқариш ва раҳбарлик қилиш имконияти, етакчилик фазилатларингиз ёрдам беради. Ташқи кўринишингиз ва дунёга очиқлигингиз сиз учун катта истиқболларни очади. Ўзингизни дунёга намоён қилишдан, кимлигингизни кўрсатишдан қўрқманг, ҳар бир бурчакда ўзингиз ҳақингизда гапиринг. Ўзингиз ва фаолиятингиз ҳақида визиткалар яратинг ва ҳар кимга беринг ва мумкин бўлган ҳамма жойда қолдиринг. Машинангизга лойиҳаларингиз ҳақида ёзиб қўйинг, шаҳар бўйлаб баннерлар ва интернет ва телевидениеда реклама қилинг.","Будьте честны и ярки, явите себя миру – вы прекрасны. Презентуйте себя везде, где только можно, в вашей жизни возможности зависят от того, как вы говорите о себе сами, как вы заявляете о себе. Создавайте личный бренд. Идите в социум с посылом «Я на коне, Я – царь!». Создавайте свой имидж и следите за тем, чтобы вы производили неизгладимое впечатление на людей, чтобы запоминаться ярким, харизматичным специалистом. Вам не желательно договариваться, решайте сами, смело и открыто тяните одеяло на себя. Ваша личная власть и активность дает возможности для того, чтобы осуществить задуманное.":"Ҳалол ва ёрқин бўлинг, ўзингизни дунёга намоён қилинг — сиз ажойибсиз. Мумкин бўлган ҳамма жойда ўзингизни тақдим этинг, ҳаётингиздаги имкониятлар ўзингиз ҳақингизда қандай гапиришингизга, ўзингизни қандай эълон қилишингизга боғлиқ. Шахсий бренд яратинг. Жамиятга «Мен отдаман, Мен — подшоҳман!» деган ғоя билан боринг. Имижингизни яратинг ва ёрқин, харизматик мутахассис сифатида эсда қолиш учун одамларда унутилмас таассурот қолдиришингизни кузатинг. Сизга келишиш исталмайди, ўзингиз ҳал қилинг, жасорат билан ва очиқ кўрпани ўзингизга тортинг. Шахсий ҳокимиятингиз ва фаоллигингиз режалаштирганингизни амалга ошириш учун имкониятлар беради.","Творчество, свидания, игры, любовь, ваше авторское искусство открывают вам все двери. Действуйте вдохновенно, используйте свои хобби в достижении своих целей и получайте удовольствие от того, чем вы заняты.":"Ижод, учрашувлар, ўйинлар, севги, муаллифлик санъатингиз сизга барча эшикларни очади. Илҳом билан ҳаракат қилинг, мақсадларингизга эришишда хоббиларингиздан фойдаланинг ва машғул бўлган ишингиздан лаззат олинг.","Вам помогают в жизни связь с родственниками, мама, дети. Изменения и непостоянство событий, то, что вы занимаете второе место и всегда находитесь за кем-то в жизни помогает вам. Дом и семья, связь с подсознанием и ваши психологические способности видеть суть и понимать людей интуитивно. Ваша способность адаптироваться и изменяться, перепады настроения, материнство. Способность делать все качественно в соответствии с регламентом, Серьезное отношение к зачатию и воспитанию детей, заботливость. Отказ от кофе и алкоголя, от любой вредной воды помогает в здоровье. Хорошая память помогает не сбиться с пути. Полный контроль и осознание своих эмоций, спокойный ум, умиротворение, удовлетворение и независимость. Откажитесь от постоянных беспокойств и суетливости, мнительности. Избегайте стрессов, неуправляемых эмоций и потребительства.":"Ҳаётда сизга қариндошлар, она, болалар билан алоқа ёрдам беради. Воқеаларнинг ўзгариши ва беқарорлиги, иккинчи ўринни эгаллашингиз ва ҳаётда доим кимнингдир ортида бўлишингиз сизга ёрдам беради. Уй ва оила, онгости билан алоқа ва моҳиятни кўриш ва одамларни интуитив тушуниш бўйича психологик қобилиятларингиз. Мослашиш ва ўзгариш қобилиятингиз, кайфият ўзгаришлари, оналик. Ҳамма нарсани регламентга мувофиқ сифатли қилиш қобилияти, ҳомиладорлик ва болалар тарбиясига жиддий муносабат, ғамхўрлик. Қаҳва ва алкоголдан, ҳар қандай зарарли сувдан воз кечиш саломатликда ёрдам беради. Яхши хотира йўлдан адашмасликка ёрдам беради. Ҳисларингизни тўлиқ назорат қилиш ва англаш, хотиржам ақл, осойишталик, қониқиш ва мустақиллик. Доимий хавотирлар ва шошқалоқлик, шубҳаланувчанликдан воз кечинг. Стресслар, бошқарилмайдиган ҳислар ва истеъмолчиликдан қочинг.","Вам помогают ваши знания, экспертность в вопросах, стремления к правде, искренности и честности, вера в лучшее, в высшие силы и оптимизм. Авторитетные люди вам дают новые возможности для роста, муж помогает и дети. У вас огромные возможности, умейте их видеть сквозь рамки, ограничения и пессимизм. Философский подход к жизни часто выручает вас и вы не реагируете гневно. Вера в бога и духовность позволяет вам выходить сухим из воды. Выполнение данных обещаний, отдача долгов, самообладание и честность открывают перед вами новые двери. Учителя и наставники двигают вас вперед. Ваше мировоззрение помогает не только вам, но и другим людям.":"Сизга билимларингиз, масалалардаги экспертлигингиз, ҳақиқатга, самимийлик ва ҳалолликка интилиш, яхшиликка, олий кучларга ишонч ва оптимизм ёрдам беради. Обрўли одамлар сизга ўсиш учун янги имкониятлар беради, эр ва болалар ёрдам беради. Сизда улкан имкониятлар бор, уларни чегаралар, чекловлар ва пессимизм орқали кўра билинг. Ҳаётга фалсафий ёндашув сизни тез-тез қутқаради ва сиз ғазаб билан муносабат билдирмайсиз. Худога ишонч ва маънавият сизга сувдан қуруқ чиқишга имкон беради. Берилган ваъдаларни бажариш, қарзларни қайтариш, ўзини тута билиш ва ҳалоллик олдингизда янги эшикларни очади. Устозлар ва мураббийлар сизни олдинга сурадилар. Дунёқарашингиз нафақат сизга, балки бошқа одамларга ҳам ёрдам беради.","Помогает ясность мышления, практичность, истинные желания, четкий план, способность читать между строк, постоянное самопознание, способность видеть суть, сила мысли и вера в свои сверхспособности. Осознание иллюзорности этого мира, умение распознавать обман и иллюзии, прекрасная интуиция. Регулярные медитации, принятие своих страхов, неожиданные внезапные незапланированные перемены в жизни помогают. Чистоплотность и стремление к естественности, натуральности, природному, отказ от искусственного и токсичного. Отказ от вредных привычек и зависимостей. Способность влиять на толпы людей. Упрямство, стабильность, способность преодолевать препятствия и критику в свой адрес. Трудолюбие, способность всегда быть в движении вперед, не стоять на месте. Твердость характера, способность рушить препятствия и возможность много бороться для своего развития и роста. Ясное представление о будущем ведет вас вперед максимально мягко, вырабатывайте его, знайте чего хотите достичь и как выглядит ваше будущее.":"Фикрлаш аниқлиги, амалийлик, ҳақиқий истаклар, аниқ режа, сатрлар орасини ўқиш қобилияти, доимий ўзини англаш, моҳиятни кўриш қобилияти, фикр кучи ва ўз ғайритабиий қобилиятларингизга ишонч ёрдам беради. Бу дунёнинг иллюзорлигини англаш, алдов ва иллюзияларни таний олиш кўникмаси, ажойиб интуиция. Мунтазам медитациялар, қўрқувларингизни қабул қилиш, ҳаётдаги кутилмаган тўсатдан режалаштирилмаган ўзгаришлар ёрдам беради. Озодалик ва табиийлик, ўзига хосликка, табиатга интилиш, сунъий ва заҳарли нарсадан воз кечиш. Зарарли одатлар ва қарамликлардан воз кечиш. Одамлар оломонига таъсир кўрсатиш қобилияти. Ўжарлик, барқарорлик, тўсиқларни ва ўзингизга қаратилган танқидни енгиш қобилияти. Меҳнатсеварлик, доим олдинга ҳаракатда бўлиш, бир жойда турмаслик қобилияти. Феълнинг қатъийлиги, тўсиқларни бузиш қобилияти ва ривожланиш ва ўсиш учун кўп курашиш имконияти. Келажак ҳақидаги аниқ тасаввур сизни максимал юмшоқ олдинга олиб боради, уни ишлаб чиқинг, нимага эришмоқчи эканлигингизни ва келажагингиз қандай кўринишини билинг.","Нужно договариваться, учиться, коммуницировать, много знакомиться и заводить друзей. Найдите учителя и получайте знания о всем, что вам интересно. Путешествуйте, стремитесь к свободе, равенству и братству. Избавляйтесь от расфокуса и суетливости. Тренируйте память и интеллект. Хорошее чувство юмора выручает. Вежливость, отсутствие эгоизма, принятие других, добрый нрав и игривость помогает получать новые возможности. Умение выслушать и услышать собеседника, ясность мышления, понимание своей цели в будущем и знание как к ней прийти. Легкость на подъем, разговорчивость, красноречие и ораторский талант. Способность быть подвижным, мобильным, свободным, не привязанным.":"Келишиш, ўқиш, мулоқот қилиш, кўп танишиш ва дўстлар орттириш керак. Устоз топинг ва сизни қизиқтирган ҳамма нарса ҳақида билим олинг. Саёҳат қилинг, эркинлик, тенглик ва биродарликка интилинг. Диққатнинг тарқоқлиги ва шошқалоқликдан қутулинг. Хотира ва интеллектни машқ қилдиринг. Яхши юмор ҳисси қутқаради. Хушмуомалалик, худбинликнинг йўқлиги, бошқаларни қабул қилиш, меҳрибон феъл ва ўйноқилик янги имкониятлар олишга ёрдам беради. Суҳбатдошни тинглай ва эшита олиш кўникмаси, фикрлаш аниқлиги, келажакдаги мақсадингизни тушуниш ва унга қандай етиб бориш ҳақидаги билим. Енгил кўтарилувчанлик, гапдонлик, нотиқлик ва нотиқлик истеъдоди. Ҳаракатчан, мобиль, эркин, боғланмаган бўлиш қобилияти.","Красота, доброта, богатство, финансовая независимость, умение зарабатывать деньги, девушки – все это помогает. Умение контролировать свои чувства и свои желания, не идти на поводу у своих низких желаний, и оставаться верным партнеру. Способность и желание делать людей счастливыми, удовлетворять их. Умение быть благодарным приносит в жизнь еще больше изобилия. Любовь ко всем и всему, радость и кайф, удовольствие и радость от жизни. Всегда довольна и с хорошим чувством юмора. Возможности появляются когда делаете то, что вам нравится, так же подруги ваши привлекают вам возможности и помогают.":"Гўзаллик, меҳрибонлик, бойлик, молиявий мустақиллик, пул топа олиш кўникмаси, қизлар — буларнинг барчаси ёрдам беради. Ҳислар ва истакларингизни назорат қилиш, паст истакларингизга эргашмаслик ва шерикка содиқ қолиш кўникмаси. Одамларни бахтли қилиш, уларни қониқтириш қобилияти ва истаги. Миннатдор бўла олиш кўникмаси ҳаётга янада кўпроқ мўл-кўллик келтиради. Ҳаммага ва ҳамма нарсага севги, қувонч ва кайф, ҳаётдан лаззат ва қувонч. Доим мамнун ва яхши юмор ҳисси билан. Имкониятлар ўзингизга ёққан нарсани қилганингизда пайдо бўлади, шунингдек дугоналарингиз сизга имкониятлар жалб қилади ва ёрдам беради.","Мистические совпадения, ваша отрешенность и не привязанность, помогает ваша победа над страхом перемен, над консерватизмом и отжившими установками. Философское восприятие неудач, великолепная интуиция и прозрения, медитации и стремление к духовности. Огромная проницательность и сила предвидения помогают сделать верный выбор. Мудрость, решительность, дисциплинированность и большая внутренняя сила помогают в жизни. Держите аскезу когда вам нужна помощь от судьбы.":"Мистик тасодифлар, ўзингизни четга олиш ва боғланмаслигингиз, ўзгаришлардан қўрқиш, консерватизм ва эскирган қарашлар устидан ғалабангиз ёрдам беради. Омадсизликларни фалсафий қабул қилиш, ажойиб интуиция ва ичдан англашлар, медитациялар ва маънавиятга интилиш. Улкан зийраклик ва олдиндан кўриш кучи тўғри танлов қилишга ёрдам беради. Донолик, қатъият, интизомлилик ва катта ички куч ҳаётда ёрдам беради. Тақдирдан ёрдам керак бўлганда зоҳидлик тутинг.","Постоянное и четкое исполнение своих обязанностей, серьезность, целеустремленность и упорство в достижении целей, стремление занять высокий социальный статус, надежность, замкнутость и верность. Начальники помогают, люди старшего возраста, дедушки, бабушки, люди занимающее высокое социальное положение, карьеристы. Помогает способность преодолевать препятствия и быть терпимым и выносливым, иметь внутренний стержень. Труд, дисциплина и режим дня, аскетичность и отказ от роскоши. Способность сосредоточиться и сконцен- трироваться. Холодная расчетливость, избавление от деспотизма и предателей, от предательств ваших собственных. Умейте быть стойким и работать в долгую, повременить с малыми и короткими удовольствиями ради удовольствий крупных.":"Мажбуриятларингизни доимий ва аниқ бажариш, жиддийлик, мақсадга интилувчанлик ва мақсадларга эришишда қатъийлик, юқори ижтимоий мақомни эгаллашга интилиш, ишончлилик, камгаплик ва садоқат. Бошлиқлар, катта ёшдаги одамлар, бобо, бувилар, юқори ижтимоий мавқега эга одамлар, карьеристлар ёрдам беради. Тўсиқларни енгиш ва сабрли ва чидамли бўлиш, ички ўзакка эга бўлиш қобилияти ёрдам беради. Меҳнат, интизом ва кун тартиби, зоҳидлик ва ҳашаматдан воз кечиш. Диққатни жамлаш ва тўплаш қобилияти. Совуққон ҳисобкорлик, золимлик ва хоинлардан, ўз хиёнатларингиздан қутулиш. Бардошли бўлишни ва узоқ муддатга ишлашни, йирик лаззатлар учун кичик ва қисқа лаззатларни кечиктира билинг.","Бесстрашие, решительность, смелость, целеустремленность и достижение целей в любом случае, способность управлять своей сексуальной энергией. Занятия спортом, энтузиазм и физическая активность. Желание и умение защищать слабых и бороться там, где это спасает жизни. Практичность, преданность, способность не просто говорить, а делать. Работа над своей ленью и трусостью, над агрессией и насилием. Мужчины вам помогут, активные женщины, собаки и животные способные укусить (не кошка, только если дикая и опасная). Желание все упростить и донести простым языком сложные вещи, способность бороться.":"Қўрқмаслик, қатъият, жасорат, мақсадга интилувчанлик ва ҳар қандай ҳолда мақсадларга эришиш, жинсий энергиянгизни бошқариш қобилияти. Спорт билан шуғулланиш, ғайрат ва жисмоний фаоллик. Заифларни ҳимоя қилиш ва бу ҳаётларни қутқарадиган жойда курашиш истаги ва кўникмаси. Амалийлик, садоқат, шунчаки гапириш эмас, балки қилиш қобилияти. Дангасалик ва қўрқоқлигингиз, тажовуз ва зўравонлик устида ишлаш. Сизга эркаклар, фаол аёллар, итлар ва тишлай оладиган ҳайвонлар ёрдам беради (мушук эмас, фақат ёввойи ва хавфли бўлса). Ҳамма нарсани соддалаштириш ва мураккаб нарсаларни оддий тилда етказиш истаги, курашиш қобилияти.","Нет определенного мировоззрения, нужно найти духовного учителя достигшего того, чего вы хотите сами достичь и выбрать для себя картину мира с ним. Вы можете верить только в себя и быть атеистом или всецело верить в абсолют. Не можете понять этот мир и эту жизнь, можете вестись на все подряд, потом сталкиваться с препятствиями и опять путаться что и как работает. Можете верить во все сразу и это все работает. Или нет привязанности к определенному мировосприятию, вы сами можете выбрать во что верить, здесь вы не обусловлены. Можете ни во что не верить, наблюдать за миром и слушать то, что отзывается в вас в это и верить, препятствий нет – все в голове, нет границ и бесконечная пустота, что посеешь – то и пожнешь, все просто, потерянность ми и страхи к миру.":"Аниқ дунёқараш йўқ, ўзингиз эришмоқчи бўлган нарсага эришган маънавий устоз топиш ва у билан ўзингиз учун дунё манзарасини танлаш керак. Сиз фақат ўзингизга ишонишингиз ва атеист бўлишингиз ёки мутлақга бутунлай ишонишингиз мумкин. Бу дунё ва бу ҳаётни тушуна олмайсиз, ҳамма нарсага эргашиб кетишингиз, кейин тўсиқларга дуч келиб, яна нима ва қандай ишлашини чалкаштиришингиз мумкин. Бирданига ҳамма нарсага ишонишингиз мумкин ва буларнинг барчаси ишлайди. Ёки муайян дунёқарашга боғлиқлик йўқ, нимага ишонишни ўзингиз танлашингиз мумкин, бу ерда сиз шартланмагансиз. Ҳеч нарсага ишонмаслигингиз, дунёни кузатиб, ўзингизда акс садо берадиган нарсани тинглаб, шунга ишонишингиз мумкин, тўсиқлар йўқ — ҳаммаси бошда, чегаралар йўқ ва чексиз бўшлиқ, нима эксанг — шуни ўрасан, ҳаммаси оддий, дунёда йўқотилганлик ва дунёга қўрқувлар.","Вы считаете, что все зависит от вас самих. Может быть даже излишняя ответственность либо наоборот безответственное отношение. Ваше мировоззрение сформировано от мужской части вашего рода, отцов, дедов, возможно, отчима. Вы можете равняться на отца, начальника или президента. Вы считаете, что достойны самого лучшего, все возможно в этом мире. Самореализация играет важную роль в жизни, ребенок, муж и отец тоже.":"Сиз ҳаммаси ўзингизга боғлиқ деб ҳисоблайсиз. Ҳатто ортиқча масъулият ёки аксинча масъулиятсиз муносабат бўлиши мумкин. Дунёқарашингиз уруғингизнинг эркак қисмидан, оталар, боболардан, эҳтимол, ўгай отадан шаклланган. Сиз отага, бошлиққа ёки президентга тенглашишингиз мумкин. Сиз энг яхшисига лойиқсиз, бу дунёда ҳамма нарса мумкин деб ҳисоблайсиз. Ўзини рўёбга чиқариш ҳаётда муҳим рол ўйнайди, бола, эр ва ота ҳам.","Вы центр своего мира и это вполне нормально, если другие не страдают от этого. Если вы не имеете к кому-то уважения, то можете быть вспыльчивы с ним. Если вы уверены в себе, то не имеете претензий к окружающему миру. Вы можете желать признания и почета, если зависите от мнения других людей. На самом деле вам нужно убедиться, что вы хорош и стать уверенным в себе, почувствовать себя уникальным. Желание действовать на помощь другим людям может перебороть любую лень, как и чрезмерная активность ради материальных благ. Способность ясно мыслить и улавливать суть помогает искоренить импульсивность.":"Сиз ўз дунёингизнинг марказисиз ва агар бошқалар бундан азоб чекмаса, бу мутлақо нормал. Агар кимгадир ҳурматингиз бўлмаса, у билан жаҳлдор бўлишингиз мумкин. Агар ўзингизга ишонсангиз, атрофдаги дунёга даъволарингиз бўлмайди. Агар бошқа одамлар фикрига боғлиқ бўлсангиз, тан олиниш ва ҳурматни исташингиз мумкин. Аслида сизга яхши эканлигингизга ишонч ҳосил қилиш ва ўзингизга ишонган бўлиш, ўзингизни ноёб ҳис қилиш керак. Бошқа одамларга ёрдам бериш учун ҳаракат қилиш истаги ҳар қандай дангасаликни енгиши мумкин, худди моддий неъматлар учун ҳаддан ташқари фаоллик каби. Аниқ фикрлаш ва моҳиятни илғаш қобилияти импульсивликни йўқотишга ёрдам беради.","У вас может быть сильное желание быть в центре внимания, которое скатывается в тщеславие и излишний эгоизм. Благодарность к людям искореняют длительный гнев. Высокомерие появ- ляется от заниженной самооценки и отсутствия чувства собственного достоинства. Если вы делаете то, что хотите, то получаете блаженство в своей деятельности и в жизни. Для вас важно делать то, что вы хотите, исполнять свои желания, вы становитесь очень ресурсным человеком при этом. «Я и никого кроме» – не очень эффективное мировоззрение.":"Сизда диққат марказида бўлишга кучли истак бўлиши мумкин, у шуҳратпарастлик ва ортиқча худбинликка ўтиб кетади. Одамларга миннатдорлик узоқ давом этадиган ғазабни йўқотади. Кибр пасайтирилган ўзини баҳолаш ва ўз қадр-қиммат ҳиссининг йўқлигидан пайдо бўлади. Агар истаган нарсангизни қилсангиз, фаолиятингизда ва ҳаётда саодат оласиз. Сиз учун истаган нарсангизни қилиш, истакларингизни бажариш муҳим, бунда сиз жуда ресурсли инсонга айланасиз. «Мен ва мендан бошқа ҳеч ким» — унча самарали бўлмаган дунёқараш.","Важно в жизни партнерство, строить близкие отношения, нужно заботиться о природе, людях животных, нужно создавать семью, рожать детей. Вы заботитесь о своих проектах и берете под свое крыло тех, кому нужна помощь. Все большая семья, все люди братья и тп. Можете придерживаться лунного цикла. Умеете уступать и быть альтруистами. Как мать ставите на первое место заботы и чувства других, потом свои. Можете считать, что все текуче и изменчиво, все непостоянно в этом бренном мире. Эмоции сильно влияют на мировоззрение, излишняя эмоциональность, решения на основе эмоций принимаются. Само мировоззрение может меняться в течении жизни или быть запутанным, непонятным. Очень психологичны и разбираетесь в людях, считаете, что подсознание управляет всем. Вы можете отражать мировоззрение того, кто рядом с вами, как луна отражает свет солнца. Считаете, что нужно адаптироваться под обстоятельства. Вы приспосабливаетесь, выживаете сами и помогаете выживать другим. Можете иногда кроме быта ничего и не видеть вокруг.":"Ҳаётда шериклик, яқин муносабатлар қуриш муҳим, табиат, одамлар, ҳайвонларга ғамхўрлик қилиш керак, оила қуриш, фарзанд кўриш керак. Сиз лойиҳаларингизга ғамхўрлик қиласиз ва ёрдамга муҳтожларни қанотингиз остига оласиз. Ҳамма катта оила, барча одамлар ака-ука ва ҳ.к. Ой циклига амал қилишингиз мумкин. Ён бера оласиз ва альтруист бўла оласиз. Она каби биринчи ўринга бошқаларнинг ташвишлари ва ҳисларини, кейин ўзингизникини қўясиз. Ҳаммаси оқувчан ва ўзгарувчан, бу фоний дунёда ҳамма нарса беқарор деб ҳисоблашингиз мумкин. Ҳислар дунёқарашга кучли таъсир қилади, ортиқча ҳиссиётлилик, қарорлар ҳислар асосида қабул қилинади. Дунёқарашнинг ўзи ҳаёт давомида ўзгариши ёки чалкаш, тушунарсиз бўлиши мумкин. Жуда психологсиз ва одамларни яхши тушунасиз, онгости ҳамма нарсани бошқаради деб ҳисоблайсиз. Ой Қуёш нурини акс эттиргандек, ёнингиздаги инсоннинг дунёқарашини акс эттиришингиз мумкин. Шароитларга мослашиш керак деб ҳисоблайсиз. Сиз мослашасиз, ўзингиз омон қоласиз ва бошқаларга омон қолишга ёрдам берасиз. Баъзан атрофда маишатдан бошқа ҳеч нарсани кўрмаслигингиз мумкин.","Картину мира формируют авторитеты, муж, дети помогают формировать мировоззрение. Считаете, что нужно передавать знания учиться, стремиться к расширению и путешествиям. Можете быть отличным философом. Вы сами можете давать советы тем, кто нуждается в ваших рекомендациях. Вы очень оптимистичны, понимаете законы Бога, имеете уважение к авторитетам или наоборот ненавидите учителей. Можете следовать только тем моральным нормам, которые ведут к материальному прогрессу. Кое-где можете быть догматичным и слепо следовать законам, не разбираясь в их сути. А можете иметь высокую мораль, считать искренность и честность одними из важных качеств в жизни. Вы можете видеть суть и систему всю целиком, полную картину происходящего. Бежите вперед, заскакивая по пути еще в несколько мест. Можете быть реалистом и говорить все в лицо, не боясь обидеть. Можете обладать гордыней или же быть щедрыми. Считаете, что нужно иметь много хобби и потом можете каждое из них делать делом своей жизни в разные периоды жизни. Каждый должен быть богатым и вы тоже, успешным и вы с радостью стремитесь к благополучию и успеху, к тому чтобы иметь вес в социуме и авторитет, занимать высокий социальный статус, получать высшее образование, работать в мировых или очень крупных организациях и проектах. Признание в обществе очень важно. Вероятна религиозная картина мира. Можете иметь много излишеств, как в еде так и в характере.":"Дунё манзарасини обрўли кишилар шакллантиради, эр, болалар дунёқарашни шакллантиришга ёрдам беради. Билимларни узатиш, ўқиш, кенгайиш ва саёҳатларга интилиш керак деб ҳисоблайсиз. Аъло файласуф бўлишингиз мумкин. Тавсияларингизга муҳтожларга ўзингиз маслаҳат беришингиз мумкин. Сиз жуда оптимистиксиз, Худо қонунларини тушунасиз, обрўли кишиларга ҳурматингиз бор ёки аксинча устозларни ёмон кўрасиз. Фақат моддий тараққиётга олиб борадиган ахлоқий меъёрларга амал қилишингиз мумкин. Баъзи жойларда догматик бўлишингиз ва қонунларнинг моҳиятини тушунмасдан кўр-кўрона уларга амал қилишингиз мумкин. Ёки юксак ахлоққа эга бўлишингиз, самимийлик ва ҳалолликни ҳаётдаги муҳим фазилатлардан бири деб ҳисоблашингиз мумкин. Сиз моҳиятни ва бутун тизимни яхлит, содир бўлаётган нарсаларнинг тўлиқ манзарасини кўришингиз мумкин. Йўл-йўлакай яна бир нечта жойга кириб ўтиб, олдинга югурасиз. Реалист бўлишингиз ва хафа қилишдан қўрқмай, ҳаммасини юзга айтишингиз мумкин. Кибрга эга бўлишингиз ёки саховатли бўлишингиз мумкин. Кўп хоббига эга бўлиш керак деб ҳисоблайсиз ва кейин ҳаётнинг турли даврларида уларнинг ҳар бирини ҳаётингиз ишига айлантиришингиз мумкин. Ҳар ким бой бўлиши керак, сиз ҳам, муваффақиятли, ва сиз фаровонлик ва муваффақиятга, жамиятда салмоқ ва обрўга эга бўлишга, юқори ижтимоий мақомни эгаллашга, олий маълумот олишга, жаҳон ёки жуда йирик ташкилотлар ва лойиҳаларда ишлашга қувонч билан интиласиз. Жамиятда тан олиниш жуда муҳим. Диний дунё манзараси эҳтимоли бор. Овқатда ҳам, феълда ҳам кўп ортиқчаликларга эга бўлишингиз мумкин.","Вы можете верить во что-то неправильное, могут быть секты, иллюзии, обманные религии. Можете верить в неправильного проводника, пустого. Склоняетесь к тому, чего не существует, сами обманываетесь и обманываете. Видите разные религии, как частицы одного большого, как разные пути к одному и тому же. Читаете между строк и видите суть всего и каждого. В мировоззрении может быть полный хаос и путаница. Верите в карму и понимаете как с ней работать, или просто верите в карму и фатальность. У вас очень много желаний, которые после исполнения не приносят удовлетворения. Верите в мечты. Верите в то, что способны влиять на массы людей. Мировоззрение может формироваться под воздействием ТВ, сериалов. Магическая картина мира.":"Сиз нотўғри нимагадир ишонишингиз мумкин, мазҳаблар, иллюзиялар, алдамчи динлар бўлиши мумкин. Нотўғри, бўш йўлбошчига ишонишингиз мумкин. Мавжуд бўлмаган нарсага мойил бўласиз, ўзингиз алданасиз ва алдайсиз. Турли динларни бир катта нарсанинг зарралари, бир нарсага олиб борадиган турли йўллар сифатида кўрасиз. Сатрлар орасини ўқийсиз ва ҳамма нарса ва ҳар кимнинг моҳиятини кўрасиз. Дунёқарашда тўлиқ хаос ва чалкашлик бўлиши мумкин. Кармага ишонасиз ва у билан қандай ишлашни тушунасиз, ёки шунчаки карма ва тақдирга ишонасиз. Сизда бажарилгандан кейин қониқиш келтирмайдиган жуда кўп истаклар бор. Орзуларга ишонасиз. Одамлар оммасига таъсир кўрсата олишингизга ишонасиз. Дунёқараш ТВ, сериаллар таъсирида шаклланиши мумкин. Сеҳрли дунё манзараси.","Картина мира может меняться в течении жизни. В жизни важны знакомства, контакты, обмен информацией. Мышление как обмен информацией, ее анализ и оценка, без излишних эмоций. Вы легки на подъем, умеете переключаться, а иногда даже скачете по верхам. Можете верите в то, что выгодно сейчас, можете менять религии в течении жизни. Считаете, что нужно учиться всегда, перемещаться и важна свобода, легкость. Обучаетесь практичному, конкретному, а не духовно-философскому. Иногда можете не сдержать слово, обмануть если надо и будет легче, считаете интеллект ведущим в жизни. Больше вероятна научная картина мира, чем духовная или магическая. А если последние, то ищете практические доказательства, чтобы рассказывать другим об этом. Можете много говорить о своем мышлении и мировоззрении с людьми и формировать его от знакомств, книг и ближнего окружения.":"Дунё манзараси ҳаёт давомида ўзгариши мумкин. Ҳаётда танишувлар, алоқалар, маълумот алмашиш муҳим. Фикрлаш маълумот алмашиш, уни ортиқча ҳиссиз таҳлил қилиш ва баҳолаш сифатида. Сиз енгил кўтариласиз, бошқа нарсага ўтишни биласиз, баъзан эса ҳатто юзаки сакраб юрасиз. Ҳозир фойдали бўлган нарсага ишонишингиз, ҳаёт давомида динларни ўзгартиришингиз мумкин. Доим ўқиш, ҳаракатланиш керак ва эркинлик, енгиллик муҳим деб ҳисоблайсиз. Маънавий-фалсафий эмас, амалий, аниқ нарсаларни ўрганасиз. Баъзан сўзингизда турмаслигингиз, агар керак бўлса ва осонроқ бўлса алдашингиз мумкин, интеллектни ҳаётда етакчи деб ҳисоблайсиз. Маънавий ёки сеҳрлидан кўра илмий дунё манзараси эҳтимоли кўпроқ. Агар кейингилари бўлса, бу ҳақда бошқаларга гапириб бериш учун амалий далиллар излайсиз. Фикрлашингиз ва дунёқарашингиз ҳақида одамлар билан кўп гаплашишингиз ва уни танишувлар, китоблар ва яқин атрофдан шакллантиришингиз мумкин.","В жизни важны отношения, семья, брак, договора, мир во всем мире, гармония. Важно чтобы все было комфортное и красивое, любите праздники жизни и украшать все вокруг, в т.ч. себя. Отношения нужны для любви, делать нужно то, что нравится, нужно быть богатым и привлекательным. Можете любить сладкое. Важна любовь и комфорт в жизни. Можете быть излишне материальны и зациклены на этом. Чувства – одни из важных вещей в мире. Денежное мышление, понимание денег и их энергии. Любите искусство, эстетику, изящество. Считаете, что нужно быть справедливым иметь честь. Нужно получать радость и удовольствие от жизни и удовлетворять других. Важно не стать удобным для других, но не для себя. Вы умеете договариваться так чтобы было комфортно и справедливо, часто идете на уступки и умеете принимать ситуации и людей.":"Ҳаётда муносабатлар, оила, никоҳ, шартномалар, бутун дунёда тинчлик, уйғунлик муҳим. Ҳаммаси қулай ва чиройли бўлиши муҳим, ҳаёт байрамларини ва атрофдаги ҳамма нарсани, жумладан ўзингизни безатишни яхши кўрасиз. Муносабатлар севги учун керак, ёқадиган нарсани қилиш керак, бой ва жозибали бўлиш керак. Ширинликни яхши кўришингиз мумкин. Ҳаётда севги ва қулайлик муҳим. Ҳаддан ташқари моддий бўлишингиз ва бунга қотиб қолишингиз мумкин. Ҳислар — дунёдаги муҳим нарсалардан бири. Пулли фикрлаш, пул ва унинг энергиясини тушуниш. Санъат, эстетика, нафосатни яхши кўрасиз. Адолатли бўлиш, номусга эга бўлиш керак деб ҳисоблайсиз. Ҳаётдан қувонч ва лаззат олиш ва бошқаларни қониқтириш керак. Бошқалар учун қулай, лекин ўзингиз учун эмас бўлиб қолмаслик муҳим. Сиз қулай ва адолатли бўлиши учун келиша оласиз, тез-тез ён берасиз ва вазиятлар ва одамларни қабул қила оласиз.","У вас мир мистика, духовности. воспринимаете мир непонятно для всех, считаете, что все должны расти духовно (отрастить голову, тк Кету – тело без головы, нужно отрастить голову). Действуете интуитивно. Новаторское мышление, необычное, оригинальное. Можете заниматься аскезами и жить в уединении и в отречении. Мировоззрение формируется в одиночестве и уединении, вдали от всех. Часто бывает отречение от материального, хотя тут должен быть баланс между духовным и материальным. Можете смотреть в прошлое и жить в нем, бояться перемен и быть консерватором, но от этого нужно отказаться. Принимайте перемены, идите в свои страхи и станьте в них главным. Вы как не от мира сего, можете верить в инопланетян и во все разные духовные картины мира. Все это работает и все сразу умещается в вашей голове. Если не развиваетесь духовно и не идете к богу, могут быть проблемы с психикой, неадекватность, глюки, фобии. Духовное развитие и внутренний мир, подсознание занимают ведущую роль в вашей жизни, через это вы смотрите на мир. Слабо можете объяснить через рот во, что вы верите, но одно это точно – это в Творца, Бога, Вселенную, в то, что есть что-то единое для всех. У вас большой богатый опыт внутренней жизни и вы можете помнить свои воплощения, и легко регрессировать в них. Слабо оформляете в слова свою картину мира, она и магическая, и научная сразу вместе.":"Сизда мистика, маънавият дунёси. Дунёни ҳамма учун тушунарсиз қабул қиласиз, ҳамма маънавий ўсиши керак деб ҳисоблайсиз (бош ўстириш, чунки Кету — бошсиз тана, бош ўстириш керак). Интуитив ҳаракат қиласиз. Новаторлик фикрлаш, ғайриоддий, оригинал. Зоҳидликлар билан шуғулланишингиз ва ёлғизликда ва воз кечишда яшашингиз мумкин. Дунёқараш ёлғизлик ва хилватда, ҳаммадан узоқда шаклланади. Тез-тез моддий нарсадан воз кечиш бўлади, гарчи бу ерда маънавий ва моддий ўртасида мувозанат бўлиши керак. Ўтмишга қарашингиз ва унда яшашингиз, ўзгаришлардан қўрқишингиз ва консерватор бўлишингиз мумкин, лекин бундан воз кечиш керак. Ўзгаришларни қабул қилинг, қўрқувларингизга боринг ва уларда асосий бўлинг. Сиз бу дунёдан эмасдексиз, ўзга сайёраликларга ва турли маънавий дунё манзараларига ишонишингиз мумкин. Буларнинг барчаси ишлайди ва ҳаммаси бирданига бошингизга сиғади. Агар маънавий ривожланмасангиз ва Худога бормасангиз, руҳият билан муаммолар, номутаносиблик, галлюцинациялар, фобиялар бўлиши мумкин. Маънавий ривожланиш ва ички дунё, онгости ҳаётингизда етакчи рол ўйнайди, сиз дунёга шу орқали қарайсиз. Нимага ишонишингизни оғзаки яхши тушунтира олмайсиз, лекин бир нарса аниқ — бу Яратувчига, Худога, Коинотга, ҳамма учун ягона нимадир борлигига. Сизда ички ҳаётнинг катта бой тажрибаси бор ва мужассамланишларингизни эслашингиз ва уларга осонгина регрессия қилишингиз мумкин. Дунё манзарангизни сўзларга яхши солмайсиз, у ҳам сеҳрли, ҳам илмий, бирданига бирга.","Важность соблюдения законов, причем любых, даже плохих и деструктивных. Важно сделать карьеру и иметь высокий пост на работе, подниматься в иерархии. Умеете соблюдать правила и последовательно выполнять свои обязанности. Каждый должен быть ответственным и нести свою ношу. Мировоззрение трудоголика, очень материалистичное, четкое, с четкими правилами. Важность времени в жизни, распорядка дня, режима и тайм менеджмента. Строгость, структура, труд, достижение целей и успеха своим трудом. Вы очень терпеливы, выносливы и имеете стальной внутренний стержень. Считайте, что всю жизнь нужно преодолевать препятствия, чтобы чего – то достичь, много ограничений в голове, запретов – от этого нужно избавится. Мировоззрение формируют бабушки, дедушки, люди старшего возраста, люди добившиеся успеха. Трудно убедить в чем-либо, упрямство. Стойкая позиция в жизни. Могут быть неудачи от слишком серьезного отношения к жизни и повышенной важности чего- либо. А обратной стороной может быть аскетизм и полное неверие в Высшие Силы, от чего чрезмерная осторожность, уныние, депрессии и плохие наклонности.":"Қонунларга, яна ҳар қандайига, ҳатто ёмон ва бузғунчиларига ҳам риоя қилишнинг муҳимлиги. Карьера қилиш ва ишда юқори лавозимга эга бўлиш, иерархияда кўтарилиш муҳим. Қоидаларга риоя қилишни ва мажбуриятларингизни изчил бажаришни биласиз. Ҳар ким масъулиятли бўлиши ва ўз юкини кўтариши керак. Меҳнаткашнинг дунёқараши, жуда материалистик, аниқ, аниқ қоидалар билан. Ҳаётда вақт, кун тартиби, режим ва тайм-менежментнинг муҳимлиги. Қатъийлик, тузилма, меҳнат, ўз меҳнати билан мақсадлар ва муваффақиятга эришиш. Сиз жуда сабрли, чидамли ва пўлат ички ўзакка эгасиз. Нимагадир эришиш учун бутун ҳаёт тўсиқларни енгиш керак деб ҳисоблайсиз, бошда кўп чекловлар, тақиқлар — булардан қутулиш керак. Дунёқарашни бувилар, боболар, катта ёшдаги одамлар, муваффақиятга эришган одамлар шакллантиради. Нимагадир ишонтириш қийин, ўжарлик. Ҳаётда барқарор позиция. Ҳаётга ҳаддан ташқари жиддий муносабат ва нимагадир ортиқча аҳамият беришдан омадсизликлар бўлиши мумкин. Тескари томони эса зоҳидлик ва Олий Кучларга бутунлай ишонмаслик бўлиши мумкин, бундан ҳаддан ташқари эҳтиёткорлик, тушкунлик, депрессиялар ва ёмон мойилликлар.","ЯЗЫК ЛЮБВИ":"СЕВГИ ТИЛИ","Вам нужно говорить о любви просто и открыто, без намеков, вы их не понимаете. Самое простое говорить вам как чувствуется и очень разборчиво, доходчиво, не усложняя. А желательно даже на вашем языке. Вы хотите, чтобы ваш любимый и любящий показывал вашему окружению и родственникам, как он прекрасно к вам относится, как вас любит. Даже в не лучший период отношений. Вы не хотите, чтобы ваш человек недоговаривал чего-то, но себе это позволяете, думая что все итак понятно, потому что если вы с ним еще, значит вы любите его.":"Сизга севги ҳақида оддий ва очиқ, ишораларсиз гапириш керак, сиз уларни тушунмайсиз. Энг осони сизга қандай ҳис қилинаётганини жуда аниқ, тушунарли, мураккаблаштирмай айтиш. Яхшиси ҳатто ўз тилингизда. Сиз севимли ва севувчи инсонингиз атрофингиздагиларга ва қариндошларингизга сизга қанчалик ажойиб муносабатда бўлишини, сизни қанчалик севишини кўрсатишини истайсиз. Ҳатто муносабатларнинг энг яхши бўлмаган даврида ҳам. Инсонингиз ниманидир айтмай қолдиришини истамайсиз, лекин ўзингизга бунга йўл қўясиз, ҳаммаси шундоқ ҳам тушунарли деб ўйлаб, чунки агар сиз ҳали у билан бўлсангиз, демак уни севасиз.","Для вас любовь – это забота и опека, вам важно ощущать душевное спокойствие в любви с человеком, вы как малое дитя дома у мамы хотите уюта и безопасности. Вы всегда накормите, выслушаете, обогреете. В любви ваша задача слушать, понимать, давать тепло душевное и физическое, заботиться. Вам нужна семья, родственники, дети, хотя вы сами себя ведете иногда как малое дитя и капризничаете. Вас за это не нужно строго судить, но и сильно баловать нельзя, иначе привыкнете и будете требовать всегда. Вы ранимый и обидчивый, с вами нужно очень аккуратно общаться.":"Сиз учун севги — бу ғамхўрлик ва васийлик, сиз учун инсон билан севгида қалб хотиржамлигини ҳис қилиш муҳим, сиз онасининг уйидаги кичик боладек қулайлик ва хавфсизликни истайсиз. Сиз доим овқатлантирасиз, тинглайсиз, иситасиз. Севгида вазифангиз тинглаш, тушуниш, маънавий ва жисмоний илиқлик бериш, ғамхўрлик қилиш. Сизга оила, қариндошлар, болалар керак, гарчи ўзингиз баъзан кичик боладек тутиб, инжиқлик қиласиз. Бунинг учун сизни қаттиқ қоралаш керак эмас, лекин жуда эркалатиш ҳам мумкин эмас, акс ҳолда одатланиб, доим талаб қиласиз. Сиз нозик ва аразчисиз, сиз билан жуда эҳтиёткорлик билан мулоқот қилиш керак.","Вы хотите, чтобы ваш возлюбленный разделял ваши ценности, ваше мировоззрение и убеждения были максимально схожи. Вам важно говорить с ним об устройстве вселенной, о мироздании, помечтать, пофилософствовать, строить планы и верить в светлое будущее. Вы хотите справедливого человека к вам и к миру в целом. Вам нужно, чтобы интерес к вам был явно показан, к вашей жизни, к вашим делам. Вы много разговариваете, как самые близкие и раскрываете друг другу свои души. Вы хотите, чтобы ваш любимый был вам учителем, и вы тоже можете наставить его, иногда, на истинный путь. Вы хотите позитива вместе с любимым и верите, что все у всех получится.":"Сиз севгилингиз қадриятларингизни баҳам кўришини, дунёқарашингиз ва эътиқодларингиз максимал ўхшаш бўлишини истайсиз. Сиз учун у билан коинот тузилиши, оламнинг яратилиши ҳақида гаплашиш, орзу қилиш, фалсафа сўқиш, режалар тузиш ва ёрқин келажакка ишониш муҳим. Сизга ва умуман дунёга адолатли инсонни истайсиз. Сизга, ҳаётингизга, ишларингизга қизиқиш аниқ кўрсатилиши керак. Сиз энг яқинлардек кўп гаплашасиз ва бир-бирингизга қалбингизни очасиз. Севимли инсонингиз сизга устоз бўлишини истайсиз, сиз ҳам уни баъзан ҳақ йўлга солишингиз мумкин. Севимли инсон билан бирга ижобийликни истайсиз ва ҳаммада ҳаммаси чиқишига ишонасиз.","Вы хотите, чтобы вам в отношениях вместе было очень просто, чтобы вы могли оценивать, критиковать, быть объективным человеком, а не с замыленными любовью глазами. Иногда вы отите бунтовать и вам нужно это позволять себе и партнер, чтобы тоже позволял вам это, вы от бунтарства заряжаетесь. Вы хотите, чтобы вашу материалистичность принимали как должное. Вы считаете что любовь – это просто. Не нужно усложнять и излишняя сентиментальность даже вредит. Рядом с человеком вам нужно, чтобы было телесно комфортно, вы хотите говорить о ваших финансах и возможностях, вам важно материальное проявление в любви и отношениях.":"Сиз муносабатларда бирга жуда оддий бўлишини, севгидан хираланган кўзлар билан эмас, баҳолай, танқид қила, объектив инсон бўла олишингизни истайсиз. Баъзан исён қилишни истайсиз ва бунга ўзингизга йўл қўйишингиз керак, шерик ҳам сизга бунга йўл қўйиши керак, сиз исёнкорликдан қувват оласиз. Моддиятпарастлигингизни табиий ҳол сифатида қабул қилишларини истайсиз. Сиз севги — бу оддий деб ҳисоблайсиз. Мураккаблаштириш керак эмас ва ортиқча сентиментализм ҳатто зарар қилади. Инсон ёнида сизга жисмонан қулай бўлиши керак, молияларингиз ва имкониятларингиз ҳақида гаплашишни истайсиз, сиз учун севги ва муносабатларда моддий намоён бўлиш муҳим.","Вы легкий и дружелюбный, игривый и кажетесь поверхностным, но это не так. Для вас любовь – это дружба, когда легко, играючи, без выноса мозга и чрезмерной философии. Вы хотите вместе много передвигаться, гулять, общаться, узнавать новое, иметь общее хобби, и вместе ходили на курсы, обучения, тренинги. Неплохо вместе создать проект или бизнес. вам важно, чтобы любимый человек был самым близким другом.":"Сиз енгил ва дўстона, ўйноқисиз ва юзаки кўринасиз, лекин бундай эмас. Сиз учун севги — бу дўстлик, енгил, ўйнаб-кулиб, миянинг қатиғини чиқармасдан ва ортиқча фалсафасиз бўлганда. Бирга кўп ҳаракатланиш, сайр қилиш, мулоқот қилиш, янги нарсаларни билиш, умумий хоббига эга бўлиш, бирга курсларга, ўқишларга, тренингларга боришни истайсиз. Бирга лойиҳа ёки бизнес яратиш ёмон эмас. Сиз учун севимли инсон энг яқин дўст бўлиши муҳим.","Вы хотите, чтобы все вокруг было дорого-богато, красиво, а уж если вас любят и того всего побольше. Вы хотите подарков, красивые слова, стихи и искусство, чтобы вами восхищались. А вы в ответ нежно и красиво любите, готовы служить вашим отношениям, ведь это ваше предназначение в любви. Вы можете переходить границы, временами, и вам может казаться, что любви стало мало, но как только вам сделают приятно, вы снова готовы на все ради любви. Вы любите драму, как в фильме, а вы в нем актер, а возлюбленный благодарный зритель, который тем не менее, не позволит вам заиграться. Вам нужно, чтобы к вам проявляли чувства и даже жалели.":"Сиз атрофдаги ҳамма нарса қиммат-бой, чиройли бўлишини истайсиз, агар сизни севишса, буларнинг ҳаммаси янада кўпроқ. Сиз совғалар, чиройли сўзлар, шеърлар ва санъат, сиздан ҳайратланишларини истайсиз. Сиз эса жавобан нозик ва чиройли севасиз, муносабатларингизга хизмат қилишга тайёрсиз, ахир бу севгидаги вазифангиз. Баъзан чегаралардан ўтишингиз мумкин ва сизга севги камайиб қолгандек туюлиши мумкин, лекин сизга ёқимли нарса қилишлари биланоқ, яна севги учун ҳамма нарсага тайёрсиз. Сиз фильмдагидек драмани яхши кўрасиз, сиз унда актёрсиз, севгилингиз эса миннатдор томошабин, у шунга қарамай сизга ҳаддан ошиб кетишга йўл қўймайди. Сизга ҳисларни намоён қилишлари ва ҳатто раҳм қилишлари керак.","Вы любите знаки, мистику, совпадения, метафоры и сюрпризы. Вас в любви не просто понять, потому что в душе вы философ и эзотерик, и свое особое видение отношений. Вы хотите уметь понимать друг друга без слов, чтобы чувствовали друг друга даже на расстоянии. Вы живете сердцем, а не разумом, у вас сильнейшая интуиция, вы доверяете себе и Богу, и хотите доверия от других. Вам важно, когда ваш любимый спрашивает у вас совета, тогда вы прислушиваетесь к себе и даете ответ. В отношениях для вас доверие – самое главное, вы не выносите недомолвок и тайн друг от друга.":"Сиз белгилар, мистика, тасодифлар, метафоралар ва сюрпризларни яхши кўрасиз. Севгида сизни тушуниш осон эмас, чунки қалбингизда сиз файласуф ва эзотериксиз ва муносабатларга ўзгача қарашингиз бор. Сиз бир-бирингизни сўзсиз тушуна олишни, ҳатто масофада ҳам бир-бирингизни ҳис қилишни истайсиз. Сиз ақл билан эмас, юрак билан яшайсиз, сизда жуда кучли интуиция бор, сиз ўзингизга ва Худога ишонасиз ва бошқалардан ишонч истайсиз. Сиз учун севимли инсонингиз сиздан маслаҳат сўраганида муҳим, шунда сиз ўзингизга қулоқ соласиз ва жавоб берасиз. Муносабатларда сиз учун ишонч — энг асосийси, сиз чала гаплар ва бир-бирингиздан сирларни кўтара олмайсиз.","Вы любите дисциплину, закон, порядок и правила. Вашему любимому может казаться, что вы эмоционально холодны, но это не так. Вы выглядите отстраненным, но при том внутри у вас тонкая, душевная организация, которую вы не стремитесь показывать, как и проявления романтической любви. Вы не любите излишние эмоции и хотите, чтобы с вами общались спокойно, без надрыва, четко, логично и тогда вы сможете услышать собеседника. В любви у вас должны быть правила и все по честному. Вы любите договоренности, планирование и пунктуальность. Вы стабильный и ответственный человек и хотите такого же партнера себе.":"Сиз интизом, қонун, тартиб ва қоидаларни яхши кўрасиз. Севимли инсонингизга сиз ҳиссий совуқдек туюлишингиз мумкин, лекин бундай эмас. Сиз ўзингизни четга олгандек кўринасиз, лекин бунда ичингизда нозик, қалбан ташкилот бор, уни худди романтик севги намоён бўлишлари каби кўрсатишга интилмайсиз. Сиз ортиқча ҳисларни ёқтирмайсиз ва сиз билан хотиржам, зўриқишсиз, аниқ, мантиқий мулоқот қилишларини истайсиз, шунда сиз суҳбатдошни эшита оласиз. Севгида сизда қоидалар бўлиши ва ҳаммаси ҳалол бўлиши керак. Сиз келишувлар, режалаштириш ва вақтга риоя қилишни яхши кўрасиз. Сиз барқарор ва масъулиятли инсонсиз ва ўзингизга худди шундай шерик истайсиз.","Вы любите эмоциональные страсти, действия, движение, поступки. Ваша любовь похожа на испанские страсти или пожар, потому что в любви вы – огонь. С вами не соскучишься. Вам в любви должно быть ярко и эмоционально, иногда, чтоб дух захватывало, но в тоже время вы хотите, чтобы ваш пожар возлюбленный мог потушить, если этот пожар может спалить все до тла. Вашему партнеру придется лавировать между спокойствием, мудростью и эмоциональными подъемами. Секс – это важно, в нем вы хотите и можете выразить всю свою любовь. Во флирте тоже. Вы ревнуете и вам это нравится, но если вы любите, вы верны до конца.":"Сиз ҳиссий эҳтирослар, ҳаракатлар, ҳаракат, хатти-ҳаракатларни яхши кўрасиз. Севгингиз испан эҳтирослари ёки ёнғинга ўхшайди, чунки севгида сиз — оловсиз. Сиз билан зерикмайсан. Севгида сизга ёрқин ва ҳиссий, баъзан нафас тўхтайдиган даражада бўлиши керак, лекин айни пайтда агар бу ёнғин ҳаммасини кулга айлантириши мумкин бўлса, севгилингиз ёнғинингизни ўчира олишини истайсиз. Шеригингизга хотиржамлик, донолик ва ҳиссий кўтарилишлар ўртасида маневр қилишга тўғри келади. Секс — бу муҳим, унда сиз бутун севгингизни ифода этишни истайсиз ва ифода эта оласиз. Флиртда ҳам. Сиз рашк қиласиз ва бу сизга ёқади, лекин агар севсангиз, охиригача содиқсиз.","Число Дживы":"Джива сони","Число Кармы":"Карма сони","взаимоотношений с близкими":"яқинлар билан ўзаро муносабатлар","расходы, потери":"харажатлар, йўқотишлар","расходов, потери":"харажатлар, йўқотишлар","Отношения с партнером":"Шерик билан муносабатлар","талантов, способностей":"истеъдодлар, қобилиятлар","радости и удачи":"қувонч ва омад","Ключевых задач":"Асосий вазифалар","приносит любовь":"севги келтиради","Самореализации, денег":"Ўзини рўёбга чиқариш, пул","отдачи, заботливости":"бериш, ғамхўрлик","наших возможностей":"имкониятларимиз","Мировоззрения":"Дунёқараш","Янтра: Интегральное число":"Янтра: Интеграл сон"});
